// ── Bildirim servisi — çoklu dil desteği
class NotificationService {
  static final _plugin = fln.FlutterLocalNotificationsPlugin();
  static const _notifId = 42;

  // TEST ANAHTARI: true iken bildirim 1 dk sonra + exact (test için).
  // PRODUCTION'A ALMADAN ÖNCE MUTLAKA false YAP → 24 saat + inexact.
  static const bool _testMode = false;

  static Future<void> init() async {
    tz_data.initializeTimeZones();
    // Telefonun saat dilimini bul ve ayarla
    // (yapılmazsa tz.local UTC kalır, bildirim yanlış zamanlanır → tetiklenmez)
    try {
      final localTz = await FlutterTimezone.getLocalTimezone();
      tz.setLocalLocation(tz.getLocation(localTz.identifier));
      debugPrint('=== SAAT DILIMI: ${localTz.identifier} ===');
    } catch (e) {
      debugPrint('=== Saat dilimi ayarlanamadı: $e ===');
    }
    const androidSettings =
        fln.AndroidInitializationSettings('@mipmap/ic_launcher');
    const settings = fln.InitializationSettings(android: androidSettings);
    await _plugin.initialize(settings);
    // İzin iste (Android 13+)
    final androidImpl = _plugin.resolvePlatformSpecificImplementation<
        fln.AndroidFlutterLocalNotificationsPlugin>();
    await androidImpl?.requestNotificationsPermission();
  }

  static Future<String> _getLang() async {
    final prefs = await SharedPreferences.getInstance();
    final lang = prefs.getString('ui.lang') ?? 'en';
    return lang.contains('-')
        ? lang.split('-')[0].toLowerCase()
        : lang.toLowerCase();
  }

