  // Sıradaki mesajı döndürür ve indeksi ilerletir (0-9 arası döngü)
  static Future<List<String>> _pickMessage(String lang) async {
    final prefs = await SharedPreferences.getInstance();
    final index = prefs.getInt('notif_msg_index') ?? 0;
    final messages = _getMessages(lang);
    final msg = messages[index % messages.length];
    await prefs.setInt('notif_msg_index', (index + 1) % messages.length);
    return msg;
  }

  // Anlık bildirim — sadece test için
  static Future<void> showReminderNotification() async {
    final lang = await _getLang();
    final msg = await _pickMessage(lang);
    final androidDetails = fln.AndroidNotificationDetails(
      'daily_reminder',
      'Daily Reminder',
      channelDescription: 'EasyReading daily usage reminder',
      importance: fln.Importance.high,
      priority: fln.Priority.high,
    );
    final details = fln.NotificationDetails(android: androidDetails);
    await _plugin.show(0, msg[0], msg[1].isNotEmpty ? msg[1] : null, details);
  }

  // 24 saat sonraya bildirim zamanla
  static Future<void> scheduleReminder() async {
    final lang = await _getLang();
    final msg = await _pickMessage(lang);
    // Önce varsa eski bildirimi iptal et
    await _plugin.cancel(_notifId);

    final scheduledTime = tz.TZDateTime.now(tz.local).add(
        _testMode ? const Duration(minutes: 2) : const Duration(hours: 24));

    final androidDetails = fln.AndroidNotificationDetails(
      'daily_reminder',
      'Daily Reminder',
      channelDescription: 'EasyReading daily usage reminder',
      importance: fln.Importance.high,
      priority: fln.Priority.high,
    );
    final details = fln.NotificationDetails(android: androidDetails);

    try {
      await _plugin.zonedSchedule(
        _notifId,
        msg[0],
        msg[1].isNotEmpty ? msg[1] : null,
        scheduledTime,
        details,
        androidScheduleMode: _testMode
            ? fln.AndroidScheduleMode.exactAllowWhileIdle
            : fln.AndroidScheduleMode.inexactAllowWhileIdle,
        uiLocalNotificationDateInterpretation:
            fln.UILocalNotificationDateInterpretation.absoluteTime,
      );
      debugPrint('=== BILDIRIM ZAMANLANDI: $scheduledTime ===');
      final pending = await _plugin.pendingNotificationRequests();
      debugPrint('=== KUYRUKTA: ${pending.length} bildirim ===');
    } catch (e, st) {
      debugPrint('=== BILDIRIM HATASI: $e ===');
      debugPrint('=== STACK: $st ===');
    }
  }
}

// ── FCM + Firestore: re-engagement push altyapısı
class PushService {
  static const String _collection = 'er_users'; // EasyReading kullanıcıları

  // Kalıcı cihaz kimliği (FCM token değişse de aynı kalır)
  static Future<String> _deviceId() async {
    final prefs = await SharedPreferences.getInstance();
    String id = prefs.getString('device_id') ?? '';
    if (id.isEmpty) {
      id =
          '${DateTime.now().microsecondsSinceEpoch}_${math.Random().nextInt(1 << 31)}';
      await prefs.setString('device_id', id);
    }
    return id;
  }

  // Uygulama açılışında 1 kez: izin al, token al, Firestore'a yaz
  static Future<void> register() async {
    try {
      final messaging = FirebaseMessaging.instance;
      await messaging.requestPermission();

      final id = await _deviceId();
      final token = await messaging.getToken();
      final prefs = await SharedPreferences.getInstance();
      final lang = prefs.getString('ui.lang') ?? 'en';

      await FirebaseFirestore.instance.collection(_collection).doc(id).set({
        'token': token,
        'lang': lang,
        'platform': Platform.isAndroid ? 'android' : 'ios',
        'lastActive': FieldValue.serverTimestamp(),
        'notifiedAt': null, // kullanıcı aktif → bildirim işareti sıfır
      }, SetOptions(merge: true));

      debugPrint('=== FCM KAYIT OK: token alindi, Firestore yazildi ===');

      // Token yenilenirse güncelle
      messaging.onTokenRefresh.listen((newToken) async {
        await FirebaseFirestore.instance
            .collection(_collection)
            .doc(id)
            .set({'token': newToken}, SetOptions(merge: true));
      });
    } catch (e) {
      debugPrint('=== FCM KAYIT HATASI: $e ===');
    }
  }

  // Her açılış/dönüşte: son aktiflik zamanını güncelle, bildirim işaretini sıfırla
  static Future<void> trackActive() async {
    try {
      final id = await _deviceId();
      await FirebaseFirestore.instance.collection(_collection).doc(id).set({
        'lastActive': FieldValue.serverTimestamp(),
        'notifiedAt': null, // döndü → tekrar bildirilebilir
      }, SetOptions(merge: true));
    } catch (e) {
      debugPrint('=== FCM AKTIFLIK HATASI: $e ===');
    }
  }
}

// ── Son kullanım zamanını kaydet ve bildirimi yeniden zamanla
Future<void> _updateLastUsedTimestamp() async {
  final prefs = await SharedPreferences.getInstance();
  await prefs.setInt(
      'last_used_timestamp', DateTime.now().millisecondsSinceEpoch);
  // Uygulama açıldı → 24 saat sonraya yeni bildirim zamanla (local fallback)
  unawaited(NotificationService.scheduleReminder());
  // Firestore'a aktiflik yaz (FCM re-engagement için)
  unawaited(PushService.trackActive());
}

void main() async {
  WidgetsFlutterBinding.ensureInitialized();

  if (Platform.isIOS) {
    // ── iOS-ONLY: her adım timeout'lu ve hataya dayanıklı ──────
    Future<void> safeStep(
      Future<void> Function() action, {
      Duration timeout = const Duration(seconds: 6),
    }) async {
      try {
        await action().timeout(timeout);
      } catch (e) {
        debugPrint('[BOOT] step failed/timeout: $e');
      }
    }

    await safeStep(() async {
      await Firebase.initializeApp(
        options: DefaultFirebaseOptions.currentPlatform,
      );
    });
    await safeStep(() => _checkAndResetForNewBuild());
    await safeStep(() => PremiumService.instance.load());
    await safeStep(() => GoogleFonts.pendingFonts([GoogleFonts.lora()]));
    await safeStep(() => NotificationService.init());

    unawaited(PushService.register());
    unawaited(_updateLastUsedTimestamp());

    await Future.delayed(const Duration(milliseconds: 2000));

    bool firstOpenShown = false;
    await safeStep(() async {
      firstOpenShown = await PremiumService.instance.isFirstOpenShown();
    });

    final String initialRoute = firstOpenShown ? '/reading' : '/welcome';
    runApp(EasyReadingTestApp(initialRoute: initialRoute));
    return;
  }

  // ── ANDROID FLOW — DEĞİŞTİRİLMEDİ ────────────────────────────
  await Firebase.initializeApp(
    options: DefaultFirebaseOptions.currentPlatform,
  );

  await _checkAndResetForNewBuild();
  await PremiumService.instance.load();
  await GoogleFonts.pendingFonts([GoogleFonts.lora()]);

  await NotificationService.init();

  unawaited(PushService.register());
  unawaited(_updateLastUsedTimestamp());

  await Future.delayed(const Duration(milliseconds: 2000));

  final bool firstOpenShown = await PremiumService.instance.isFirstOpenShown();
  final String initialRoute = firstOpenShown ? '/reading' : '/welcome';

  runApp(EasyReadingTestApp(initialRoute: initialRoute));
}

// ================== ISOLATE HELPER FUNCTIONS (top-level for compute()) ==================

// Maks kaç sayfa yüklensin (büyük PDF'ler için)
const int _kPdfMaxPages = 5;

/// Bozuk PDF glyph mapping'i düzelt (Türkçe ligature hatası)
/// Bu font'ta Türkçe karakterler iki parçaya bölünmüş:
/// ü → u + ǅ/ǚ,  ö → o + ǆ,  ğ → g + Ǎ/ǎ,  Ü → U + ǅ/ǚ,  Ğ → G + Ǎ/ǎ
String _fixPdfGlyphErrors(String text) {
  String t = text;

  // ── Glyph-ismi encoding (UYAP/resmi belge PDF'leri) ──────────────────────
  // Bu PDF'lerde Türkçe karakterler glyph adı olarak gömülür:
  // "Idotaccent" → İ,  "Gbreve" → Ğ,  "Scedilla" → Ş, vb.
  t = t.replaceAll('Idotaccent', 'İ');
  t = t.replaceAll('idotaccent', 'i');
  t = t.replaceAll('Gbreve', 'Ğ');
  t = t.replaceAll('gbreve', 'ğ');
  t = t.replaceAll('Scedilla', 'Ş');
  t = t.replaceAll('scedilla', 'ş');
  t = t.replaceAll('Ccedilla', 'Ç');
  t = t.replaceAll('ccedilla', 'ç');
  t = t.replaceAll('Odieresis', 'Ö');
  t = t.replaceAll('odieresis', 'ö');
  t = t.replaceAll('Udieresis', 'Ü');
  t = t.replaceAll('udieresis', 'ü');
  t = t.replaceAll('Adieresis', 'Ä');
  t = t.replaceAll('adieresis', 'ä');

  return t
      // ── Çift karakter düzeltmeleri (önce bunlar — sıra önemli) ───────────
      .replaceAll('uǅ', 'ü')
      .replaceAll('uǚ', 'ü')
      .replaceAll('Uǅ', 'Ü')
      .replaceAll('Uǚ', 'Ü')
      .replaceAll('Uǆ', 'Ü')
      .replaceAll('oǆ', 'ö')
      .replaceAll('Oǆ', 'Ö')
      .replaceAll('gǍ', 'ğ')
      .replaceAll('gǎ', 'ğ')
      .replaceAll('GǍ', 'Ğ')
      .replaceAll('Gǎ', 'Ğ')
      // Tek başına kalan artifact'lar (eşleşemeyen)
      .replaceAll('Ǆ', '')
      .replaceAll('ǅ', '')
      .replaceAll('ǆ', '')
      .replaceAll('ǚ', '')
      .replaceAll('Ǎ', '')
      .replaceAll('ǎ', '');
}

/// Bozuk PDF tespiti — Türkçe karakterler yerine sayı/noktalı bozuk encoding var mı?
bool _isBrokenTurkishPdf(String text) {
  if (text.length < 100) return false;
  final sample = text.length > 2000 ? text.substring(0, 2000) : text;
  // Bozuk pattern sayısını say
  int brokenCount = 0;
  // ı → 1 (kelime içinde rakam)
  brokenCount += RegExp(r'[a-z]1[a-z]').allMatches(sample).length;
  // ş → r; veya r;err; pattern
  brokenCount += RegExp(r'r;').allMatches(sample).length;
  // ü → ii, ö → oo pattern (çift harf)
  brokenCount += RegExp(r'[a-z]ii[a-z]|[a-z]oo[a-z]').allMatches(sample).length;
  // Boşluklu tek harf pattern: "N Ö R B Ö" gibi — encoding bozukluğu
  final spacedLetters = RegExp(r'\b[A-ZÇĞİÖŞÜ] [A-ZÇĞİÖŞÜ] [A-ZÇĞİÖŞÜ]\b')
      .allMatches(sample)
      .length;
  if (spacedLetters >= 3) return true;
  return brokenCount >= 3;
}

Future<String> _extractPdfInIsolate(String path) async {
  // Önce Syncfusion dene — Türkçe encoding için daha güvenilir
  try {
    final bytes = await File(path).readAsBytes();
    await Future.delayed(Duration.zero); // UI'a nefes aldır
    final document = PdfDocument(inputBytes: bytes);
    final extractor = PdfTextExtractor(document);
    final totalPages = document.pages.count;
    final buffer = StringBuffer();
    for (int p = 0; p < totalPages; p++) {
      try {
        final t = extractor.extractText(startPageIndex: p, endPageIndex: p);
        if (t.isNotEmpty) buffer.writeln(t);
      } catch (_) {}
      // Her 5 sayfada bir UI'a nefes aldır — ANR önler
      if (p % 5 == 0) await Future.delayed(Duration.zero);
    }
    document.dispose();
    final syncResult = buffer.toString().trim();
    if (syncResult.isNotEmpty) {
      return _postProcessPdf(_fixPdfGlyphErrors(syncResult));
    }
  } catch (e) {}

  // Fallback: pdfrx (PDFium)
  final buffer = StringBuffer();
  try {
    final doc = await pdfrx.PdfDocument.openFile(path);
    final pageCount = doc.pages.length;
    for (int p = 1; p <= pageCount; p++) {
      try {
        final page = doc.pages[p - 1];
        final pageText = await page.loadText();
        final text = _fixPdfGlyphErrors(pageText.fullText);
        if (text.isNotEmpty) buffer.writeln(text);
      } catch (e) {}
      if (p % 5 == 0) await Future.delayed(Duration.zero); // UI'a nefes aldır
    }
    doc.dispose();
  } catch (e) {
    return 'PDF okunamadı: \$e';
  }

  // Single \n to space, double \n\n stays as paragraph break
  String raw = _fixPdfGlyphErrors(buffer.toString().trim());
  raw = raw.replaceAll('\r\n', '\n').replaceAll('\r', '\n');
  raw = raw.replaceAll(RegExp(r'\n{3,}'), '\n\n');
  // PDF kitap metni: tek \n → boşluk, çift \n → paragraf (korunur)
  raw = raw.replaceAll('\n\n', '§PARA§');
  raw = raw.replaceAll('\n', ' ');
  raw = raw.replaceAll('§PARA§', '\n\n');
  raw = raw.replaceAll(RegExp(r' {2,}'), ' ');
  return raw.trim();
}

/// PDF post-process: satır birleştirme, şiir tespiti
String _postProcessPdf(String raw) {
  raw = raw.replaceAll('\r\n', '\n').replaceAll('\r', '\n');
  raw = raw.replaceAll(RegExp(r'\n{3,}'), '\n\n');
  // PDF'den gelen metinde tek \n → boşluk (kitap satır sonu)
  // Çift \n → paragraf sonu (korunur)
  raw = raw.replaceAll('\n\n', '§PARA§');
  raw = raw.replaceAll('\n', ' ');
  raw = raw.replaceAll('§PARA§', '\n\n');
  raw = raw.replaceAll(RegExp(r' {2,}'), ' ');
  return raw.trim();
}

/// PDF'den gelen tek kelime per satır formatını düzeltir
String _fixPdfLineBreaks(String text) {
  final lines = text.split('\n');
  final nonEmpty = lines.where((l) => l.trim().isNotEmpty).toList();
  if (nonEmpty.isEmpty) return text;

  // Kısa satır oranı %40'dan fazlaysa VEYA ortalama satır uzunluğu < 25 ise
  // kelime-satır formatı kabul et
  final shortCount = nonEmpty.where((l) {
    final t = l.trim();
    return t.split(RegExp(r'\s+')).length <= 4 && t.length < 50;
  }).length;
  final shortRatio = shortCount / nonEmpty.length;
  final avgLineLen =
      nonEmpty.map((l) => l.trim().length).reduce((a, b) => a + b) /
          nonEmpty.length;
  final isWordPerLine = shortRatio > 0.4 || avgLineLen < 25;

  if (!isWordPerLine) {
    return text.replaceAll(RegExp(r'\n{3,}'), '\n\n').trim();
  }

  // Kelime-satır formatı → birleştir
  // Büyük harfle başlayan kısa satır = yeni paragraf başlangıcı olabilir
  final buffer = StringBuffer();
  bool lastWasEmpty = false;
  String prevLine = '';

  for (final line in lines) {
    final t = line.trim();
    if (t.isEmpty) {
      if (!lastWasEmpty && buffer.isNotEmpty) {
        buffer.write('\n\n');
        lastWasEmpty = true;
      }
      continue;
    }
    lastWasEmpty = false;

    // Eğer önceki satır nokta/ünlem/soru ile bittiyse → yeni paragraf
    if (prevLine.isNotEmpty &&
        RegExp(r'[.!?]$').hasMatch(prevLine) &&
        t[0] == t[0].toUpperCase()) {
      buffer.write('\n\n$t ');
    } else {
      buffer.write('$t ');
    }
    prevLine = t;
  }

  return buffer
      .toString()
      .replaceAll(RegExp(r' {2,}'), ' ')
      .replaceAll(RegExp(r' \n'), '\n')
      .replaceAll(RegExp(r'\n{3,}'), '\n\n')
      .trim();
}

