Future<String> _extractEpubInIsolate(String path) async {
  try {
    final bytes = await File(path).readAsBytes();
    final dynamic book = await epub_plus.EpubReader.readBook(bytes);
    final buffer = StringBuffer();

    void extractChapter(dynamic ch) {
      try {
        final String htmlContent =
            (ch?.htmlContent ?? ch?.HtmlContent ?? '') as String? ?? '';
        if (htmlContent.isNotEmpty) {
          final doc = html_parser.parse(htmlContent);
          doc.querySelectorAll('script').forEach((e) => e.remove());
          doc.querySelectorAll('style').forEach((e) => e.remove());
          // Paragraf etiketlerini \n\n ile ayır
          for (final p
              in doc.querySelectorAll('p, h1, h2, h3, h4, h5, h6, br')) {
            p.innerHtml = '${p.innerHtml}\n\n';
          }
          final chapterText = doc.body?.text ?? doc.text ?? '';
          final cleaned = chapterText
              .replaceAll(RegExp(r'\n{3,}'), '\n\n')
              .replaceAll(RegExp(r'[ \t]+'), ' ')
              .trim();
          if (cleaned.isNotEmpty) {
            buffer.writeln(cleaned);
            buffer.writeln();
          }
        }
        final subs =
            (ch?.subChapters ?? ch?.SubChapters ?? []) as List<dynamic>;
        for (final sub in subs) {
          extractChapter(sub);
        }
      } catch (_) {}
    }

    final chapters = (book?.chapters ?? book?.Chapters ?? []) as List<dynamic>;
    for (final chapter in chapters) {
      extractChapter(chapter);
    }

    final result = buffer.toString().trim();
    if (result.isEmpty) {
      final spineBuffer = StringBuffer();
      try {
        final dynamic htmlItems = book?.content?.html ?? book?.Content?.Html;
        if (htmlItems != null) {
          final values = (htmlItems as Map).values;
          for (final dynamic item in values) {
            final String html =
                (item?.content ?? item?.Content ?? '') as String? ?? '';
            if (html.isNotEmpty) {
              final doc = html_parser.parse(html);
              doc.querySelectorAll('script').forEach((e) => e.remove());
              doc.querySelectorAll('style').forEach((e) => e.remove());
              final txt = doc.body?.text ?? '';
              final cleaned = txt.replaceAll(RegExp(r'\s+'), ' ').trim();
              if (cleaned.isNotEmpty) {
                spineBuffer.writeln(cleaned);
                spineBuffer.writeln();
              }
            }
          }
        }
      } catch (_) {}
      return spineBuffer.toString().trim();
    }
    return result;
  } catch (e) {
    return 'EPUB_ERROR: $e';
  }
}
