// Unified source of truth for UI/menu languages (used in WelcomePage and ReadingPage)
class UiLang {
  final String code; // Short code (e.g., "en", "tr", "bg", "ja", "ko")
  final String nameKey; // Translation key (e.g., "lang_en", "lang_tr")
  final String
      displayName; // User-friendly display name (e.g., "Bulgarian", "Japanese", "Korean")
  final String flag; // Flag emoji

  const UiLang({
    required this.code,
    required this.nameKey,
    required this.displayName,
    required this.flag,
  });
}

const List<UiLang> kUiLanguages = [
  UiLang(code: 'tr', nameKey: 'lang_tr', displayName: 'Turkish', flag: '🇹🇷'),
  UiLang(code: 'en', nameKey: 'lang_en', displayName: 'English', flag: '🇺🇸'),
  UiLang(code: 'it', nameKey: 'lang_it', displayName: 'Italian', flag: '🇮🇹'),
