];

// Single source of truth for finding UiLang by code
UiLang _uiLangOf(String code) {
  final key = code
      .trim()
      .toLowerCase()
      .split(RegExp(r'[_\-]'))
      .first; // 'ja-JP' gelirse 'ja' olur
  return kUiLanguages.firstWhere(
    (l) => l.code == key,
    orElse: () => kUiLanguages.firstWhere((l) => l.code == 'en',
        orElse: () => kUiLanguages.first),
  );
}

// Normalize language key from raw input (handles both codes like "de-DE" and labels like "German")
String _normLangKey(String raw) {
  final s = raw.trim().toLowerCase();
  // If already a BCP-47 like "ja-JP" or "ja"
  final key = s.split(RegExp(r'[_\-]')).first;
  // Accept only known keys; otherwise check label mapping
  if (kUiFlag.containsKey(key)) return key;

  // If raw is a label like "German", map labels -> keys
  const labelToKey = {
    'german': 'de',
    'deutsch': 'de',
    'turkish': 'tr',
    'türkçe': 'tr',
    'english': 'en',
    'english (us)': 'en',
    'russian': 'ru',
    'bulgarian': 'bg',
    'български': 'bg',
    'greek': 'el',
    'ελληνικά': 'el',
    'italian': 'it',
    'français': 'fr',
    'french': 'fr',
    'spanish': 'es',
    'japanese': 'ja',
    '日本語': 'ja',
    'korean': 'ko',
    '한국어': 'ko',
    'hindi': 'hi',
    'हिन्दी': 'hi',
  };
  return labelToKey[s] ?? 'en';
}

// Get flag from kUiFlag using normalized key (handles both codes and labels)
String _getFlagFromUiCode(String uiCode) {
  final key = _normLangKey(uiCode);
  final flag = kUiFlag[key] ?? kUiFlag['en']!;
  return flag;
}

// Explicit flag mapping for UI languages (no heuristic fallback)
// This ensures flags are always derived synchronously from the short code
String getUiLanguageFlag(String shortCode) {
  const flagMap = {
    'tr': '🇹🇷',
    'en': '🇺🇸',
    'it': '🇮🇹',
    'de': '🇩🇪',
    'hi': '🇮🇳',
    'fr': '🇫🇷',
    'es': '🇪🇸',
    'ru': '🇷🇺',
    'el': '🇬🇷',
    'bg': '🇧🇬',
    'ja': '🇯🇵',
    'ko': '🇰🇷',
  };
  return flagMap[shortCode] ?? '';
}

