// ======================= THEME ==========================
enum CustomThemeMode { light, dim, dark }

class AppTheme {
  static final ValueNotifier<CustomThemeMode> mode =
      ValueNotifier(CustomThemeMode.light);
  static final ValueNotifier<int> dimLevel = ValueNotifier(0); // 0-100
  // Animated interpolation value: 0.0 = fully light, 1.0 = fully dark
  // Updated by _AppThemeAnimator when mode changes
  static final ValueNotifier<double> animatedT = ValueNotifier(0.0);
  // E-ink modu: yüksek kontrast, animasyonsuz görünüm (e-ink ekranlar için)
  static final ValueNotifier<bool> eInk = ValueNotifier(false);
  static const _prefsKey = 'ui.theme';
  static const _prefsKeyDimLevel = 'ui.dim_level';
  static const _prefsKeyEInk = 'ui.eink_mode';

  static Future<void> load() async {
    final sp = await SharedPreferences.getInstance();
    final saved = sp.getString(_prefsKey);
    if (saved != null) {
      switch (saved) {
        case 'light':
          mode.value = CustomThemeMode.light;
          break;
        case 'dim':
          mode.value = CustomThemeMode.dark;
          dimLevel.value = 100;
          await sp.setInt(_prefsKeyDimLevel, 100);
          break;
        case 'dark':
          mode.value = CustomThemeMode.dark;
          break;
      }
    }
    // Load dim level
    final savedDimLevel = sp.getInt(_prefsKeyDimLevel);
    if (savedDimLevel != null) {
      dimLevel.value = savedDimLevel.clamp(0, 100);
    }
    // Load e-ink modu
    eInk.value = sp.getBool(_prefsKeyEInk) ?? false;
  }

  static Future<void> set(CustomThemeMode newMode) async {
    mode.value = newMode;
    final sp = await SharedPreferences.getInstance();
    await sp.setString(_prefsKey, newMode.name);
  }

  static Future<void> setDimLevel(int level) async {
    dimLevel.value = level.clamp(0, 100);
    final sp = await SharedPreferences.getInstance();
    await sp.setInt(_prefsKeyDimLevel, dimLevel.value);
  }

  static Future<void> setEInk(bool value) async {
    eInk.value = value;
    final sp = await SharedPreferences.getInstance();
    await sp.setBool(_prefsKeyEInk, value);
  }

  // E-ink ekranlar için: saf siyah/beyaz, yüksek kontrast, gölgesiz tema
  // ÖNEMLİ: appTheme()'in ÜZERİNE copyWith ile inşa ediyoruz — böylece
  // buton dolgusu, visualDensity, tapTargetSize gibi TÜM görünmez boyut
  // ayarları normal temayla birebir aynı kalır, sadece renkler değişir.
  // (Sıfırdan yeni bir ThemeData() oluşturmak, aradaki görünmez ölçü
  // farkları yüzünden butonların/ikonların yer değiştirmesine sebep oluyordu.)
  static ThemeData getEInkThemeData() {
    final base = appTheme();
    return base.copyWith(
      brightness: Brightness.light,
      scaffoldBackgroundColor: Colors.white,
      canvasColor: Colors.white,
      primaryColor: Colors.black,
      colorScheme: base.colorScheme.copyWith(
        primary: Colors.black,
        onPrimary: Colors.white,
        secondary: Colors.black,
        onSecondary: Colors.white,
        surface: Colors.white,
        onSurface: Colors.black,
        error: Colors.black,
        onError: Colors.white,
      ),
      appBarTheme: base.appBarTheme.copyWith(
        backgroundColor: Colors.white,
        foregroundColor: Colors.black,
        elevation: 0,
      ),
      textTheme: base.textTheme.apply(
        bodyColor: Colors.black,
        displayColor: Colors.black,
      ),
      iconTheme: (base.iconTheme).copyWith(color: Colors.black),
      dividerColor: Colors.black,
      // Sayfa geçişi animasyonu kapalı — e-ink'te bulanıklık yaratmasın
      pageTransitionsTheme: const PageTransitionsTheme(
        builders: {
          TargetPlatform.android: _NoAnimationPageTransitionsBuilder(),
          TargetPlatform.iOS: _NoAnimationPageTransitionsBuilder(),
        },
      ),
    );
  }

  // Helper to convert to Flutter's ThemeMode for MaterialApp
  static ThemeMode get themeMode {
    switch (mode.value) {
      case CustomThemeMode.light:
      case CustomThemeMode.dim:
      case CustomThemeMode.dark:
        return ThemeMode.dark;
    }
  }

  // Helper to get the appropriate theme data
  static ThemeData getThemeData() {
    switch (mode.value) {
      case CustomThemeMode.light:
        return appTheme();
      case CustomThemeMode.dim:
      case CustomThemeMode.dark:
        return appDarkThemeWithDimLevel(dimLevel.value);
    }
  }
}

// E-ink modunda sayfa geçişleri animasyonsuz olsun — ghosting'i azaltır
class _NoAnimationPageTransitionsBuilder extends PageTransitionsBuilder {
  const _NoAnimationPageTransitionsBuilder();
  @override
  Widget buildTransitions<T>(
    PageRoute<T> route,
    BuildContext context,
    Animation<double> animation,
    Animation<double> secondaryAnimation,
    Widget child,
  ) {
    return child;
  }
}

IconData _getThemeIcon(CustomThemeMode mode) {
  switch (mode) {
    case CustomThemeMode.light:
      return Icons.light_mode_rounded;
    case CustomThemeMode.dim:
    case CustomThemeMode.dark:
      return Icons.dark_mode_rounded;
  }
}

// Show vertical brightness slider popup (standalone function)
void _showBrightnessSliderPopup(BuildContext buttonContext) {
  final RenderBox? buttonBox = buttonContext.findRenderObject() as RenderBox?;
  if (buttonBox == null) return;

  final RenderBox? overlay =
      Overlay.of(buttonContext).context.findRenderObject() as RenderBox?;
  if (overlay == null) return;

  final buttonPosition = buttonBox.localToGlobal(Offset.zero);
  final buttonSize = buttonBox.size;
  final overlaySize = overlay.size;

  // Position popup to the left of the button (landscape safe)
  final double popupWidth = 100.0;
  final double popupHeight = 320.0;

  // Landscape: buton sağda olunca popup taşıyor — sola çıkar
  final double dxLeft = buttonPosition.dx - popupWidth - 8.0;
  final double dxRight = buttonPosition.dx + buttonSize.width + 8.0;
  final double dy = buttonPosition.dy;

  // Eğer sola yer varsa sola, yoksa sağa çıkar
  final double adjustedDx = dxLeft >= 0 ? dxLeft : dxRight;

  showDialog(
    context: buttonContext,
    barrierColor: Colors.transparent,
    builder: (dialogContext) => Stack(
      children: [
        // Invisible barrier to dismiss on tap outside
        Positioned.fill(
          child: GestureDetector(
            onTap: () => Navigator.of(dialogContext).pop(),
            child: Container(color: Colors.transparent),
          ),
        ),
        // Popup positioned near button
        Positioned(
          left: adjustedDx,
          top: dy,
          child: Material(
            color: Colors.transparent,
            child: Container(
              width: popupWidth,
              height: popupHeight,
              decoration: BoxDecoration(
                color: Theme.of(dialogContext).cardColor,
                borderRadius: BorderRadius.circular(12),
                boxShadow: [
                  BoxShadow(
                    color: Colors.black.withValues(alpha: 0.2),
                    blurRadius: 8,
                    offset: const Offset(0, 4),
                  ),
                ],
              ),
              padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 16),
              child: ValueListenableBuilder<CustomThemeMode>(
                valueListenable: AppTheme.mode,
                builder: (context, mode, _) {
                  return ValueListenableBuilder<int>(
                    valueListenable: AppTheme.dimLevel,
                    builder: (context, dimLevel, _) {
                      final currentValue = mode == CustomThemeMode.light
                          ? 0.0
                          : dimLevel.clamp(1, 100).toDouble();

                      return Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          // Value label at top
                          Text(
                            '${currentValue.round()}',
                            style: Theme.of(context)
                                .textTheme
                                .titleMedium
                                ?.copyWith(
                                  fontWeight: FontWeight.bold,
                                ),
                          ),
                          const SizedBox(height: 12),
                          // Vertical slider
                          Expanded(
                            child: Center(
                              child: RotatedBox(
                                quarterTurns:
                                    3, // Rotate 270 degrees (vertical)
                                child: SizedBox(
                                  width: 240, // Height when rotated
                                  child: Slider(
                                    value: currentValue,
                                    min: 0,
                                    max: 100,
                                    divisions: 100,
                                    onChanged: (value) {
                                      final roundedValue = value.round();
                                      if (roundedValue == 0) {
                                        AppTheme.set(CustomThemeMode.light);
                                      } else {
                                        if (mode == CustomThemeMode.light) {
                                          AppTheme.set(CustomThemeMode.dark);
                                        }
                                        AppTheme.setDimLevel(roundedValue);
                                      }
                                    },
                                  ),
                                ),
                              ),
                            ),
                          ),
                          const SizedBox(height: 12),
                          // Min/Max labels at bottom
                          Row(
                            mainAxisAlignment: MainAxisAlignment.spaceBetween,
                            children: [
                              Text(
                                '0',
                                style: Theme.of(context).textTheme.bodySmall,
                              ),
                              Text(
                                '100',
                                style: Theme.of(context).textTheme.bodySmall,
                              ),
                            ],
                          ),
                        ],
                      );
                    },
                  );
                },
              ),
            ),
          ),
        ),
      ],
    ),
  );
}

// Helper function for smooth easing (smoothstep)
// Provides smooth transition instead of linear
double _smoothEase(double t) {
  t = t.clamp(0.0, 1.0);
  // Smoothstep function: t * t * (3 - 2 * t)
  // This creates a smooth S-curve transition
  return t * t * (3.0 - 2.0 * t);
}

// Helper function to interpolate between two colors
Color _interpolateColor(Color start, Color end, double t) {
  t = t.clamp(0.0, 1.0);
  return Color.fromARGB(
    (start.alpha + (end.alpha - start.alpha) * t).round(),
    (start.red + (end.red - start.red) * t).round(),
    (start.green + (end.green - start.green) * t).round(),
    (start.blue + (end.blue - start.blue) * t).round(),
  );
}

