// ======================= RESPONSIVE PAGE WRAPPER =======================
class ResponsivePage extends StatelessWidget {
  final Widget child;
  final EdgeInsetsGeometry padding;
  final bool centerWhenFits;
  final bool skipScrollView; // For scrollable widgets like ListView

  const ResponsivePage({
    super.key,
    required this.child,
    this.padding = const EdgeInsets.all(16),
    this.centerWhenFits = true,
    this.skipScrollView = false,
  });

  @override
  Widget build(BuildContext context) {
    return SafeArea(
      child: LayoutBuilder(
        builder: (context, constraints) {
          final content = Padding(
            padding: padding,
            child: child,
          );

          if (skipScrollView) {
            // For scrollable widgets, just provide SafeArea and padding
            return content;
          }

          return SingleChildScrollView(
            child: ConstrainedBox(
              constraints: BoxConstraints(minHeight: constraints.maxHeight),
              child: centerWhenFits
                  ? IntrinsicHeight(
                      child: Column(
                        mainAxisAlignment: MainAxisAlignment.center,
                        children: [content],
                      ),
                    )
                  : content,
            ),
          );
        },
      ),
    );
  }
}

