// Base dark theme (dim level = 0)
ThemeData appDarkTheme() => appDarkThemeWithDimLevel(0);

// Dynamic dark theme with dim level interpolation (0-100)
// 0 = pure dark, 100 = soft dark (similar to old dim theme)
ThemeData appDarkThemeWithDimLevel(int dimLevel) {
  // Apply smooth easing for gradual transition instead of linear
  final linearT = (dimLevel.clamp(0, 100) / 100.0);
  final t = _smoothEase(linearT);

  // Dark theme colors (t=0)
  const darkScaffold = Color(0xFF121212);
  const darkBackground = Color(0xFF121212);
  const darkSurface = Color(0xFF1A1A1A);
  const darkAppBar = Color(0xFF121212);
  const darkCard = Color(0xFF1A1A1A);
  const darkDialog = Color(0xFF222222);

  // Dim theme colors (t=1)
  const dimScaffold = Color(0xFF1E1E1E);
  const dimBackground = Color(0xFF1E1E1E);
  const dimSurface = Color(0xFF2A2A2A);
  const dimAppBar = Color(0xFF1E1E1E);
  const dimCard = Color(0xFF2A2A2A);
  const dimDialog = Color(0xFF2F2F2F);

  // Interpolate colors
  final scaffoldColor = _interpolateColor(darkScaffold, dimScaffold, t);
  final backgroundColor = _interpolateColor(darkBackground, dimBackground, t);
  final surfaceColor = _interpolateColor(darkSurface, dimSurface, t);
  final appBarColor = _interpolateColor(darkAppBar, dimAppBar, t);
  final cardColor = _interpolateColor(darkCard, dimCard, t);
  final dialogColor = _interpolateColor(darkDialog, dimDialog, t);

  return ThemeData(
    useMaterial3: false,
    brightness: Brightness.dark,
    scaffoldBackgroundColor: scaffoldColor,
    colorScheme: ColorScheme.dark(
      primary: kBeigeDark,
      onPrimary: Colors.white,
      background: backgroundColor,
      surface: surfaceColor,
      onSurface: Colors.white,
    ),
    appBarTheme: AppBarTheme(
      backgroundColor: appBarColor,
      foregroundColor: Colors.white,
      elevation: 0,
      centerTitle: true,
    ),
    elevatedButtonTheme: ElevatedButtonThemeData(
      style: ElevatedButton.styleFrom(
        backgroundColor: kBeigeDark,
        foregroundColor: Colors.white,
        padding: const EdgeInsets.symmetric(vertical: 10, horizontal: 20),
        textStyle: const TextStyle(fontSize: 16),
        shape: RoundedRectangleBorder(
          borderRadius: BorderRadius.circular(12),
        ),
      ),
    ),
    cardTheme: CardThemeData(
      color: cardColor,
      elevation: 1,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.all(Radius.circular(16)),
      ),
    ),
    scrollbarTheme: ScrollbarThemeData(
      thumbColor: WidgetStateProperty.all(Colors.transparent),
      trackColor: WidgetStateProperty.all(Colors.transparent),
      thickness: WidgetStateProperty.all(6.0),
      trackVisibility: WidgetStateProperty.all(false),
      thumbVisibility: WidgetStateProperty.all(false),
    ),
    snackBarTheme: SnackBarThemeData(
      contentTextStyle:
          GoogleFonts.lora(fontSize: 13, fontWeight: FontWeight.w300),
      actionTextColor: Colors.white,
    ),
    textTheme:
        GoogleFonts.loraTextTheme(_noBoldTextTheme(ThemeData.dark().textTheme)),
  ).copyWith(
    // ⭐ GECE DIALOG TEMA
    dialogTheme: DialogThemeData(
      backgroundColor: dialogColor,
      shape: RoundedRectangleBorder(
        borderRadius: BorderRadius.circular(18),
      ),
      // Başlık: altın/bej tonu
      titleTextStyle: const TextStyle(
        color: Color(0xFFD6C8B3), // bizim bej-gold
        fontSize: 18,
        fontWeight: FontWeight.w400,
      ),
      // Uzun açıklama metni: beyazımsı, okuyabilir
      contentTextStyle: const TextStyle(
        color: Colors.white70,
        fontWeight: FontWeight.w400,
        fontSize: 14,
        height: 1.4,
      ),
    ),
  );
}

// ===================== SIMPLE I18N ======================
class AppLang {
  static final ValueNotifier<String> code = ValueNotifier<String>('en');
  static const _prefsKey = 'ui.lang';
  // Callback to update TTS locale when UI language changes
  static Future<void> Function(String ttsLocale)? onUiLanguageChanged;

  // Convert old locale code (bg-BG) to short code (bg) for migration
  static String _migrateOldLocale(String oldLocale) {
    if (!oldLocale.contains('-')) {
      return oldLocale.toLowerCase();
    }
    final parts = oldLocale.split('-');
    return parts[0].toLowerCase();
  }

  static Future<void> load() async {
    final sp = await SharedPreferences.getInstance();
    final c = sp.getString(_prefsKey);
    if (c != null) {
      String shortCode;
      // Migration: convert old format (bg-BG) to new format (bg)
      if (c.contains('-')) {
        shortCode = _migrateOldLocale(c);
      } else {
        shortCode = c.toLowerCase();
      }

      // Validate against kUiLanguages - ensure it's a valid short code
      if (kUiLanguages.any((lang) => lang.code == shortCode)) {
        code.value = shortCode;
        // Save migrated format if it was changed
        if (c != shortCode) {
          await sp.setString(_prefsKey, shortCode);
        }
      } else {
        // Invalid code, default to first language
        final defaultCode = kUiLanguages.first.code;
        code.value = defaultCode;
        await sp.setString(_prefsKey, code.value);
      }
    } else {}
    // Set default TTS follow UI preference if not set
    if (!sp.containsKey(kPrefTtsFollowUi)) {
      await sp.setBool(kPrefTtsFollowUi, true);
    }
  }

  // ⚠️ CRITICAL: This function should ONLY be called from user-initiated actions
  // (e.g., UI language dropdown selection). It MUST NEVER be called from auto-detection
  // code paths. Auto-detection should only affect reading/TTS language, not UI language.
  static Future<void> set(String c) async {
    // Accept both old locale codes (en-US) and short codes (en) for backward compatibility
    String shortCode;
    if (c.contains('-')) {
      // Migration: convert old format to short code
      shortCode = _migrateOldLocale(c);
    } else {
      shortCode = c.toLowerCase();
    }

    // Validate against kUiLanguages - ensure it's a valid short code
    if (!kUiLanguages.any((lang) => lang.code == shortCode)) {
      // If not found, default to first language
      shortCode = kUiLanguages.first.code;
    }

    code.value = shortCode;
    final sp = await SharedPreferences.getInstance();
    await sp.setString(_prefsKey, shortCode);

    // Update TTS locale if follow_ui is enabled
    final follow = sp.getBool(kPrefTtsFollowUi) ?? true;
    if (follow && onUiLanguageChanged != null) {
      try {
        final targetTts = kUiToTtsLocale[shortCode] ?? 'en-US';
        await onUiLanguageChanged!(targetTts);
      } catch (e) {}
    }
  }

  // Get language code (same as code.value now, kept for backward compatibility)
  static String get langCode => code.value;

  // Get all supported short codes
  static List<String> get supportedLocales =>
      kUiLanguages.map((lang) => lang.code).toList();

  static List<String> get supportedUiCodes => supportedLocales;
}

// Global listener for AppLang.code changes (TEŞHİS)
bool _appLangListenerInitialized = false;
void _initAppLangListener() {
  if (_appLangListenerInitialized) return;
  _appLangListenerInitialized = true;
  AppLang.code.addListener(() {});
}

