String humanizeLocale(String code) {
  const map = {
    'tr-TR': 'Türkçe (Türkiye)',
    'en-US': 'English (US)',
    'en-GB': 'English (UK)',
    'en-AU': 'English (Australia)',
    'de-DE': 'Deutsch (Deutschland)',
    'fr-FR': 'Français (France)',
    'es-ES': 'Español (España)',
    'it-IT': 'Italiano (Italia)',
    'hi-IN': 'Hindi (India)',
    'pt-BR': 'Português (Brasil)',
    'pt-PT': 'Português (Portugal)',
    'zh-CN': '中文 (中国)',
    'ja-JP': '日本語 (日本)',
    'ko-KR': '한국어 (대한민국)',
    'el-GR': 'Greek (Greece)',
    'ru-RU': 'Russian (Russia)',
  };
  return map[code] ?? code;
}

String flagForLocale(String locale) {
  // Normalize locale (underscore to dash)
  locale = locale.replaceAll('_', '-');
  final normalized = locale.toLowerCase();

  // Explicit mapping for UI languages (never fallback to country code from first 2 letters)
  const uiLangMap = {
    'en-us': '🇺🇸',
    'en-gb': '🇬🇧',
    'tr-tr': '🇹🇷',
    'de-de': '🇩🇪',
    'hi-in': '🇮🇳', // Explicit: Hindi must show India flag, not Germany
    'it-it': '🇮🇹',
    'fr-fr': '🇫🇷',
    'es-es': '🇪🇸',
    'ja-jp': '🇯🇵',
    'ko-kr': '🇰🇷',
    'bg-bg': '🇧🇬',
    'el-gr': '🇬🇷',
    'ru-ru': '🇷🇺',
    // Handle language-only codes for UI languages
    'hi': '🇮🇳', // Hindi -> India
    'de': '🇩🇪', // German -> Germany
    'en': '🇺🇸', // English -> US (default)
  };

  // Check explicit UI language mappings first
  if (uiLangMap.containsKey(normalized)) {
    return uiLangMap[normalized]!;
  }

  // For non-UI languages, use country code mapping
  final parts = locale.split('-');
  if (parts.length > 1) {
    final country = parts.last.toUpperCase();
    const countryMap = {
      'US': '🇺🇸',
      'GB': '🇬🇧',
      'AU': '🇦🇺',
      'DE': '🇩🇪',
      'FR': '🇫🇷',
      'ES': '🇪🇸',
      'IT': '🇮🇹',
      'IN': '🇮🇳',
      'BR': '🇧🇷',
      'PT': '🇵🇹',
      'CN': '🇨🇳',
      'TW': '🇹🇼',
      'JP': '🇯🇵',
      'KR': '🇰🇷',
      'TR': '🇹🇷',
      'EL': '🇬🇷',
      'RU': '🇷🇺',
      'BG': '🇧🇬',
      'NL': '🇳🇱',
      'DK': '🇩🇰',
      'IL': '🇮🇱',
      'IR': '🇮🇷',
    };
    return countryMap[country] ?? '';
  }

  return '';
}

