// return translations[lang]?[k] ?? translations['en']?[k] ?? k; // Fallback en

String t(String key) {
  final lang = AppLang.langCode; // Get language code from locale
  final currentLocaleMap = translations[lang];
  final englishMap = translations['en'];

  // 1) If currentLocaleMap contains key -> return it
  if (currentLocaleMap != null && currentLocaleMap.containsKey(key)) {
    return currentLocaleMap[key]!;
  }

  // 2) Else if EnglishMap contains key -> return EnglishMap[key]
  if (englishMap != null && englishMap.containsKey(key)) {
    return englishMap[key]!;
  }

  // 3) Else -> return key (last resort)
  return key;
}

// Localization helper with fallbacks - never shows raw keys
String lt(BuildContext context, String key,
    {required String fallbackEn, required String fallbackGeneric}) {
  final lang = AppLang.langCode;
  return translations[lang]?[key] ??
      translations['en']?[key] ??
      fallbackGeneric;
}

// ======================= BUILD RESET LOGIC =======================
// Extract build number from version string (e.g., "v0.8.2 (35)" -> 35)
int _extractBuildNumber(String versionString) {
  final match = RegExp(r'\((\d+)\)').firstMatch(versionString);
  if (match != null) {
    return int.tryParse(match.group(1) ?? '') ?? 0;
  }
  return 0;
}

// Check if this is a new build and reset preferences if needed
Future<void> _checkAndResetForNewBuild() async {
  try {
    final sp = await SharedPreferences.getInstance();
    final currentBuild = _extractBuildNumber(kVersionShort);
    final lastBuild = sp.getInt('app.last_build') ?? 0;

    // If build number changed, reset preferences
    if (currentBuild != lastBuild && currentBuild > 0) {
      // Her durumda önce eski içeriği oku — clipboard engeli için
      final oldContent = sp.getString('reading.content') ?? '';

      // İlk kurulumda (lastBuild == 0) tüm prefs'i temizle (premium key'leri koru)
      if (lastBuild == 0) {
        final premiumKeys =
            sp.getKeys().where((k) => k.startsWith('premium.')).toList();
        final premiumValues = <String, dynamic>{};
        for (final k in premiumKeys) {
          premiumValues[k] = sp.get(k);
        }
        await sp.clear();
        for (final entry in premiumValues.entries) {
          if (entry.value is int)
            await sp.setInt(entry.key, entry.value as int);
          else if (entry.value is bool)
            await sp.setBool(entry.key, entry.value as bool);
          else if (entry.value is String)
            await sp.setString(entry.key, entry.value as String);
        }
      } else {
        // Reset theme to light
        await sp.setString('ui.theme', 'light');
        await sp.setInt('ui.dim_level', 0);
        AppTheme.mode.value = CustomThemeMode.light;
        AppTheme.dimLevel.value = 0;

        // Clear reading text and related data
        await sp.setString('reading.content', '');
        await sp.setDouble('reading.scroll', 0);
        await sp.remove('reading.tts_offset');
        await sp.remove('reading.history');
        await sp.remove('reading.favorites');
        await sp.remove('notes_v1');
        await sp.remove('reading_notes_v1');
        await sp.remove('file.name');

        // Clear tour dismiss flag
        await sp.setBool('tour_reading_done_v1', false);
        await sp.setBool('force_show_reading_tour', true);
      }

      // Eski içeriği blocked olarak kaydet — temizlemeden sonra set et
      if (oldContent.isNotEmpty) {
        await sp.setString('blocked_clipboard_content', oldContent);
      }

      // Save current build number
      await sp.setInt('app.last_build', currentBuild);
    }
  } catch (e) {}
}

// ======================= IN-APP UPDATE CHECK =======================
Future<void> _checkForUpdate(BuildContext context) async {
  try {
    final info = await InAppUpdate.checkForUpdate();
    if (info.updateAvailability == UpdateAvailability.updateAvailable) {
      if (!context.mounted) return;
      showDialog(
        context: context,
        barrierDismissible: false,
        builder: (_) => AlertDialog(
          title: Text(t('update.title')),
          content: Text(t('update.message')),
          actions: [
            TextButton(
              onPressed: () => Navigator.pop(context),
              child: Text(t('update.later')),
            ),
            ElevatedButton(
              onPressed: () {
                Navigator.pop(context);
                InAppUpdate.performImmediateUpdate();
              },
              child: Text(t('update.now')),
            ),
          ],
        ),
      );
    }
  } catch (_) {
    // Sessizce geç — debug/emülatörde her zaman hata verir
  }
}

// ======================= APP ROOT =======================
class EasyReadingTestApp extends StatelessWidget {
  final String initialRoute;
  const EasyReadingTestApp({super.key, required this.initialRoute});
  @override
  Widget build(BuildContext context) {
    // Initialize global listener for AppLang.code changes (TEŞHİS)
    _initAppLangListener();
    AppLang.load();
    AppTheme.load();
    return ValueListenableBuilder<bool>(
      valueListenable: AppTheme.eInk,
      builder: (context, eInkOn, _) {
        return ValueListenableBuilder<CustomThemeMode>(
          valueListenable: AppTheme.mode,
          builder: (context, mode, _) {
            return ValueListenableBuilder<int>(
              valueListenable: AppTheme.dimLevel,
              builder: (context, dimLevel, _) {
                return _AppThemeAnimator(
                  isDark: AppTheme.themeMode == ThemeMode.dark,
                  dimLevel: dimLevel,
                  child: ValueListenableBuilder<double>(
                    valueListenable: AppTheme.animatedT,
                    builder: (context, t, _) {
                      final light = appTheme();
                      final dark = appDarkThemeWithDimLevel(dimLevel);
                      final ThemeData interpolated = eInkOn
                          ? AppTheme.getEInkThemeData()
                          : ThemeData.lerp(light, dark, t);
                      return MaterialApp(
                        scaffoldMessengerKey: appScaffoldMessengerKey,
                        title: 'EasyReading TEST 999',
                        debugShowCheckedModeBanner: false,
                        theme: interpolated,
                        darkTheme: interpolated,
                        themeMode: ThemeMode.light,
                        // E-ink'e geçişte MaterialApp'ın dahili tema animasyonunu kapat
                        // (yoksa ikon/buton boyutları 200-300ms boyunca "kayıyor" gibi görünür)
                        themeAnimationDuration: eInkOn
                            ? Duration.zero
                            : const Duration(milliseconds: 200),
                        initialRoute: initialRoute,
                        routes: {
                          '/welcome': (_) => const WelcomeScreen(),
                          '/language': (_) => const LanguageScreen(),
                          '/reading': (_) => const ReadingPage(),
                          '/about': (_) => const AboutPage(),
                          '/notes': (_) => const NotesPage(),
                        },
                        builder: (context, child) =>
                            ValueListenableBuilder<String>(
                          valueListenable: AppLang.code,
                          builder: (_, lang, __) {
                            // Sistem font büyüklüğü ayarını devre dışı bırak
                            // Her telefonda aynı görünüm için
                            final mq = MediaQuery.of(context);
                            return MediaQuery(
                              data:
                                  mq.copyWith(textScaler: TextScaler.noScaling),
                              child: ScrollConfiguration(
                                behavior: ScrollConfiguration.of(context)
                                    .copyWith(scrollbars: false),
                                child: Directionality(
                                    textDirection: TextDirection.ltr,
                                    child: child!),
                              ),
                            );
                          },
                        ),
                      );
                    },
                  ),
                );
              },
            );
          },
        );
      },
    );
  }
}

// ======================= THEME ANIMATOR ==========================
/// Drives AppTheme.animatedT between 0.0 (light) and 1.0 (dark)
/// whenever isDark or dimLevel changes. MaterialApp uses animatedT
/// via ThemeData.lerp so every widget gets smooth colour transitions
/// without the navigator being rebuilt (no accidental route resets).
class _AppThemeAnimator extends StatefulWidget {
  final bool isDark;
  final int dimLevel;
  final Widget child;
  const _AppThemeAnimator({
    required this.isDark,
    required this.dimLevel,
    required this.child,
  });
  @override
  State<_AppThemeAnimator> createState() => _AppThemeAnimatorState();
}

class _AppThemeAnimatorState extends State<_AppThemeAnimator>
    with SingleTickerProviderStateMixin {
  late AnimationController _ctrl;

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 600),
      value: widget.isDark ? (widget.dimLevel / 100.0) : 0.0,
    );
    AppTheme.animatedT.value = _ctrl.value;
    _ctrl.addListener(() {
      AppTheme.animatedT.value = _ctrl.value;
    });
  }

  @override
  void didUpdateWidget(_AppThemeAnimator old) {
    super.didUpdateWidget(old);
    final targetT = widget.isDark ? (widget.dimLevel / 100.0) : 0.0;
    final currentT = _ctrl.value;
    if ((targetT - currentT).abs() > 0.01) {
      _ctrl.animateTo(targetT, curve: Curves.easeInOut);
    }
  }

  @override
  void dispose() {
    _ctrl.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => widget.child;
}

