// Font size constant for Welcome landscape buttons (matches page 2 menu language selection)
const double _kOnboardingLandscapeMenuFont = 20.0;
// Font size constant for Welcome landscape About button (matches page 2 Other Languages button)
const double _kLandscapeOtherLanguagesFont = 15.0;

// TextStyle for Page2 LANDSCAPE "Other Languages" button (reused in Welcome LANDSCAPE About button)
TextStyle _otherLanguagesTextStyle(BuildContext context) {
  return const TextStyle(
    color: Colors.white,
    fontSize: _kLandscapeOtherLanguagesFont,
  );
}

// Shared button widget for Page2 LANDSCAPE "Other Languages" and Welcome LANDSCAPE About button
// This ensures both buttons have identical visual appearance
Widget _buildOnboardingOtherLanguagesButtonClone({
  required BuildContext context,
  required double width,
  required double height,
  required VoidCallback? onPressed,
  required String labelText,
  required List<DropdownMenuItem<String>>? dropdownItems,
  required Function(String?)? onDropdownChanged,
}) {
  return Align(
    alignment: Alignment.center,
    child: SizedBox(
      width: width,
      height: height,
      child: Container(
        alignment: Alignment.center,
        decoration: BoxDecoration(
          gradient: const LinearGradient(
            colors: [kGoldMain, kGoldDark],
            begin: Alignment.centerLeft,
            end: Alignment.centerRight,
          ),
          borderRadius: BorderRadius.circular(12),
        ),
        child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 4),
          child: dropdownItems != null && onDropdownChanged != null
              ? DropdownButton<String>(
                  alignment: AlignmentDirectional.center,
                  value: null,
                  hint: MediaQuery(
                    data: MediaQuery.of(context)
                        .copyWith(textScaler: TextScaler.noScaling),
                    child: Text(
                      labelText,
                      style: _otherLanguagesTextStyle(context),
                      textAlign: TextAlign.center,
                    ),
                  ),
                  isExpanded: true,
                  dropdownColor: kGoldMain,
                  borderRadius: BorderRadius.circular(12),
                  style: _otherLanguagesTextStyle(context),
                  underline: const SizedBox(),
                  itemHeight: kMinInteractiveDimension,
                  items: dropdownItems,
                  icon: const SizedBox.shrink(),
                  onChanged: onDropdownChanged,
                )
              : InkWell(
                  onTap: onPressed,
                  borderRadius: BorderRadius.circular(12),
                  child: Center(
                    child: FittedBox(
                      fit: BoxFit.scaleDown,
                      child: MediaQuery(
                        data: MediaQuery.of(context)
                            .copyWith(textScaler: TextScaler.noScaling),
                        child: Text(
                          labelText,
                          maxLines: 3,
                          softWrap: false,
                          overflow: TextOverflow.visible,
                          style: _otherLanguagesTextStyle(context).copyWith(
                            fontWeight: FontWeight.normal,
                          ),
                        ),
                      ),
                    ),
                  ),
                ),
        ),
      ),
    ),
  );
}

class _OnboardingLandscapeMetrics {
  final double primaryW, primaryH, primaryFont;
  final double secondaryW, secondaryH, secondaryFont;
  final double logoSize;
  const _OnboardingLandscapeMetrics({
    required this.primaryW,
    required this.primaryH,
    required this.primaryFont,
    required this.secondaryW,
    required this.secondaryH,
    required this.secondaryFont,
    required this.logoSize,
  });
}

_OnboardingLandscapeMetrics _calcOnboardingLandscapeMetrics(BoxConstraints c) {
  final h = c.maxHeight;
  final w = c.maxWidth;

  // Güvenli scale: çok kısa ekranlarda her şeyi biraz küçült
  final safeScale = (h / 360.0).clamp(0.75, 1.0);

  // Welcome logo %200 (2x) büyük
  final logoSize = ((h * 0.30) * 2.0 * safeScale).clamp(220.0, 420.0);

  // Page 2 Language button metrics (from _WideButton in ConstrainedBox maxWidth: 600 with Padding 24)
  // Width: constrained by ConstrainedBox(maxWidth: 600) - Padding(24*2) = 552 max
  // In Language page, LayoutBuilder constraints come from ConstrainedBox(maxWidth: 600)
  // After Padding(24) inside LayoutBuilder, available width = w - 48
  // To match exactly, calculate: min(w - 48, 552) where w is constraints.maxWidth
  // This works for both pages: Language page (w=600) -> 552, Welcome page (w=screen) -> min(screen-48, 552)
  final availableWidth = (w - 48).clamp(
      200.0, 552.0); // Account for Padding(24*2), clamp to match page 2 max
  final primaryW =
      availableWidth; // Language button uses available width (matches page 2 exactly)
  final primaryH =
      48.0; // Default ElevatedButton minimum height (matches Material default)
  final primaryFont =
      16.0; // From ElevatedButtonTheme textStyle fontSize (matches theme)

  // Page 2 Other Languages button metrics (fixed values from page 2)
  final secondaryW = 200.0; // Fixed width from page 2 (SizedBox width: 200)
  final secondaryH = 32.0; // Fixed height from page 2 (SizedBox height: 32)
  final secondaryFont =
      13.0; // Fixed fontSize from page 2 (TextStyle fontSize: 13)

  return _OnboardingLandscapeMetrics(
    primaryW: primaryW,
    primaryH: primaryH,
    primaryFont: primaryFont,
    secondaryW: secondaryW,
    secondaryH: secondaryH,
    secondaryFont: secondaryFont,
    logoSize: logoSize,
  );
}

