// PREMIUM SERVICE
class PremiumService {
  PremiumService._();
  static final instance = PremiumService._();

  // ── Product ID'ler ──────────────────────────────────────────
  static const String _monthlyId = 'easyreading_monthly';
  static const String _yearlyId = 'easyreading_yearly';
  static const Set<String> _productIds = {_monthlyId, _yearlyId};

  // ── SharedPreferences keys ──────────────────────────────────
  static const _keyActive = 'premium.active';
  static const _keyTrialEnd = 'premium.trial_end';
  static const _keyFirstOpen = 'premium.first_open_shown';
  static const _keyVoiceSecs = 'premium.voice_secs_today';
  static const _keyVoiceDate = 'premium.voice_date';
  static const _keyScrollSecs = 'premium.scroll_secs_today';
  static const _keyScrollDate = 'premium.scroll_date';
  static const _keyOcrUses = 'premium.ocr_uses';
  static const _keyBothUses = 'premium.both_uses';
  static const _keyNightUses = 'premium.night_uses';
  static const _keyLangUses = 'premium.lang_uses';
  static const _keyPasteUses = 'premium.paste_uses';
  static const _keyTtsUses = 'premium.tts_uses';

  static const int freeDailyVoiceSecs = 45;
  static const int freeDailyScrollSecs = 60;
  static const int freeOcrUses = 1;
  static const int freeBothUses = 1;
  static const int freeNightUses = 1;
  static const int freeLangUses = 2;
  static const int freePasteUses = 1;
  static const int freeTtsUses = 1;

  // Dinamik fiyatlar — RevenueCat'ten yüklenir, fallback hardcode
  String monthlyPrice = r'$7.99';
  String yearlyPrice = r'$59.99';
  String yearlyPerMonth = r'$5.00';
  String savePercent = '37%';

  final ValueNotifier<bool> isPremium = ValueNotifier(false);

  bool get hasFullAccess => isPremium.value || isTrialActive;
  bool trialStarted = false;
  DateTime? trialStartDate;

  bool get isTrialActive {
    if (!trialStarted) return false;
    if (trialStartDate == null) return false;
    return DateTime.now().difference(trialStartDate!).inDays < 7;
  }

  bool get trialExpired => trialStarted && !isTrialActive && !isPremium.value;

  int get trialDaysLeft {
    if (trialStartDate == null) return 7;
    final diff = 7 - DateTime.now().difference(trialStartDate!).inDays;
    return diff < 0 ? 0 : diff;
  }

  static final String _rcApiKey = kIsWeb
      ? ''
      : (Platform.isIOS
          ? 'appl_hpzNsNYaDhHYJWcMmavRGpmeWug' // RevenueCat iOS API key
          : 'goog_KscqZrzNUbyFyDYBRIkmLePZSRY'); // RevenueCat Android API key

  // ── Init ────────────────────────────────────────────────────
  Future<void> load() async {
    // RevenueCat'i başlat
    await Purchases.setLogLevel(LogLevel.debug);
    await Purchases.configure(PurchasesConfiguration(_rcApiKey));

    // Mevcut abonelik durumunu kontrol et
    await _refreshPremiumStatus();
    // Trial durumunu yükle
    final prefs = await SharedPreferences.getInstance();
    trialStarted = prefs.getBool('trial_started') ?? false;
    final trialStr = prefs.getString('trial_start');
    if (trialStr != null) trialStartDate = DateTime.tryParse(trialStr);

    // Fiyatları RevenueCat'ten çek
    await _loadPrices();
  }

  Future<void> _refreshPremiumStatus() async {
    try {
      final isConfigured = await Purchases.isConfigured;
      if (!isConfigured) {
        isPremium.value = false;
        return;
      }
      final customerInfo = await Purchases.getCustomerInfo();
      isPremium.value =
          customerInfo.entitlements.active.containsKey('Beytans Apps Pro');
    } catch (e) {
      isPremium.value = false;
    }
  }

  String _currencySymbol(String code) {
    const map = {
      'TRY': '₺',
      'USD': '\$',
      'EUR': '€',
      'GBP': '£',
      'JPY': '¥',
      'KRW': '₩',
      'INR': '₹',
      'RUB': '₽',
      'BRL': 'R\$',
      'CAD': 'CA\$',
      'AUD': 'A\$',
      'CHF': 'CHF ',
      'SEK': 'kr',
      'NOK': 'kr',
      'DKK': 'kr',
      'PLN': 'zł',
      'CZK': 'Kč',
      'HUF': 'Ft',
      'MXN': 'MX\$',
      'SGD': 'S\$',
    };
    return map[code] ?? '\$';
  }

  Future<void> _loadPrices() async {
    try {
      final offerings = await Purchases.getOfferings();
      final offering = offerings.getOffering('default') ?? offerings.current;
      if (offering == null) return;

      final monthly = offering.monthly;
      final annual = offering.annual;

      if (monthly != null) {
        monthlyPrice = monthly.storeProduct.priceString;
      }
      if (annual != null) {
        yearlyPrice = annual.storeProduct.priceString;
        // Aylığa böl
        final rawPrice = annual.storeProduct.price;
        final perMonth = rawPrice / 12;
        final symbol = _currencySymbol(annual.storeProduct.currencyCode);
        yearlyPerMonth = '$symbol${perMonth.toStringAsFixed(2)}';
        if (monthly != null) {
          final monthlyRaw = monthly.storeProduct.price;
          final pct =
              ((monthlyRaw * 12 - rawPrice) / (monthlyRaw * 12) * 100).round();
          savePercent = '$pct%';
        }
      }
    } catch (_) {
      // Hata olursa hardcode fallback kalır
    }
  }

  void dispose() {}

  // ── Satın alma ──────────────────────────────────────────────
  Future<bool> buyMonthly() async {
    return _buy(_monthlyId);
  }

  Future<bool> buyYearly() async {
    return _buy(_yearlyId);
  }

  Future<bool> _buy(String productId) async {
    try {
      final offerings = await Purchases.getOfferings();
      final offering = offerings.getOffering('default') ?? offerings.current;
      if (offering == null) return false;

      Package? package;
      if (productId == _monthlyId) {
        package = offering.monthly;
      } else if (productId == _yearlyId) {
        package = offering.annual;
      }

      // Paket bulunamadıysa available packages içinde ürün ID'ye göre ara
      if (package == null) {
        package = offering.availablePackages.firstWhere(
          (p) => p.storeProduct.identifier.contains(
            productId == _monthlyId ? 'monthly' : 'yearly',
          ),
          orElse: () => offering.availablePackages.first,
        );
      }
      if (package == null) return false;
      // Intro offer varsa logla
      final purchaseResult = await Purchases.purchasePackage(package);
      final customerInfo = purchaseResult.customerInfo;
      isPremium.value =
          customerInfo.entitlements.active.containsKey('Beytans Apps Pro');
      return isPremium.value;
    } catch (e) {
      return false;
    }
  }

  // ── Restore ─────────────────────────────────────────────────
  Future<bool> restorePurchase() async {
    try {
      final customerInfo = await Purchases.restorePurchases();
      isPremium.value =
          customerInfo.entitlements.active.containsKey('Beytans Apps Pro');
      return isPremium.value;
    } catch (e) {
      return false;
    }
  }

  Future<void> startTrial() async {
    trialStarted = true;
    trialStartDate = DateTime.now();
    final prefs = await SharedPreferences.getInstance();
    await prefs.setBool('trial_started', true);
    await prefs.setString('trial_start', trialStartDate!.toIso8601String());
  }

  Future<void> activate() async {
    await _refreshPremiumStatus();
  }

  Future<void> deactivate() async {
    isPremium.value = false;
  }

  // ── First open ──────────────────────────────────────────────
  Future<bool> isFirstOpenShown() async {
    final sp = await SharedPreferences.getInstance();
    return sp.getBool(_keyFirstOpen) ?? false;
  }

  Future<void> markFirstOpenShown() async {
    final sp = await SharedPreferences.getInstance();
    await sp.setBool(_keyFirstOpen, true);
  }

  // ── Kullanım limitleri (değişmedi) ──────────────────────────
  Future<int> getTodayVoiceSecs() async {
    final sp = await SharedPreferences.getInstance();
    final today = DateTime.now().toIso8601String().substring(0, 10);
    final savedDate = sp.getString(_keyVoiceDate) ?? '';
    if (savedDate != today) {
      await sp.setString(_keyVoiceDate, today);
      await sp.setInt(_keyVoiceSecs, 0);
      return 0;
    }
    return sp.getInt(_keyVoiceSecs) ?? 0;
  }

  Future<void> addVoiceSecs(int secs) async {
    final sp = await SharedPreferences.getInstance();
    final today = DateTime.now().toIso8601String().substring(0, 10);
    await sp.setString(_keyVoiceDate, today);
    final cur = sp.getInt(_keyVoiceSecs) ?? 0;
    await sp.setInt(_keyVoiceSecs, cur + secs);
  }

  Future<void> setVoiceSecs(int secs) async {
    final sp = await SharedPreferences.getInstance();
    final today = DateTime.now().toIso8601String().substring(0, 10);
    await sp.setString(_keyVoiceDate, today);
    await sp.setInt(_keyVoiceSecs, secs);
  }

  Future<int> getTodayScrollSecs() async {
    final sp = await SharedPreferences.getInstance();
    final today = DateTime.now().toIso8601String().substring(0, 10);
    final savedDate = sp.getString(_keyScrollDate) ?? '';
    if (savedDate != today) {
      await sp.setString(_keyScrollDate, today);
      await sp.setInt(_keyScrollSecs, 0);
      return 0;
    }
    return sp.getInt(_keyScrollSecs) ?? 0;
  }

  Future<void> setScrollSecs(int secs) async {
    final sp = await SharedPreferences.getInstance();
    final today = DateTime.now().toIso8601String().substring(0, 10);
    await sp.setString(_keyScrollDate, today);
    await sp.setInt(_keyScrollSecs, secs);
  }

  Future<int> getOcrUses() async {
    final sp = await SharedPreferences.getInstance();
    return sp.getInt(_keyOcrUses) ?? 0;
  }

  Future<bool> canUseOcrFree() async {
    final uses = await getOcrUses();
    return uses < freeOcrUses;
  }

  Future<void> incrementOcrUses() async {
    final sp = await SharedPreferences.getInstance();
    final cur = sp.getInt(_keyOcrUses) ?? 0;
    await sp.setInt(_keyOcrUses, cur + 1);
  }

  Future<int> getBothUses() async {
    final sp = await SharedPreferences.getInstance();
    return sp.getInt(_keyBothUses) ?? 0;
  }

  Future<bool> canUseBothFree() async {
    final uses = await getBothUses();
    return uses < freeBothUses;
  }

  Future<void> incrementBothUses() async {
    final sp = await SharedPreferences.getInstance();
    final cur = sp.getInt(_keyBothUses) ?? 0;
    await sp.setInt(_keyBothUses, cur + 1);
  }

  Future<bool> canUseNightFree() async {
    final sp = await SharedPreferences.getInstance();
    return (sp.getInt(_keyNightUses) ?? 0) < freeNightUses;
  }

  Future<void> incrementNightUses() async {
    final sp = await SharedPreferences.getInstance();
    await sp.setInt(_keyNightUses, (sp.getInt(_keyNightUses) ?? 0) + 1);
  }

  Future<bool> canUseLangFree() async {
    final sp = await SharedPreferences.getInstance();
    return (sp.getInt(_keyLangUses) ?? 0) < freeLangUses;
  }

  Future<void> incrementLangUses() async {
    final sp = await SharedPreferences.getInstance();
    await sp.setInt(_keyLangUses, (sp.getInt(_keyLangUses) ?? 0) + 1);
  }

  Future<bool> canUsePasteFree() async {
    final sp = await SharedPreferences.getInstance();
    return (sp.getInt(_keyPasteUses) ?? 0) < freePasteUses;
  }

  Future<void> incrementPasteUses() async {
    final sp = await SharedPreferences.getInstance();
    await sp.setInt(_keyPasteUses, (sp.getInt(_keyPasteUses) ?? 0) + 1);
  }

  Future<bool> canUseTtsFree() async {
    final sp = await SharedPreferences.getInstance();
    return (sp.getInt(_keyTtsUses) ?? 0) < freeTtsUses;
  }

  Future<void> incrementTtsUses() async {
    final sp = await SharedPreferences.getInstance();
    await sp.setInt(_keyTtsUses, (sp.getInt(_keyTtsUses) ?? 0) + 1);
  }
}

