// PREMIUM POPUP — küçük modal (BOTH, OCR, 3dk tetikleyici)
// ══════════════════════════════════════════════════════════════
Future<bool?> showPremiumPopup(
  BuildContext context, {
  required String title,
  required String body,
  required String cta,
}) {
  return showModalBottomSheet<bool>(
    context: context,
    backgroundColor: Colors.transparent,
    isScrollControlled: true,
    builder: (_) => _PremiumPopup(title: title, body: body, cta: cta),
  );
}

class _PremiumPopup extends StatelessWidget {
  final String title, body, cta;
  const _PremiumPopup(
      {required this.title, required this.body, required this.cta});

  static const _bg = Color(0xFFFDF8F0);
  static const _gold = Color(0xFFC9A96B);
  static const _brown = Color(0xFF2E2519);
  static const _mid = Color(0xFF6F5A3B);
  static const _cream = Color(0xFFF5EDD8);

  @override
  Widget build(BuildContext context) {
    return Container(
      decoration: const BoxDecoration(
        color: _bg,
        borderRadius: BorderRadius.vertical(top: Radius.circular(24)),
      ),
      padding: EdgeInsets.fromLTRB(
          24, 12, 24, MediaQuery.of(context).padding.bottom + 32),
      child: Column(mainAxisSize: MainAxisSize.min, children: [
        // Handle bar
        Container(
          width: 40,
          height: 4,
          decoration: BoxDecoration(
              color: const Color(0xFFD4C4A8),
              borderRadius: BorderRadius.circular(2)),
        ),
        const SizedBox(height: 20),
        Container(
          padding: const EdgeInsets.all(14),
          decoration: BoxDecoration(color: _cream, shape: BoxShape.circle),
          child: const Icon(Icons.workspace_premium_rounded,
              color: _gold, size: 32),
        ),
        const SizedBox(height: 16),
        Text(
          title,
          textAlign: TextAlign.center,
          style: const TextStyle(
              fontSize: 20, fontWeight: FontWeight.w700, color: _brown),
        ),
        const SizedBox(height: 8),
        Text(
          body,
          textAlign: TextAlign.center,
          style: const TextStyle(fontSize: 14, color: _mid, height: 1.5),
        ),
        const SizedBox(height: 24),
        SizedBox(
          width: double.infinity,
          child: ElevatedButton(
            onPressed: () async {
              Navigator.of(context).pop();
              final unlocked = await Navigator.of(context).push<bool>(
                MaterialPageRoute(
                    builder: (_) => const PaywallScreen(),
                    fullscreenDialog: true),
              );
              if (context.mounted) Navigator.of(context).pop(unlocked == true);
            },
            style: ElevatedButton.styleFrom(
              backgroundColor: _gold,
              foregroundColor: Colors.white,
              padding: const EdgeInsets.symmetric(vertical: 15),
              shape: RoundedRectangleBorder(
                  borderRadius: BorderRadius.circular(14)),
              elevation: 0,
            ),
            child: Text(cta,
                style:
                    const TextStyle(fontSize: 16, fontWeight: FontWeight.w700)),
          ),
        ),
        const SizedBox(height: 12),
        TextButton(
          onPressed: () => Navigator.of(context).pop(false),
          child: Text(t('popup.maybe_later'),
              style: const TextStyle(fontSize: 14, color: _mid)),
        ),
      ]),
    );
  }
}

