// ══════════════════════════════════════════════════════════════
// PAYWALL NAVIGATOR — doğrudan PaywallScreen'e gider
// ══════════════════════════════════════════════════════════════
Future<bool> navigateToPaywall(BuildContext context) async {
  await FirebaseAnalytics.instance.logEvent(name: 'paywall_shown');
  final ps = PremiumService.instance;
  if (!ps.trialStarted && !ps.trialExpired) {
    final result = await Navigator.of(context).push<bool>(
      MaterialPageRoute(
        builder: (_) => TrialOnboardingScreen(
            onDone: () => Navigator.of(context).pop(true)),
        fullscreenDialog: true,
      ),
    );
    return result == true;
  }
  final result = await Navigator.of(context).push<bool>(
    MaterialPageRoute(
      builder: (_) => const PaywallScreen(),
      fullscreenDialog: true,
    ),
  );
  return result == true;
}

