// PAYWALL SCREEN — tam ekran abonelik
// ══════════════════════════════════════════════════════════════
class PaywallScreen extends StatefulWidget {
  const PaywallScreen({super.key});
  @override
  State<PaywallScreen> createState() => _PaywallScreenState();
}

class _PaywallScreenState extends State<PaywallScreen>
    with SingleTickerProviderStateMixin {
  bool _isYearly = true;
  bool _isLoading = false;
  bool _isRestoring = false;
  late AnimationController _ctrl;
  late Animation<double> _fade;

  static const _bg = Color(0xFFFDF8F0);
  static const _card = Color(0xFFFFFFFF);
  static const _gold = Color(0xFFC9A96B);
  static const _brown = Color(0xFF2E2519);
  static const _mid = Color(0xFF6F5A3B);
  static const _light = Color(0xFFAA9070);
  static const _cream = Color(0xFFF5EDD8);

  @override
  void initState() {
    super.initState();
    _ctrl = AnimationController(
        vsync: this, duration: const Duration(milliseconds: 600));
    _fade = CurvedAnimation(parent: _ctrl, curve: Curves.easeOut);
    _ctrl.forward();
    // Fiyatları yükle ve UI'ı güncelle
    PremiumService.instance._loadPrices().then((_) {
      if (mounted) setState(() {});
    });
  }

  @override
  void dispose() {
    _ctrl.dispose();
    super.dispose();
  }

  Future<void> _onPurchase() async {
    setState(() => _isLoading = true);
    try {
      final ok = _isYearly
          ? await PremiumService.instance.buyYearly()
          : await PremiumService.instance.buyMonthly();
      if (!ok && mounted) {
        ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
            'Purchase could not be started.',
            behavior: SnackBarBehavior.floating));
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
            'Error: $e',
            behavior: SnackBarBehavior.floating));
      }
    } finally {
      if (mounted) setState(() => _isLoading = false);
    }
  }

  Future<void> _onRestore() async {
    setState(() => _isRestoring = true);
    final ok = await PremiumService.instance.restorePurchase();
    if (!mounted) return;
    setState(() => _isRestoring = false);
    if (ok) {
      Navigator.of(context).pop(true);
      return;
    }
    ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
        t('paywall.no_sub'),
        behavior: SnackBarBehavior.floating));
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      backgroundColor: _bg,
      body: FadeTransition(
        opacity: _fade,
        child: SafeArea(
            child: Column(children: [
          // Top bar
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 12),
            child: Row(children: [
              const Spacer(),
              GestureDetector(
                onTap: () => Navigator.of(context).pop(false),
                child: Container(
                  padding: const EdgeInsets.all(7),
                  decoration:
                      BoxDecoration(color: _cream, shape: BoxShape.circle),
                  child: const Icon(Icons.close, color: _mid, size: 18),
                ),
              ),
            ]),
          ),
          Expanded(
              child: SingleChildScrollView(
            padding: const EdgeInsets.symmetric(horizontal: 22),
            child: Column(children: [
              Image.asset(
                'assets/easyreading_app_icon.png',
                width: 96,
                height: 96,
                errorBuilder: (_, __, ___) => Container(
                  width: 96,
                  height: 96,
                  decoration: BoxDecoration(
                      color: _cream, borderRadius: BorderRadius.circular(20)),
                  child: const Icon(Icons.menu_book_rounded,
                      size: 52, color: _gold),
                ),
              ),
              const SizedBox(height: 14),
              Text(
                t('paywall.title'),
                textAlign: TextAlign.center,
                style: const TextStyle(
                    fontSize: 26,
                    fontWeight: FontWeight.w700,
                    color: _brown,
                    letterSpacing: -0.3),
              ),
              const SizedBox(height: 6),
              Text(
                t('paywall.subtitle'),
                textAlign: TextAlign.center,
                style: const TextStyle(fontSize: 14, color: _mid),
              ),
              const SizedBox(height: 22),
              // Features
              Container(
                decoration: BoxDecoration(
                  color: _card,
                  borderRadius: BorderRadius.circular(18),
                  border: Border.all(color: const Color(0xFFEDE4D0)),
                  boxShadow: [
                    BoxShadow(
                        color: _gold.withOpacity(0.07),
                        blurRadius: 16,
                        offset: const Offset(0, 4))
                  ],
                ),
                padding:
                    const EdgeInsets.symmetric(horizontal: 18, vertical: 14),
                child: Column(children: [
                  _featureRow(
                      _cream,
                      _gold,
                      _brown,
                      _mid,
                      Icons.all_inclusive_rounded,
                      t('paywall.feat1.title'),
                      t('paywall.feat1.sub')),
                  _featureRow(
                      _cream,
                      _gold,
                      _brown,
                      _mid,
                      Icons.auto_awesome_rounded,
                      t('paywall.feat2.title'),
                      t('paywall.feat2.sub')),
                  _featureRow(
                      _cream,
                      _gold,
                      _brown,
                      _mid,
                      Icons.document_scanner_rounded,
                      t('paywall.feat3.title'),
                      t('paywall.feat3.sub')),
                ]),
              ),
              const SizedBox(height: 16),
              // Review
              Container(
                decoration: BoxDecoration(
                  color: _cream,
                  borderRadius: BorderRadius.circular(16),
                  border: Border.all(color: const Color(0xFFEDE4D0)),
                ),
                padding: const EdgeInsets.all(16),
                child: Column(
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      Row(children: [
                        ...List.generate(
                            5,
                            (_) => const Icon(Icons.star_rounded,
                                color: _gold, size: 16)),
                        const SizedBox(width: 8),
                        const Text('5.0',
                            style: TextStyle(
                                fontWeight: FontWeight.w700,
                                fontSize: 13,
                                color: _brown)),
                      ]),
                      const SizedBox(height: 8),
                      Text(
                        t('paywall.review'),
                        style: const TextStyle(
                            fontSize: 13,
                            color: _mid,
                            fontStyle: FontStyle.italic,
                            height: 1.5),
                      ),
                      const SizedBox(height: 6),
                      Text(t('paywall.reviewer'),
                          style: TextStyle(
                              fontSize: 12,
                              color: _light,
                              fontWeight: FontWeight.w500)),
                    ]),
              ),
              const SizedBox(height: 20),
              // Plan cards
              _planTile(
                isSelected: _isYearly,
                onTap: () => setState(() => _isYearly = true),
                title: t('paywall.yearly'),
                badge: t('paywall.best_value'),
                savingLabel: 'Save ${PremiumService.instance.savePercent}',
                subtitle:
                    '${PremiumService.instance.yearlyPerMonth}${t('paywall.yearly_sub').replaceAll('{price}', PremiumService.instance.yearlyPrice)}',
                price: PremiumService.instance.yearlyPrice,
              ),
              const SizedBox(height: 10),
              _planTile(
                isSelected: !_isYearly,
                onTap: () => setState(() => _isYearly = false),
                title: t('paywall.monthly'),
                subtitle: t('paywall.monthly_sub'),
                price: PremiumService.instance.monthlyPrice,
              ),
              const SizedBox(height: 20),
            ]),
          )),
          // Bottom CTA
          Container(
            decoration: const BoxDecoration(
              color: _bg,
              border: Border(top: BorderSide(color: Color(0xFFEDE4D0))),
            ),
            padding: const EdgeInsets.fromLTRB(22, 14, 22, 20),
            child: Column(children: [
              SizedBox(
                width: double.infinity,
                child: ElevatedButton(
                  onPressed: _isLoading ? null : _onPurchase,
                  style: ElevatedButton.styleFrom(
                    backgroundColor: _gold,
                    foregroundColor: Colors.white,
                    disabledBackgroundColor: _gold.withOpacity(0.6),
                    padding: const EdgeInsets.symmetric(vertical: 16),
                    shape: RoundedRectangleBorder(
                        borderRadius: BorderRadius.circular(14)),
                    elevation: 0,
                  ),
                  child: _isLoading
                      ? const SizedBox(
                          width: 22,
                          height: 22,
                          child: CircularProgressIndicator(
                              color: Colors.white, strokeWidth: 2.5))
                      : Text(
                          _isYearly
                              ? t('paywall.cta_yearly').replaceAll('{price}',
                                  PremiumService.instance.yearlyPrice)
                              : t('paywall.cta_monthly').replaceAll('{price}',
                                  PremiumService.instance.monthlyPrice),
                          style: const TextStyle(
                              fontSize: 16, fontWeight: FontWeight.w700),
                        ),
                ),
              ),
              const SizedBox(height: 10),
              Row(mainAxisAlignment: MainAxisAlignment.center, children: [
                const Icon(Icons.lock_outline_rounded, size: 13, color: _light),
                const SizedBox(width: 4),
                Text(t('paywall.cancel'),
                    style: const TextStyle(fontSize: 12, color: _light)),
                const SizedBox(width: 14),
                GestureDetector(
                  onTap: _isRestoring ? null : _onRestore,
