class LanguageScreen extends StatefulWidget {
  const LanguageScreen({super.key});

  @override
  State<LanguageScreen> createState() => _LanguageScreenState();
}

class _LanguageScreenState extends State<LanguageScreen>
    with SingleTickerProviderStateMixin {
  final GlobalKey _otherLangBtnKey = GlobalKey();
  late AnimationController _logoAnimCtrl;
  late Animation<double> _logoFade;
  late Animation<double> _logoScale;

  @override
  void initState() {
    super.initState();
    _logoAnimCtrl = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 900),
    );
    _logoFade = CurvedAnimation(
      parent: _logoAnimCtrl,
      curve: Curves.easeIn,
    );
    _logoScale = Tween<double>(begin: 0.75, end: 1.0).animate(
      CurvedAnimation(parent: _logoAnimCtrl, curve: Curves.easeOutBack),
    );
    _logoAnimCtrl.forward();
  }

  @override
  void dispose() {
    _logoAnimCtrl.dispose();
    super.dispose();
  }

  void _goReading(BuildContext context) async {
    await PremiumService.instance.markFirstOpenShown();
    Navigator.pushNamedAndRemoveUntil(context, '/reading', (_) => false);
  }

  @override
  Widget build(BuildContext context) {
    final isLandscape =
        MediaQuery.of(context).orientation == Orientation.landscape;
    if (isLandscape) {
      return Column(
        children: [
          Expanded(
            child: PopScope(
              canPop: false,
              onPopInvokedWithResult: (didPop, result) {
                if (!didPop)
                  Navigator.pushReplacementNamed(context, '/welcome');
              },
              child: _buildLanguageLandscape(context),
            ),
          ),
        ],
      );
    }
    // Portrait mode: use Scaffold with SafeArea and crash guard
    return Scaffold(
      appBar: AppBar(
        title: const Text(''),
        leading: IconButton(
          icon: const Icon(Icons.arrow_back),
          onPressed: () => Navigator.pushReplacementNamed(context, '/welcome'),
        ),
      ),
      body: SafeArea(
        child: _buildPage2Body(context),
      ),
    );
  }

