class _LandscapeLangPanel extends StatefulWidget {
  final Future<void> Function(String code) onLanguageSelected;
  const _LandscapeLangPanel({required this.onLanguageSelected});
  @override
  State<_LandscapeLangPanel> createState() => _LandscapeLangPanelState();
}

class _LandscapeLangPanelState extends State<_LandscapeLangPanel> {
  bool _showOthers = false;

  @override
  Widget build(BuildContext context) {
    return SingleChildScrollView(
      physics: _showOthers
          ? const ClampingScrollPhysics()
          : const NeverScrollableScrollPhysics(),
      child: _CircleLangSelector(
        onLanguageSelected: widget.onLanguageSelected,
        onShowOthersChanged: (val) => setState(() => _showOthers = val),
      ),
    );
  }
}

// ── Daire dil seçici widget ────────────────────────────────────────────────
class _CircleLangSelector extends StatefulWidget {
  final Future<void> Function(String code) onLanguageSelected;
  final ValueChanged<bool>? onShowOthersChanged;
  const _CircleLangSelector(
      {required this.onLanguageSelected, this.onShowOthersChanged});
  @override
  State<_CircleLangSelector> createState() => _CircleLangSelectorState();
}

class _CircleLangSelectorState extends State<_CircleLangSelector> {
  bool _showOthers = false;
  final Set<String> _flipped = {};

  // Emoji → country code mapping
  static const Map<String, String> _emojiToCode = {
    '🇺🇸': 'US',
    '🇹🇷': 'TR',
    '🇮🇹': 'IT',
    '🇩🇪': 'DE',
    '🇫🇷': 'FR',
    '🇪🇸': 'ES',
    '🇯🇵': 'JP',
    '🇷🇺': 'RU',
    '🇰🇷': 'KR',
    '🇬🇷': 'GR',
    '🇮🇳': 'IN',
    '🇧🇷': 'BR',
    '🇧🇬': 'BG',
    '🇵🇱': 'PL',
    '🇳🇱': 'NL',
    '🇵🇹': 'PT',
  };

  Widget _circle({
    required String label,
    String? flag,
    required double size,
    required VoidCallback onTap,
  }) {
    final code = flag != null ? (_emojiToCode[flag] ?? '') : '';
    final isFlipped = _flipped.contains(code.isNotEmpty ? code : label);
    final key = code.isNotEmpty ? code : label;

    return GestureDetector(
      onTap: () {
        if (label == 'Other\nLanguages') {
          // Flip yok — direkt aç/kapat
          onTap();
        } else if (flag != null) {
          // Bayraklar için flip efekti
          setState(() {
            _flipped.add(key);
          });
          Future.delayed(const Duration(milliseconds: 500), () {
            if (mounted) {
              setState(() => _flipped.remove(key));
              onTap();
            }
          });
        } else {
          onTap();
        }
      },
      child: TweenAnimationBuilder<double>(
        tween: Tween(begin: 0, end: isFlipped ? 1 : 0),
        duration: const Duration(milliseconds: 400),
        curve: Curves.easeInOut,
        builder: (context, value, child) {
          final angle = value * 3.14159;
          final showBack = value > 0.5;
          return Transform(
            alignment: Alignment.center,
            transform: Matrix4.identity()
              ..setEntry(3, 2, 0.001)
              ..rotateY(angle),
            child: Container(
              width: size,
              height: size,
              decoration: const BoxDecoration(
                shape: BoxShape.circle,
                gradient: LinearGradient(
                  colors: [kGoldMain, kGoldDark],
                  begin: Alignment.topLeft,
                  end: Alignment.bottomRight,
                ),
              ),
              child: showBack
                  ? Center(
                      child: Transform(
                        alignment: Alignment.center,
                        transform: Matrix4.identity()..rotateY(3.14159),
                        child: Text(
                          label == 'Other\nLanguages' ? '...' : code,
                          textAlign: TextAlign.center,
                          textScaler: TextScaler.noScaling,
                          style: GoogleFonts.lora(
                            fontSize: size * 0.22,
                            color: Colors.white,
                            fontWeight: FontWeight.normal,
                          ),
                        ),
                      ),
                    )
                  : Column(
                      mainAxisAlignment: MainAxisAlignment.center,
                      children: [
                        if (flag != null) ...[
                          SizedBox(
                            width: size * 0.55,
                            height: size * 0.55,
                            child: _buildFlag(flag, size),
                          ),
                          if (label.isNotEmpty) const SizedBox(height: 4),
                        ],
                        if (label.isNotEmpty)
                          Text(
                            label,
                            textAlign: TextAlign.center,
                            textScaler: TextScaler.noScaling,
                            style: GoogleFonts.lora(
                              fontSize: size >= 110 ? 16 : 14,
                              color: Colors.white,
                              fontWeight: FontWeight.normal,
                            ),
                          ),
                      ],
                    ),
            ),
          );
        },
      ),
    );
  }

  Widget _buildFlag(String flagEmoji, double size) {
    final code = _emojiToCode[flagEmoji];
    if (code != null) {
      return ClipOval(
        child: SizedBox(
          width: size * 0.55,
          height: size * 0.55,
          child: CountryFlag.fromCountryCode(code),
        ),
      );
    }
    return FittedBox(
      fit: BoxFit.contain,
      child: Text(flagEmoji),
    );
  }

  @override
  Widget build(BuildContext context) {
    final mainLangs = [
      kUiLanguages.firstWhere((l) => l.code == 'en'),
      kUiLanguages.firstWhere((l) => l.code == 'tr'),
      kUiLanguages.firstWhere((l) => l.code == 'it'),
    ];
    final otherLangs = kUiLanguages
        .where((l) => l.code != 'en' && l.code != 'tr' && l.code != 'it')
        .toList();

    return LayoutBuilder(
      builder: (context, constraints) {
        // Ekran yüksekliğine göre daire boyutunu hesapla
        final isLandscape =
            MediaQuery.of(context).orientation == Orientation.landscape;
        final mainSize = isLandscape ? 75.0 : 100.0;
        final otherSize = isLandscape ? 60.0 : 55.0;
        final gap = isLandscape ? 8.0 : 12.0;

        if (isLandscape) {
          return Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.center,
            children: [
              const SizedBox(height: 8),
              ShaderMask(
                shaderCallback: (bounds) => const LinearGradient(
                  colors: [kGoldMain, kGoldDark],
                  begin: Alignment.centerLeft,
                  end: Alignment.centerRight,
                ).createShader(bounds),
                child: const Text(
                  "Choose your app language below",
                  textAlign: TextAlign.center,
                  textScaler: TextScaler.noScaling,
                  style: TextStyle(
                    color: Colors.white,
                    fontSize: 22,
                    fontWeight: FontWeight.normal,
                  ),
                ),
              ),
              const SizedBox(height: 24),
              // 4 daire — sabit, hiç hareket etmez
              Row(
                mainAxisAlignment: MainAxisAlignment.center,
                children: [
                  _circle(
                      label: '',
                      flag: mainLangs[0].flag,
                      size: 100,
                      onTap: () =>
                          widget.onLanguageSelected(mainLangs[0].code)),
                  const SizedBox(width: 12),
                  _circle(
                      label: '',
                      flag: mainLangs[1].flag,
                      size: 100,
                      onTap: () =>
                          widget.onLanguageSelected(mainLangs[1].code)),
                  const SizedBox(width: 12),
                  _circle(
                      label: '',
                      flag: mainLangs[2].flag,
                      size: 100,
                      onTap: () =>
                          widget.onLanguageSelected(mainLangs[2].code)),
                  const SizedBox(width: 12),
                  _circle(
                    label: 'Other\nLanguages',
                    size: 100,
                    onTap: () => setState(() {
                      _showOthers = !_showOthers;
                      widget.onShowOthersChanged?.call(_showOthers);
                    }),
                  ),
                ],
              ),
              // Other daireler — flip efektiyle, üsttekiler oynamaz
              if (_showOthers)
                TweenAnimationBuilder<double>(
                  tween: Tween(begin: 0.0, end: 1.0),
                  duration: const Duration(milliseconds: 350),
                  curve: Curves.easeOut,
                  builder: (context, value, child) => Opacity(
                    opacity: value,
                    child: Transform.translate(
                      offset: Offset(0, 20 * (1 - value)),
                      child: child,
                    ),
                  ),
                  child: Padding(
                    padding: const EdgeInsets.only(top: 12),
                    child: Wrap(
                      alignment: WrapAlignment.center,
                      spacing: 10,
                      runSpacing: 10,
                      children: otherLangs
                          .map((lang) => _circle(
                                label: '',
                                flag: lang.flag,
                                size: 55,
                                onTap: () =>
                                    widget.onLanguageSelected(lang.code),
                              ))
                          .toList(),
                    ),
                  ),
                ),
            ],
          );
        }

        // PORTRAIT
        return Column(
          children: [
            _circle(
              label: '',
              flag: mainLangs[0].flag,
              size: mainSize,
              onTap: () => widget.onLanguageSelected(mainLangs[0].code),
            ),
            SizedBox(height: gap),
            Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                _circle(
                  label: '',
                  flag: mainLangs[1].flag,
                  size: mainSize,
                  onTap: () => widget.onLanguageSelected(mainLangs[1].code),
                ),
                SizedBox(width: gap * 2),
                _circle(
                  label: '',
                  flag: mainLangs[2].flag,
                  size: mainSize,
                  onTap: () => widget.onLanguageSelected(mainLangs[2].code),
                ),
              ],
            ),
            SizedBox(height: gap),
            _circle(
              label: 'Other\nLanguages',
              size: mainSize,
              onTap: () => setState(() {
                _showOthers = !_showOthers;
                widget.onShowOthersChanged?.call(_showOthers);
              }),
            ),
            if (_showOthers)
              TweenAnimationBuilder<double>(
                tween: Tween(begin: 0.0, end: 1.0),
                duration: const Duration(milliseconds: 350),
                curve: Curves.easeOut,
                builder: (context, value, child) {
                  return Opacity(
                    opacity: value,
                    child: Transform.translate(
                      offset: Offset(0, 20 * (1 - value)),
                      child: child,
                    ),
                  );
                },
                child: Padding(
                  padding: const EdgeInsets.only(top: 20),
                  child: Wrap(
                    alignment: WrapAlignment.center,
                    spacing: 12,
                    runSpacing: 12,
                    children: otherLangs.map((lang) {
                      return _circle(
                        label: '',
                        flag: lang.flag,
                        size: otherSize,
                        onTap: () => widget.onLanguageSelected(lang.code),
                      );
                    }).toList(),
                  ),
                ),
              ),
          ],
        );
      },
    );
  }
}

class _WideButton extends StatelessWidget {
  final String? flag;
  final String label;
  final VoidCallback onPressed;
  final double? forcedFontSize;
  final double? forcedHeight;
  final double? forcedMaxWidth;
  const _WideButton({
    super.key,
    this.flag,
    required this.label,
    required this.onPressed,
    this.forcedFontSize,
    this.forcedHeight,
    this.forcedMaxWidth,
  });

  // Legacy constructor for backward compatibility
  factory _WideButton.fromText({
    required String text,
    required VoidCallback onPressed,
    double? forcedFontSize,
    double? forcedHeight,
  }) {
    // Try to parse flag and label from text like "🇹🇷  Turkish"
    final parts = text.split(RegExp(r'\s+'));
    String? flag;
    String label;
    // Check if first part looks like a flag emoji (2 characters, typically regional indicator symbols)
    if (parts.isNotEmpty &&
        parts[0].length <= 4 &&
        parts[0].runes.length >= 2) {
      // Simple heuristic: if first part is short and contains emoji-like characters, treat as flag
      final firstPart = parts[0];
      final hasEmojiLikeChars =
          firstPart.runes.any((rune) => rune >= 0x1F1E6 && rune <= 0x1F1FF);
      if (hasEmojiLikeChars) {
        flag = parts[0];
        label = parts.sublist(1).join(' ');
      } else {
        label = text;
      }
    } else {
      label = text;
    }
    return _WideButton(
      flag: flag,
      label: label,
      onPressed: onPressed,
      forcedFontSize: forcedFontSize,
      forcedHeight: forcedHeight,
    );
  }

  @override
  Widget build(BuildContext context) {
    final screenWidth = MediaQuery.of(context).size.width;
    final isLandscape =
        MediaQuery.of(context).orientation == Orientation.landscape;

    // Calculate button width
    final buttonWidth = forcedMaxWidth != null
        ? forcedMaxWidth!
        : isLandscape
            ? (screenWidth * 0.62).clamp(0.0, 560.0)
            : (screenWidth * 0.62).clamp(0.0, 560.0);

    Widget buttonContent;
    if (flag != null) {
      // Use Center > Row structure with flag and label centered together
      final existingTextStyle =
          GoogleFonts.lora(fontSize: forcedFontSize ?? 16);
      buttonContent = Center(
        child: Row(
          mainAxisSize: MainAxisSize.min,
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            SizedBox(
              width: 26,
              height: 18,
              child: FittedBox(
                fit: BoxFit.contain,
                child: Text(flag!),
              ),
            ),
            const SizedBox(width: 10),
            Text(
              label,
              textAlign: TextAlign.center,
              style: existingTextStyle.copyWith(fontWeight: FontWeight.normal),
            ),
          ],
        ),
      );
    } else {
      buttonContent = Text(
        label,
        style: GoogleFonts.lora(fontSize: forcedFontSize ?? 16),
      );
    }

    final defaultH = isLandscape ? 42.0 : 40.0;

    return _gradientButton(
      onPressed: onPressed,
      height: forcedHeight ?? defaultH,
      maxWidth: buttonWidth,
      child: DefaultTextStyle(
        style: GoogleFonts.lora(
          fontSize: forcedFontSize ?? 16,
          color: Colors.white,
          fontWeight: FontWeight.normal,
        ),
        child: buttonContent,
      ),
    );
  }
}

