// Custom text selection toolbar widget
class _CustomTextSelectionToolbar extends StatelessWidget {
  final TextEditingController controller;
  final FocusNode focusNode;
  final VoidCallback hide;
  final BuildContext rootContext;

  const _CustomTextSelectionToolbar({
    required this.controller,
    required this.focusNode,
    required this.hide,
    required this.rootContext,
  });

  @override
  Widget build(BuildContext context) {
    final value = controller.value;
    final selection = value.selection;
    final hasSelection = selection.isValid && !selection.isCollapsed;
    final selectedText = hasSelection
        ? value.text.substring(selection.start, selection.end)
        : '';

    final backgroundColor = Theme.of(context).colorScheme.surfaceVariant;
    final foregroundColor = Theme.of(context).colorScheme.onSurfaceVariant;

    return Container(
      decoration: BoxDecoration(
        color: backgroundColor,
        borderRadius: BorderRadius.circular(8),
      ),
      padding: const EdgeInsets.symmetric(horizontal: 4, vertical: 4),
      child: Row(
        mainAxisSize: MainAxisSize.min,
        children: [
          // Cut
          _ToolbarButton(
            icon: Icons.content_cut,
            label: t('context.cut'),
            onPressed: () {
              final sel = controller.selection;
              if (!sel.isValid || sel.isCollapsed) return;

              final selected = controller.text.substring(sel.start, sel.end);
              Clipboard.setData(ClipboardData(text: selected));

              final newText =
                  controller.text.replaceRange(sel.start, sel.end, '');
              controller.value = TextEditingValue(
                text: newText,
                selection: TextSelection.collapsed(offset: sel.start),
              );
            },
            foregroundColor: foregroundColor,
          ),
          // Copy
          _ToolbarButton(
            icon: Icons.content_copy,
            label: t('context.copy'),
            onPressed: () {
              final sel = controller.selection;
              if (!sel.isValid || sel.isCollapsed) return;

              final selected = controller.text.substring(sel.start, sel.end);
              Clipboard.setData(ClipboardData(text: selected));
            },
            foregroundColor: foregroundColor,
          ),
          // Select all
          _ToolbarButton(
            icon: Icons.select_all,
            label: t('context.select_all'),
            onPressed: () {
              controller.selection = TextSelection(
                baseOffset: 0,
                extentOffset: controller.text.length,
              );
            },
            foregroundColor: foregroundColor,
          ),
          // Translate
          if (hasSelection && selectedText.trim().isNotEmpty)
            _ToolbarButton(
              icon: Icons.translate,
              label: t('context.translate'),
              onPressed: () {
                hide();
                showModalBottomSheet<void>(
                  context: rootContext,
                  isScrollControlled: true,
                  backgroundColor: Theme.of(rootContext).cardColor,
                  shape: const RoundedRectangleBorder(
                    borderRadius:
                        BorderRadius.vertical(top: Radius.circular(18)),
                  ),
                  builder: (ctx) {
                    final isLandscapeT =
                        MediaQuery.of(ctx).orientation == Orientation.landscape;
                    final screenHT = MediaQuery.of(ctx).size.height;
                    return ConstrainedBox(
                      constraints: BoxConstraints(
                          maxHeight:
                              isLandscapeT ? screenHT * 0.88 : double.infinity),
                      child: SingleChildScrollView(
                        child: Container(
                          padding: const EdgeInsets.all(24),
                          child: Column(
                            mainAxisSize: MainAxisSize.min,
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              Text(
                                t('context.translate'),
                                style: TextStyle(
                                  fontSize: 20,
                                  fontWeight: FontWeight.w500,
                                  color: Theme.of(ctx).colorScheme.onSurface,
                                ),
                              ),
                              const SizedBox(height: 16),
                              Text(
                                selectedText,
                                style: TextStyle(
                                  fontSize: 16,
                                  color: Theme.of(ctx)
                                      .colorScheme
                                      .onSurfaceVariant,
                                ),
                              ),
                              const SizedBox(height: 24),
                              SizedBox(
                                width: double.infinity,
                                child: ElevatedButton(
                                  onPressed: () => Navigator.pop(ctx),
                                  child: Text(t('common.ok')),
                                ),
                              ),
                            ],
                          ),
                        ),
                      ),
                    );
                  },
                );
              },
              foregroundColor: foregroundColor,
            ),
        ],
      ),
    );
  }
}

