// Custom painter for dim overlay with hole
class _DimOverlayPainter extends CustomPainter {
  final Rect? holeRect;
  final double holeRadius;
  final double borderWidth;
  final Color dimColor;
  final Color borderColor;

  _DimOverlayPainter({
    this.holeRect,
    required this.holeRadius,
    required this.borderWidth,
    required this.dimColor,
    required this.borderColor,
  });

  @override
  void paint(Canvas canvas, Size size) {
    // Create full screen path
    final fullRect = Rect.fromLTWH(0, 0, size.width, size.height);
    final fullPath = Path()..addRect(fullRect);

    // Draw dim overlay
    final dimPaint = Paint()..color = dimColor;

    if (holeRect != null) {
      // Create hole path (rounded rectangle)
      final holePath = Path()
        ..addRRect(
          RRect.fromRectAndRadius(holeRect!, Radius.circular(holeRadius)),
        );

      // Cut out the hole from the full screen using Path difference
      final pathWithHole = Path.combine(
        PathOperation.difference,
        fullPath,
        holePath,
      );

      // Draw dim overlay with hole cut out
      canvas.drawPath(pathWithHole, dimPaint);

      // Draw border around the hole (highlight ring)
      final borderPaint = Paint()
        ..color = borderColor
        ..style = PaintingStyle.stroke
        ..strokeWidth = borderWidth;

      canvas.drawRRect(
        RRect.fromRectAndRadius(holeRect!, Radius.circular(holeRadius)),
        borderPaint,
      );
    } else {
      // No hole - just draw full dim overlay
      canvas.drawPath(fullPath, dimPaint);
    }
  }

  @override
  bool shouldRepaint(_DimOverlayPainter oldDelegate) {
    return oldDelegate.holeRect != holeRect ||
        oldDelegate.holeRadius != holeRadius ||
        oldDelegate.borderWidth != borderWidth ||
        oldDelegate.dimColor != dimColor ||
        oldDelegate.borderColor != borderColor;
  }
}

// Custom painter for TTS highlight background (BOTH mode)
class _HighlightPainter extends CustomPainter {
  // Legacy fields kept for API compatibility but no longer used for painting.
  final String fullText;
  final TextStyle baseStyle;
  final int highlightStart;
  final int highlightEnd;
  final EdgeInsets padding;
  final double maxWidth;
  final Color highlightColor;
  // New: pre-computed pixel rects from RenderEditable (pixel-perfect)
  final List<Rect> highlightRects;
  final TextScaler textScaler;

  _HighlightPainter({
    required this.fullText,
    required this.baseStyle,
    required this.highlightStart,
    required this.highlightEnd,
    required this.padding,
    required this.maxWidth,
    required this.highlightColor,
    this.highlightRects = const [],
    this.textScaler = TextScaler.noScaling,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()..color = highlightColor;

    if (highlightRects.isNotEmpty) {
      // Fast path: draw pre-computed rects from RenderEditable (pixel-perfect)
      for (final rect in highlightRects) {
        if (rect.width > 0 && rect.height > 0) {
          canvas.drawRRect(
            RRect.fromRectAndRadius(rect, const Radius.circular(4)),
            paint,
          );
        }
      }
      return;
    }

    // Fallback: compute rects via TextPainter (used before first RenderEditable read)
    if (highlightStart < 0 ||
        highlightEnd <= highlightStart ||
        highlightStart >= fullText.length ||
        highlightEnd > fullText.length) {
      return;
    }

    final textPainter = TextPainter(
      text: TextSpan(text: fullText, style: baseStyle),
      textDirection: TextDirection.ltr,
      textAlign: TextAlign.left,
      textScaler: textScaler,
    );

    final layoutWidth = maxWidth > 0
        ? maxWidth - padding.horizontal
        : size.width - padding.horizontal;
    textPainter.layout(maxWidth: layoutWidth > 0 ? layoutWidth : size.width);

    final selection = TextSelection(
      baseOffset: highlightStart,
      extentOffset: highlightEnd,
    );

    final boxes = textPainter.getBoxesForSelection(selection);
    if (boxes.isEmpty) {
      textPainter.dispose();
      return;
    }

    for (final b in boxes) {
      final rect = Rect.fromLTRB(
        b.left + padding.left,
        b.top + padding.top,
        b.right + padding.left,
        b.bottom + padding.top,
      );
      if (rect.width > 0 && rect.height > 0) {
        canvas.drawRRect(
          RRect.fromRectAndRadius(rect, const Radius.circular(4)),
          paint,
        );
      }
    }
    textPainter.dispose();
  }

  @override
  bool shouldRepaint(_HighlightPainter oldDelegate) {
    return oldDelegate.highlightStart != highlightStart ||
        oldDelegate.highlightEnd != highlightEnd ||
        oldDelegate.maxWidth != maxWidth ||
        oldDelegate.highlightColor != highlightColor ||
        oldDelegate.highlightRects != highlightRects ||
        oldDelegate.textScaler != textScaler;
  }
}

