// TourTarget widget that reports its global rect
class TourTarget extends StatefulWidget {
  final String id;
  final Widget child;
  final void Function(String id, Rect rect) onRect;

  const TourTarget({
    super.key,
    required this.id,
    required this.child,
    required this.onRect,
  });

  @override
  State<TourTarget> createState() => _TourTargetState();
}

class _TourTargetState extends State<TourTarget> with WidgetsBindingObserver {
  final GlobalKey _k = GlobalKey();
  Rect? _last;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    WidgetsBinding.instance.addPostFrameCallback((_) => _report());
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    super.dispose();
  }

  @override
  void didChangeMetrics() {
    WidgetsBinding.instance.addPostFrameCallback((_) => _report());
  }

  void _report() {
    final ctx = _k.currentContext;
    if (ctx == null) return;
    final box = ctx.findRenderObject() as RenderBox?;
    if (box == null || !box.hasSize) return;
    final topLeft = box.localToGlobal(Offset.zero);
    final rect = topLeft & box.size;
    if (rect.width < 2 || rect.height < 2) return;
    if (_last == rect) return;
    _last = rect;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      widget.onRect(widget.id, rect);
    });
  }

  @override
  Widget build(BuildContext context) {
    WidgetsBinding.instance.addPostFrameCallback((_) => _report());
    return KeyedSubtree(key: _k, child: widget.child);
  }
}

// Painter for tour highlight overlay with hole
class _HolePainter extends CustomPainter {
  final Rect target;

  _HolePainter({required this.target});

  @override
  void paint(Canvas canvas, Size size) {
    final overlay = Path()
      ..addRect(Rect.fromLTWH(0, 0, size.width, size.height));
    final hole = Path()
      ..addRRect(RRect.fromRectAndRadius(
          target.inflate(8), const Radius.circular(10)));
    final p = Paint()..color = Colors.black.withValues(alpha: 0.55);
    final combined = Path.combine(PathOperation.difference, overlay, hole);
    canvas.drawPath(combined, p);

    final border = Paint()
      ..color = Colors.white.withValues(alpha: 0.9)
      ..style = PaintingStyle.stroke
      ..strokeWidth = 2;
    canvas.drawRRect(
      RRect.fromRectAndRadius(target.inflate(8), const Radius.circular(10)),
      border,
    );
  }

  @override
  bool shouldRepaint(covariant _HolePainter old) => old.target != target;
}

// Tour widget with highlight and explanation panel
class ReadingPageTour extends StatefulWidget {
  final TourStep step;
  final VoidCallback onNext;
  final VoidCallback onClose;
  final VoidCallback? onBack;
  final VoidCallback? onDontShowAgain;
  final int totalSteps;

  const ReadingPageTour({
    super.key,
    required this.step,
    required this.onNext,
    required this.onClose,
    this.onBack,
    this.onDontShowAgain,
    required this.totalSteps,
  });

  @override
  State<ReadingPageTour> createState() => _ReadingPageTourState();
}

class _ReadingPageTourState extends State<ReadingPageTour> {
  final GlobalKey _bubbleKey = GlobalKey();
  Size? _measuredBubbleSize;

  /// Tour bubble body: 'EasyReading' geçen yerleri bold yapar
  Widget _buildTourBodyText(String text, {required bool isDark}) {
    const brand = 'EasyReading';
    const kText = Color(0xFF3E2723);
    final color = isDark ? Colors.black87 : kText;
    final baseStyle = GoogleFonts.lora(
        textStyle: TextStyle(
      fontSize: 14,
      color: color,
      height: 1.4,
      fontWeight: FontWeight.w400,
    ));
    final boldStyle = GoogleFonts.lora(
        textStyle: TextStyle(
      fontSize: 14,
      color: color,
      height: 1.4,
      fontWeight: FontWeight.w700,
    ));
    if (!text.contains(brand)) {
      return Text(text, style: baseStyle, textScaler: TextScaler.noScaling);
    }
    final parts = text.split(brand);
    final spans = <TextSpan>[];
    for (int i = 0; i < parts.length; i++) {
      if (parts[i].isNotEmpty)
        spans.add(TextSpan(text: parts[i], style: baseStyle));
      if (i < parts.length - 1)
        spans.add(TextSpan(text: brand, style: boldStyle));
    }
    return RichText(
      text: TextSpan(children: spans),
      textScaler: TextScaler.noScaling,
    );
  }

  @override
  void initState() {
    super.initState();
    // Measure bubble size after first frame
    WidgetsBinding.instance.addPostFrameCallback((_) => _measureBubble());
  }

  @override
  void didUpdateWidget(ReadingPageTour oldWidget) {
    super.didUpdateWidget(oldWidget);
    // Reset measured size when step changes (content might change)
    if (oldWidget.step.index != widget.step.index) {
      _measuredBubbleSize = null;
      WidgetsBinding.instance.addPostFrameCallback((_) => _measureBubble());
    }
  }

  void _measureBubble() {
    final box = _bubbleKey.currentContext?.findRenderObject() as RenderBox?;
    final bubbleSize = box?.size;
    if (bubbleSize != null && bubbleSize.width > 0 && bubbleSize.height > 0) {
      if (_measuredBubbleSize != bubbleSize) {
        setState(() {
          _measuredBubbleSize = bubbleSize;
        });
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    final screenSize = MediaQuery.of(context).size;

    final renderBox =
        widget.step.targetKey?.currentContext?.findRenderObject() as RenderBox?;
    final targetPosition = renderBox?.localToGlobal(Offset.zero) ?? Offset.zero;
    final targetSize = renderBox?.size ?? Size.zero;

    // Check if targetRect is valid (has size > 0)
    final bool hasValidTarget = targetSize.width > 0 && targetSize.height > 0;

    final targetRectGlobal = hasValidTarget
        ? Rect.fromLTWH(
            targetPosition.dx,
            targetPosition.dy,
            targetSize.width,
            targetSize.height,
          )
        : null;

    final targetCenter = hasValidTarget
        ? Offset(
            targetPosition.dx + targetSize.width / 2,
            targetPosition.dy + targetSize.height / 2,
          )
        : Offset(screenSize.width / 2, screenSize.height / 2);

    // Measure bubble after build
    WidgetsBinding.instance.addPostFrameCallback((_) => _measureBubble());

    return LayoutBuilder(
      builder: (context, constraints) {
        // Convert global targetRect to local coordinates relative to ReadingPageTour
        Rect? targetRectLocal;
        if (targetRectGlobal != null) {
          final box = context.findRenderObject() as RenderBox?;
          if (box != null) {
            final topLeft = box.localToGlobal(Offset.zero);
            targetRectLocal =
                targetRectGlobal.translate(-topLeft.dx, -topLeft.dy);
          } else {
            // Fallback: use global coordinates if RenderBox not available yet
            // Since ReadingPageTour is in a full-screen dialog, coordinates should match
            targetRectLocal = targetRectGlobal;
          }
        }

        // Check for special landscape positioning (steps 3, 11)
        final mq = MediaQuery.of(context);
        final isLandscape = mq.orientation == Orientation.landscape;
        final int stepShown = widget.step.index + 1; // Displayed as 3/12 etc.
        final bool panelMode =
            isLandscape && (stepShown == 3 || stepShown == 11);

        // Build bubble widget - use special positioning for landscape steps 3/11
        Widget bubbleWidgetRaw;
        if (panelMode && hasValidTarget && targetRectGlobal != null) {
          // PanelMode: Use Positioned.fill + Align for landscape steps 3/11
          final insets = mq.padding;
          const pad = 12.0;
          final availW = mq.size.width - insets.left - insets.right - pad * 2;
          final availH = mq.size.height - insets.top - insets.bottom - pad * 2;

          // Global landscape cubic limits for ALL steps
          final panelW = math.min(320.0, availW * 0.48);
          final panelH = math.min(260.0, availH * 0.70);

          // Step 3 ve 11 için Align köşesini hedefe göre seç
          final targetOnRight = targetRectGlobal.center.dx > mq.size.width / 2;
          final targetOnTop = targetRectGlobal.center.dy < mq.size.height / 2;

          // Step 3 ve 11: hedefin ters tarafı alignment'ı koru (x ters, y için top kalabilir)
          final Alignment baseAlign =
              targetOnRight ? Alignment.topLeft : Alignment.topRight;
          final Alignment panelAlign = baseAlign;

          final bubbleContent = _buildChatBubbleContent(
            context,
            targetCenter,
            targetPosition,
            targetSize,
            screenSize,
          );

          // Apply text scale clamp for landscape steps 3 & 11
          final bubbleSafe = _wrapTourBubbleScale(
            context,
            stepShown: stepShown,
            child: bubbleContent,
          );

          // PART A: Wrap bubble root with LayoutBuilder to constrain height in landscape
          final Widget panelChild = LayoutBuilder(
            builder: (context, c) {
              final mq = MediaQuery.of(context);

              // Global landscape cubic limits for ALL steps
              final isLandscape = mq.orientation == Orientation.landscape;
              final bubbleMaxW = isLandscape
                  ? math.min(
                      320.0,
                      (mq.size.width - mq.padding.left - mq.padding.right) *
                          0.48)
                  : double.infinity;
              final bubbleMaxH = isLandscape
                  ? math.min(
                      260.0,
                      (mq.size.height - mq.padding.top - mq.padding.bottom) *
                          0.70)
                  : double.infinity;

              return ClipRRect(
                borderRadius: BorderRadius.circular(18),
                child: ConstrainedBox(
                  constraints: BoxConstraints(
                    maxWidth: bubbleMaxW,
                    maxHeight: bubbleMaxH,
                  ),
                  child: Material(
                    elevation: 4,
                    color: kCream,
                    borderRadius: BorderRadius.circular(18),
                    child: bubbleSafe,
                  ),
                ),
              );
            },
          );

          // Step 11 için overlap kaçışlı dy hesaplama:
          double desiredDy;
          if (stepShown == 11) {
            // Step 11: overlap kontrolü ile dy seç
            // Panel rect'i hesaplamak için panelAlign ve panelW/panelH kullan
            final panelLeft = targetOnRight
                ? (insets.left + pad)
                : (mq.size.width - insets.right - pad - panelW);
            final panelTop = insets.top + pad;

            // Panel rect'i verilen dy için hesapla
            Rect panelRectForDy(double dy) {
              return Rect.fromLTWH(panelLeft, panelTop + dy, panelW, panelH);
            }

            // Overlap kontrolü ile dy seç
            double pickDy() {
              // Önce aşağı dene: [0, 60, 120]
              for (final d in [0.0, 60.0, 120.0]) {
                final panelRect = panelRectForDy(d);
                if (!panelRect.overlaps(targetRectGlobal!)) {
                  return d;
                }
              }
              // Sonra yukarı dene: [-40, -80]
              for (final d in [-40.0, -80.0]) {
                final panelRect = panelRectForDy(d);
                if (!panelRect.overlaps(targetRectGlobal!)) {
                  return d;
                }
              }
              // Overlap kaçınılamazsa 0 (üstte dursun)
              return 0.0;
            }

            desiredDy = pickDy();
            // Panel ekranda kalacak şekilde clamp:
            final double maxDy = math.max(0.0, availH - panelH - 8.0);
            final double minDy = -math.max(0.0, panelH - availH + 8.0);
            desiredDy = desiredDy.clamp(minDy, maxDy);
          } else {
            // Step 3 için mevcut mantık
            desiredDy = stepShown == 3 ? 60.0 : 0.0;
            // Panel ekranda kalacak şekilde clamp:
            final double maxDy = math.max(0.0, availH - panelH - 8.0);
            desiredDy = desiredDy.clamp(0.0, maxDy);
          }

          final double dy = desiredDy;

          Widget movedPanel = Transform.translate(
            offset: Offset(0, dy),
            child: panelChild,
          );

          bubbleWidgetRaw = Positioned.fill(
            child: SafeArea(
              child: Padding(
                padding: const EdgeInsets.all(pad),
                child: Align(
                  alignment: panelAlign,
                  child: movedPanel, // translate edilmiş panel
                ),
              ),
            ),
          );
        } else {
          // Normal case: Use existing Positioned(left/top) positioning
          bubbleWidgetRaw = hasValidTarget
              ? _buildChatBubble(
                  context,
                  targetCenter,
                  targetPosition,
                  targetSize,
                  screenSize,
                )
              : _buildChatBubbleFallback(
                  context, screenSize, widget.step.index);
        }

        // PART D: Wrap with AnimatedSwitcher for smooth fade transitions (landscape only)
        Widget bubbleWidget = bubbleWidgetRaw;
        if (isLandscape) {
          bubbleWidget = AnimatedSwitcher(
            duration: const Duration(milliseconds: 180),
            switchInCurve: Curves.easeOut,
            switchOutCurve: Curves.easeIn,
            transitionBuilder: (child, anim) => FadeTransition(
              opacity: anim,
              child: child,
            ),
            child: KeyedSubtree(
              key:
                  ValueKey<int>(widget.step.index), // Step change triggers fade
              child: bubbleWidgetRaw,
            ),
          );
        }

        return SizedBox.expand(
          child: Stack(
            clipBehavior: Clip.none,
            children: [
              // FIRST: Dim overlay with hole (background layer) - only if target is valid
              if (targetRectLocal != null)
                Positioned.fill(
                  child: IgnorePointer(
                    child: CustomPaint(
                      painter: _HolePainter(target: targetRectLocal!),
                    ),
                  ),
                ),
              // LAST: Chat bubble - MUST ALWAYS RENDER (top-most layer)
              // NOT wrapped in IgnorePointer so Next/Skip buttons work
              bubbleWidget,
            ],
          ),
        );
      },
    );
  }

  Widget _buildChatBubbleFallback(
      BuildContext context, Size screenSize, int stepIndex) {
    // Fallback: show panel centered on screen when target rect is not available
    final padding = MediaQuery.of(context).padding;
    final centerX = screenSize.width / 2;
    final centerY = screenSize.height / 2;
    final fallbackCenter = Offset(centerX, centerY);
    final fallbackPosition =
        Offset(centerX - 140, centerY - 70); // Centered position
    final fallbackSize = const Size(280, 140);

    // Debug message only in debug mode
    final debugMessage =
        kDebugMode ? 'Target not found for step $stepIndex' : null;

    return _buildChatBubble(
      context,
      fallbackCenter,
      fallbackPosition,
      fallbackSize,
      screenSize,
      debugMessage: debugMessage,
    );
  }

  // Calculate intersection area between two rects
  double _intersectionArea(Rect a, Rect b) {
    final left = math.max(a.left, b.left);
    final top = math.max(a.top, b.top);
    final right = math.min(a.right, b.right);
    final bottom = math.min(a.bottom, b.bottom);
    if (left < right && top < bottom) {
      return (right - left) * (bottom - top);
    }
    return 0;
  }

  // Wrap tour bubble with text scale clamp for landscape steps 3 & 11
  Widget _wrapTourBubbleScale(BuildContext context,
      {required int stepShown, required Widget child}) {
    final mq = MediaQuery.of(context);
    final isLandscape = mq.orientation == Orientation.landscape;

    // Sadece step 3 & 11 ve sadece landscape:
    if (!isLandscape) return child;
    if (stepShown != 3 && stepShown != 11) return child;

    // Üst limit: 1.10 (çok az clamp; aşırı küçültme yok)
    final currentFactor = mq.textScaleFactor;
    final cappedFactor = math.min(currentFactor, 1.10);

    return MediaQuery(
      data: mq.copyWith(
        textScaler: TextScaler.linear(cappedFactor),
      ),
      child: child,
    );
  }

