  Widget _buildChatBubble(
    BuildContext context,
    Offset targetCenter,
    Offset targetPosition,
    Size targetSize,
    Size screenSize, {
    String? debugMessage,
  }) {
    // Detect dark theme
    final isDark = Theme.of(context).brightness == Brightness.dark;

    const bubbleMinWidth = 200.0;
    const tailSize = 12.0;
    const bubbleMargin = 12.0;
    const bubbleRadius = 12.0;
    const gapSize = 12.0; // Gap between bubble and target
    const screenMargin = 8.0; // Margin from screen edges
    const overlapTolerance = 8.0; // Tolerance for overlap check

    // Get MediaQuery for orientation and size
    final mq = MediaQuery.of(context);
    final isLand = mq.orientation == Orientation.landscape;
    final screenW = mq.size.width;
    final screenH = mq.size.height;

    // Construct targetRect from targetPosition and targetSize
    final targetRect = Rect.fromLTWH(
      targetPosition.dx,
      targetPosition.dy,
      targetSize.width,
      targetSize.height,
    );

    // Define bubble constraints based on orientation
    // Landscape: clamp to 68% width and 70% height to prevent overflow
    // Portrait: keep existing behavior (no changes)
    final bubbleMaxWidth =
        isLand ? screenW * 0.68 : math.min(360.0, screenW * 0.85);

    final bubbleMaxHeight =
        isLand ? screenH * 0.70 : math.min(300.0, screenH * 0.6);

    // Use measured bubble size if available, otherwise use max height estimate
    final bubbleHeight = _measuredBubbleSize?.height ?? bubbleMaxHeight;
    final bubbleWidthEstimate = _measuredBubbleSize?.width ?? bubbleMaxWidth;

    // HARD FAILSAFE: Overlap-checking placement algorithm
    // Try candidates in priority order and reject overlapping ones
    List<_PlacementCandidate> candidates = [];

    if (isLand) {
      // Landscape: right -> left -> below -> above
      // Right placement
      double rightWidth = math.min(
          bubbleMaxWidth, screenW - targetRect.right - gapSize - screenMargin);
      rightWidth = rightWidth.clamp(bubbleMinWidth, bubbleMaxWidth);
      double rightY = (targetRect.center.dy - bubbleHeight / 2)
          .clamp(screenMargin, screenH - bubbleHeight - screenMargin);
      candidates.add(_PlacementCandidate(
        position: BubblePosition.right,
        offset: Offset(targetRect.right + gapSize, rightY),
        width: rightWidth,
        height: bubbleHeight,
      ));

      // Left placement
      double leftWidth =
          math.min(bubbleMaxWidth, targetRect.left - gapSize - screenMargin);
      leftWidth = leftWidth.clamp(bubbleMinWidth, bubbleMaxWidth);
      double leftY = (targetRect.center.dy - bubbleHeight / 2)
          .clamp(screenMargin, screenH - bubbleHeight - screenMargin);
      candidates.add(_PlacementCandidate(
        position: BubblePosition.left,
        offset: Offset(targetRect.left - leftWidth - gapSize, leftY),
        width: leftWidth,
        height: bubbleHeight,
      ));

      // Below placement
      double belowWidth = math.min(bubbleMaxWidth, targetRect.width + 24);
      belowWidth = belowWidth.clamp(bubbleMinWidth, bubbleMaxWidth);
      double belowX = (targetRect.left + targetRect.width / 2 - belowWidth / 2)
          .clamp(screenMargin, screenW - belowWidth - screenMargin);
      candidates.add(_PlacementCandidate(
        position: BubblePosition.below,
        offset: Offset(belowX, targetRect.bottom + gapSize),
        width: belowWidth,
        height: bubbleHeight,
      ));

      // Above placement
      double aboveWidth = math.min(bubbleMaxWidth, targetRect.width + 24);
      aboveWidth = aboveWidth.clamp(bubbleMinWidth, bubbleMaxWidth);
      double aboveX = (targetRect.left + targetRect.width / 2 - aboveWidth / 2)
          .clamp(screenMargin, screenW - aboveWidth - screenMargin);
      candidates.add(_PlacementCandidate(
        position: BubblePosition.above,
        offset: Offset(aboveX, targetRect.top - bubbleHeight - gapSize),
        width: aboveWidth,
        height: bubbleHeight,
      ));
    } else {
      // Portrait: below -> above
      // Below placement
      double belowWidth = math.min(bubbleMaxWidth, targetRect.width + 24);
      belowWidth = belowWidth.clamp(bubbleMinWidth, bubbleMaxWidth);
      double belowX = (targetRect.left + targetRect.width / 2 - belowWidth / 2)
          .clamp(screenMargin, screenW - belowWidth - screenMargin);
      candidates.add(_PlacementCandidate(
        position: BubblePosition.below,
        offset: Offset(belowX, targetRect.bottom + gapSize),
        width: belowWidth,
        height: bubbleHeight,
      ));

      // Above placement
      double aboveWidth = math.min(bubbleMaxWidth, targetRect.width + 24);
      aboveWidth = aboveWidth.clamp(bubbleMinWidth, bubbleMaxWidth);
      double aboveX = (targetRect.left + targetRect.width / 2 - aboveWidth / 2)
          .clamp(screenMargin, screenW - aboveWidth - screenMargin);
      candidates.add(_PlacementCandidate(
        position: BubblePosition.above,
        offset: Offset(aboveX, targetRect.top - bubbleHeight - gapSize),
        width: aboveWidth,
        height: bubbleHeight,
      ));
    }

    // Candidate selection logic
    // Clamp all candidates to screen bounds
    final targetRectInflated = targetRect.inflate(overlapTolerance);
    _PlacementCandidate? bestCandidate;
    double minIntersection = double.infinity;

    for (final candidate in candidates) {
      // Clamp to screen bounds
      final clampedX = candidate.offset.dx
          .clamp(screenMargin, screenW - candidate.width - screenMargin);
      final clampedY = candidate.offset.dy
          .clamp(screenMargin, screenH - candidate.height - screenMargin);
      final clampedRect =
          Rect.fromLTWH(clampedX, clampedY, candidate.width, candidate.height);

      // Check for overlap with target
      final intersection = _intersectionArea(clampedRect, targetRectInflated);

      if (intersection == 0) {
        // No overlap - this is the best candidate
        bestCandidate = _PlacementCandidate(
          position: candidate.position,
          offset: Offset(clampedX, clampedY),
          width: candidate.width,
          height: candidate.height,
        );
        break; // Use first non-overlapping candidate (priority order)
      } else {
        // Track minimum intersection for fallback
        if (intersection < minIntersection) {
          minIntersection = intersection;
          bestCandidate = _PlacementCandidate(
            position: candidate.position,
            offset: Offset(clampedX, clampedY),
            width: candidate.width,
            height: candidate.height,
          );
        }
      }
    }

    // Fallback: use best candidate (minimum intersection) if all overlap
    final finalCandidate = bestCandidate ?? candidates.first;
    final double finalBubbleWidth = finalCandidate.width;
    Offset clampedOffset = finalCandidate.offset;
    final BubblePosition position = finalCandidate.position;

    // Extra safety clamp for landscape: ensure bubble doesn't overflow screen
    if (isLand) {
      final maxW = bubbleMaxWidth;
      final maxH = bubbleMaxHeight;
      clampedOffset = Offset(
        clampedOffset.dx.clamp(screenMargin, screenW - maxW - screenMargin),
        clampedOffset.dy.clamp(screenMargin, screenH - maxH - screenMargin),
      );
    }

    // Landscape overlap detection and auto-shift
    if (isLand) {
      // Use real measured bubble size if available, otherwise use calculated width/height
      final double actualBubbleWidth =
          _measuredBubbleSize?.width ?? finalBubbleWidth;
      final double actualBubbleHeight =
          _measuredBubbleSize?.height ?? bubbleHeight;

      final bubbleRect = Rect.fromLTWH(
        clampedOffset.dx,
        clampedOffset.dy,
        actualBubbleWidth,
        actualBubbleHeight,
      );

      final bool overlaps = bubbleRect.overlaps(targetRect);

      if (overlaps) {
        final double sideWidth = math.min(screenW * 0.50, 340.0);

        if (targetRect.center.dx > screenW / 2) {
          clampedOffset = Offset(12.0, clampedOffset.dy);
        } else {
          clampedOffset = Offset(screenW - sideWidth - 12.0, clampedOffset.dy);
        }

        clampedOffset = Offset(
          clampedOffset.dx,
          math.max(
            12.0,
            math.min(targetRect.top, screenH - actualBubbleHeight - 12.0),
          ),
        );
      }
    }

    // Calculate tail tip position relative to bubble (pointing to target center)
    final Offset tailTipLocal;
    switch (position) {
      case BubblePosition.above:
        // Tail at bottom edge, pointing down to target center
        tailTipLocal = Offset(
          (targetCenter.dx - clampedOffset.dx)
              .clamp(bubbleRadius, finalBubbleWidth - bubbleRadius)
              .toDouble(),
          bubbleHeight,
        );
        break;
      case BubblePosition.below:
        // Tail at top edge, pointing up to target center
        tailTipLocal = Offset(
          (targetCenter.dx - clampedOffset.dx)
              .clamp(bubbleRadius, finalBubbleWidth - bubbleRadius)
              .toDouble(),
          0.0,
        );
        break;
      case BubblePosition.left:
        // Tail at right edge, pointing right to target center
        tailTipLocal = Offset(
          finalBubbleWidth,
          (targetCenter.dy - clampedOffset.dy)
              .clamp(bubbleRadius, bubbleHeight - bubbleRadius)
              .toDouble(),
        );
        break;
      case BubblePosition.right:
        // Tail at left edge, pointing left to target center
        tailTipLocal = Offset(
          0.0,
          (targetCenter.dy - clampedOffset.dy)
              .clamp(bubbleRadius, bubbleHeight - bubbleRadius)
              .toDouble(),
        );
        break;
    }

    // Original code with dark theme text color fixes
    return Positioned(
      left: clampedOffset.dx,
      top: clampedOffset.dy,
      child: Material(
        color: Colors.transparent,
        elevation: 0,
        child: ClipPath(
          clipper: _SpeechBubbleClipper(
            position: position,
            tailTipLocal: tailTipLocal,
            radius: bubbleRadius,
            tailSize: tailSize,
          ),
          child: ConstrainedBox(
            constraints: BoxConstraints(
              minWidth: bubbleMinWidth,
              maxWidth: finalBubbleWidth,
              maxHeight: bubbleMaxHeight,
            ),
            child: Container(
              key: _bubbleKey, // Add GlobalKey for measurement
