enum BubblePosition { above, below, left, right }

// Helper class to hold placement candidate
class _PlacementCandidate {
  final BubblePosition position;
  final Offset offset;
  final double width;
  final double height;

  _PlacementCandidate({
    required this.position,
    required this.offset,
    required this.width,
    required this.height,
  });

  Rect get rect => Rect.fromLTWH(offset.dx, offset.dy, width, height);
}

class _SpeechBubbleClipper extends CustomClipper<Path> {
  final BubblePosition position;
  final Offset tailTipLocal;
  final double radius;
  final double tailSize;

  _SpeechBubbleClipper({
    required this.position,
    required this.tailTipLocal,
    required this.radius,
    required this.tailSize,
  });

  @override
  Path getClip(Size size) {
    // Create rounded rectangle path
    final rect = Rect.fromLTWH(0, 0, size.width, size.height);
    final bubblePath = Path()
      ..addRRect(RRect.fromRectAndRadius(rect, Radius.circular(radius)));

    // Create tail (triangle) path pointing to target
    final tailPath = Path();
    switch (position) {
      case BubblePosition.above:
        // Tail at bottom edge, pointing down
        tailPath.moveTo(tailTipLocal.dx - tailSize / 2, size.height);
        tailPath.lineTo(tailTipLocal.dx, size.height + tailSize);
        tailPath.lineTo(tailTipLocal.dx + tailSize / 2, size.height);
        tailPath.close();
        break;
      case BubblePosition.below:
        // Tail at top edge, pointing up
        tailPath.moveTo(tailTipLocal.dx - tailSize / 2, 0);
        tailPath.lineTo(tailTipLocal.dx, -tailSize);
        tailPath.lineTo(tailTipLocal.dx + tailSize / 2, 0);
        tailPath.close();
        break;
      case BubblePosition.left:
        // Tail at right edge, pointing right
        tailPath.moveTo(size.width, tailTipLocal.dy - tailSize / 2);
        tailPath.lineTo(size.width + tailSize, tailTipLocal.dy);
        tailPath.lineTo(size.width, tailTipLocal.dy + tailSize / 2);
        tailPath.close();
        break;
      case BubblePosition.right:
        // Tail at left edge, pointing left
        tailPath.moveTo(0, tailTipLocal.dy - tailSize / 2);
        tailPath.lineTo(-tailSize, tailTipLocal.dy);
        tailPath.lineTo(0, tailTipLocal.dy + tailSize / 2);
        tailPath.close();
        break;
    }

    // Combine rounded rectangle with tail using union
    return Path.combine(PathOperation.union, bubblePath, tailPath);
  }

  @override
  bool shouldReclip(_SpeechBubbleClipper oldClipper) {
    return oldClipper.position != position ||
        oldClipper.tailTipLocal != tailTipLocal ||
        oldClipper.radius != radius ||
        oldClipper.tailSize != tailSize;
  }
}

class _TourOverlayPainter extends CustomPainter {
  final Rect targetRect;
  final Size screenSize;
  final Color borderColor;

  _TourOverlayPainter({
    required this.targetRect,
    required this.screenSize,
    required this.borderColor,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..color = Colors.black.withValues(alpha: 0.7)
      ..style = PaintingStyle.fill;

    final path = Path()
      ..addRect(Rect.fromLTWH(0, 0, screenSize.width, screenSize.height));

    // Cut out target area with rounded corners
    final roundedRect = RRect.fromRectAndRadius(
      targetRect.inflate(8),
      const Radius.circular(8),
    );
    final holePath = Path()..addRRect(roundedRect);

    final combinedPath = Path.combine(
      PathOperation.difference,
      path,
      holePath,
    );

    canvas.drawPath(combinedPath, paint);

    // Draw border around target
    final borderPaint = Paint()
      ..color = borderColor
      ..style = PaintingStyle.stroke
      ..strokeWidth = 2;

    canvas.drawRRect(roundedRect, borderPaint);
  }

  @override
  bool shouldRepaint(_TourOverlayPainter oldDelegate) {
    return targetRect != oldDelegate.targetRect ||
        screenSize != oldDelegate.screenSize ||
        borderColor != oldDelegate.borderColor;
  }
}

