  // ================== DOSYADAN METİN ÇIKARAN HELPER (compute() ile UI donmaz) ==================
  Future<String> _extractTextFromFile(PlatformFile file) async {
    final path = file.path;
    if (path == null) return '';

    final ext = path.split('.').last.toLowerCase();

    switch (ext) {
      // -------- TXT --------
      case 'txt':
        // readAsString async — büyük dosyada bile UI donmaz
        final raw = await File(path).readAsString();
        // Satır sonlarını normalize et
        return raw.replaceAll('\r\n', '\n').replaceAll('\r', '\n');

      // -------- PDF --------
      case 'pdf':
        // Syncfusion compute() ile çalışmaz, direkt çağır
        // ANR önlemi: her 5 sayfada Future.delayed(Duration.zero) eklendi
        return await _extractPdfInIsolate(path);

      // -------- DOCX --------
      case 'docx':
        // Büyük dosya → arka planda işle
        return await compute(_extractDocxInIsolate, path);

      // -------- EPUB --------
      case 'epub':
        // Büyük dosya → arka planda işle
        final result = await compute(_extractEpubInIsolate, path);
        if (result.startsWith('EPUB_ERROR:')) {
          return AppLang.code.value == 'tr'
              ? 'EPUB dosyası okunamadı.'
              : 'Could not read EPUB file.';
        }
        return result;

      // Diğer uzantılar
      default:
        return AppLang.code.value == 'tr'
            ? 'Bu dosya formatı desteklenmiyor.'
            : 'This file format is not supported.';
    }
  }

  // ================== DOSYA AÇ ==================
  Future<void> _pickAndOpenFile() async {
    try {
      // 1) Dosya seçme başlangıcı
      setState(() {
        _isLoadingFile = true;
      });

      final res = await FilePicker.platform.pickFiles(
        type: FileType.custom,
        allowedExtensions: ['txt', 'pdf', 'docx', 'epub'],
        withData: false,
      );

      // Kullanıcı vazgeçtiyse
      if (res == null || res.files.isEmpty) {
        if (mounted) {
          setState(() {
            _isLoadingFile = false;
          });
        }
        return;
      }

      // Seçilen tek dosya
      final file = res.files.single;

      // PDF boyut kontrolü
      final fileSize = file.size;
      final isPdfFile = file.name.toLowerCase().endsWith('.pdf');
      final fileSizeMB = (fileSize / (1024 * 1024)).round();

      // 20MB üzeri PDF → reddet
      if (isPdfFile && fileSize > 20 * 1024 * 1024 && mounted) {
        setState(() => _isLoadingFile = false);
        final lang = AppLang.code.value;
        final msg = lang == 'tr'
            ? 'Bu PDF çok büyük (${fileSizeMB}MB). Lütfen 20MB altı PDF yükleyin.'
            : lang == 'de'
                ? 'Diese PDF ist zu groß (${fileSizeMB}MB). Bitte eine PDF unter 20MB laden.'
                : lang == 'fr'
                    ? 'Ce PDF est trop grand (${fileSizeMB}MB). Veuillez charger un PDF de moins de 20MB.'
                    : lang == 'es'
                        ? 'Este PDF es demasiado grande (${fileSizeMB}MB). Por favor cargue un PDF menor a 20MB.'
                        : lang == 'it'
                            ? 'Questo PDF è troppo grande (${fileSizeMB}MB). Caricare un PDF sotto i 20MB.'
                            : lang == 'ru'
                                ? 'Этот PDF слишком большой ($fileSizeMBМБ). Загрузите PDF меньше 20МБ.'
                                : lang == 'ja'
                                    ? 'このPDFは大きすぎます（${fileSizeMB}MB）。20MB以下のPDFをお使いください。'
                                    : lang == 'ko'
                                        ? '이 PDF는 너무 큽니다（${fileSizeMB}MB）. 20MB 미만의 PDF를 업로드하세요.'
                                        : 'This PDF is too large (${fileSizeMB}MB). Please load a PDF under 20MB.';
        ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(msg));
        return;
      }

      // 6-20MB arası PDF → uyarı ver ama yükle
      if (isPdfFile && fileSize > 6 * 1024 * 1024 && mounted) {
        ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
            t('file.loading_large'),
            behavior: SnackBarBehavior.floating));
      }

      // 2) Metni dosyadan çıkar (arka planda, UI donmaz)
      String text;
      try {
        text = await _extractTextFromFile(file);
      } catch (e) {
        if (mounted) {
          setState(() => _isLoadingFile = false);
          ScaffoldMessenger.of(context).clearSnackBars();
          ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
            AppLang.code.value == 'tr'
                ? 'Dosya yüklenemedi: ${file.name}'
                : 'Could not load file: ${file.name}',
          ));
        }
        return;
      }

      if (!mounted) return;

      // PDF bozuk karakter tespiti — Türkçe PDF ise kontrol et
      if (isPdfFile && _isBrokenTurkishPdf(text)) {
        // Bozuk metin uyarısı + OCR önerisi
        ScaffoldMessenger.of(context).clearSnackBars();
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            backgroundColor: Colors.transparent,
            elevation: 0,
            behavior: SnackBarBehavior.floating,
            duration: const Duration(seconds: 6),
            padding: EdgeInsets.zero,
            content: Container(
              padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
              decoration: BoxDecoration(
                gradient: const LinearGradient(
                  colors: [kGoldMain, kGoldDark],
                  begin: Alignment.centerLeft,
                  end: Alignment.centerRight,
                ),
                borderRadius: BorderRadius.circular(8),
              ),
              child: Row(
                children: [
                  Expanded(
                      child: Text(t('pdf.broken_chars'),
                          style: TextStyle(color: Colors.white))),
                  GestureDetector(
                    onTap: () async {
                      ScaffoldMessenger.of(context).clearSnackBars();
                      if (!PremiumService.instance.hasFullAccess) {
                        final canFree =
                            await PremiumService.instance.canUseOcrFree();
                        if (!canFree) {
                          await navigateToPaywall(context);
                          return;
                        }
                        await PremiumService.instance.incrementOcrUses();
                      }
                      _openCameraWithOcr();
                    },
                    child: const Padding(
                      padding: EdgeInsets.only(left: 8),
                      child:
                          Icon(Icons.camera_alt, color: Colors.white, size: 22),
                    ),
                  ),
                ],
              ),
            ),
          ),
        );
      }

      // 3) Normalize paragraph indents before inserting
      final normalizedText = _normalizeParagraphIndents(text);

      // 4) Okuma alanına metni yaz + dosya adını sakla
      _isUpdatingTextProgrammatically = true;
      _userOcrText = true; // Dosya içeriği — şiir formatı uygulanmasın
      _trackTextChange(normalizedText);
      setState(() {
        _isLoadingFile = false;
        _text.text = normalizedText; // 🔥 ARTIK _text KULLANIYORUZ
        _selectedFileName = file.name;
        _text.selection = TextSelection.collapsed(offset: 0);
      });
      _buildTtsTextAndIndexMap(normalizedText);
      _isUpdatingTextProgrammatically = false;
      // Scroll to top when loading new text
      if (_scroll.hasClients) {
        _scroll.jumpTo(0);
      }
      // TextField render sonrası metni yeniden set et — birkaç frame bekle
      Future.delayed(const Duration(milliseconds: 300), () {
        if (!mounted) return;
        _isUpdatingTextProgrammatically = true;
        final current = _text.text;
        _text.text = '';
        setState(() {
          _text.text = current;
        });
        _text.selection = const TextSelection.collapsed(offset: 0);
        _isUpdatingTextProgrammatically = false;
        if (_scroll.hasClients) _scroll.jumpTo(0);
      });
      // Capture history (file open)
      _captureHistory(normalizedText, fileName: file.name);

      // Auto-detect language and switch silently
      final detectedLang = _detectLanguageFromText(normalizedText);
      if (detectedLang != null && mounted) {
        if (detectedLang == 'fr-FR') {
          _allowAutoFrenchOnce = true;
        }
        _switchToLanguageSilently(detectedLang);
      }

      // 5) Kullanıcıya güzel bir bilgi ver
      ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
          '${t('file.loaded')}: ${file.name}',
          behavior: SnackBarBehavior.floating));
    } catch (e) {
      if (!mounted) return;

      setState(() {
        _isLoadingFile = false;
      });

      ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
          AppLang.code.value == 'tr'
              ? 'Dosya açılırken hata: \$e'
              : 'Error while opening file: \$e',
          behavior: SnackBarBehavior.floating));
    }
  }

  // ================== FOTOĞRAFTAN OKU (OCR) ==================
  // OCR sonrası Türkçe/Latin karakter düzeltme
  // OCR'dan gelen şiirde dörtlükler arası boşluk genellikle tek \n olarak gelir.
  // Bu fonksiyon: şiir ise, belirli sayıda satırdan sonra \n\n ekler (dörtlük tespiti).
  String _restorePoetryStanzas(String text) {
    // OCR'dan gelen metni olduğu gibi koru — satır yapısına dokunma.
    // ML Kit zaten bloklar arasına \n\n koyuyor.
    // Sabit sayı ile boşluk eklemek serbest nazım, üçlük vb. için yanlış sonuç verir.
    return text;
  }

  /// OCR çıktısının kalitesini kontrol eder.
  /// Bozuk/anlamsız karakter oranı yüksekse true döner.
  bool _isOcrLowQuality(String raw) {
    if (raw.isEmpty) return true;
    int total = 0;
    int garbage = 0;
    for (final r in raw.runes) {
      // Boşluk ve satır sonu say ama garbage değil
      if (r == 0x20 || r == 0x0A || r == 0x0D) continue;
      total++;
      // Anlamlı karakter: harf (Latin, Kiril, Arapça, CJK vb.), rakam, yaygın noktalama
      final isLetter = (r >= 0x0041 && r <= 0x007A) || // A-Z a-z
          (r >= 0x00C0 && r <= 0x024F) || // Latin extended
          (r >= 0x0370 && r <= 0x03FF) || // Greek
          (r >= 0x0400 && r <= 0x04FF) || // Cyrillic
          (r >= 0x0600 && r <= 0x06FF) || // Arabic
          (r >= 0x0900 && r <= 0x097F) || // Devanagari
          (r >= 0x3040 && r <= 0x9FFF) || // CJK/Hiragana/Katakana
          (r >= 0xAC00 && r <= 0xD7A3); // Korean
      final isDigit = r >= 0x0030 && r <= 0x0039;
      final isPunct = [
        0x2E,
        0x2C,
        0x21,
        0x3F,
        0x3A,
        0x3B,
        0x27,
        0x22,
        0x28,
        0x29,
        0x2D,
        0x2014,
        0x2013,
        0x0130,
        0x0131
      ].contains(r);
      if (!isLetter && !isDigit && !isPunct) garbage++;
    }
    if (total == 0) return true;
    final garbageRatio = garbage / total;
    return garbageRatio >
        0.35; // %35'ten fazla bozuk karakter varsa düşük kalite
  }

  String _fixOcrText(String raw) {
    if (raw.isEmpty) return raw;

    String text = raw;

    // Birden fazla boşluğu teke indir
    text = text.replaceAll(RegExp(r' {2,}'), ' ');

    // Fazla boş satırları temizle
    text = text.replaceAll(RegExp(r'\n{3,}'), '\n\n');

    // ── Telefon UI yazılarını filtrele (screenshot'tan gelen sistem elementleri) ──
    final lines = text.split('\n');
    final filtered = <String>[];
    for (final line in lines) {
      final t = line.trim();
      if (t.isEmpty) {
        filtered.add('');
        continue;
      }
      // Saat formatı: "18:59", "09:57" gibi
      if (RegExp(r'^\d{1,2}:\d{2}(\s.*)?$').hasMatch(t)) continue;

      // Sinyal/batarya göstergesi: "100", "• 100", "aall 100", "l 100", ".l 100", "I 100"
      if (RegExp(r'^[•·\s\d%]+$').hasMatch(t) && t.length < 8) continue;
      if (RegExp(r'^[a-zA-Z•·|.\s]{0,6}\s*\d{2,3}\s*$').hasMatch(t) &&
          t.length < 14) continue;

      // Navigation / UI butonları (tam eşleşme)
      const uiWords = [
        'Home',
        'Search',
        'Back',
        'Notifications',
        'Recent',
        'Menu',
        'Share',
        'More',
        'Go to source',
        'Save',
        'Activity',
        'Visit',
        'Visit >',
        'More v',
        'X',
        'Learn More',
        'See More',
        'Close',
        'Cancel',
        '<',
        '>',
      ];
      if (uiWords.any((w) => t == w || t == '\$w >')) continue;

      // 1-2 harf satırları (G, X, kk gibi OCR artefaktları)
      if (RegExp(r'^[A-Za-z]{1,2}$').hasMatch(t)) continue;

      // E-ticaret / web UI kalıntıları — kısmi eşleşme yeterli
      if (RegExp(r'Check (website|here|for latest|for more)',
              caseSensitive: false)
          .hasMatch(t)) continue;
      if (RegExp(
              r'(latest pricing|and availability|subject to copyright|Images may be|Learn More)',
              caseSensitive: false)
          .hasMatch(t)) continue;
      if (RegExp(r'^\*\s*Check', caseSensitive: false).hasMatch(t)) continue;
      if (RegExp(r'^Go to source', caseSensitive: false).hasMatch(t)) continue;

      // Fiyat satırı tek başına: "$136.00*", "€29.99", "₺450" gibi
      if (RegExp(r'^[\$€£¥₺][\d,.]+[\*]?$').hasMatch(t)) continue;

      // Sadece noktalama / sembol satırları: "...", "* * *", "---"
      if (RegExp(r'^[.\-*•·_~=\s]{1,6}$').hasMatch(t)) continue;

      filtered.add(line);
    }
    text = filtered.join('\n');

    // Tekrar fazla boşlukları temizle
    text = text.replaceAll(RegExp(r'\n{3,}'), '\n\n');

    // ── Sütunlu menü tespiti ve birleştirme ──────────────────────────────────
    final mergeResult = _mergeMenuColumns(text);
    text = mergeResult['text'] as String;
    _lastOcrWasMultiColumn = mergeResult['isMultiColumn'] as bool;

    return text.trim();
  }

  bool _lastOcrWasMultiColumn = false;

  /// İki sütunlu menü OCR çıktısını tespit eder, uyarı flag'i döner.
  /// Fiyatları yemek adlarıyla birleştirmeyi artık yapmıyoruz — ML Kit sütun sırası
  /// tutarsız olduğundan eşleştirme yanlış sonuç verir. Sadece uyarı gösteriyoruz.
  Map<String, dynamic> _mergeMenuColumns(String text) {
    final lines = text.split('\n');
    if (lines.length < 3) return {'text': text, 'isMultiColumn': false};

    // Fiyat satırı mı? t360, ₺360, 360, 360 TL, $10, €15 gibi
    bool isPriceLine(String line) {
      final t = line.trim();
      return RegExp(
        r'^[t₺$€£]?\s*\d{1,5}([.,]\d{1,2})?\s*([t₺TLtl$€£]|TL|lira)?$',
        caseSensitive: false,
      ).hasMatch(t);
    }

    // Fiyat içeren satır mı? (satır içinde fiyat geçiyor)
    bool hasPrice(String line) {
      final t = line.trim();
      return RegExp(
        r'[₺t$€£]\s*\d{1,5}|\d{1,5}\s*[₺TL]|\d{2,5}\s*(TL|lira)|\d{2,4}$',
        caseSensitive: false,
      ).hasMatch(t);
    }

    // Kaç satır fiyat? Eğer %15+ fiyat satırı/içeriği varsa -> çok sütunlu menü
    final priceCount = lines.where((l) => isPriceLine(l) || hasPrice(l)).length;
    final nonEmptyCount = lines.where((l) => l.trim().isNotEmpty).length;
    // Fiyat içeriyorsa direkt true — menü tespiti
    final isMultiColumn = priceCount >= 3;

    return {'text': text, 'isMultiColumn': isMultiColumn};
  }

  // Tek satır sonlarını boşluğa, gerçek boş satırları paragrafa çeviren helper
  // Şiir ve liste/menü metinlerinde satır sonları korunur.
  String _normalizeForReading(String input, {bool isOcr = false}) {
    if (input.isEmpty) return input;

    // Tüm platformlarda satır sonlarını sadeleştir
    String text = input.replaceAll('\r\n', '\n').replaceAll('\r', '\n');

    // Satır yapısını koru mu? → Şiir VEYA kısa satırlı liste/menü
    // OCR metninde şiir formatı algılama — atla
    if (!isOcr && (_isPoetryText(text) || _isListOrMenuText(text))) {
      // Dörtlük/bölüm arası boşlukları koru
      text = text.replaceAll(RegExp(r'\n{4,}'), '\n\n\n');
      // Eğer hiç \n\n yoksa → dörtlükleri otomatik tespit et ve boşluk ekle
      if (!text.contains('\n\n') && _isPoetryText(text)) {
        text = _detectAndAddStanzaBreaks(text);
      }
      return text;
    }

    // Prose: 3+ newline → 2'ye indir
    text = text.replaceAll(RegExp(r'\n{3,}'), '\n\n');

    // Tire ile bölünmüş kelimeleri birleştir: "olay-\ndan" → "olaydan"
    text = text.replaceAllMapped(
      RegExp(r'([a-zA-ZÀ-ÿğüşıöçĞÜŞİÖÇ])-\n([a-zA-ZÀ-ÿğüşıöçĞÜŞİÖÇ])'),
      (m) => m[1]! + m[2]!,
    );
    // Sadece TEK newline olanları boşluğa çevir (prose/kitap modu)
    text = text.replaceAll(RegExp(r'(?<!\n)\n(?!\n)'), ' ');

    return text;
  }

  /// Menü, liste, fiyat listesi gibi kısa satırlı yapıları tespit eder.
  /// Satırların çoğu kısaysa (1-6 kelime) → liste/menü olarak kabul et, satırları koru.
  bool _isListOrMenuText(String text) {
    final lines = text
        .split('\n')
        .map((l) => l.trim())
        .where((l) => l.isNotEmpty)
        .toList();
    if (lines.length < 2) return false;

    int shortLines = 0;
    for (final line in lines) {
      final wordCount =
          line.split(RegExp(r'\s+')).where((w) => w.isNotEmpty).length;
      // 1-6 kelimelik satırlar → liste/menü kalemi
      if (wordCount >= 1 && wordCount <= 6) shortLines++;
    }
    // %60+ kısa satır → liste/menü
    return (shortLines / lines.length) >= 0.60;
  }

  /// Şiirde dörtlük aralarını otomatik tespit eder ve \n\n ekler.
  String _detectAndAddStanzaBreaks(String text) {
    final lines = text.split('\n').where((l) => l.trim().isNotEmpty).toList();
    if (lines.length < 4) return text;
    const stanzaSize = 4;
    final result = StringBuffer();
    for (int i = 0; i < lines.length; i++) {
      result.writeln(lines[i]);
      if ((i + 1) % stanzaSize == 0 && i + 1 < lines.length) {
        result.writeln();
      }
    }
    return result.toString().trim();
  }

  // Remove leading indentation from paragraphs (book view normalization)
  // Strips leading spaces/tabs/non-breaking spaces on each line while preserving paragraph breaks
  String _normalizeParagraphIndents(String input) {
    if (input.isEmpty) return input;

    // Normalize line endings
    String text = input.replaceAll('\r\n', '\n').replaceAll('\r', '\n');

    // Split into lines
    final lines = text.split('\n');
    final normalizedLines = <String>[];

    for (final line in lines) {
      // For blank lines, preserve them as-is
      if (line.trim().isEmpty) {
        normalizedLines.add('');
        continue;
      }

      // Strip leading whitespace: spaces, tabs, and non-breaking spaces (\u00A0)
      // Match all leading whitespace characters (space, tab, non-breaking space) at once
      final normalized = line.replaceFirst(RegExp(r'^[\t \u00A0]+'), '');

      normalizedLines.add(normalized);
    }

    // Join lines back together
    return normalizedLines.join('\n');
  }

  // 🖼 Fotoğraftan okuma (Image → OCR → metin → TTS + Scroll)
  Future<void> _openImageWithOcr() async {
    final ImagePicker picker = ImagePicker();
    final XFile? photo = await picker.pickImage(
      source: ImageSource.gallery,
      imageQuality: 95, // yüksek kalite → daha iyi OCR
    );

    // User cancelled
    if (photo == null) return;

    final path = photo.path;
    final name = photo.name;

    try {
      // Locale'e göre doğru script seç
      final locale = (_selectedLocale ?? 'en').toLowerCase();
      TextRecognitionScript script = TextRecognitionScript.latin;
      if (locale.startsWith('zh')) {
        script = TextRecognitionScript.chinese;
      } else if (locale.startsWith('ja')) {
        script = TextRecognitionScript.japanese;
      } else if (locale.startsWith('ko')) {
        script = TextRecognitionScript.korean;
      } else if (locale.startsWith('hi') || locale.startsWith('sa')) {
        script = TextRecognitionScript.devanagiri;
      }

      // 1) Image → Google ML Kit ile OCR
      final inputImage = InputImage.fromFilePath(path);
      final textRecognizer = TextRecognizer(script: script);
      final recognizedText = await textRecognizer.processImage(inputImage);
      await textRecognizer.close();

      // 2) OCR sonrası temizle ve düzelt
      final raw = recognizedText.text.trim();
      if (raw.isEmpty) {
        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
            t('file.errorLoading'),
            behavior: SnackBarBehavior.floating));
        return;
      }

      // Kalite kontrolü — bozuk metin uyarısı
      if (_isOcrLowQuality(raw)) {
        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
            t('ocr.lowQuality'),
            behavior: SnackBarBehavior.floating));
        return;
      }

      // OCR çıktısını temizle + prose/şiir normalizasyonu uygula
      final cleaned = _normalizeForReading(
          _normalizeParagraphIndents(_fixOcrText(raw)),
          isOcr: true);

      if (!mounted) return;
      _isUpdatingTextProgrammatically = true;
      _ocrImageCounter++;
      final ocrLabel = 'JPG_$_ocrImageCounter';
      _userOcrText = true; // OCR metni — şiir formatı uygulanmasın
      _trackTextChange(cleaned);
      setState(() {
        _text.text = cleaned;
        _currentFile = ocrLabel;
        _selectedFileName = ocrLabel;
        _text.selection = TextSelection.collapsed(offset: 0);
      });
      _buildTtsTextAndIndexMap(cleaned);
      _isUpdatingTextProgrammatically = false;
      if (_scroll.hasClients) _scroll.jumpTo(0);
      _captureHistory(cleaned, fileName: ocrLabel);

      if (mounted) {
        final ocrUsesNow = await PremiumService.instance.getOcrUses();
        final nextWillPaywall = !PremiumService.instance.hasFullAccess &&
            ocrUsesNow >= PremiumService.freeOcrUses;
        ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
            nextWillPaywall
                ? _ocrTriedToast()
                : '${t('file.loaded')} $ocrLabel',
            behavior: SnackBarBehavior.floating));
        if (_lastOcrWasMultiColumn) {
          Future.delayed(const Duration(milliseconds: 1200), () {
            if (!mounted) return;
            ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
                t('ocr.multicolumn'),
                behavior: SnackBarBehavior.floating));
          });
        }
        // Dil hint snackbar — her zaman çıkar
        Future.delayed(const Duration(milliseconds: 1500), () {
          if (!mounted) return;
          ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
              t('ocr.langHint'),
              behavior: SnackBarBehavior.floating));
        });
        // Dil uyumsuzluğu kontrolü — _userManuallySelectedLanguage ve _autoDetectEnabled'dan bağımsız
        final currentLocale = _selectedLocale ?? '';
        final wasManual = _userManuallySelectedLanguage;
        final wasAutoDetect = _autoDetectEnabled;
        _userManuallySelectedLanguage = false;
        _autoDetectEnabled = true;
        final detectedLang = _detectLanguageFromText(cleaned);
        _userManuallySelectedLanguage = wasManual;
        _autoDetectEnabled = wasAutoDetect;
        if (detectedLang != null) {
          if (detectedLang == 'fr-FR') _allowAutoFrenchOnce = true;
          _switchToLanguageSilently(detectedLang);
          final detectedBase = detectedLang.toLowerCase().split('-')[0];
          final currentBase = currentLocale.toLowerCase().split('-')[0];
          if (detectedBase != currentBase) {
            Future.delayed(const Duration(milliseconds: 1500), () {
              if (!mounted) return;
              ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
                  t('ocr.langMismatch'),
                  behavior: SnackBarBehavior.floating));
            });
          }
        }
      }

      await _savePersisted();
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
          t('file.errorLoading'),
          behavior: SnackBarBehavior.floating));
    }
  }

  // 📷 Kamera ile fotoğraf çek ve OCR yap (Camera → OCR → metin → TTS + Scroll)
  Future<void> _openCameraWithOcr() async {
    if (!mounted) return;
    final source = await showModalBottomSheet<ImageSource>(
      context: context,
      backgroundColor: Colors.transparent,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(18)),
      ),
      builder: (ctx) {
        final isDark = Theme.of(ctx).brightness == Brightness.dark;
        final sheetBg = isDark ? const Color(0xFF222222) : kCream;
        final primaryText = isDark ? kBeigeDark : kText;
        final secondaryText =
            isDark ? kBeigeDark.withValues(alpha: 0.8) : kBeigeDark;
        return Container(
          decoration: BoxDecoration(
            color: sheetBg,
            borderRadius: const BorderRadius.vertical(top: Radius.circular(18)),
          ),
          child: SafeArea(
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                ListTile(
                  leading: Icon(Icons.camera_alt, color: primaryText),
                  title: Text(
                    AppLang.code.value == 'tr' ? 'Kamera' : 'Camera',
                    style: TextStyle(
                        color: primaryText,
                        fontSize: 15,
                        fontWeight: FontWeight.normal),
                  ),
                  subtitle: Text(
                    AppLang.code.value == 'tr'
                        ? 'Fotoğraf çek ve metni oku'
                        : 'Take a photo and read text',
                    style: TextStyle(color: secondaryText, fontSize: 12),
                  ),
                  onTap: () => Navigator.pop(ctx, ImageSource.camera),
                ),
                const Divider(height: 1),
                ListTile(
                  leading: Icon(Icons.photo_library, color: primaryText),
                  title: Text(
                    AppLang.code.value == 'tr' ? 'Galeri' : 'Gallery',
                    style: TextStyle(
                        color: primaryText,
                        fontSize: 15,
                        fontWeight: FontWeight.normal),
                  ),
                  subtitle: Text(
                    AppLang.code.value == 'tr'
                        ? 'Galeriden fotoğraf seç'
                        : 'Choose a photo from gallery',
                    style: TextStyle(color: secondaryText, fontSize: 12),
                  ),
                  onTap: () => Navigator.pop(ctx, ImageSource.gallery),
                ),
              ],
            ),
          ),
        );
      },
    );
    if (source == null) return;

    try {
      final ImagePicker picker = ImagePicker();
      XFile? photo;
      try {
        photo = await picker.pickImage(
          source: source,
          imageQuality: 95,
        );
      } catch (e) {
        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
            t('ocr.cameraError'),
            behavior: SnackBarBehavior.floating));
        return;
      }

      if (photo == null) return;

      final path = photo.path;
      final name = photo.name;

      try {
        // Locale'e göre doğru script seç
        final locale = (_selectedLocale ?? 'en').toLowerCase();
        TextRecognitionScript script = TextRecognitionScript.latin;
        if (locale.startsWith('zh')) {
          script = TextRecognitionScript.chinese;
        } else if (locale.startsWith('ja')) {
          script = TextRecognitionScript.japanese;
        } else if (locale.startsWith('ko')) {
          script = TextRecognitionScript.korean;
        } else if (locale.startsWith('hi') || locale.startsWith('sa')) {
          script = TextRecognitionScript.devanagiri;
        }

        // 1) Image → Google ML Kit ile OCR
        final inputImage = InputImage.fromFilePath(path);
        final textRecognizer = TextRecognizer(script: script);
        final recognizedText = await textRecognizer.processImage(inputImage);
        await textRecognizer.close();

        final raw = recognizedText.text.trim();
        if (raw.isEmpty) {
          if (!mounted) return;
          ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
              t('file.errorLoading'),
              behavior: SnackBarBehavior.floating));
          return;
        }

        // Kalite kontrolü — bozuk metin uyarısı
        if (_isOcrLowQuality(raw)) {
          if (!mounted) return;
          ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
              t('ocr.lowQuality'),
              behavior: SnackBarBehavior.floating));
          return;
        }

        // 2) OCR sonrası temizle ve normalize et (prose/şiir ayrımı dahil)
        final cleaned = _normalizeForReading(
            _normalizeParagraphIndents(_fixOcrText(raw)),
            isOcr: true);

        if (!mounted) return;
        _isUpdatingTextProgrammatically = true;
        final finalText =
            _text.text.trim().isEmpty ? cleaned : '${_text.text}\n\n$cleaned';
        _ocrImageCounter++;
        final ocrLabel = 'JPG_$_ocrImageCounter';
        _userOcrText = true; // OCR metni — şiir formatı uygulanmasın
        _trackTextChange(finalText);
        setState(() {
          if (_text.text.trim().isEmpty) {
            _text.text = cleaned;
          } else {
            _text.text = '${_text.text}\n\n$cleaned';
          }
          _currentFile = ocrLabel;
          _selectedFileName = ocrLabel;
          _text.selection = TextSelection.collapsed(
            offset: _text.text.length,
          );
        });
        _buildTtsTextAndIndexMap(_text.text);
        _isUpdatingTextProgrammatically = false;
        _captureHistory(_text.text, fileName: ocrLabel);

        if (mounted) {
          ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
              '${t('file.loaded')} $ocrLabel',
              behavior: SnackBarBehavior.floating));
          if (_lastOcrWasMultiColumn) {
            Future.delayed(const Duration(milliseconds: 1200), () {
              if (!mounted) return;
              ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
                  t('ocr.multicolumn'),
                  behavior: SnackBarBehavior.floating));
            });
          }
          // Dil hint snackbar — her zaman çıkar
          Future.delayed(const Duration(milliseconds: 1500), () {
            if (!mounted) return;
            ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
                t('ocr.langHint'),
                behavior: SnackBarBehavior.floating));
          });
          // OCR sonrası dil algıla ve otomatik değiştir
          WidgetsBinding.instance.addPostFrameCallback((_) {
            if (!mounted) return;
            final wasManual = _userManuallySelectedLanguage;
            final wasAutoDetect = _autoDetectEnabled;
            _userManuallySelectedLanguage = false;
            _autoDetectEnabled = true;
            _runAutoLanguageDetectionIfNeeded(source: 'camera_ocr');
            _userManuallySelectedLanguage = wasManual;
            _autoDetectEnabled = wasAutoDetect;
          });
          if (false) {
            // eski snackbar kodu devre dışı
            final detectedBase = '';
            final currentBase = '';
            if (detectedBase != currentBase) {
              Future.delayed(const Duration(milliseconds: 1500), () {
                if (!mounted) return;
                ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
                    t('ocr.langMismatch'),
                    behavior: SnackBarBehavior.floating));
              });
            }
          }
        }

        await _savePersisted();
      } catch (e) {
        if (!mounted) return;
        ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
            t('file.errorLoading'),
            behavior: SnackBarBehavior.floating));
      }
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
          t('file.errorLoading'),
          behavior: SnackBarBehavior.floating));
    }
  }

  // Nova – TTS & Scroll kilitleri
  bool _isTtsPlaying = false;
  bool _isAutoScrollOn = false;

  // TTS – insan sesine en yakın varsayılanlar
  double _ttsPitch = 1.0; // Doğal insan tonu
  // Note: _ttsRate removed - using _rate instead
  double _ttsVolume = 1.0; // Tam ses
  String _ttsGender = 'female'; // Varsayılan kadın ses

  Color _menuTextColor(BuildContext c) {
    final isDark = Theme.of(c).brightness == Brightness.dark;
    return isDark ? Colors.white : Colors.black;
  }

  // Tablet tespiti - kısa kenar >= 600px genellikle tablet
  bool _isTablet(BuildContext context) {
    final size = MediaQuery.of(context).size;
    final shortestSide = size.shortestSide;
    return shortestSide >= 600;
  }

  void _pauseAutoScroll() {
    if (mounted) {
      setState(() => _isPaused = true);
    } else {
      _isPaused = true;
    }
  }

  void _resumeAutoScroll() {
    if (mounted) {
      setState(() => _isPaused = false);
    } else {
      _isPaused = false;
    }
    if (_autoScrollTimer == null && _autoScroll) {
      _startAutoScrollFresh();
    }
  }

  // TASK: Hard stop for scroll - MUST fully reset objects
  // This method ensures complete cleanup so scroll can restart cleanly
  void _stopAutoScrollHard() {
    _autoScrollTimer?.cancel();
    _autoScrollTimer = null;
    _syntheticStepTimer?.cancel();
    _syntheticStepTimer = null;
    if (mounted) {
      setState(() {
        _autoScroll = false;
        _isAutoScrollOn = false;
        _isPaused = false; // STOP is not pause
      });
    } else {
      _autoScroll = false;
      _isAutoScrollOn = false;
      _isPaused = false;
    }
  }

  void _startAutoScrollFresh() {
    _stopAutoScrollHard();

    // Compute pixels per tick (16ms = 0.016s)
    _autoScrollPxPerTick = _autoScrollPxPerSec * 0.016;

    // 1) Ensure flags are set BEFORE scheduling post-frame callback
    if (mounted) {
      setState(() {
        _autoScroll = true;
        _isAutoScrollOn = true;
        _isPaused = false;
      });
    } else {
      _autoScroll = true;
      _isAutoScrollOn = true;
      _isPaused = false;
    }

    // IMPORTANT: start after first frame so _scroll has clients and extents exist
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!_autoScroll || _isPaused) return;

      // Handle "start from top" for new text before starting scroll
      if (_shouldStartFromTop && _scroll.hasClients) {
        _scroll.jumpTo(0.0);
        _shouldStartFromTop = false;
      }

      // 2) Always create Timer.periodic if _autoScroll is true (DO NOT require layout to be ready)
      _autoScrollTimer?.cancel();
      _autoScrollTimer = Timer.periodic(const Duration(milliseconds: 16), (_) {
        if (!_autoScroll || _isPaused) return;
        // BOTH mode: scroll is driven by follow-highlight only; scroll speed has no effect
        if (_readingMode == ReadingMode.both) return;
        if (!_scroll.hasClients) return;

        final pos = _scroll.position;
        final max = pos.maxScrollExtent;

        // If layout not ready (max==0) wait until layout ready, but DO NOT stop
        if (max <= 0) return;

        final next = (pos.pixels + _autoScrollPxPerTick).clamp(0.0, max);

        // Reached end => stop cleanly
        if ((next - pos.pixels).abs() < 0.01) {
          _stopAutoScrollHard();
          return;
        }

        // Scroll secs tracking (16ms * ~62 = ~1 sn)
        _scrollTickCount = (_scrollTickCount ?? 0) + 1;
        if (_scrollTickCount! >= 62) {
          _scrollTickCount = 0;
          if (!PremiumService.instance.hasFullAccess) {
            _scrollSecsUsed++;
            if (_scrollSecsUsed % 10 == 0) {
              PremiumService.instance.setScrollSecs(_scrollSecsUsed);
            }
            if (_scrollSecsUsed >= PremiumService.freeDailyScrollSecs) {
              PremiumService.instance.setScrollSecs(_scrollSecsUsed);
              _stopAutoScrollHard();
              if (mounted) setState(() => _scrollLimitReached = true);
              _showScrollLimitPaywall();
              return;
            }
          }
        }

        _scroll.jumpTo(next);
      });
    });
  }

  // Scroll to caret/index position in text (Task 3 helper).
  void _scrollToCaretPosition(int textOffset) {
    _scrollToIndex(textOffset);
  }

  // Helper to determine if highlight should be applied immediately (short text / no scroll case)
  bool _shouldApplyHighlightImmediately() {
    // If auto-scroll isn't running, we may not get frames.
    if (!(_autoScroll && !_isPaused)) return true;

    // If scroll can't actually scroll, don't rely on post-frame scheduling.
    if (!_scroll.hasClients) return true;
    final max = _scroll.position.maxScrollExtent;
    if (max <= 0.0) return true;

    return false;
  }

  /// Build TTS text from UI text with whitespace normalization and index map.
  /// Call whenever the reading UI text is set (file load, paste, etc.).
  void _buildTtsTextAndIndexMap(String uiText) {
    _uiTextForReading = uiText;
    // Not: _currentSentenceIndex burada sıfırlanmıyor
    // Sıfırlama sadece yeni metin yüklenince (_trackTextChange) yapılır

    final sb = StringBuffer();
    final map = <int>[];

    // Normalizasyon: TTS'nin UI ile aynı mantıkta ilerlemesi için
    // - Birden fazla boşluğu tek boşluğa indir
    // - \n kalsın (satır yapısı önemli)
    // - Tab'ı boşluğa çevir
    // - NBSP vs -> normal space
    bool lastWasSpace = false;

    for (int ui = 0; ui < uiText.length; ui++) {
      String ch = uiText[ui];

      // unify whitespace
      if (ch == '\t') ch = ' ';
      if (ch == '\u00A0') ch = ' '; // nbsp

      final isSpace = (ch == ' ');
      final isNewline = (ch == '\n');

      if (isNewline) {
        sb.write('\n');
        map.add(ui); // ttsIndex -> uiIndex
        lastWasSpace = false;
        continue;
      }

      if (isSpace) {
        if (lastWasSpace) {
          // skip extra spaces in ttsText (BUT preserve mapping continuity)
          continue;
        }
        sb.write(' ');
        map.add(ui);
        lastWasSpace = true;
        continue;
      }

      // keep everything else as-is
      sb.write(ch);
      map.add(ui);
      lastWasSpace = false;
    }

    _ttsText = sb.toString();
    _mapTtsToUi = map;
  }

  /// Map TTS character index to UI character index (for progress handler).
  int _ttsIndexToUi(int ttsIndex) {
    if (_mapTtsToUi.isEmpty) return ttsIndex.clamp(0, _uiTextForReading.length);
    if (ttsIndex <= 0)
      return _mapTtsToUi.first.clamp(0, _uiTextForReading.length);
    if (ttsIndex >= _mapTtsToUi.length)
      return _mapTtsToUi.last.clamp(0, _uiTextForReading.length);
    return _mapTtsToUi[ttsIndex].clamp(0, _uiTextForReading.length);
  }

  /// Map UI character index to TTS character index (for resume/startOffset).
  int _uiIndexToTts(int uiIndex) {
    if (_mapTtsToUi.isEmpty) return uiIndex.clamp(0, _ttsText.length);
    for (int i = 0; i < _mapTtsToUi.length; i++) {
      if (_mapTtsToUi[i] >= uiIndex) return i.clamp(0, _ttsText.length);
    }
    return _ttsText.length;
  }

  /// Build a character-level alignment map: spokenIndex → offset in originalText.
  /// Uses a greedy two-pointer approach: for each char in spoken, find it in
  /// original at or after the current original pointer. If not found within a
  /// small lookahead window, the spoken char was inserted by transformation
  /// (e.g. Roman-numeral expansion) and we map it to the current original position.
  List<int> _buildSpokenToOrigMap(String original, String spoken) {
    final map = List<int>.filled(spoken.length + 1, original.length);
    int oi = 0; // pointer into original
    for (int si = 0; si < spoken.length; si++) {
      final sc = spoken[si].toLowerCase();
      // Try to find spoken char in original within a lookahead window
      bool found = false;
      // Window: allow up to 32 chars of drift per character for transformations
      for (int look = 0; look < 32 && oi + look < original.length; look++) {
        if (original[oi + look].toLowerCase() == sc) {
          oi += look; // advance original to match
          map[si] = oi;
          oi++;
          found = true;
          break;
        }
      }
      if (!found) {
        // Transformation inserted this char; map to current original position
        map[si] = oi.clamp(0, original.length);
      }
    }
    map[spoken.length] = original.length; // sentinel
    return map;
  }

  /// Translate a spoken-text offset to an offset in the original chunk text.
  int _spokenOffsetToOrig(int spokenOffset) {
    if (_spokenToOrigMap.isEmpty) return spokenOffset;
    final clamped = spokenOffset.clamp(0, _spokenToOrigMap.length - 1);
    return _spokenToOrigMap[clamped];
  }

  /// Chunk _ttsText into exact substrings (no content change) so progress indices match.
  List<String> _chunkTtsTextPreserving(String ttsText, {int maxChars = 320}) {
    if (ttsText.isEmpty) return [];
    final out = <String>[];
    int i = 0;
    while (i < ttsText.length) {
      int end = (i + maxChars).clamp(0, ttsText.length);
      // Prefer break at sentence end or newline
      if (end < ttsText.length) {
        final segment = ttsText.substring(i, end);
        final lastPeriod = segment.lastIndexOf(RegExp(r'[.!?\n]'));
        if (lastPeriod >= 0 && lastPeriod > maxChars ~/ 2) {
          end = i + lastPeriod + 1;
        }
      }
      if (end <= i) end = (i + maxChars).clamp(0, ttsText.length);
      out.add(ttsText.substring(i, end));
      i = end;
    }
    return out;
  }

  /// WORD SNAP: Delimiter check (whitespace + punctuation) so highlight stays on whole words.
  bool _isDelimiter(String ch) {
    if (ch.isEmpty) return true;
    if (ch == ' ' || ch == '\n' || ch == '\t' || ch == '\r') return true;
    final delims = '.,;:!?()[]{}<>"\'""' '•…—–-_/\\|@#\$%^&*+=~`';
    return delims.contains(ch);
  }

  /// WORD SNAP: Snap [start, end) to whole word bounds in [text]; no partial word or space-only highlight.
  ({int s, int e}) _snapToWordBounds(String text, int start, int end) {
    final len = text.length;
    int s = start.clamp(0, len);
    int e = end.clamp(0, len);
    if (e < s) e = s;

    final locale = (_selectedLocale ?? '').toLowerCase();
    final isCjk = locale.startsWith('zh') ||
        locale.startsWith('ja') ||
        locale.startsWith('ko');
    final isRtl = false; // RTL disabled — to be fixed later
    // final isRtl = locale.startsWith('ar') ||
    //     locale.startsWith('he') ||
    //     locale.startsWith('iw');

    // CJK: her karakter kendi başına kelime — max 2 karakter highlight
    if (isCjk) {
      if (s >= len) return (s: len, e: len);
      // Sadece s konumundaki karakteri highlight et (boşluk/noktalama atla)
      while (s < len && _isDelimiter(text[s])) s++;
      if (s >= len) return (s: len, e: len);
      // CJK karakteri mi kontrol et
      final cp = text.codeUnitAt(s);
      final isCjkChar = (cp >= 0x4E00 && cp <= 0x9FFF) ||
          (cp >= 0x3040 && cp <= 0x30FF) ||
          (cp >= 0xAC00 && cp <= 0xD7AF);
      if (isCjkChar) {
        return (s: s, e: (s + 1).clamp(0, len));
      }
      // CJK değilse normal kelime snap
    }

    // RTL (Arapça/İbranice): boşlukla ayrılmış kelime sınırı
    if (isRtl) {
      // Anchor olarak start kullan (end değil!) — RTL'de TTS start daha güvenilir
      int anchor = s.clamp(0, len > 0 ? len - 1 : 0);
      // Boşluk atla
      while (anchor < len && _isDelimiter(text[anchor])) anchor++;
      if (anchor >= len) return (s: len, e: len);
      // Sola genişlet (RTL kelime başı)
      int left = anchor;
      while (left > 0 && !_isDelimiter(text[left - 1])) left--;
      // Sağa genişlet (RTL kelime sonu)
      int right = anchor;
      while (right < len && !_isDelimiter(text[right])) right++;
      if (right <= left) return (s: s, e: e);
      return (s: left, e: right);
    }

    // LTR diller: orijinal mantık
    // Skip leading whitespace in the provided range
    while (s < len && _isDelimiter(text[s])) s++;
    if (s >= len) return (s: len, e: len);

    // Use the midpoint of [s, e] as the anchor
    final anchor = (s + e) ~/ 2 < len ? (s + e) ~/ 2 : s;

    // Expand left to word start
    int left = anchor;
    while (left > 0 && !_isDelimiter(text[left - 1])) left--;

    // Expand right to word end
    int right = anchor;
    while (right < len && !_isDelimiter(text[right])) right++;

    if (right <= left) return (s: s, e: e);

    return (s: left, e: right);
  }

  /// Returns true if the current TTS locale uses a script that has no spaces
  /// between words (CJK) or is RTL (Hebrew, Arabic) where Google TTS sends
  /// whole-sentence progress instead of word-by-word progress.
  bool _isSyntheticStepLocale() {
    final locale = (_selectedLocale ?? '').toLowerCase();
    return locale.startsWith('zh') ||
        locale.startsWith('ja') ||
        locale.startsWith('ko');
    // RTL (Arabic/Hebrew) highlight disabled — to be fixed later:
    // || locale.startsWith('he')
    // || locale.startsWith('iw')
    // || locale.startsWith('ar')
  }

  /// For CJK/RTL: splits the TTS range into single characters (CJK) or
  /// short word-like chunks (Hebrew/Arabic split on spaces) and steps through
  /// them one by one at a pace that matches the TTS speech rate.
  int _lastStepperStart = -1;
  int _lastStepperEnd = -1;

  void _startSyntheticStepper(int start, int end) {
    final text = _text.text;
    if (text.isEmpty || start >= end) return;

    // Aynı aralık için stepper zaten çalışıyorsa yeniden başlatma
    if (_syntheticStepTimer != null &&
        _lastStepperStart == start &&
        _lastStepperEnd == end) {
      return;
    }

    _lastStepperStart = start;
    _lastStepperEnd = end;
    _syntheticStepTimer?.cancel();
    _syntheticStepTimer = null;

    final safeStart = start.clamp(0, text.length);
    final safeEnd = end.clamp(0, text.length);
    final segment = text.substring(safeStart, safeEnd);

    // Build step list: for Arabic/Hebrew split on whitespace; for CJK each char
    final locale = (_selectedLocale ?? '').toLowerCase();
    final isRtlSpaced = false; // RTL disabled — to be fixed later
    // final isRtlSpaced = locale.startsWith('he') ||
    //     locale.startsWith('iw') ||
    //     locale.startsWith('ar');

    List<({int s, int e})> steps = [];
    if (isRtlSpaced) {
      // RTL word-level chunks — disabled
      // final regex = RegExp(r'\S+');
      // for (final m in regex.allMatches(segment)) {
      //   steps.add((s: safeStart + m.start, e: safeStart + m.end));
      // }
    } else {
      // CJK: each character is its own step, skip whitespace/punctuation
      for (int i = 0; i < segment.length; i++) {
        final ch = segment[i];
        if (!_isDelimiter(ch)) {
          steps.add((s: safeStart + i, e: safeStart + i + 1));
        }
      }
    }

    if (steps.isEmpty) return;

    // Estimate ms per step using TTS rate:
    // Base: ~150ms per char at rate=0.5. Adjust by rate.
    // RTL: average Arabic/Hebrew word is ~5 chars
    final totalChars = segment.replaceAll(RegExp(r'\s'), '').length;
    final rateAdjust =
        (0.5 / _rate.clamp(0.1, 1.0)); // slower rate = longer per step
    final estimatedTotalMs =
        (totalChars * 150 * rateAdjust).round().clamp(300, 12000);
    final msPerStep = (estimatedTotalMs / steps.length).round().clamp(100, 800);

    int stepIndex = 0;

    // RTL için direkt highlight uygula — _snapToWordBounds atla (zaten kelime sınırında)
    // applyStep disabled — RTL highlight to be fixed later
    // void applyStep(int s, int e) {
    //   if (!mounted) return;
    //   setState(() {
    //     _ttsHighlightStart = s;
    //     _ttsHighlightEnd = e;
    //     _lastUiStart = s;
    //     _lastUiEnd = e;
    //   });
    //   WidgetsBinding.instance.addPostFrameCallback((_) {
    //     if (mounted) _updateHighlightRectsAndScroll(s, e);
    //   });
    // }

    // İlk adımı hemen göster
    if (isRtlSpaced) {
      // applyStep(steps[0].s, steps[0].e); // RTL disabled
    } else {
      _handleProgress(steps[0].s, steps[0].e);
    }
    stepIndex = 1;

    if (steps.length == 1) return;

    _syntheticStepTimer =
        Timer.periodic(Duration(milliseconds: msPerStep), (timer) {
      if (!mounted || stepIndex >= steps.length) {
        timer.cancel();
        return;
      }
      final step = steps[stepIndex++];
      if (isRtlSpaced) {
        // applyStep(step.s, step.e); // RTL disabled
      } else {
        _handleProgress(step.s, step.e);
      }
    });
  }

  /// Progress handler: snap range to word bounds and set highlight (single source for highlight).
  void _handleProgress(int start, int end) {
    final text = _text.text;
    if (text.isEmpty) return;

    final snapped = _snapToWordBounds(text, start, end);
    final s = snapped.s;
    final e = snapped.e;

    if (s >= e) return;
    if (!mounted) return;

    setState(() {
      _ttsHighlightStart = s;
      _ttsHighlightEnd = e;
      _lastUiStart = s;
      _lastUiEnd = e;
    });

    // After the frame is painted, pull real pixel rects from RenderEditable
    // and use them for both highlight painting AND scroll positioning.
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      _updateHighlightRectsAndScroll(s, e);
    });
  }

  /// Uses the actual RenderEditable to get pixel-accurate highlight rects AND scroll position.
  /// RenderEditable boxes are already in the coordinate space of the RenderEditable itself.
  /// The CustomPaint is Positioned.fill over the same Stack that contains the TextField,
  /// so we need boxes relative to the Stack's top-left — which equals the RenderEditable's
  /// own offset within that Stack.
  void _updateHighlightRectsAndScroll(int start, int end) {
    if (!mounted) return;

    final ctx = _readingTextKey.currentContext;
    if (ctx == null) {
      _scrollToCurrentHighlight();
      return;
    }

    // Walk render tree to find RenderEditable inside TextField
    // Wrapped in try/catch for older Android devices (e.g. Samsung A07)
    // where the render tree structure may differ and visitChildren can throw.
    RenderEditable? renderEditable;
    void findRE(RenderObject obj) {
      if (renderEditable != null) return;
      if (obj is RenderEditable) {
        renderEditable = obj;
        return;
      }
      try {
        obj.visitChildren(findRE);
      } catch (_) {}
    }

    final ro = ctx.findRenderObject();
    if (ro != null) {
      try {
        findRE(ro);
      } catch (_) {}
    }

    if (renderEditable == null) {
      // Fallback for older devices (e.g. Samsung A07) where RenderEditable
      // cannot be found in the render tree. Use TextPainter to approximate
      // highlight rects so the highlight is still painted.
      _computeHighlightRectsViaTextPainter(start, end);
      _scrollToCurrentHighlight();
      return;
    }

    final re = renderEditable!;
    final safeStart = start.clamp(0, _text.text.length);
    // Sondaki boşluk/newline karakterleri hariç tut → satır sonu boşluğu boyanmasın
    int rawEnd = end.clamp(0, _text.text.length);
    while (rawEnd > safeStart &&
        (_text.text[rawEnd - 1] == ' ' || _text.text[rawEnd - 1] == '\n')) {
      rawEnd--;
    }
    final safeEnd = rawEnd;

    List<TextBox> boxes;
    try {
      boxes = re.getBoxesForSelection(
        TextSelection(baseOffset: safeStart, extentOffset: safeEnd),
      );
    } catch (_) {
      _scrollToCurrentHighlight();
      return;
    }

    if (boxes.isEmpty) {
      _scrollToCurrentHighlight();
      return;
    }

    // ─── Clamp box widths to actual word width ──────────────────────────────
    // Flutter getBoxesForSelection: satır sonu kelimede box.right = satır genişliği döner.
    // İPUCU: Noktalama işareti sonrasındaysa Flutter doğru döndürüyor.
    // ÇÖZÜM: safeEnd'i bir karakter öteye uzat (boşluk/sonraki char dahil et),
    // genişletilmiş boxes'ın LAST box'ını at → kalan box'lar doğru right'a sahip.
    List<TextBox> clampedBoxes;
    try {
      if (boxes.isNotEmpty) {
        final text = _text.text;
        final nextChar = safeEnd < text.length ? text[safeEnd] : '';
        final hasPunctAfter = nextChar.isNotEmpty &&
            const ['.', ',', ':', ';', '!', '?', ')', '"'].contains(nextChar);

        if (!hasPunctAfter && safeEnd < text.length) {
          // Bir karakter öteye uzatılmış boxes al
          final extBoxes = re.getBoxesForSelection(
            TextSelection(baseOffset: safeStart, extentOffset: safeEnd + 1),
          );
          if (extBoxes.length >= 2) {
            // Son box sonraki karaktere ait → at, geriye kalan doğru
            clampedBoxes = extBoxes.sublist(0, extBoxes.length - 1);
          } else if (extBoxes.length == 1) {
            // Tek box: right'ı orijinal boxes'ın right'ından küçükse kullan
            final origRight = boxes.last.right;
            final extRight = extBoxes.last.right;
            if (extRight < origRight) {
              clampedBoxes = extBoxes;
            } else {
              clampedBoxes = boxes;
            }
          } else {
            clampedBoxes = boxes;
          }
        } else {
          // Noktalama var veya metin sonu → orijinal boxes doğru
          clampedBoxes = boxes;
        }
      } else {
        clampedBoxes = boxes;
      }
    } catch (_) {
      clampedBoxes = boxes;
    }

    // ─── Coordinate transform ───────────────────────────────────────────────
    // The CustomPaint lives in the same Stack as the TextField and is
    // Positioned.fill, so its (0,0) equals the Stack widget's (0,0).
    // RenderEditable's (0,0) is offset from the Stack by its padding/position.
    // We get that offset by converting RenderEditable's local (0,0) to the
    // Stack's local coordinate space via the Stack's RenderBox.
    //
    // Stack's RenderBox = the LayoutBuilder ancestor that wraps both widgets.
    // We find it via the same _readingTextKey context's parent.
    RenderBox? stackBox;
    try {
      // _readingTextKey is on the TextField; its parent is the Stack.
      // Walk up to find the first RenderBox ancestor that is NOT RenderEditable.
      RenderObject? cur = ro!.parent;
      while (cur != null) {
        if (cur is RenderBox && cur is! RenderEditable) {
          stackBox = cur;
          break;
        }
        cur = cur.parent;
      }
    } catch (_) {}

    final reBox = re as RenderBox;
    List<Rect> stackRects;

    if (stackBox != null) {
      // Offset of RenderEditable (0,0) in Stack-local coordinates
      final reOriginInStack =
          reBox.localToGlobal(Offset.zero, ancestor: stackBox);
      stackRects = clampedBoxes.map((b) {
        return Rect.fromLTRB(
          b.left + reOriginInStack.dx,
          b.top + reOriginInStack.dy,
          b.right + reOriginInStack.dx,
          b.bottom + reOriginInStack.dy,
        );
      }).toList();
    } else {
      // Fallback: use RenderEditable-local coords (works when RE fills the Stack)
      stackRects = clampedBoxes
          .map((b) => Rect.fromLTRB(b.left, b.top, b.right, b.bottom))
          .toList();
    }

    if (mounted) setState(() => _highlightRects = stackRects);

    // ─── Scroll so the word is visible ──────────────────────────────────────
    if (!_scroll.hasClients) return;

    // Word's global Y (top of first box)
    final wordGlobalY = reBox.localToGlobal(Offset(0, boxes.first.top)).dy;

    // Viewport's global Y
    RenderBox? vpBox;
    try {
      vpBox = _scroll.position.context.storageContext.findRenderObject()
          as RenderBox?;
    } catch (_) {}

    if (vpBox == null) {
      _scrollToCurrentHighlight();
      return;
    }

    final vpGlobalY = vpBox.localToGlobal(Offset.zero).dy;
    final vpHeight = _scroll.position.viewportDimension;
    final wordRelY = wordGlobalY - vpGlobalY; // position within viewport

    final bandTop = vpHeight * 0.18;
    final bandBottom = vpHeight * 0.72;

    if (wordRelY >= bandTop && wordRelY <= bandBottom)
      return; // already visible

    final targetOffset = (_scroll.offset + wordRelY - vpHeight * 0.35).clamp(
        _scroll.position.minScrollExtent, _scroll.position.maxScrollExtent);

    if ((targetOffset - _scroll.offset).abs() < 8) return;

    _scroll.animateTo(
      targetOffset,
      duration: const Duration(milliseconds: 500),
      curve: Curves.easeInOutCubic,
    );
  }

  /// TTS progress → UI indices via map, then _handleProgress (word snap + highlight).
  void _onTtsProgressMapped(int start, int end) {
    int uiStart = _ttsIndexToUi(start);
    int uiEnd = _ttsIndexToUi(end);
    if (uiEnd < uiStart) uiEnd = uiStart;

    // CJK/RTL: her zaman synthetic stepper kullan (chunk büyüklüğünden bağımsız)
    if (_isSyntheticStepLocale()) {
      _startSyntheticStepper(uiStart, uiEnd);
    } else {
      _syntheticStepTimer?.cancel();
      _handleProgress(uiStart, uiEnd);
    }
  }

  // Apply highlight (single source: called only from _onTtsProgressMapped).
  // TASK 1: Highlight only real characters; do not paint leading/trailing spaces.
  void _applyHighlight(int s, int e) {
    _pendingHighlightPaint = false;
    if (!mounted) return;
    if (!_isReadingRunningNow) return;
    if (s < 0 || e < 0 || e <= s) return;

    final fullText = _text.text;
    if (s >= fullText.length || e > fullText.length) return;

    final rawText = fullText.substring(s, e);

// Hem baştaki hem sondaki whitespace/newline kırp:
    final int leadingSpaces = rawText.length - rawText.trimLeft().length;
    final int trailingSpaces = rawText.length - rawText.trimRight().length;

    final int adjustedStart = s + leadingSpaces;
    final int adjustedEnd = e - trailingSpaces;

// Tamamen boş kalıyorsa highlight yapma:
    if (adjustedEnd <= adjustedStart) return;

// Aynı highlight ise boşuna setState yapma:
    if (_ttsHighlightStart == adjustedStart && _ttsHighlightEnd == adjustedEnd)
      return;

    setState(() {
      _ttsHighlightStart = adjustedStart;
      _ttsHighlightEnd = adjustedEnd;
      _lastUiStart = adjustedStart;
      _lastUiEnd = adjustedEnd;
    });

    // Scroll after highlight is painted: smooth animateTo, only when outside viewport band
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted) _scrollToCurrentHighlight();
    });
  }

  /// Yazarken imleci görünür tut — klavye varsa viewInsets.bottom da hesaba katılır
  void _scrollToCursor() {
    if (!mounted || !_scroll.hasClients) return;
    final mq = MediaQuery.maybeOf(context);
    final kbHeight = mq?.viewInsets.bottom ?? 0.0;
    // A07: viewInsets.bottom=0 dönebilir, _detectedKbHeight'i kullan
    // effectiveKb=0 olsa bile çalış: cursor görünür değilse scroll et
    final effectiveKb = kbHeight > 0 ? kbHeight : _detectedKbHeight;

    // RenderEditable'dan cursor rect'i al - en doğru yöntem
    try {
      final ctx = _readingTextKey.currentContext;
      if (ctx == null) return;
      RenderEditable? re;
      void find(RenderObject o) {
        if (re != null) return;
        if (o is RenderEditable) {
          re = o;
          return;
        }
        o.visitChildren(find);
      }

      ctx.findRenderObject()?.visitChildren(find);
      if (re == null) return;

      final cursorRect = re!.getLocalRectForCaret(
        TextPosition(
            offset: _text.selection.baseOffset.clamp(0, _text.text.length)),
      );
      // cursorRect.top = cursor'ın RenderEditable içindeki Y konumu
      // Bunu scroll koordinatına çevir
      final reBox = re! as RenderBox;
      final reOriginInScroll = reBox.localToGlobal(Offset.zero);

      RenderBox? vpBox;
      try {
        vpBox = _scroll.position.context.storageContext.findRenderObject()
            as RenderBox?;
      } catch (_) {}
      if (vpBox == null) return;

      final vpOrigin = vpBox.localToGlobal(Offset.zero);
      final cursorAbsY = reOriginInScroll.dy + cursorRect.top - vpOrigin.dy;
      final cursorScrollY = _scroll.offset + cursorAbsY;

      final pos = _scroll.position;
      final visibleBottom = pos.viewportDimension - effectiveKb;
      final viewTop = pos.pixels;
      final viewBottom = viewTop + visibleBottom;

      if (cursorScrollY < viewTop + 20 || cursorScrollY > viewBottom - 40) {
        final target = (cursorScrollY - visibleBottom * 0.5)
            .clamp(pos.minScrollExtent, pos.maxScrollExtent);
        if ((target - pos.pixels).abs() < 4) return;
        _scroll.jumpTo(target);
      }
    } catch (_) {}
  }

  void _scrollToIndex(int index) {
    if (!mounted || !_scroll.hasClients) return;

    final text = _text.text;
    if (text.isEmpty) return;

    final screenWidth = MediaQuery.of(context).size.width;
    // contentPadding ile senkron: ekran genişliğinin %6'sı, min 14 max 28
    final screenWidth2 = MediaQuery.maybeOf(context)?.size.width ?? 360.0;
    final horizontalPadding = (screenWidth2 * 0.06).clamp(14.0, 28.0);
    final rawWidth = _textAreaWidth > 0
        ? _textAreaWidth - (horizontalPadding * 2)
        : (screenWidth - 32);
    final maxW = rawWidth.clamp(50.0, 5000.0);

    final TextStyle style = _readingTextStyle ??
        TextStyle(
          color: Theme.of(context).colorScheme.onSurface,
          fontSize: 18,
          height: 1.5,
          fontFamilyFallback: ['Roboto', 'Noto Sans', 'Arial'],
          letterSpacing: 0,
        );

    final tp = TextPainter(
      text: TextSpan(text: text, style: style),
      textDirection: TextDirection.ltr,
      maxLines: null,
    );

    tp.layout(maxWidth: maxW);

    final safeIndex = index.clamp(0, text.length);
    final caret = tp.getOffsetForCaret(
      TextPosition(offset: safeIndex),
      Rect.zero,
    );

    tp.dispose();

    final highlightY = caret.dy;

    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted || !_scroll.hasClients) return;
      final pos = _scroll.position;
      final viewTop = pos.pixels;
      final viewBottom = pos.pixels + pos.viewportDimension;
      // Only scroll when the highlighted word is outside the comfortable band
      // (top 20% or bottom 20% of viewport)
      final bandTop = viewTop + pos.viewportDimension * 0.20;
      final bandBottom = viewTop + pos.viewportDimension * 0.80;
      if (highlightY >= bandTop && highlightY <= bandBottom) return;

      final target = (highlightY - pos.viewportDimension * 0.40)
          .clamp(pos.minScrollExtent, pos.maxScrollExtent);
      if ((target - pos.pixels).abs() < 8) return;

      _scroll.animateTo(
        target,
        duration: const Duration(milliseconds: 500),
        curve: Curves.easeInOutCubic,
      );
    });
  }

  /// Fallback highlight rect computation using TextPainter.
  /// Used on older devices (e.g. Samsung A07) where RenderEditable cannot be
  /// found in the render tree. Approximates word position well enough to paint
  /// the highlight correctly without needing a RenderEditable reference.
  void _computeHighlightRectsViaTextPainter(int start, int end) {
    if (!mounted) return;
    final fullText = _text.text;
    if (fullText.isEmpty) return;

    final safeStart = start.clamp(0, fullText.length);
    final safeEnd = end.clamp(0, fullText.length);
    if (safeEnd <= safeStart) return;

    try {
      final mediaData = MediaQuery.maybeOf(context);
      final textScaler = mediaData?.textScaler ?? TextScaler.noScaling;
      final style = _readingTextStyle ?? const TextStyle(fontSize: 16);

      final tpFull = TextPainter(
        text: TextSpan(text: fullText, style: style),
        textDirection: TextDirection.ltr,
        textScaler: textScaler,
      )..layout(maxWidth: mediaData?.size.width ?? 360);

      final boxes = tpFull.getBoxesForSelection(
        TextSelection(baseOffset: safeStart, extentOffset: safeEnd),
      );

      if (boxes.isEmpty) return;

      final wordText = fullText.substring(safeStart, safeEnd);
      final tpWord = TextPainter(
        text: TextSpan(text: wordText, style: style),
        textDirection: TextDirection.ltr,
        textScaler: textScaler,
      )..layout();
      final tightWidth = tpWord.width;

      final rects = boxes.map((b) {
        final clampedRight = tightWidth > 0
            ? (b.left + tightWidth).clamp(b.left, b.right)
            : b.right;
        return Rect.fromLTRB(b.left, b.top, clampedRight, b.bottom);
      }).toList();

      if (mounted) setState(() => _highlightRects = rects);
    } catch (_) {}
  }

  /// Scroll so current highlight is visible, centered in viewport. Uses smooth animateTo.
  void _scrollToCurrentHighlight() {
    if (!_scroll.hasClients || !mounted) return;
    if (_ttsHighlightStart < 0) return;
    _scrollToIndex(_ttsHighlightStart);
  }

  // Recalculate highlight rect from latest pending values (called in post-frame callback)
  // TASK 1: Use trimmed range so highlight does not paint leading/trailing spaces.
  void _recalcHighlightRectFromLatest() {
    if (!mounted) return;
    if (!_isReadingRunningNow) return;

    final start = _pendingHlStart;
    final end = _pendingHlEnd;

    // Check if pending values are valid
    if (start < 0 || end < 0 || end <= start) {
      return;
    }

    final fullText = _text.text;
    if (start >= fullText.length || end > fullText.length) return;

    final rawText = fullText.substring(start, end);
    final trimmedText = rawText.trimLeft();
    if (trimmedText.isEmpty) return;

    final leadingSpaces = rawText.length - trimmedText.length;
    final adjustedStart = start + leadingSpaces;
    final adjustedEnd = adjustedStart + trimmedText.length;

    // Update highlight state (this triggers repaint with new rect calculation)
    if (_ttsHighlightStart != adjustedStart ||
        _ttsHighlightEnd != adjustedEnd) {
      setState(() {
        _ttsHighlightStart = adjustedStart;
        _ttsHighlightEnd = adjustedEnd;
      });
    }
  }

  /// TTS word boundary: scroll/highlight only from TTS progress handler (single source).
  /// Do not trigger scroll or highlight here.
  void _onTtsWordBoundary({required int start, required int end}) {
    // Intentionally no-op: highlight and scroll are driven only by _onTtsProgressMapped.
  }

  /// Follow highlight: scroll only when highlight is outside viewport (BOTH mode, no timer).
  void _followHighlightIfNeeded(double targetTop, double targetBottom) {
    if (!_scroll.hasClients) return;
    final viewportHeight = _scroll.position.viewportDimension;
    if (viewportHeight <= 0) return;

    final viewTop = _scroll.offset;
    final viewBottom = _scroll.offset + viewportHeight;

    final isLandscape =
        MediaQuery.of(context).orientation == Orientation.landscape;
    final topPad = isLandscape ? 60.0 : 80.0;
    final bottomPad = isLandscape ? 100.0 : 140.0;

    double? target;

    if (targetTop - topPad < viewTop) {
      target = targetTop - topPad;
    } else if (targetBottom + bottomPad > viewBottom) {
      target = targetBottom + bottomPad - viewportHeight;
    }

    if (target == null) return;

    final clamped = target.clamp(
      _scroll.position.minScrollExtent,
      _scroll.position.maxScrollExtent,
    );

    if ((clamped - _scroll.offset).abs() < 6) return;

    _scroll.animateTo(
      clamped,
      duration: const Duration(milliseconds: 500),
      curve: Curves.easeInOutCubic,
    );
  }

  // D) Follow-scroll function that keeps highlighted text visible in BOTH mode only
  // Uses TextPainter to compute highlight position and smooth animation with comfort band
  void _followScrollToReadingPosition() {
    // Scroll is handled exclusively by _scrollToCurrentHighlight (via _handleProgress).
    // This secondary scroll path is disabled to prevent conflicting animations.
  }

  // DISABLED: Scroll only from TTS progress handler (_scrollToCurrentHighlight).
  void _scheduleFollowScroll() {
    _followScrollThrottle?.cancel();
    // Do not schedule timer — single source: TTS progress only.
  }

  bool _isPaused = false;
  final TextEditingController _text = TextEditingController();
  final FocusNode _textFocus = FocusNode();

  // Check if user has an active text selection
  bool get _hasActiveSelection {
    final sel = _text.selection;
    return sel.start >= 0 && sel.end >= 0 && !sel.isCollapsed;
  }

  // True while any reading session (scroll and/or TTS) is currently running
  bool get _isReadingRunningNow {
    final ttsRunning =
        (_ttsRunning || _isTtsPlaying || _isSpeaking) && !_ttsPaused;
    final scrollRunning = _autoScroll && !_isPaused;
    return ttsRunning || scrollRunning;
  }

  // Find the start of the word containing the given position
  int _findWordStart(String text, int position) {
    if (position <= 0 || position > text.length)
      return position.clamp(0, text.length);

    // Kelime karakterleri: harfler, rakamlar, Türkçe karakterler
    final wordCharPattern = RegExp(r'[\w\u00C0-\u017F]');

    // Geriye doğru kelime başlangıcını bul
    int start = position;
    while (start > 0 && wordCharPattern.hasMatch(text[start - 1])) {
      start--;
    }

    return start;
  }

  // Find the end of the word containing the given position
  int _findWordEnd(String text, int position) {
    if (position < 0 || position >= text.length)
      return position.clamp(0, text.length);

    // Kelime karakterleri: harfler, rakamlar, Türkçe karakterler
    final wordCharPattern = RegExp(r'[\w\u00C0-\u017F]');

    // İleriye doğru kelime sonunu bul
    int end = position;
    while (end < text.length && wordCharPattern.hasMatch(text[end])) {
      end++;
    }

    return end;
  }

  // Find the start of the sentence containing the given position
  // If position is at or after a sentence ending (. ? !), find the start of that sentence
  // Sentence ends with . ? ! followed by whitespace or end of text
  int _findSentenceStart(String text, int position) {
    if (position <= 0 || position > text.length)
      return position.clamp(0, text.length);

    // Find the last sentence ending (. ? !) before or at position
    int sentenceEndPos = -1;
    for (int i = (position - 1).clamp(0, text.length - 1); i >= 0; i--) {
      final char = text[i];
      if (char == '.' || char == '?' || char == '!') {
        sentenceEndPos = i;
        break;
      }
    }

    // If no sentence ending found, start from beginning
    if (sentenceEndPos == -1) {
      return 0;
    }

    // Find the start of this sentence by going backwards from the punctuation
    // The sentence starts after the previous sentence ending (or at text start)
    int start = 0;

    // Go backwards from sentenceEndPos to find the previous sentence ending
    for (int i = sentenceEndPos - 1; i >= 0; i--) {
      final char = text[i];
      // If we hit another sentence ending, the start is right after it
      if (char == '.' || char == '?' || char == '!') {
        start = i + 1; // Start is after this punctuation
        break;
      }
    }
    // If no previous sentence ending found, start is at beginning of text

    // Now start is at or after the previous sentence ending
    // Skip any whitespace to get to the actual sentence start
    while (start < text.length &&
        (text[start] == ' ' || text[start] == '\n' || text[start] == '\t')) {
      start++;
    }

    return start.clamp(0, text.length);
  }

  // Build sentence chunks from text ONCE per text load
  void _buildSentenceChunks(String text) {
    _sentenceChunks.clear();
    if (text.isEmpty) {
      _currentSentenceIndex = 0;
      return;
    }

    final protected = _protectUrlLikeTextForSentenceSplit(text);
    final splitText = protected['text'] as String;
    final urlTokenMap = protected['tokenMap'] as Map<String, String>;

    int start = 0;
    int i = 0;

    while (i < splitText.length) {
      // Find sentence ending (. ? ! or newline for poetry)
      if (splitText[i] == '\n') {
        // Newline = line break (poetry or paragraph) — treat as sentence boundary
        int end = i + 1;
        while (end < splitText.length && splitText[end] == '\n') end++;
        final sentenceText = _restoreProtectedUrlLikeText(
            splitText.substring(start, i).trim(), urlTokenMap);
        if (sentenceText.isNotEmpty) {
          int actualStart = start;
          while (actualStart < i &&
              (splitText[actualStart] == ' ' ||
                  splitText[actualStart] == '\n' ||
                  splitText[actualStart] == '\t')) {
            actualStart++;
          }
          _sentenceChunks.add(SentenceChunk(
            text: sentenceText,
            globalStart: actualStart,
            globalEnd: i,
          ));
        }
        start = end;
        i = end;
        continue;
      }
      if (splitText[i] == '.' || splitText[i] == '?' || splitText[i] == '!') {
        // Nokta Romen rakamından sonra geliyorsa (II. XIX. XX.) cümle sonu sayma
        if (splitText[i] == '.') {
          // Binlik ayraç kontrolü: sayı.sayı → cümle sonu değil (10.000, 1.500.000)
          final prevIsDigit = i > 0 && RegExp(r'\d').hasMatch(splitText[i - 1]);
          final nextIsDigit = i + 1 < splitText.length &&
              RegExp(r'\d').hasMatch(splitText[i + 1]);
          if (prevIsDigit && nextIsDigit) {
            i++;
            continue; // Binlik ayraç noktasında kesme
          }

          // Noktadan önceki kelimeye bak
          int j = i - 1;
          while (j >= start && splitText[j] != ' ' && splitText[j] != '\n') {
            j--;
          }
          final word = splitText.substring(j + 1, i).toUpperCase();
          final isRoman =
              RegExp(r'^[IVXLCDM]+$').hasMatch(word) && word.isNotEmpty;
          if (isRoman) {
            i++;
            continue; // Romen rakamı noktasında kesme
          }
        }
        // Found sentence ending - include it in the sentence
        int end = i + 1;

        // Skip whitespace after punctuation
        while (end < splitText.length &&
            (splitText[end] == ' ' ||
                splitText[end] == '\n' ||
                splitText[end] == '\t')) {
          end++;
        }

        // Extract sentence (from start to end, including punctuation)
        final sentenceText = _restoreProtectedUrlLikeText(
            splitText.substring(start, end).trim(), urlTokenMap);
        if (sentenceText.isNotEmpty) {
          // Find actual start in original text (accounting for leading whitespace)
          int actualStart = start;
          while (actualStart < end &&
              (splitText[actualStart] == ' ' ||
                  splitText[actualStart] == '\n' ||
                  splitText[actualStart] == '\t')) {
            actualStart++;
          }

          _sentenceChunks.add(SentenceChunk(
            text: sentenceText,
            globalStart: actualStart,
            globalEnd: end,
          ));
        }

        start = end;
        i = end;
      } else {
        i++;
      }
    }

    // Handle remaining text (if no sentence ending at the end)
    if (start < splitText.length) {
      final remaining = _restoreProtectedUrlLikeText(
          splitText.substring(start).trim(), urlTokenMap);
      if (remaining.isNotEmpty) {
        int actualStart = start;
        while (actualStart < splitText.length &&
            (splitText[actualStart] == ' ' ||
                splitText[actualStart] == '\n' ||
                splitText[actualStart] == '\t')) {
          actualStart++;
        }

        _sentenceChunks.add(SentenceChunk(
          text: remaining,
          globalStart: actualStart,
          globalEnd: splitText.length,
        ));
      }
    }

    // Index reset is handled by the caller (_ensureSentenceQueueSynced)
  }

  Map<String, Object> _protectUrlLikeTextForSentenceSplit(String text) {
    final tokenMap = <String, String>{};
    final usedTokens = <String>{};
    final urlPattern = RegExp(
      r"(?:(?:https?:\/\/|www\.)[A-Za-z0-9\-._~:/?#\[\]@!$&'()*+,;=%]+|(?:[A-Za-z0-9-]+\.)+[A-Za-z]{2,}(?:\/[A-Za-z0-9\-._~:/?#\[\]@!$&'()*+,;=%]*)?)",
      caseSensitive: false,
    );

    int tokenIndex = 0;
    final protectedText = text.replaceAllMapped(urlPattern, (match) {
      final original = match.group(0) ?? '';
      if (original.isEmpty || !original.contains('.')) {
        return original;
      }

      final token = _buildUrlProtectionToken(
        tokenIndex++,
        original.length,
        text,
        usedTokens,
      );
      if (token == null) {
        return original;
      }

      usedTokens.add(token);
      tokenMap[token] = original;
      return token;
    });

    return {
      'text': protectedText,
      'tokenMap': tokenMap,
    };
  }

  String? _buildUrlProtectionToken(
    int index,
    int targetLength,
    String sourceText,
    Set<String> usedTokens,
  ) {
    if (targetLength < 4) return null;

    final id = index.toRadixString(36).toUpperCase();
    var core = 'ER$id';
    if (core.length > targetLength) {
      core = core.substring(0, targetLength);
    }

    var token = core.padRight(targetLength, 'X');
    int nonce = 0;
    while (usedTokens.contains(token) || sourceText.contains(token)) {
      final suffix = nonce.toRadixString(36).toUpperCase();
      final available = targetLength - suffix.length;
      if (available <= 0) return null;
      final prefix =
          core.length > available ? core.substring(0, available) : core;
      token = (prefix + suffix).padRight(targetLength, 'X');
      nonce++;
      if (nonce > 128) return null;
    }
    return token;
  }

  String _restoreProtectedUrlLikeText(
      String text, Map<String, String> tokenMap) {
    var restored = text;
    tokenMap.forEach((token, original) {
      restored = restored.replaceAll(token, original);
    });
    return restored;
  }

  // Ensure sentence queue is synced with current text
  void _ensureSentenceQueueSynced({bool resetIndexIfTextChanged = true}) {
    final current = _text.text;
    final hash = current.hashCode;
    if (current.trim().isEmpty) {
      _sentenceChunks.clear();
      _currentSentenceIndex = 0;
      _lastBuiltTextHash = 0;
      return;
    }
    if (hash != _lastBuiltTextHash) {
      _buildSentenceChunks(current);
      _lastBuiltTextHash = hash;
      if (resetIndexIfTextChanged) {
        _currentSentenceIndex = 0;
      }
    }
  }

  // Find the start of the next sentence after the given position
  // Optional helper - DO NOT use for resume offset
  int _findNextSentenceStart(String text, int position) {
    if (position < 0 || position >= text.length) {
      return text.length;
    }

    // Find the next sentence ending (. ? !) after position
    int sentenceEndPos = -1;
    for (int i = position; i < text.length; i++) {
      final char = text[i];
      if (char == '.' || char == '?' || char == '!') {
        sentenceEndPos = i;
        break;
      }
    }

    // If no sentence ending found, return end of text
    if (sentenceEndPos == -1) {
      return text.length;
    }

    // Find the start of the next sentence by going forward from the punctuation
    // Skip whitespace after the punctuation
    int start = sentenceEndPos + 1;
    while (start < text.length &&
        (text[start] == ' ' || text[start] == '\n' || text[start] == '\t')) {
      start++;
    }

    return start.clamp(0, text.length);
  }

  final ScrollController _scroll = ScrollController();
  // Attach this key to the RichText/SelectableText.rich that renders the reading text
  final GlobalKey _readingTextKey = GlobalKey();

  // TASK 3 – reading text layout metrics
  double _textAreaWidth = 0;
  double _textAreaPaddingH = 0;
  TextStyle? _readingTextStyle;

  bool _isWs(int cc) =>
      cc == 0x20 ||
      cc == 0x09 ||
      cc == 0x0A ||
      cc == 0x0D; // space, tab, \n, \r

  /// Trims leading/trailing whitespace from [start,end).
  /// Returns null if the resulting range is empty or whitespace-only.
  ({int start, int end})? _trimHighlightRange(String text, int start, int end) {
    if (start < 0) start = 0;
    if (end < 0) end = 0;
    if (start > text.length) start = text.length;
    if (end > text.length) end = text.length;
    if (end <= start) return null;

    int s = start;
    int e = end;

    while (s < e && _isWs(text.codeUnitAt(s))) {
      s++;
    }
    while (e > s && _isWs(text.codeUnitAt(e - 1))) {
      e--;
    }
    if (e <= s) return null;

    return (start: s, end: e);
  }

  double _lineHeightFor(TextStyle style) {
    final fs = (style.fontSize ?? 16.0);
    final h = (style.height ?? 1.25);
    return fs * h;
  }

  /// Scrolls to the TOP of the line containing the current (trimmed) word.
  /// Prevents "between lines" drifting.
  Future<void> _snapScrollToWordLine({
    required int start,
    required int end,
    required TextStyle textStyle,
    double topPad = 12,
  }) async {
    if (!_scroll.hasClients) return;
    final ctx = _readingTextKey.currentContext;
    if (ctx == null) return;

    final ro = ctx.findRenderObject();
    List<TextBox> boxes;
    if (ro is RenderParagraph) {
      boxes = ro.getBoxesForSelection(
        TextSelection(baseOffset: start, extentOffset: end),
      );
    } else if (ro is RenderEditable) {
      boxes = ro.getBoxesForSelection(
        TextSelection(baseOffset: start, extentOffset: end),
      );
    } else {
      return;
    }
    if (boxes.isEmpty) return;

    final rectTop = boxes.first.toRect().top;
    final lineH = _lineHeightFor(textStyle);
    if (lineH <= 0) return;

    final lineIndex = (rectTop / lineH).floor();
    final lineTop = (lineIndex * lineH) - topPad;

    final target = lineTop.clamp(
      0.0,
      _scroll.position.maxScrollExtent,
    );

    await _scroll.animateTo(
      target,
      duration: const Duration(milliseconds: 120),
      curve: Curves.easeOut,
    );
  }

  final FlutterTts _tts = FlutterTts();
  int _previousTextLength = 0; // Track text length for paste detection
  static const MethodChannel _sys = MethodChannel('easyreading/system');
  bool _isSpeaking = false;
  bool _ttsPaused = false;
  String _ttsText = '';
  int _ttsOffset = 0;

  // TTS ↔ UI index mapping (normalization: collapse spaces so highlight stays in sync)
  String _uiTextForReading = '';
  List<int> _mapTtsToUi = <int>[];

  // Per-sentence spoken-text → original-UI-text index map
  // Filled in _ttsRunNextSentence before each speak call.
  String _currentSentenceOriginal = ''; // chunk.text (original sentence)
  String _currentSentenceSpoken = ''; // ttsOut (what TTS actually speaks)
  int _currentSentenceUiBase = 0; // chunk.globalStart in full UI text
  List<int> _spokenToOrigMap =
      <int>[]; // spokenIndex → offset within chunk.text

  // TTS highlight aralığı (okunan kısım)
  int _ttsHighlightStart = 0;
  int _ttsHighlightEnd =
      0; // TTS metni parça parça (chunk) geldiği için takip değişkenleri
  String _ttsLastChunk = '';
  int _ttsChunkBase = 0;
  // Pending highlight state for 1-frame delayed paint (prevents overlap/blur)
  bool _pendingHighlightPaint = false;
  int _pendingHlStart = -1;
  int _pendingHlEnd = -1;

  // Highlight: single source (_onTtsProgressMapped), every onProgress tries update
  int _lastAppliedStart = 0;
  int _lastAppliedEnd = 0;
  int _lastUiStart = 0;
  int _lastUiEnd = 0;
  bool _dbgHighlight = true;
  bool _dbgHilite = false; // set true for highlight debug logs

  // Real pixel rects from RenderEditable – used for accurate highlight painting
  List<Rect> _highlightRects = [];

  // TASK 3: Reading position source for synchronized TTS + auto-scroll
  int _ttsCharOffset =
      0; // Current reading position (startOffset from TTS progress)
  Timer?
      _followScrollThrottle; // Throttle follow-scroll updates (4-8 times per second)
  int _lastFollowWord = -1;
  DateTime _lastFollowAt = DateTime.fromMillisecondsSinceEpoch(0);
  DateTime? _ttsStartTime; // Track TTS start time for fallback estimation
  // Track last spoken position for voice resume after pause/stop
  int _lastSpokenOffset = 0;
  DateTime? _lastSpokenOffsetUpdateTime; // Throttle updates to avoid jank
  // Flag to force next TTS start from top (set by "Go to top" button)
  bool _forceStartFromTopOnce = false;
