  // Check if values match defaults (with tolerance for float comparison)
  bool _isDefault() {
    final rateMatches = (_rate - defaultVoiceRate).abs() < 0.01;
    final scrollMatches =
        (_autoScrollPxPerSec - defaultScrollSpeed).abs() < 0.5;
    return rateMatches && scrollMatches;
  }

