  void _startTour() {
    // Find first valid step
    for (int i = 1; i <= 6; i++) {
      final step = _buildTourStep(i);
      if (step != null) {
        setState(() {
          _tourCurrentStep = i;
        });
        // Wait for next frame to ensure UI is ready
        WidgetsBinding.instance.addPostFrameCallback((_) {
          _updateTourStep();
        });
        return;
      }
    }
    // No valid steps found
    _endTour();
  }

  void _nextTourStep() {
    if (_tourCurrentStep == null) {
      _endTour();
      return;
    }

    // Find next valid step
    int nextStep = _tourCurrentStep! + 1;
    while (nextStep <= 6) {
      final step = _buildTourStep(nextStep);
      if (step != null) {
        setState(() {
          _tourCurrentStep = nextStep;
        });
        WidgetsBinding.instance.addPostFrameCallback((_) {
          _updateTourStep();
        });
        return;
      }
      nextStep++;
    }
    // No more valid steps found, end tour
    _endTour();
  }

  void _previousTourStep() {
    if (_tourCurrentStep == null || _tourCurrentStep! <= 1) {
      return;
    }

    // Find previous valid step
    int prevStep = _tourCurrentStep! - 1;
    while (prevStep >= 1) {
      final step = _buildTourStep(prevStep);
      if (step != null) {
        setState(() {
          _tourCurrentStep = prevStep;
        });
        WidgetsBinding.instance.addPostFrameCallback((_) {
          _updateTourStep();
        });
        return;
      }
      prevStep--;
    }
  }

  void _endTour() {
    setState(() {
      _tourCurrentStep = null;
    });
  }

  void _updateTourStep() {
    if (_tourCurrentStep == null) return;
    // Scroll to target if needed
    final targetKey = _getTourStepKey(_tourCurrentStep!);
    if (targetKey != null) {
      final renderBox =
          targetKey.currentContext?.findRenderObject() as RenderBox?;
      if (renderBox != null && _scroll.hasClients) {
        final position = renderBox.localToGlobal(Offset.zero);
        final targetScroll =
            position.dy - MediaQuery.of(context).size.height / 3;
        if (targetScroll > 0 &&
            targetScroll < _scroll.position.maxScrollExtent) {
          _scroll.animateTo(
            targetScroll,
            duration: const Duration(milliseconds: 300),
            curve: Curves.easeInOut,
          );
        }
      }
    }
  }

  GlobalKey? _getTourStepKey(int step) {
    switch (step) {
      case 1:
        return _tourKeyLanguage;
      case 2:
        return _tourKeyPaste;
      case 3:
        return _tourKeyOcr;
      case 4:
        return _tourKeyHistory;
      case 5:
        return _tourKeyFavorites;
      case 6:
        return _tourKeyControls;
      default:
        return null;
    }
  }

  TourStep? _buildTourStep(int step) {
    final key = _getTourStepKey(step);
    // Skip step if key is not mounted
    if (key?.currentContext == null) return null;

    switch (step) {
      case 1:
        return TourStep(
          index: step,
          titleKey: 'tour.step.1.title',
          descKey: 'tour.step.1.desc',
          targetKey: _tourKeyLanguage,
        );
      case 2:
        return TourStep(
          index: step,
          titleKey: 'tour.step.2.title',
          descKey: 'tour.step.2.desc',
          targetKey: _tourKeyPaste,
        );
      case 3:
        return TourStep(
          index: step,
          titleKey: 'tour.step.3.title',
          descKey: 'tour.step.3.desc',
          targetKey: _tourKeyOcr,
        );
      case 4:
        return TourStep(
          index: step,
          titleKey: 'tour.step.4.title',
          descKey: 'tour.step.4.desc',
          targetKey: _tourKeyHistory,
        );
      case 5:
        return TourStep(
          index: step,
          titleKey: 'tour.step.5.title',
          descKey: 'tour.step.5.desc',
          targetKey: _tourKeyFavorites,
        );
      case 6:
        return TourStep(
          index: step,
          titleKey: 'tour.step.6.title',
          descKey: 'tour.step.6.desc',
          targetKey: _tourKeyControls,
        );
      default:
        return null;
    }
  }

  int _getTotalTourSteps() {
    int count = 0;
    for (int i = 1; i <= 6; i++) {
      final key = _getTourStepKey(i);
      if (key?.currentContext != null) count++;
    }
    return count;
  }

  // ================== READING PAGE TOUR ==================
  static const String _readingTourPrefsKey = 'tour_reading_done_v1';

  Future<bool> _getReadingTourDontShowAgain() async {
    final sp = await SharedPreferences.getInstance();
    return sp.getBool(kPrefReadingTourDontShowAgain) ?? false;
  }

  Future<void> _setReadingTourDontShowAgain(bool v) async {
    final sp = await SharedPreferences.getInstance();
    await sp.setBool(kPrefReadingTourDontShowAgain, v);
  }

  Future<void> _checkAndStartReadingTour({bool force = false}) async {
    if (!mounted) return;

    // TEMPORARY DIAGNOSTIC: Kill-switch - do not start tour if disabled
    if (kDisableReadingTourForDiag) {
      return;
    }

    // Guard: Prevent multiple auto-start attempts
    if (!force && _tourAutoStartAttempted) {
      return;
    }

    // Mark as attempted for auto-start (but allow manual force)
    if (!force) {
      _tourAutoStartAttempted = true;
    }

    // Gate auto-start only: if flag is true and not forced, don't start
    if (!force) {
      final dontShowAgain = await _getReadingTourDontShowAgain();
      if (dontShowAgain) {
        return;
      }
    }

    final sp = await SharedPreferences.getInstance();
    final tourDone = sp.getBool(_readingTourPrefsKey) ?? false;
    final forceShowTour = sp.getBool('force_show_reading_tour') ?? false;

    // Show tour if not done, or if forced by new build reset or manual start
    if (!tourDone || forceShowTour || force) {
      // Clear the force flag after checking
      if (forceShowTour) {
        await sp.setBool('force_show_reading_tour', false);
      }
      // Wait for UI to be ready
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) {
          _startReadingTour();
        }
      });
    } else {}
  }

  void _initVoiceLimit() async {
    _voiceSecsUsed = await PremiumService.instance.getTodayVoiceSecs();
    _voiceLimitReached = _voiceSecsUsed >= PremiumService.freeDailyVoiceSecs;
    _scrollSecsUsed = await PremiumService.instance.getTodayScrollSecs();
    _scrollLimitReached = _scrollSecsUsed >= PremiumService.freeDailyScrollSecs;
  }

  void _startVoiceLimitTimer() {
    _voiceLimitTimer?.cancel();

    // Eğer limit zaten dolmuşsa: önce 7 sn fade yap, sonra paywall aç
    if (_voiceSecsUsed >= PremiumService.freeDailyVoiceSecs) {
      _runFadeThenPaywall();
      return;
    }

    _voiceLimitTimer = Timer.periodic(const Duration(seconds: 1), (timer) {
      if (!mounted) {
        timer.cancel();
        return;
      }
      if (PremiumService.instance.hasFullAccess) {
        timer.cancel();
        return;
      }
      _voiceSecsUsed++;
      if (_voiceSecsUsed % 10 == 0) {
        PremiumService.instance.setVoiceSecs(_voiceSecsUsed);
      }
      // Fade effect: son 7 saniyede metin ve ses yavaşça solar
      final limit = PremiumService.freeDailyVoiceSecs;
      final fadeStart = limit - 7;
      if (_voiceSecsUsed >= fadeStart && _voiceSecsUsed < limit) {
        final progress = (_voiceSecsUsed - fadeStart) / 7.0;
        final newOpacity = (1.0 - progress).clamp(0.1, 1.0);
        final newVolume = (1.0 - progress).clamp(0.05, 1.0);
        if (mounted) {
          setState(() {
            _voiceFadeOpacity = newOpacity;
            _voiceFadeVolume = newVolume;
          });
          _tts.setVolume(newVolume * _volume);
        }
      }
      if (_voiceSecsUsed >= limit) {
        timer.cancel();
        _voiceLimitReached = true;
        FirebaseAnalytics.instance.logEvent(name: 'voice_limit_reached');
        FirebaseAnalytics.instance.logEvent(name: 'voice_limit_reached');
        PremiumService.instance.setVoiceSecs(_voiceSecsUsed);
        // Sesi sıfırla
        _tts.setVolume(0.0);
        _stopReading().then((_) {
          if (mounted) {
            setState(() {
              _voiceFadeOpacity = 1.0;
              _voiceFadeVolume = 1.0;
            });
            _tts.setVolume(_volume);
            navigateToPaywall(context);
          }
        });
      }
    });
  }

  /// Limit zaten dolmuşsa: 7 sn boyunca fade yap, sonra paywall aç
  void _runFadeThenPaywall() {
    int fadeStep = 0;
    const fadeDuration = 7;
    Timer.periodic(const Duration(seconds: 1), (timer) {
      if (!mounted) {
        timer.cancel();
        return;
      }
      fadeStep++;
      final progress = fadeStep / fadeDuration.toDouble();
      final newOpacity = (1.0 - progress).clamp(0.1, 1.0);
      final newVolume = (1.0 - progress).clamp(0.05, 1.0);
      setState(() {
        _voiceFadeOpacity = newOpacity;
        _voiceFadeVolume = newVolume;
      });
      _tts.setVolume(newVolume * _volume);
      if (fadeStep >= fadeDuration) {
        timer.cancel();
        _voiceLimitReached = true;
        _tts.setVolume(0.0);
        _stopReading().then((_) {
          if (mounted) {
            setState(() {
              _voiceFadeOpacity = 1.0;
              _voiceFadeVolume = 1.0;
            });
            _tts.setVolume(_volume);
            navigateToPaywall(context);
          }
        });
      }
    });
  }

  void _startReadingTour() {
    // Wait until at least one target rect is registered before starting
    if (_tourRects.isEmpty) {
      if (_tourStartRetryCount >= kMaxTourStartRetries) {
        return;
      }
      _tourStartRetryCount++;
      Future.delayed(kTourRetryDelay, () {
        if (!mounted) return;
        _startReadingTour();
      });
      return;
    }
    // Targets available, reset retry counter
    _tourStartRetryCount = 0;
    // Reset attempt counter when tour starts
    _tourMeasureAttempts = 0;
    // Find first valid step (enforce bounds: 1-12)
    for (int i = 1; i <= 12; i++) {
      final step = _buildReadingTourStep(i);
      if (step != null) {
        setState(() {
          _readingTourCurrentStep = i;
        });
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (!mounted) return;
          _showReadingTourDialog(step);
        });
        // Wait for next frame to ensure UI is ready
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (mounted) {
            // Verify step is still valid after frame
            final verifyStep = _buildReadingTourStep(i);
            if (verifyStep == null) {
              setState(() {
                _readingTourCurrentStep = null;
              });
              return;
            }
            _updateReadingTourStep();
          }
        });
        return;
      }
    }
    // No valid steps found
    _endReadingTour();
  }

  void _nextReadingTourStep() {
    if (_readingTourCurrentStep == null) {
      _endReadingTour();
      return;
    }

    // Reset attempt counter when step changes
    _tourMeasureAttempts = 0;
    // Find next valid step (enforce bounds: max 10)
    int nextStep = _readingTourCurrentStep! + 1;
    if (nextStep > 10) {
      // Step exceeds max, end tour cleanly
      _endReadingTour();
      return;
    }
    while (nextStep <= 10) {
      final step = _buildReadingTourStep(nextStep);
      if (step != null) {
        setState(() {
          _readingTourCurrentStep = nextStep;
        });
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (!mounted) return;
          _showReadingTourDialog(step);
        });
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (mounted) {
            // Verify step is still valid after frame
            final verifyStep = _buildReadingTourStep(nextStep);
            if (verifyStep == null) {
              setState(() {
                _readingTourCurrentStep = null;
              });
              return;
            }
            _updateReadingTourStep();
          }
        });
        return;
      }
      nextStep++;
    }
    // No more valid steps found, end tour
    _endReadingTour();
  }

  void _previousReadingTourStep() {
    if (_readingTourCurrentStep == null || _readingTourCurrentStep! <= 1) {
      return;
    }

    // Reset attempt counter when step changes
    _tourMeasureAttempts = 0;
    // Find previous valid step (enforce bounds: min 1)
    int prevStep = _readingTourCurrentStep! - 1;
    if (prevStep < 1) {
      // Step below min, do nothing
      return;
    }
    while (prevStep >= 1) {
      final step = _buildReadingTourStep(prevStep);
      if (step != null) {
        setState(() {
          _readingTourCurrentStep = prevStep;
        });
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (!mounted) return;
          _showReadingTourDialog(step);
        });
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (mounted) {
            // Verify step is still valid after frame
            final verifyStep = _buildReadingTourStep(prevStep);
            if (verifyStep == null) {
              setState(() {
                _readingTourCurrentStep = null;
              });
              return;
            }
            _updateReadingTourStep();
          }
        });
        return;
      }
      prevStep--;
    }
  }

  Future<void> _endReadingTour() async {
    // Close dialog if open
    if (_readingTourDialogOpen &&
        Navigator.of(context, rootNavigator: true).canPop()) {
      Navigator.of(context, rootNavigator: true).pop();
    }
    _readingTourDialogOpen = false;
    // Reset attempt counter when tour ends
    _tourMeasureAttempts = 0;
    setState(() {
      _readingTourCurrentStep = null;
    });
    _tourRects.clear();

    // Mark tour as done
    final sp = await SharedPreferences.getInstance();
    await sp.setBool(_readingTourPrefsKey, true);
  }

  Future<void> _dontShowAgainReadingTour() async {
    // Set "Don't show again" flag using helper
    await _setReadingTourDontShowAgain(true);
    // Also mark tour as done
    final sp = await SharedPreferences.getInstance();
    await sp.setBool(_readingTourPrefsKey, true);
    // End tour
    await _endReadingTour();
  }

  void _startReadingTourFromHelp() {
    if (!mounted) return;
    setState(() {
      _readingTourCurrentStep = null; // reset
    });
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (!mounted) return;
      setState(() {
        _readingTourCurrentStep = 0; // start after layout
      });
    });
  }

  // Root tour steps data
  // Single source of truth for root tour step mapping
  // Returns both text keys and targetId for the given step index
  Map<String, String> _getRootTourSpec(int step) {
    switch (step) {
      case 0:
        return {
          'titleKey': 'tour.reading.step1.title',
          'bodyKey': 'tour.reading.step1.body',
          'targetId': 'tour.language',
        };
      case 1:
        return {
          'titleKey': 'tour.reading.step2.title',
          'bodyKey': 'tour.reading.step2.body',
          'targetId': 'tour.paste',
        };
      case 2:
        return {
          'titleKey': 'tour.reading.step3.title',
          'bodyKey': 'tour.reading.step3.body',
          'targetId': 'tour.ocr',
        };
      case 3:
        return {
          'titleKey': 'tour.reading.step4.title',
          'bodyKey': 'tour.reading.step4.body',
          'targetId': 'tour.weblink',
        };
      case 4:
        return {
          'titleKey': 'tour.reading.step5.title',
          'bodyKey': 'tour.reading.step5.body',
          'targetId': 'tour.history',
        };
      case 5:
        return {
          'titleKey': 'tour.reading.step6.title',
          'bodyKey': 'tour.reading.step6.body',
          'targetId': 'tour.favorites',
        };
      case 6:
        return {
          'titleKey': 'tour.reading.step7.title',
          'bodyKey': 'tour.reading.step7.body',
          'targetId': 'tour.note',
        };
      case 7:
        return {
          'titleKey': 'tour.reading.step8.title',
          'bodyKey': 'tour.reading.step8.body',
          'targetId': 'tour.theme',
        };
      case 8:
        return {
          'titleKey': 'tour.reading.step9.title',
          'bodyKey': 'tour.reading.step9.body',
          'targetId': 'tour.clean',
        };
      case 9:
        return {
          'titleKey': 'tour.reading.step10.title',
          'bodyKey': 'tour.reading.step10.body',
          'targetId': 'tour.openFile',
        };
      case 10:
        return {
          'titleKey': 'tour.reading.step11.title',
          'bodyKey': 'tour.reading.step11.body',
          'targetId': 'tour.controls',
        };
      case 11:
        return {
          'titleKey': 'tour.reading.step12.title',
          'bodyKey': 'tour.reading.step12.body',
          'targetId': 'tour.settings',
        };
      default:
        return {
          'titleKey': '',
          'bodyKey': '',
          'targetId': '',
        };
    }
  }

  void _refreshRootTourOverlay() {
    _tourOverlayEntry?.markNeedsBuild();
  }

  // Map root tour step (0-11) to TourTarget ID
  // Now uses single source of truth
  String? _getRootTourTargetId(int step) {
    final spec = _getRootTourSpec(step);
    final targetId = spec['targetId'];
    return targetId?.isNotEmpty == true ? targetId : null;
  }

  // Capture target rect for current step from _tourRects
  void _updateActiveTourTargetRect() {
    final targetId = _getRootTourTargetId(_rootTourStep);
    _activeTourTargetRect = targetId != null ? _tourRects[targetId] : null;
    // Reset measurement state when step changes (keep _lastPos for smooth transition)
    if (_bubbleSizeStep != _rootTourStep) {
      _bubbleSize = null;
      _bubbleSizeStep = null;
      _measuringScheduled = false;
      // Keep _lastPos but mark it as stale (from previous step)
      // _lastPosStep will be updated when new measurement arrives
    }
  }

  // Schedule bubble measurement (only once per step)
  void _scheduleMeasure() {
    // Skip measurement for panelMode (steps 3 and 11 in landscape)
    // Check is also done in caller, but this is a safety guard
    if (!mounted) return;
    try {
      final mq = MediaQuery.of(context);
      final isLandscape = mq.orientation == Orientation.landscape;
      final stepShown = _rootTourStep + 1;
      final bool panelMode = isLandscape && (stepShown == 3 || stepShown == 11);

      if (panelMode) {
        // Panel mode: no measurement needed, skip
        return;
      }
    } catch (_) {
      // If context not available, continue with measurement attempt
    }

    if (_measuringScheduled) return;
    _measuringScheduled = true;
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _measuringScheduled = false;
      final ctx = _tourBubbleKey.currentContext;
      final box = ctx?.findRenderObject() as RenderBox?;
      if (box == null || !box.hasSize) return;

      final s = box.size;
      // If we already measured for this step and size hasn't changed, don't setState
      if (_bubbleSizeStep == _rootTourStep &&
          _bubbleSize != null &&
          (_bubbleSize!.width - s.width).abs() < 0.5 &&
          (_bubbleSize!.height - s.height).abs() < 0.5) {
        return;
      }

      _bubbleSize = s;
      _bubbleSizeStep = _rootTourStep;
      _refreshRootTourOverlay(); // Refresh to update position
    });
  }

  // Measure bubble size after render (kept for compatibility, but use _scheduleMeasure instead)
  void _measureBubble() {
    _scheduleMeasure();
  }

  Future<void> _showRootTourOverlay() async {
    if (_tourOverlayEntry != null) return;

    // Check if tour is disabled
    final prefs = await SharedPreferences.getInstance();
    final dontShowAgain = prefs.getBool(kPrefRootTourDontShowAgain) ?? false;
    if (dontShowAgain) {
      // Tour is disabled, show hint message
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
            t('tour.common.disabledHint'),
            behavior: SnackBarBehavior.floating));
      }
      return;
    }

    setState(() {
      _rootTourStep = 0;
      _rootTourDontShowAgain = false;
    });

    // Capture target rect BEFORE opening dialog
    _updateActiveTourTargetRect();

    _tourOverlayEntry = OverlayEntry(
      builder: (context) {
        final currentStep = _getRootTourSpec(_rootTourStep);
        final isFirstStep = _rootTourStep == 0;
        final isLastStep = _rootTourStep == _rootTourTotalSteps - 1;
        final titleKey = currentStep['titleKey']!;
        final bodyKey = currentStep['bodyKey']!;
        final title = t(titleKey);
        final body = t(bodyKey);
        final isDark = Theme.of(context).brightness == Brightness.dark;

        // Check orientation
        final mq = MediaQuery.of(context);
        final isLandscape = mq.orientation == Orientation.landscape;
        const pad = 12.0;

        // Calculate available space with SafeArea insets
        final insets = mq.padding;
        final availW = mq.size.width - insets.left - insets.right - pad * 2;
        final availH = mq.size.height - insets.top - insets.bottom - pad * 2;

        // Determine panel mode for steps 3 and 11
        final int stepShown = _rootTourStep + 1;
        final bool panelMode =
            isLandscape && (stepShown == 3 || stepShown == 11);

        // Build bubble widget content (reusable for both portrait and landscape)
        Widget buildBubbleContent() {
          return Builder(
            builder: (context) {
              final isDark = Theme.of(context).brightness == Brightness.dark;
              return DefaultTextStyle.merge(
                style: TextStyle(
                  color: isDark ? Colors.black87 : null,
                ),
                child: IconTheme.merge(
                  data: IconThemeData(color: isDark ? Colors.black87 : null),
                  child: Column(
                    mainAxisSize: MainAxisSize
                        .max, // Changed from min to max for Expanded to work
                    crossAxisAlignment: CrossAxisAlignment.start,
                    children: [
                      // HEADER (title + step counter) - fixed
                      Padding(
                        padding: const EdgeInsets.fromLTRB(16, 14, 16, 8),
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          crossAxisAlignment: CrossAxisAlignment.start,
                          children: [
                            // Step indicator
                            Text(
                              t('tour.stepCounter')
                                  .replaceAll(
                                      '{current}', '${_rootTourStep + 1}')
                                  .replaceAll(
                                      '{total}', '$_rootTourTotalSteps'),
                              style: const TextStyle(
                                fontSize: 13,
                                color: Colors.grey,
                              ),
                            ),
                            const SizedBox(height: 10),
                            // Title
                            Text(
                              title,
                              style: const TextStyle(
                                fontSize: 18,
                                fontWeight: FontWeight.bold,
                              ),
                            ),
                          ],
                        ),
                      ),
                      // BODY = Expanded + ScrollView (GARANTİ)
                      Expanded(
                        child: Scrollbar(
                          thumbVisibility: true,
                          child: SingleChildScrollView(
                            padding: const EdgeInsets.fromLTRB(16, 0, 16, 8),
                            child: _buildRootTourBodyText(body, isDark: isDark),
                          ),
                        ),
                      ),
                      // FOOTER = sabit
                      Padding(
                        padding: const EdgeInsets.fromLTRB(16, 8, 16, 12),
                        child: Column(
                          mainAxisSize: MainAxisSize.min,
                          children: [
                            // "Don't show again" checkbox
                            Theme(
                              data: Theme.of(context).copyWith(
                                checkboxTheme: CheckboxThemeData(
                                  fillColor: WidgetStateProperty.resolveWith(
                                    (states) =>
                                        states.contains(WidgetState.selected)
                                            ? kBeige
                                            : Colors.transparent,
                                  ),
                                  checkColor:
                                      WidgetStateProperty.all(Colors.black),
                                  side: const BorderSide(
                                    color: kBeigeDark,
                                    width: 1.2,
                                  ),
                                ),
                              ),
                              child: CheckboxListTile(
                                contentPadding: EdgeInsets.zero,
                                title: Text(
                                  t('tour.common.dontShowAgain'),
                                  style: TextStyle(
                                    fontSize: 13,
                                    color: isDark ? Colors.black87 : null,
                                  ),
                                ),
                                value: _rootTourDontShowAgain,
                                onChanged: (value) {
                                  setState(() {
                                    _rootTourDontShowAgain = value ?? false;
                                  });
                                  _refreshRootTourOverlay();
                                },
                              ),
                            ),
                            const SizedBox(height: 6),
                            // Buttons row
                            Wrap(
                              spacing: 4,
                              runSpacing: 4,
                              alignment: WrapAlignment.end,
                              children: [
                                // Back button
                                TextButton(
                                  onPressed: isFirstStep
                                      ? null
                                      : () {
                                          setState(() {
                                            _rootTourStep--;
                                          });
                                          _updateActiveTourTargetRect();
                                          _refreshRootTourOverlay();
                                        },
                                  style: TextButton.styleFrom(
                                    padding: const EdgeInsets.symmetric(
                                        horizontal: 6, vertical: 4),
                                    minimumSize: Size.zero,
                                    tapTargetSize:
                                        MaterialTapTargetSize.shrinkWrap,
                                  ),
                                  child: Text(
                                    t('tour.btn.back'),
                                    style: const TextStyle(fontSize: 12),
                                  ),
                                ),
                                // Next button (hidden if last step)
                                if (!isLastStep)
                                  ElevatedButton(
                                    onPressed: () {
                                      setState(() {
                                        _rootTourStep++;
                                      });
                                      _updateActiveTourTargetRect();
                                      _refreshRootTourOverlay();
                                    },
                                    style: ElevatedButton.styleFrom(
                                      padding: const EdgeInsets.symmetric(
                                          horizontal: 10, vertical: 4),
                                      minimumSize: Size.zero,
                                      tapTargetSize:
                                          MaterialTapTargetSize.shrinkWrap,
                                    ),
                                    child: Text(
                                      t('tour.btn.next'),
                                      style: const TextStyle(fontSize: 12),
                                    ),
                                  ),
                                // Close button (always visible)
                                TextButton(
                                  onPressed: () async {
                                    await _hideRootTourOverlay();
                                  },
                                  style: TextButton.styleFrom(
                                    padding: const EdgeInsets.symmetric(
                                        horizontal: 6, vertical: 4),
                                    minimumSize: Size.zero,
                                    tapTargetSize:
                                        MaterialTapTargetSize.shrinkWrap,
                                  ),
                                  child: Text(
                                    t('tour.btn.close'),
                                    style: const TextStyle(fontSize: 12),
                                  ),
                                ),
                              ],
                            ),
                          ],
                        ),
                      ),
                    ],
                  ),
                ),
              );
            },
          );
        }

        // Calculate auto-placement position for landscape mode
        double? bubbleLeft;
        double? bubbleTop;
        double? bubbleW; // Store for Step 3 & 11
        double? bubbleH; // Store for Step 3 & 11

        if (isLandscape && _activeTourTargetRect != null) {
          final screen = mq.size;
          final targetRect = _activeTourTargetRect!;

          // Panel mode positioning for steps 3 and 11
          if (panelMode) {
            // Bubble dimensions (kübik: 320x260 max)
            bubbleW = math.min(320.0,
                (mq.size.width - mq.padding.left - mq.padding.right) * 0.48);
            bubbleH = math.min(260.0,
                (mq.size.height - mq.padding.top - mq.padding.bottom) * 0.70);

            // Safe area values
            final double safeTop = mq.padding.top + 8.0;
            final double safeBottom = mq.size.height - mq.padding.bottom - 8.0;

            // Hard placement rules for Step 3 and Step 11
            if (stepShown == 3) {
              // STEP 3 (OCR) — bubble hedefin ALTINA, sağ tarafa gelsin
              // targetRect'in altı görünür kalmalı
              double calculatedTop =
                  math.max(targetRect.bottom + 12.0, safeTop);
              double calculatedLeft =
                  (mq.size.width - mq.padding.right - 12.0) - bubbleW;

              // Clamp to ensure bubble stays on screen
              bubbleTop = calculatedTop.clamp(safeTop, safeBottom - bubbleH);
              bubbleLeft = calculatedLeft.clamp(mq.padding.left + 12.0,
                  mq.size.width - mq.padding.right - 12.0 - bubbleW);
            } else if (stepShown == 11) {
              // STEP 11 (Controls) — bubble hedefin ÜSTÜNE, controls bar'ı kapatmamalı
              // Define "noCoverZoneTop" - controls bar'ın hemen üstü
              final noCoverZoneTop = targetRect.top - 8.0;

              // Bubble controls'un üstüne oturur
              bubbleTop = noCoverZoneTop - bubbleH!;
              // Clamp to safe area
              bubbleTop = math.max(bubbleTop!, safeTop);
              bubbleTop =
                  math.min(bubbleTop!, (noCoverZoneTop - 4.0) - bubbleH!);

              // Start with right-aligned position
              bubbleLeft = (mq.size.width - mq.padding.right - 12.0) - bubbleW!;

              // If bubble is too close to controls, shift horizontally left
              final minGap = 16.0;
              final wouldOverlapVertically =
                  (bubbleTop! + bubbleH! + minGap) > targetRect.top;
              if (wouldOverlapVertically) {
                // Shift left (if closing from right)
                bubbleLeft =
                    math.max(mq.padding.left + 12.0, bubbleLeft! - 80.0);
              }

              // Clamp to ensure bubble stays on screen
              bubbleTop = bubbleTop!.clamp(safeTop, safeBottom - bubbleH!);
              bubbleLeft = bubbleLeft!.clamp(mq.padding.left + 12.0,
                  mq.size.width - mq.padding.right - 12.0 - bubbleW!);

              // Final safety check: prevent bubble from covering controls bar
              final bubbleRect =
                  Rect.fromLTWH(bubbleLeft!, bubbleTop!, bubbleW!, bubbleH!);
              if (bubbleRect.overlaps(targetRect.inflate(6))) {
                // Move bubble to the left of target (still within screen)
                bubbleLeft = math.max(
                    mq.padding.left + 12.0, targetRect.left - bubbleW! - 12.0);
                // Clamp again
                bubbleLeft = math.min(bubbleLeft!,
                    mq.size.width - mq.padding.right - bubbleW! - 12.0);
              }
            } else {
              // Fallback (should not happen, but keep old logic)
              final bool targetOnRight =
                  targetRect.center.dx > mq.size.width / 2;
              double panelLeft = targetOnRight
                  ? (insets.left + pad)
                  : (mq.size.width - insets.right - pad - bubbleW);
              double panelTop = (insets.top + pad);

              bubbleLeft = panelLeft.clamp(insets.left + pad,
                  mq.size.width - insets.right - pad - bubbleW);
              bubbleTop = panelTop.clamp(insets.top + pad,
                  mq.size.height - insets.bottom - pad - bubbleH);
            }

            // Update last position
            _lastPos = Offset(bubbleLeft, bubbleTop);
            _lastPosStep = _rootTourStep;
          } else if (_bubbleSize != null) {
            // Normal auto-placement for other steps
            final bw = _bubbleSize!.width;
            final bh = _bubbleSize!.height;

            // 4 candidate positions: right, left, below, above
            final candidates = <Offset>[
              Offset(targetRect.right + pad, targetRect.top), // right
              Offset(targetRect.left - bw - pad, targetRect.top), // left
              Offset(targetRect.left, targetRect.bottom + pad), // below
              Offset(targetRect.left, targetRect.top - bh - pad), // above
            ];

            Offset clamp(Offset p) => Offset(
                  p.dx.clamp(pad, screen.width - bw - pad).toDouble(),
                  p.dy.clamp(pad, screen.height - bh - pad).toDouble(),
                );

            Rect rectAt(Offset p) => Rect.fromLTWH(p.dx, p.dy, bw, bh);

            // Find first non-overlapping position, or use first candidate if all overlap
            Offset best = clamp(candidates.first);
            for (final c in candidates) {
              final p = clamp(c);
              if (!rectAt(p).overlaps(targetRect)) {
                best = p;
                break;
              }
            }

            bubbleLeft = best.dx;
            bubbleTop = best.dy;
            // Update last position
            _lastPos = Offset(bubbleLeft, bubbleTop);
            _lastPosStep = _rootTourStep;
          } else {
            // PART B: Use last position until measurement arrives (prevent jumps)
            // _lastPos is initialized to Offset(12, 12), so always use it
            bubbleLeft = _lastPos.dx;
            bubbleTop = _lastPos.dy;
          }
        }

        // Build bubble widget with key for measurement
        Widget bubbleWidget;
        if (panelMode) {
          // Panel mode: build with LayoutBuilder for proper height constraint
          bubbleWidget = LayoutBuilder(
            builder: (context, constraints) {
              final mq = MediaQuery.of(context);
              final isLandscape = mq.orientation == Orientation.landscape;
              final safeH = mq.size.height - mq.padding.top - mq.padding.bottom;
              final safeW = mq.size.width - mq.padding.left - mq.padding.right;

              final bubbleMaxW = isLandscape
                  ? math.min(320.0, safeW * 0.48)
                  : math.min(360.0, safeW * 0.85);
              final bubbleMaxH = isLandscape
                  ? math.min(320.0, safeH * 0.80)
                  : math.min(420.0, safeH * 0.65);

              return ConstrainedBox(
                constraints: BoxConstraints(
                  maxWidth: bubbleMaxW,
                  maxHeight: bubbleMaxH,
                ),
                child: ClipRRect(
                  borderRadius: BorderRadius.circular(18),
                  child: Material(
                    elevation: 4,
                    color: kCream,
                    borderRadius: BorderRadius.circular(18),
                    child: buildBubbleContent(),
                  ),
                ),
              );
            },
          );
        } else {
          // Normal mode: build with LayoutBuilder for proper height constraint in landscape
          bubbleWidget = LayoutBuilder(
            builder: (context, constraints) {
              final mq = MediaQuery.of(context);
              final isLandscape = mq.orientation == Orientation.landscape;
              final safeH = mq.size.height - mq.padding.top - mq.padding.bottom;
              final safeW = mq.size.width - mq.padding.left - mq.padding.right;

              final bubbleMaxW = isLandscape
                  ? math.min(320.0, safeW * 0.48)
                  : math.min(360.0, safeW * 0.85);
              final bubbleMaxH = isLandscape
                  ? math.min(320.0, safeH * 0.80)
                  : math.min(420.0, safeH * 0.65);

              return ConstrainedBox(
                constraints: BoxConstraints(
                  maxWidth: bubbleMaxW,
                  maxHeight: bubbleMaxH,
                ),
                child: Material(
                  elevation: 4,
                  borderRadius: BorderRadius.circular(16),
                  color: kCream,
                  child: buildBubbleContent(),
                ),
              );
            },
          );
        }

        // PART C: Wrap with text scale clamp for steps 3 & 11
        Widget bubbleWidgetAfterScale = bubbleWidget;
        if (isLandscape && (stepShown == 3 || stepShown == 11)) {
          final mq = MediaQuery.of(context);
          final currentFactor = mq.textScaleFactor;
          final cappedFactor = math.min(currentFactor, 1.10);
          bubbleWidgetAfterScale = MediaQuery(
            data: mq.copyWith(
              textScaler: TextScaler.linear(cappedFactor),
            ),
            child: bubbleWidget,
          );
        }

        // Wrap with AnimatedSwitcher for smooth content transitions (landscape only)
        Widget bubbleContent = bubbleWidgetAfterScale;
        if (isLandscape) {
          bubbleContent = AnimatedSwitcher(
            duration: const Duration(milliseconds: 180),
            switchInCurve: Curves.easeOut,
            switchOutCurve: Curves.easeIn,
            transitionBuilder: (child, anim) {
              // PART D: Use only FadeTransition (no scale)
              return FadeTransition(
                opacity: anim,
                child: child,
              );
            },
            child: KeyedSubtree(
              key: ValueKey<int>(_rootTourStep), // Step change triggers fade
              child: bubbleWidgetAfterScale,
            ),
          );
        }

        // Wrap with key for measurement (only in landscape, skip for panelMode)
        if (isLandscape && !panelMode) {
          bubbleContent = KeyedSubtree(
            key: _tourBubbleKey,
            child: ConstrainedBox(
              constraints: BoxConstraints(
                maxWidth: math.min(
                    320.0,
                    (mq.size.width - mq.padding.left - mq.padding.right) *
                        0.48),
                maxHeight: math.min(
                    260.0,
                    (mq.size.height - mq.padding.top - mq.padding.bottom) *
                        0.70),
              ),
              child: bubbleContent,
            ),
          );
        }

        // PART A: Schedule measurement only if needed (landscape only, skip for panelMode)
        if (isLandscape && !panelMode && _bubbleSizeStep != _rootTourStep) {
          _scheduleMeasure();
        }

        return Stack(
          children: [
            // FIRST: Dim overlay with hole highlight (background layer)
            if (_activeTourTargetRect != null)
              Positioned.fill(
                child: IgnorePointer(
                  child: CustomPaint(
                    painter: _HolePainter(
                      target: _activeTourTargetRect!,
                    ),
                  ),
                ),
              ),
            // BLOCKER: Klavye ve focus tamamen engelle — hiçbir modda klavye açılmasın
            Positioned.fill(
              child: GestureDetector(
                behavior: HitTestBehavior.opaque,
                onTap: () => FocusManager.instance.primaryFocus?.unfocus(),
                onPanDown: (_) => FocusManager.instance.primaryFocus?.unfocus(),
                child: const SizedBox.expand(),
              ),
            ),
            // SECOND: White modal dialog (foreground layer)
            if (isLandscape)
              // Landscape: Auto-placed side panel layout with smooth animations
              bubbleLeft != null && bubbleTop != null
                  ? (panelMode && bubbleW != null && bubbleH != null
                      ? AnimatedPositioned(
                          duration: const Duration(milliseconds: 180),
                          curve: Curves.easeOutCubic,
                          left: bubbleLeft,
                          top: bubbleTop,
                          width: bubbleW,
                          height: bubbleH,
                          child: bubbleContent,
                        )
                      : AnimatedPositioned(
                          duration: const Duration(milliseconds: 240),
                          curve: Curves.easeOutCubic,
                          left: bubbleLeft,
                          top: bubbleTop,
                          child: bubbleContent,
                        ))
                  : Positioned.fill(
                      child: SafeArea(
                        child: Padding(
                          padding: const EdgeInsets.all(12),
                          child: Align(
                            alignment: Alignment.topRight,
                            child: bubbleContent,
                          ),
                        ),
                      ),
                    )
            else
              // Portrait: Original centered layout
              Material(
                color: Colors.transparent,
                child: Center(
                  child: SizedBox(
                    width: 350,
                    height: 320,
                    child: Container(
                      margin: const EdgeInsets.all(20),
                      decoration: BoxDecoration(
                        color: kCream,
                        borderRadius: BorderRadius.circular(11),
                      ),
                      child: Padding(
                        padding: const EdgeInsets.all(12),
                        child: buildBubbleContent(),
                      ),
                    ),
                  ),
                ),
              ),
          ],
        );
      },
    );

    Overlay.of(context, rootOverlay: true).insert(_tourOverlayEntry!);
  }

  Future<void> _hideRootTourOverlay() async {
    // Save preference if checkbox is checked
    if (_rootTourDontShowAgain) {
      final prefs = await SharedPreferences.getInstance();
      await prefs.setBool(kPrefRootTourDontShowAgain, true);
    }

    _tourOverlayEntry?.remove();
    _tourOverlayEntry = null;
  }

  void _showReadingTourDialog(TourStep step) {
    if (_readingTourDialogOpen) {
      try {
        Navigator.of(context, rootNavigator: true).pop();
      } catch (_) {}
      _readingTourDialogOpen = false;
    }

    _readingTourDialogOpen = true;

    showGeneralDialog(
      context: context,
      barrierDismissible: false,
      barrierLabel: 'ReadingTour',
      barrierColor: Colors
          .transparent, // Transparent - dim overlay is handled by ReadingPageTour
      pageBuilder: (_, __, ___) {
        return ReadingPageTour(
          step: step,
          onNext: _nextReadingTourStep,
          onClose: _endReadingTour,
          onBack:
              _readingTourCurrentStep != null && _readingTourCurrentStep! > 1
                  ? _previousReadingTourStep
                  : null,
          onDontShowAgain: _dontShowAgainReadingTour,
          totalSteps: _getTotalReadingTourSteps(),
        );
      },
    );
  }

  void _updateReadingTourStep() {
    if (_readingTourCurrentStep == null) return;

    // Enforce step bounds: 0-12
    if (_readingTourCurrentStep! < 0 || _readingTourCurrentStep! > 12) {
      _endReadingTour();
      return;
    }

    // Measure targetRect after layout (post-frame)
    final targetKey = _getReadingTourStepKey(_readingTourCurrentStep!, context);
    if (targetKey != null) {
      final renderBox =
          targetKey.currentContext?.findRenderObject() as RenderBox?;

      // Measure targetRect: if renderBox is null or size is zero, retry max 3 times
      if (renderBox == null ||
          renderBox.size.width == 0 ||
          renderBox.size.height == 0) {
        // Increment attempt counter
        _tourMeasureAttempts++;

        // If attempts < 3, retry once more
        if (_tourMeasureAttempts < 3) {
          WidgetsBinding.instance.addPostFrameCallback((_) {
            if (mounted && _readingTourCurrentStep != null) {
              setState(() {
                // Trigger rebuild to re-measure
              });
            }
          });
          return; // Exit early, will retry
        }
        // If attempts >= 3, stop retrying and show fallback
        // Tour overlay will show fallback bubble with debug message (if kDebugMode)
        // Next/Skip buttons will still work
      } else {
        // Target found successfully, reset counter
        _tourMeasureAttempts = 0;
      }

      // Capture and log rect when available for diagnostics
      if (renderBox != null &&
          renderBox.size.width != 0 &&
          renderBox.size.height != 0) {
        final position = renderBox.localToGlobal(Offset.zero);
        final rect = Rect.fromLTWH(position.dx, position.dy,
            renderBox.size.width, renderBox.size.height);
        final targetId = targetKey.toString();
        _tourRects[targetId] = rect;
      }

      // Scroll to target if needed (only if target is valid)
      if (renderBox != null && _scroll.hasClients) {
        final position = renderBox.localToGlobal(Offset.zero);
        final targetScroll =
            position.dy - MediaQuery.of(context).size.height / 3;
        if (targetScroll > 0 &&
            targetScroll < _scroll.position.maxScrollExtent) {
          _scroll.animateTo(
            targetScroll,
            duration: const Duration(milliseconds: 300),
            curve: Curves.easeInOut,
          );
        }
      }
    }

    // Force rebuild of tour overlay after measurement to ensure targetRect is updated
    // Only rebuild once, not in a loop
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (mounted && _readingTourCurrentStep != null) {
        setState(() {
          // Trigger rebuild to update tour overlay with measured targetRect
        });
      }
    });
  }

  GlobalKey? _getReadingTourStepKey(int step, BuildContext context) {
    switch (step) {
      case 0:
        return _readingTourKeyControls;
      case 1:
        return _readingTourKeyLanguage;
      case 2:
        return _readingTourKeyPaste;
      case 3:
        return _readingTourKeyOcr;
      case 4:
        return _readingTourKeyWebLink;
      case 5:
        return _readingTourKeyHistory;
      case 6:
        return _readingTourKeyFavorites;
      case 7:
        return _readingTourKeyNote;
      case 8:
        return _readingTourKeyTheme;
      case 9:
        return _readingTourKeyClean;
      case 10:
        return _readingTourKeyOpenFile;
      case 11:
        return _readingTourKeyControls;
      case 12:
        return isLandscape(context)
            ? _readingTourKeySettingsLandscape
            : _readingTourKeySettings;
      default:
        return null;
    }
  }

  TourStep? _buildReadingTourStep(int step) {
    final key = _getReadingTourStepKey(step, context);
    // Skip step if key is not mounted
    if (key?.currentContext == null) return null;

    switch (step) {
      case 0:
        return TourStep(
          index: 1,
          titleKey: 'tour.reading.step1.title',
          descKey: 'tour.reading.step1.body',
          targetId: 'tour.controls',
          targetKey: _readingTourKeyControls,
        );
      case 1:
        return TourStep(
          index: step,
          titleKey: 'tour.reading.step1.title',
          descKey: 'tour.reading.step1.body',
          targetId: 'tour.language',
          targetKey: _readingTourKeyLanguage,
        );
      case 2:
        return TourStep(
          index: step,
          titleKey: 'tour.reading.step2.title',
          descKey: 'tour.reading.step2.body',
          targetId: 'tour.paste',
          targetKey: _readingTourKeyPaste,
        );
      case 3:
        return TourStep(
          index: step,
          titleKey: 'tour.reading.step3.title',
          descKey: 'tour.reading.step3.body',
          targetId: 'tour.ocr',
          targetKey: _readingTourKeyOcr,
        );
      case 4:
        return TourStep(
          index: step,
          titleKey: 'tour.reading.step4.title',
          descKey: 'tour.reading.step4.body',
          targetId: 'tour.weblink',
          targetKey: _readingTourKeyWebLink,
        );
      case 5:
        return TourStep(
          index: step,
          titleKey: 'tour.reading.step5.title',
          descKey: 'tour.reading.step5.body',
          targetId: 'tour.history',
          targetKey: _readingTourKeyHistory,
        );
      case 6:
        return TourStep(
          index: step,
          titleKey: 'tour.reading.step6.title',
          descKey: 'tour.reading.step6.body',
          targetId: 'tour.favorites',
          targetKey: _readingTourKeyFavorites,
        );
      case 7:
        return TourStep(
          index: step,
          titleKey: 'tour.reading.step7.title',
          descKey: 'tour.reading.step7.body',
          targetId: 'tour.note',
          targetKey: _readingTourKeyNote,
        );
      case 8:
        return TourStep(
          index: step,
          titleKey: 'tour.reading.step8.title',
          descKey: 'tour.reading.step8.body',
          targetId: 'tour.theme',
          targetKey: _readingTourKeyTheme,
        );
      case 9:
        return TourStep(
          index: step,
          titleKey: 'tour.reading.step9.title',
          descKey: 'tour.reading.step9.body',
          targetId: 'tour.clean',
          targetKey: _readingTourKeyClean,
        );
      case 10:
        return TourStep(
          index: step,
          titleKey: 'tour.reading.step10.title',
          descKey: 'tour.reading.step10.body',
          targetId: 'tour.openFile',
          targetKey: _readingTourKeyOpenFile,
        );
      case 11:
        return TourStep(
          index: step,
          titleKey: 'tour.reading.step11.title',
          descKey: 'tour.reading.step11.body',
          targetId: 'tour.controls',
          targetKey: _readingTourKeyControls,
