  }

  int _getTotalReadingTourSteps() {
    return 12;
  }

  Widget _buildReadingTourHighlightOverlay() {
    final stepIndex = _readingTourCurrentStep;
    if (stepIndex == null) return const SizedBox.shrink();
    final step = _buildReadingTourStep(stepIndex);
    if (step == null) return const SizedBox.shrink();
    final String? id = step.targetId;
    if (id == null) return const SizedBox.shrink();
    Rect? rect = _tourRects[id];
    if (rect == null) return const SizedBox.shrink();

    // Convert global rect to Stack-local coordinate system
    final stackCtx = _readingTourStackKey.currentContext;
    if (stackCtx != null) {
      final stackBox = stackCtx.findRenderObject() as RenderBox?;
      if (stackBox != null && stackBox.hasSize) {
        final stackTopLeft = stackBox.localToGlobal(Offset.zero);
        rect = rect.translate(-stackTopLeft.dx, -stackTopLeft.dy);
      }
    }

    return IgnorePointer(
      child: CustomPaint(
        size: Size.infinite,
        painter: _HolePainter(target: rect),
      ),
    );
  }

  // Track build count for lifecycle logging
  int _buildCount = 0;

  @override

  /// Root tour body: 'EasyReading' geçen yerleri bold yapar
  Widget _buildRootTourBodyText(String text, {required bool isDark}) {
    const brand = 'EasyReading';
    final color = isDark ? Colors.black87 : const Color(0xFF3E2723);
    final baseStyle = GoogleFonts.lora(
        textStyle: TextStyle(
      fontSize: 14,
      color: color,
      height: 1.4,
      fontWeight: FontWeight.w400,
    ));
    final boldStyle = GoogleFonts.lora(
        textStyle: TextStyle(
      fontSize: 14,
      color: color,
      height: 1.4,
      fontWeight: FontWeight.w700,
    ));
    if (!text.contains(brand)) {
      return Text(text, style: baseStyle, textScaler: TextScaler.noScaling);
    }
    final parts = text.split(brand);
    final spans = <TextSpan>[];
    for (int i = 0; i < parts.length; i++) {
      if (parts[i].isNotEmpty)
        spans.add(TextSpan(text: parts[i], style: baseStyle));
      if (i < parts.length - 1)
        spans.add(TextSpan(text: brand, style: boldStyle));
    }
    return RichText(
      text: TextSpan(children: spans),
      textScaler: TextScaler.noScaling,
    );
  }

  @override
  void didChangeDependencies() {
    super.didChangeDependencies();
    // A07 gibi viewInsets.bottom=0 dönen cihazlar için ekran yüksekliği takibi
    final h = MediaQuery.of(context).size.height;
    if (_lastScreenHeight == 0) {
      _lastScreenHeight = h;
    } else if (h < _lastScreenHeight - 50) {
      _detectedKbHeight = _lastScreenHeight - h;
    } else if (h >= _lastScreenHeight - 10) {
      _detectedKbHeight = 0;
      _lastScreenHeight = h;
    }
  }

  @override
  void initState() {
    super.initState();
    _initVoiceLimit();
    WidgetsBinding.instance
        .addPostFrameCallback((_) => _checkForUpdate(context));

    // Log initial state (dontShow check is async, log separately in microtask)
    // Initialize reading language from UI language if not set
    _selectedLocale ??= _getLocaleFromAppLangCode(AppLang.code.value);
    _previousTextLength = _text.text.length; // Initialize for paste detection
    _lastTextHash = _text.text.hashCode; // Initialize text hash
    WidgetsBinding.instance.addObserver(this);
    // Metin seçildiğinde klavye açılmasın — sadece explicit tap ile açılsın
    _textFocus.addListener(() {
      // Okuma sırasında VEYA tour aktifken focus gelince hemen unfocus yap
      if (_textFocus.hasFocus &&
          (_isReadingRunningNow || _readingTourCurrentStep != null)) {
        Future.microtask(() => FocusManager.instance.primaryFocus?.unfocus());
        return;
      }
      // Yatay modda klavye açılınca scroll'u yukarı al → imleç görünür olsun
      final isLandscape =
          MediaQuery.maybeOf(context)?.orientation == Orientation.landscape;
      if (_textFocus.hasFocus && isLandscape && _scroll.hasClients) {
        // Klavye açılınca Flutter önce aşağı scroll yapıyor.
        // Biz biraz sonra imleci görünür alana getiriyoruz.
        // 600ms: klavye animasyonu + Flutter'ın kendi scroll'u bitmeden önce gitmesin
        Future.delayed(const Duration(milliseconds: 600), () {
          if (!mounted || !_scroll.hasClients) return;
          // _scrollToCursor ile imlecin tam pozisyonunu bul
          _scrollToCursor();
        });
      }
    });
    // ANR önlemek için bootstrap'ı microtask'e taşı
    Future.microtask(() async {
      await _loadPersisted();
      // After loading persisted state, ALWAYS sync reading language with UI language
      // This ensures welcome page language selection is always reflected
      final uiLangLocale = _getLocaleFromAppLangCode(AppLang.code.value);
      if (uiLangLocale != null) {
        _selectedLocale = uiLangLocale;
        // Update voice to match UI language
        _selectedVoice =
            _findBestVoiceForLocaleAndGender(uiLangLocale, _voiceGender);
        final actualGender =
            (_selectedVoice?['gender'] as String? ?? 'female').toLowerCase();
        if (actualGender != _voiceGender.toLowerCase()) {
          _voiceGender = actualGender;
        }
        // Update TTS language
        try {
          await _tts.setLanguage(uiLangLocale);
          if (_selectedVoice != null) {
            await _tts.setVoice({
              'name': _selectedVoice!['name'],
              'locale': uiLangLocale,
            });
          }
        } catch (e) {}
        if (mounted) setState(() {});
      }
      await _loadHistory();
      await _bootstrap();
      // Bootstrap bittikten sonra UI dilini tekrar zorla uygula
      // _bootstrap _selectedLocale'i ezebilir, bu satır onu düzeltir
      final uiLocaleAfterBootstrap =
          _getLocaleFromAppLangCode(AppLang.code.value);
      if (uiLocaleAfterBootstrap != null && mounted) {
        final newVoice = _findBestVoiceForLocaleAndGender(
            uiLocaleAfterBootstrap, _voiceGender);
        setState(() {
          _selectedLocale = uiLocaleAfterBootstrap;
          if (newVoice != null) _selectedVoice = newVoice;
        });
        try {
          await _tts.setLanguage(uiLocaleAfterBootstrap);
          if (_selectedVoice != null) {
            await _tts.setVoice({
              'name': _selectedVoice!['name'],
              'locale': uiLocaleAfterBootstrap,
            });
          }
        } catch (e) {}
      }
      if (mounted) setState(() => _isLoadingVoices = false);

      // Check if Reading Page tour should start
      // Schedule after TWO post-frame callbacks to ensure UI is fully ready
      WidgetsBinding.instance.addPostFrameCallback((_) {
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (!mounted) return;
          _checkAndStartReadingTour();
        });
      });
    });

    // Listen to text changes for automatic history capture
    _text.addListener(_onTextChanged);
    _applyTtsDefaults();
    // Register callback to update TTS locale when UI language changes
    AppLang.onUiLanguageChanged = _updateTtsLocaleFromUiLanguage;
    // Listen to UI language changes to sync reading language dropdown
    AppLang.code.addListener(_onUiLanguageChangedSync);
  }

  // Sync reading language dropdown when UI language changes
  // ⚠️ This function is ONLY called when user changes UI language (via dropdown).
  // It should NOT interfere with auto-detection. Auto-detection changes _selectedLocale
  // but should NEVER trigger this function (which would require AppLang.code to change).
  void _onUiLanguageChangedSync() {
    if (!mounted) return;
    final uiLangLocale = _getLocaleFromAppLangCode(AppLang.code.value);
    if (uiLangLocale == null) return;
    _userManuallySelectedLanguage = false;
    setState(() {
      _selectedLocale = uiLangLocale;
      _selectedVoice =
          _findBestVoiceForLocaleAndGender(uiLangLocale, _voiceGender);
      final actualGender =
          (_selectedVoice?['gender'] as String? ?? 'female').toLowerCase();
      if (actualGender != _voiceGender.toLowerCase()) {
        _voiceGender = actualGender;
      }
      // Demo text varsa yeni dile güncelle
      if (_isDemoText(_text.text)) {
        _isUpdatingTextProgrammatically = true;
        _text.text = _getDemoText(AppLang.code.value);
        _text.selection = TextSelection.collapsed(offset: 0);
        _isUpdatingTextProgrammatically = false;
      }
    });
    _tts.setLanguage(uiLangLocale).then((_) async {
      if (_selectedVoice != null && mounted) {
        await _tts.setVoice({
          'name': _selectedVoice!['name'],
          'locale': uiLangLocale,
        });
      }
      // Demo text varsa TTS parametrelerini de güncelle
      if (mounted) {
        await _tts.setSpeechRate(_rate);
        await _tts.setPitch(_pitch);
        await _tts.setVolume(_volume);
      }
    }).catchError((e) {});
  }

  // Update TTS locale when UI language changes (if follow_ui is enabled)
  Future<void> _updateTtsLocaleFromUiLanguage(String targetLocale) async {
    if (!mounted) return;

    // Save previous locale for revert on error
    final previousLocale = _selectedLocale ?? kLanguages.first.ttsLocale;

    try {
      // Normalize locale
      final normalizedLocale = _normalizeLocale(targetLocale);

      // Find the language entry - check if it actually exists in kLanguages
      LanguageEntry? langEntry;
      try {
        langEntry = kLanguages.firstWhere(
          (l) => _normalizeLocale(l.ttsLocale) == normalizedLocale,
        );
      } catch (e) {
        // Locale not found in kLanguages, skip TTS update
        return;
      }

      setState(() {
        _selectedLocale = normalizedLocale;
        _selectedVoice =
            _findBestVoiceForLocaleAndGender(normalizedLocale, _voiceGender);
        final actualGender =
            (_selectedVoice?['gender'] as String? ?? 'female').toLowerCase();
        if (actualGender != _voiceGender.toLowerCase()) {
          _voiceGender = actualGender;
        }
      });

      // Set language in TTS engine
      final langResult = await _tts.setLanguage(normalizedLocale);

      final langOk =
          (langResult is int) ? (langResult == 1 || langResult == 0) : true;

      if (!langOk) {
        throw Exception('setLanguage returned: $langResult');
      }

      // Set voice if available
      if (_selectedVoice != null) {
        await _tts.setVoice({
          'name': _selectedVoice!['name'],
          'locale': normalizedLocale,
        });
      }

      // Also set speech parameters
      await _tts.setSpeechRate(_rate);
      await _tts.setPitch(_pitch);
      await _tts.setVolume(_volume);

      // Save persisted state
      await _savePersisted();
    } catch (e) {
      // Revert to previous locale on error
      if (mounted) {
        setState(() {
          _selectedLocale = previousLocale;
          _selectedVoice =
              _findBestVoiceForLocaleAndGender(previousLocale, _voiceGender);
        });
      }
    }
  }

  Future<void> _applyTtsDefaults() async {
    try {
      await _tts.setPitch(_pitch);
      await _tts.setSpeechRate(_rate);
      await _tts.setVolume(_volume);
    } catch (e) {}
  }

  // Open ChatGPT app or website with selected text copied to clipboard
  Future<void> _openChatGptWithText(String selectedText) async {
    try {
      // Copy text to clipboard
      await Clipboard.setData(ClipboardData(text: selectedText));

      bool appOpened = false;

      // Try to open ChatGPT app (Android)
      if (Platform.isAndroid) {
        try {
          final platform = MethodChannel('easyreading/system');
          // Check if ChatGPT app is installed
          final isInstalled = await platform.invokeMethod<bool>(
              'isAppInstalled', {'packageName': 'com.openai.chatgpt'});

          if (isInstalled == true) {
            // Launch the app
            final launched = await platform.invokeMethod<bool>(
                'launchApp', {'packageName': 'com.openai.chatgpt'});
            appOpened = launched == true;
          }
        } catch (e) {}

        // If app not found or launch failed, open website
        if (!appOpened) {
          final webUri = Uri.parse('https://chatgpt.com/');
          if (await canLaunchUrl(webUri)) {
            await launchUrl(webUri, mode: LaunchMode.externalApplication);
          }
        }
      } else {
        // iOS or other platforms - open website
        final webUri = Uri.parse('https://chatgpt.com/');
        if (await canLaunchUrl(webUri)) {
          await launchUrl(webUri, mode: LaunchMode.externalApplication);
        }
      }

      // Show success message
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
            'chatgpt.copiedOpened',
            behavior: SnackBarBehavior.floating));
      }
    } catch (e) {
      // Still show message even if there's an error
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
            'chatgpt.copiedOpened',
            behavior: SnackBarBehavior.floating));
      }
    }
  }

  Future<void> _openChatGptExternal() async {
    // Tek sefer çalış kilidi
    if (_openingChatGpt) return;
    _openingChatGpt = true;
    try {
      // Önce açık dialog/bottomsheet varsa kapat
      if (Navigator.of(context).canPop()) {
        Navigator.of(context).pop();
      }

      // Android'de external browser aç (ChatGPT app zaten yüklü, bu fallback)
      if (Platform.isAndroid) {
        final uri = Uri.parse('https://chatgpt.com/');
        if (await canLaunchUrl(uri)) {
          await launchUrl(uri, mode: LaunchMode.externalApplication);
        }
        _openingChatGpt = false;
        return;
      }

      // iOS veya ChatGPT uygulaması yüklüyse WebView aç (eski davranış)
      // WebViewController oluştur
      final controller = WebViewController()
        ..setJavaScriptMode(JavaScriptMode.unrestricted)
        ..setUserAgent(
            "Mozilla/5.0 (Linux; Android 13; Mobile) AppleWebKit/537.36 (KHTML, like Gecko) Chrome Mobile Safari/537.36")
        ..enableZoom(true)
        ..loadRequest(Uri.parse("https://chatgpt.com/"));

      // Full-screen bottom sheet ile aç
      await showModalBottomSheet(
        context: context,
        isScrollControlled: true,
        useSafeArea: true,
        backgroundColor: Colors.transparent,
        builder: (context) {
          return Container(
            decoration: BoxDecoration(
              color: Theme.of(context).scaffoldBackgroundColor,
              borderRadius: const BorderRadius.only(
                topLeft: Radius.circular(16),
                topRight: Radius.circular(16),
              ),
            ),
            child: Column(
              children: [
                // Header bar
                Container(
                  padding:
                      const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
                  decoration: BoxDecoration(
                    color: Theme.of(context).appBarTheme.backgroundColor ??
                        Theme.of(context).primaryColor,
                    borderRadius: const BorderRadius.only(
                      topLeft: Radius.circular(16),
                      topRight: Radius.circular(16),
                    ),
                  ),
                  child: Row(
                    children: [
                      Text(
                        'ChatGPT',
                        style: TextStyle(
                          fontSize: 18,
                          fontWeight: FontWeight.bold,
                          color:
                              Theme.of(context).appBarTheme.foregroundColor ??
                                  Colors.white,
                        ),
                      ),
                      const Spacer(),
                      IconButton(
                        icon: Icon(
                          Icons.close,
                          color:
                              Theme.of(context).appBarTheme.foregroundColor ??
                                  Colors.white,
                        ),
                        onPressed: () => Navigator.pop(context),
                      ),
                    ],
                  ),
                ),
                // WebView
                Expanded(
                  child: WebViewWidget(controller: controller),
                ),
              ],
            ),
          );
        },
      );
    } catch (e) {
    } finally {
      _openingChatGpt = false;
    }
  }

  @override
  void _onTextChanged() {
    // Guard: Skip all processing if this is a programmatic clear
    if (_isProgrammaticClear) return;

    // Kullanıcı yeni metin yazınca user_cleared flag'ini sıfırla
    if (!_isUpdatingTextProgrammatically && _text.text.isNotEmpty) {
      SharedPreferences.getInstance().then((sp) {
        sp.remove(_prefsKeyUserCleared);
      });
    }

    // Automatic history capture on text changes (manual typing/paste)
    // Skip if we're updating text programmatically (file open, OCR, etc.)
    // Those cases call _captureHistory directly
    if (!_isUpdatingTextProgrammatically) {
      _captureHistory(_text.text, fileName: _selectedFileName);

      // Detect language when text is added (paste or typing)
      final currentLength = _text.text.length;
      final lengthDiff = currentLength - _previousTextLength;
      // TASK 3: If text increased by 10+ chars (paste) or total text is minChars+ chars (enough for detection)
      if (_text.text.isNotEmpty &&
          mounted &&
          (lengthDiff >= 10 || (currentLength >= minChars && lengthDiff > 0))) {
        // TASK 3: Check cooldown period - don't detect if too soon after last detection
        final now = DateTime.now();
        final shouldDetect = _lastLanguageDetectionTime == null ||
            now.difference(_lastLanguageDetectionTime!).inMilliseconds >=
                cooldownMs;

        if (shouldDetect) {
          // Cancel existing debounce
          _languageDetectionDebounce?.cancel();

          // Debounce language detection (300ms)
          _languageDetectionDebounce =
              Timer(const Duration(milliseconds: 300), () {
            if (!mounted) return;
            final detectedLang = _detectLanguageFromText(_text.text);
            if (detectedLang != null) {
              // TASK 3: Update last detection time
              _lastLanguageDetectionTime = DateTime.now();
              if (detectedLang == 'fr-FR') {
                _allowAutoFrenchOnce = true;
              }
              _switchToLanguageSilently(detectedLang);
            }
          });
        }
      }

      // Reset TTS and scroll state when significant text is added (10+ chars or paste)
      // This ensures play button works after text is added/modified
      // Only reset if text was added (not deleted) and it's a significant change
      if (mounted && lengthDiff >= 10) {
        // Reset state flags to allow fresh start after text addition
        _isPlaying = false;
        _ttsBusy = false;
        _ttsStopRequested = false;
        _ttsPaused = false;
        _ttsRunning = false;

        // Stop any ongoing TTS and scroll
        Future.microtask(() async {
          _stopAutoScrollHard();
          await _ttsStopAll();
          // Reset stop flag after stop completes
          _ttsStopRequested = false;

          // Reset UI state
          if (mounted) {
            setState(() {
              _isPaused = false;
              _autoScroll = false;
              _isSpeaking = false;
              _ttsPaused = false;
              _ttsRunning = false;
              _isTtsPlaying = false;
            });
          }
        });
      }

      _previousTextLength = currentLength;
    } else {
      // Update tracked length even when programmatically updating
      _previousTextLength = _text.text.length;
    }
  }

  @override
  void didChangeMetrics() {
    super.didChangeMetrics();
    // Orientation değişiminde highlight rect'leri sıfırla — stretch glitch'i önler
    if (_highlightRects.isNotEmpty) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (mounted) setState(() => _highlightRects = []);
      });
    }
    // If tour is active, close keyboard on orientation change
    if (_readingTourCurrentStep != null) {
      Future.microtask(() {
        FocusManager.instance.primaryFocus?.unfocus();
      });
    }
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    super.didChangeAppLifecycleState(state);

    // TASK 3 FIX: Handle app lifecycle WITHOUT autoplay
    if (state == AppLifecycleState.paused ||
        state == AppLifecycleState.inactive ||
        state == AppLifecycleState.detached) {
      // App going to background - stop TTS if playing
      if (_isTtsPlaying) {
        _tts.stop();
      }
      _voiceLimitTimer?.cancel();
      if (_voiceSecsUsed > 0)
        PremiumService.instance.setVoiceSecs(_voiceSecsUsed);
      // Also pause auto-scroll if running
      if (_isAutoScrollOn) {
        _stopAutoScrollHard();
      }
      // Metni kaydet — uygulama kapanınca kaybolmasın
      _savePersisted();
    } else if (state == AppLifecycleState.resumed) {
      // Re-engagement: kullanıcı uygulamaya döndü → sayaçları sıfırla
      unawaited(NotificationService.scheduleReminder()); // local fallback
      unawaited(PushService.trackActive()); // FCM aktiflik güncelle
      // IMPORTANT: Do NOT auto-start TTS or scrolling here
      // Only re-check TTS engine readiness for when user manually starts
      Future.microtask(() async {
        if (_isDisposed || !mounted) return;

        try {
          // Check if engine is responsive
          if (Platform.isAndroid && _currentEngineId != null) {
            final currentEngine = await _tts.getDefaultEngine;
            if (currentEngine != _currentEngineId) {
              // Re-init TTS safely without changing UI state
              await _initTts();
            } else {
              // Engine matches, but verify it's responsive
              try {
                await _tts
                    .getLanguages; // Simple check to verify engine is responsive
              } catch (e) {
                await _initTts();
              }
            }
          } else {
            // iOS or no engine set, just verify responsiveness
            try {
              await _tts.getLanguages;
            } catch (e) {
              await _initTts();
            }
          }
        } catch (e) {
          // Re-init on any error
          await _initTts();
        }
      });

      // DO NOT call startReading() or resume TTS here
      // User must manually press play button after returning to app
    }
  }

  @override
  void dispose() {
    _immersiveAutoHideTimer?.cancel();
    _voiceLimitTimer?.cancel();
    WidgetsBinding.instance.removeObserver(this);
    _isDisposed = true;
    // Unregister callback
    AppLang.onUiLanguageChanged = null;
    // Remove UI language change listener
    AppLang.code.removeListener(_onUiLanguageChangedSync);
    _tourRects.clear();
    // Best-effort close if a dialog is still up while disposing
    if (_readingTourDialogOpen) {
      try {
        Navigator.of(context, rootNavigator: true).pop();
      } catch (_) {
        // ignore
      }
      _readingTourDialogOpen = false;
    }
    _autoScrollTimer?.cancel();
    _autoScrollTimer = null;
    _settingsDebounce?.cancel();
    _ttsStartCheckTimer?.cancel();
    _historyDebounceTimer?.cancel();
    _languageDetectionDebounce?.cancel();
    _ttsWatchdogTimer?.cancel();
    _text.removeListener(_onTextChanged);
    _tts.stop();
    _text.dispose();
    _textFocus.dispose();
    _scroll.dispose();
    super.dispose();
  }

  // Normalize locale: handle underscores vs hyphens, known aliases
  String _normalizeLocale(String locale) {
    // Convert underscores to hyphens
    locale = locale.replaceAll('_', '-');

    // Handle known aliases
    final aliasMap = {
      'cz': 'cs', // Czech
      'se': 'sv', // Swedish
      'iw': 'he', // Hebrew (old code)
    };

    final parts = locale.split('-');
    final lang = parts[0].toLowerCase();

    // Apply alias if needed
    if (aliasMap.containsKey(lang)) {
      parts[0] = aliasMap[lang]!;
      locale = parts.join('-');
    }

    // Normalize specific locales
    if (locale.toLowerCase().startsWith('tr')) {
      return 'tr-TR';
    } else if (locale.toLowerCase().startsWith('he') ||
        locale.toLowerCase().startsWith('iw')) {
      return 'he-IL';
    }

    return locale;
  }

  // Find LanguageEntry by ttsLocale
  LanguageEntry? _findLanguageEntryByLocale(String locale) {
    final normalized = _normalizeLocale(locale);
    return kLanguages.firstWhere(
      (entry) => _normalizeLocale(entry.ttsLocale) == normalized,
      orElse: () => kLanguages.first, // Fallback to first (Turkish)
    );
  }

  // Helper: Get language name from locale code
  String _getLanguageName(String locale) {
    final langEntry = _findLanguageEntryByLocale(locale);
    return langEntry?.displayName ?? locale;
  }

  // Helper: Convert AppLang.code.value to ttsLocale
  String? _getLocaleFromAppLangCode(String appLangCode) {
    final langEntry = kLanguages.firstWhere(
      (entry) => entry.id == appLangCode.toLowerCase(),
      orElse: () => kLanguages.first, // Fallback to first (Turkish)
    );
    return langEntry.ttsLocale;
  }

  // Helper functions for safe dropdown handling
  List<DropdownMenuItem<String>> _uniqItemsByValue(
      List<DropdownMenuItem<String>> items) {
    final seen = <String>{};
    final out = <DropdownMenuItem<String>>[];
    for (final it in items) {
      final v = it.value;
      if (v == null) continue;
      if (seen.add(v)) out.add(it);
    }
    return out;
  }

  String? _safeDropdownValue(
      String? value, List<DropdownMenuItem<String>> items) {
    if (value == null) return null;
    final ok = items.any((it) => it.value == value);
    return ok ? value : null;
  }

  // Build compact language dropdown for AppBar title
  Widget _buildLanguageDropdownCompact({Key? key}) {
    if (_isLoadingVoices) {
      return const SizedBox(
        width: 80,
        child: Center(child: CircularProgressIndicator(strokeWidth: 2)),
      );
    }

    // Filter languages based on whitelist for Reading Page dropdown
    final visibleReadingLocales = kLanguages.where((lang) {
      return kReadingDropdownAllowedLocales.contains(lang.ttsLocale);
    }).toList();

    // Use selected locale if set and in whitelist, otherwise fallback to first whitelisted locale
    final displayLocale = (_selectedLocale != null &&
            visibleReadingLocales.any((l) => l.ttsLocale == _selectedLocale))
        ? _selectedLocale!
        : visibleReadingLocales.first.ttsLocale;

    // Build raw items first (using filtered list)
    final rawItems = visibleReadingLocales.map((lang) {
      final isComingSoon = lang.id == 'ar' || lang.id == 'he';
      return DropdownMenuItem<String>(
        value: lang.ttsLocale,
        enabled: !isComingSoon,
        child: Opacity(
          opacity: isComingSoon ? 0.5 : 1.0,
          child: Row(
            children: [
              Text(
                lang.flag,
                style: const TextStyle(fontSize: 20),
                textScaler: TextScaler.noScaling,
              ),
              const SizedBox(width: 8),
              Expanded(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(
                      lang.displayName,
                      maxLines: 1,
                      overflow: TextOverflow.ellipsis,
                      softWrap: false,
                      textScaler: TextScaler.noScaling,
                    ),
                    if (isComingSoon)
                      Text(
                        t('lang.coming_soon'),
                        maxLines: 1,
                        textScaler: TextScaler.noScaling,
                        style: TextStyle(
                          fontSize: 10,
                          color: kBeigeDark,
                          fontStyle: FontStyle.italic,
                        ),
                      ),
                  ],
                ),
              ),
            ],
          ),
        ),
      );
    }).toList();

    // Make items unique and safe
    final items = _uniqItemsByValue(rawItems);
    final safeValue = _safeDropdownValue(displayLocale, items);

    return ConstrainedBox(
      constraints: const BoxConstraints(minWidth: 130, maxWidth: 200),
      child: DropdownButtonHideUnderline(
        child: KeyedSubtree(
          key: key,
          child: DropdownButton<String>(
            isDense: true,
            underline: const SizedBox.shrink(),
            value: safeValue,
            isExpanded: true,
            icon: Icon(
              Icons.keyboard_arrow_down_rounded,
              size: 18,
              color: Theme.of(context).brightness == Brightness.dark
                  ? Colors.white
                  : Colors.black87,
            ),
            menuMaxHeight: 360,
            selectedItemBuilder: (BuildContext context) {
              return items.map<Widget>((item) {
                final lang = visibleReadingLocales.firstWhere(
                  (l) => l.ttsLocale == item.value,
                  orElse: () => visibleReadingLocales.first,
                );
                return Row(
                  mainAxisSize: MainAxisSize.min,
                  children: [
                    Text(
                      lang.flag,
                      style: const TextStyle(fontSize: 20),
                      textScaler: TextScaler.noScaling,
                    ),
                    const SizedBox(width: 4),
                    Flexible(
                      child: Text(
                        lang.displayName,
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                        softWrap: false,
                        textScaler: TextScaler.noScaling,
                      ),
                    ),
                  ],
                );
              }).toList();
            },
            items: items,
            onChanged: (val) async {
              if (val == null) return;

              // TASK 3: Mark that user manually selected language
              _userManuallySelectedLanguage = true;
              // Disable auto-detect when user manually changes language
              _autoDetectEnabled = false;

              // Normalize locale
              final normalizedLocale = _normalizeLocale(val);

              // Allow French if user manually selects it
              if (normalizedLocale == 'fr-FR') {
                _allowAutoFrenchOnce = true;
              }

              // Save previous locale for revert on error
              final previousLocale =
                  _selectedLocale ?? kLanguages.first.ttsLocale;

              // Find the language entry for debug logging
              final langEntry = kLanguages.firstWhere(
                (l) => _normalizeLocale(l.ttsLocale) == normalizedLocale,
                orElse: () => kLanguages.first,
              );

              // Debug log as specified

              setState(() {
                _selectedLocale = normalizedLocale;
                _selectedVoice = _findBestVoiceForLocaleAndGender(
                    normalizedLocale, _voiceGender);
                final actualGender =
                    (_selectedVoice?['gender'] as String? ?? 'female')
                        .toLowerCase();
                if (actualGender != _voiceGender.toLowerCase()) {
                  _voiceGender = actualGender;
                }
              });

              try {
                // Set language first
                final langResult = await _tts.setLanguage(normalizedLocale);

                final langOk = (langResult is int)
                    ? (langResult == 1 || langResult == 0)
                    : true;

                if (!langOk) {
                  throw Exception('setLanguage returned: $langResult');
                }

                // Then set voice if available
                if (_selectedVoice != null) {
                  await _tts.setVoice({
                    'name': _selectedVoice!['name'],
                    'locale': normalizedLocale,
                  });
                }

                // Also set speech parameters
                await _tts.setSpeechRate(_rate);
                await _tts.setPitch(_pitch);
                await _tts.setVolume(_volume);
              } catch (e) {
                // Revert to previous locale
                if (mounted) {
                  setState(() {
                    _selectedLocale = previousLocale;
                    _selectedVoice = _findBestVoiceForLocaleAndGender(
                        previousLocale, _voiceGender);
                  });

                  // Show localized error message
                  final isTr = AppLang.code.value == 'tr';
                  ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
                      isTr
                          ? 'Bu dil bu cihazda desteklenmiyor.'
                          : "This language isn't supported on this device.",
                      behavior: SnackBarBehavior.floating));
                }
              }

              await _savePersisted();
            },
          ),
        ),
      ),
    );
  }

  Widget _buildUiLanguageDropdownCompact() {
    const fullLabel = <String, String>{
      'tr': 'Türkçe',
      'en': 'English',
      'it': 'Italiano',
      'de': 'Deutsch',
      'fr': 'Français',
      'es': 'Español',
      'el': 'Ελληνικά',
      'ru': 'Русский',
      'ja': '日本語',
      'ko': '한국어',
      'bg': 'Български',
      'hi': 'Hindi',
    };

    const flagLabel = <String, String>{
      'tr': '🇹🇷',
      'en': '🇺🇸',
      'it': '🇮🇹',
      'de': '🇩🇪',
      'fr': '🇫🇷',
      'es': '🇪🇸',
      'el': '🇬🇷',
      'ru': '🇷🇺',
      'ja': '🇯🇵',
      'ko': '🇰🇷',
      'bg': '🇧🇬',
      'hi': '🇮🇳',
    };

    const shortLabel = <String, String>{
      'tr': 'TR',
      'en': 'EN',
      'it': 'IT',
      'de': 'DE',
      'fr': 'FR',
      'es': 'ES',
      'el': 'EL',
      'ru': 'RU',
      'ja': 'JA',
      'ko': 'KO',
      'bg': 'BG',
    };

    String normalize(String code) {
      final c = code.trim();
      final base = c.split('_').first.split('-').first;
      return base.toLowerCase();
    }

    final codes = AppLang.supportedUiCodes;
    final current = AppLang.code.value;

    return LayoutBuilder(
      builder: (context, constraints) {
        final screenWidth = MediaQuery.of(context).size.width;
        final maxWidth = (screenWidth * 0.42).clamp(110.0, 210.0);

        final textStyle = Theme.of(context).textTheme.bodyMedium ??
            const TextStyle(fontSize: 12);

        Widget scaledText(String text) {
          return FittedBox(
            fit: BoxFit.scaleDown,
            alignment: Alignment.centerLeft,
            child: Text(
              text,
              style: textStyle.copyWith(fontSize: 12),
              maxLines: 1,
              softWrap: false,
              overflow: TextOverflow.visible,
            ),
          );
        }

        final items = codes.map((code) {
          final base = normalize(code);
          final label = fullLabel[base] ?? code;
          final flag = flagLabel[base] ?? '';
          return DropdownMenuItem<String>(
            value: code,
            child: Row(
              mainAxisSize: MainAxisSize.min,
              children: [
                if (flag.isNotEmpty) ...[
                  Text(flag, style: const TextStyle(fontSize: 16)),
                  const SizedBox(width: 6),
                ],
                Flexible(child: scaledText(label)),
              ],
            ),
          );
        }).toList();

        return ConstrainedBox(
          constraints: BoxConstraints(
            minWidth: 110,
            maxWidth: maxWidth,
          ),
          child: DropdownButtonHideUnderline(
            child: DropdownButton<String>(
              value: current,
              isExpanded: true,
              iconSize: 18,
              selectedItemBuilder: (context) {
                return codes.map((code) {
                  final base = normalize(code);
                  final full = fullLabel[base] ?? code;
                  final short = shortLabel[base] ?? base.toUpperCase();

                  final display = full.length <= 12 ? full : short;

                  return Align(
                    alignment: Alignment.centerLeft,
                    child: scaledText(display),
                  );
                }).toList();
              },
              items: items,
              onChanged: (code) async {
                if (code == null) return;
                AppLang.code.value = code;
                await AppLang.set(code);
              },
            ),
          ),
        );
      },
    );
  }

  // ================== LANGUAGE DETECTION ==================
  // Helper: Normalize language code (e.g., 'es-ES' -> 'es', 'en_US' -> 'en')
  String? _normLangCode(String? raw) {
    if (raw == null) return null;
    final s = raw.trim().toLowerCase();
    if (s.isEmpty) return null;
    // 'es-ES' -> 'es'
    if (s.contains('-')) return s.split('-').first;
    if (s.contains('_')) return s.split('_').first;
    return s;
  }

  // Helper: Convert base language code to full TTS locale (e.g., 'es' -> 'es-ES')
  String? _baseCodeToFullLocale(String? baseCode) {
    if (baseCode == null) return null;
    final normalized = _normLangCode(baseCode);
    if (normalized == null) return null;

    // Map base codes to full locales for TTS
    final localeMap = {
      'ar': 'ar-SA',
      'he': 'he-IL',
      'el': 'el-GR',
      'hi': 'hi-IN',
      'ko': 'ko-KR',
      'ja': 'ja-JP',
      'zh': 'zh-CN',
      'bg': 'bg-BG',
      'ru': 'ru-RU',
      'tr': 'tr-TR',
      'de': 'de-DE',
      'nl': 'nl-NL',
      'es': 'es-ES',
      'pt': 'pt-PT',
      'fr': 'fr-FR',
      'en': 'en-US',
      'it': 'it-IT',
    };

    return localeMap[normalized] ?? baseCode;
  }

  // Helper: Check if text looks like Spanish (fallback heuristic)
  bool _looksSpanish(String t) {
    final s = t.toLowerCase();
    // İspanyolca karakter ipuçları + stopword
    final hasMarks = RegExp(r'[ñáéíóúü¡¿]').hasMatch(s);
    final stop = RegExp(
        r'\b(el|la|los|las|un|una|de|que|y|en|por|para|con|como|pero|porque|muy|esta|este|son|se|del|al)\b');
    final m = stop.allMatches(s).length;
    // 80+ karakterde 6+ stopword veya özel karakter varsa Spanish say
    return hasMarks || m >= 6;
  }

  // Helper: Check if text actually contains Greek script characters
  bool _looksGreekScript(String text) {
    if (text.isEmpty) return false;
    int greek = 0;
    int letters = 0;
    for (final r in text.runes) {
      // Latin/Greek ayrımı için sadece harf benzeri aralıklara bakıyoruz
      final isLetter = (r >= 0x0041 && r <= 0x024F) ||
          (r >= 0x0370 && r <= 0x03FF) ||
          (r >= 0x1F00 && r <= 0x1FFF);
      if (!isLetter) continue;
      letters++;
      final isGreek =
          (r >= 0x0370 && r <= 0x03FF) || (r >= 0x1F00 && r <= 0x1FFF);
      if (isGreek) greek++;
    }
    if (letters < 30) return false; // çok kısaysa kararsız
    final ratio = greek / letters;
    return ratio >= 0.20; // %20+ Greek harfi varsa Greek say
  }

  // Detect language from text using character patterns and common words
  // ⚠️ CRITICAL: This function returns a TTS locale (e.g., 'es-ES') for reading/TTS language only.
  // The return value MUST ONLY be used to update _selectedLocale (reading language).
  // It MUST NEVER be used to change UI language (AppLang.code). Auto-detection should
  // NEVER affect the UI/menu language - only the reading/TTS language.
  String? _detectLanguageFromText(String text) {
    // Auto-detect runs ONLY when enabled
    if (!_autoDetectEnabled) return null;

    // TASK 3: Don't auto-detect if user manually selected language
    if (_userManuallySelectedLanguage) return null;

    // TASK 3: Never change reading language for very short texts (minChars threshold)
    if (text.isEmpty || text.length < minChars) return null;

    // STEP 1A — Normalize sample
    final sample = text.length > 2000 ? text.substring(0, 2000) : text;
    final sampleLower = sample.toLowerCase();
    // Keep original for uppercase scripts (some scripts need original case)

    // STEP 1B — Script detection (highest priority, deterministic)
    // Arabic → ar-SA
    if (RegExp(r'[\u0600-\u06FF\u0750-\u077F\u08A0-\u08FF]').hasMatch(sample)) {
      return _baseCodeToFullLocale(_normLangCode('ar-SA'));
    }

    // Hebrew → he-IL
    if (RegExp(r'[\u0590-\u05FF]').hasMatch(sample)) {
      return _baseCodeToFullLocale(_normLangCode('he-IL'));
    }

    // Greek → el-GR (with script guard to prevent false positives)
    if (RegExp(r'[\u0370-\u03FF\u1F00-\u1FFF]').hasMatch(sample)) {
      final normalized = _normLangCode('el-GR');
      if (normalized == 'el' && !_looksGreekScript(text)) {
        // Greek değil -> Greek sonucunu iptal et, mevcut dili koru
        // Continue detection instead of returning Greek
      } else {
        return _baseCodeToFullLocale(normalized);
      }
    }

    // Devanagari (Hindi) → hi-IN
    if (RegExp(r'[\u0900-\u097F]').hasMatch(sample)) {
      return _baseCodeToFullLocale(_normLangCode('hi-IN'));
    }

    // Hangul (Korean) → ko-KR
    // Script detection guard: if text is mostly Latin, ignore CJK/Kana/Hangul
    // (e.g. Italian article mentioning Japanese names in parentheses)
    final totalChars = sample.replaceAll(RegExp(r'\s'), '').length;
    final latinCount = RegExp(r'[a-zA-ZÀ-ÖØ-öø-ÿ]').allMatches(sample).length;
    final latinRatio = totalChars > 0 ? latinCount / totalChars : 0.0;
    final isMostlyLatin = latinRatio > 0.5;

    if (!isMostlyLatin) {
      // Hangul (Korean) → ko-KR
      if (RegExp(r'[\uAC00-\uD7AF\u1100-\u11FF]').hasMatch(sample)) {
        return _baseCodeToFullLocale(_normLangCode('ko-KR'));
      }

      // Japanese: Hiragana/Katakana → ja-JP
      if (RegExp(r'[\u3040-\u30FF]').hasMatch(sample)) {
        return _baseCodeToFullLocale(_normLangCode('ja-JP'));
      }

      // Chinese: Han characters → zh-CN (only if NOT kana/hangul)
      if (RegExp(r'[\u4E00-\u9FFF]').hasMatch(sample)) {
        final hasKana = RegExp(r'[\u3040-\u30FF]').hasMatch(sample);
        final hasHangul =
            RegExp(r'[\uAC00-\uD7AF\u1100-\u11FF]').hasMatch(sample);
        if (!hasKana && !hasHangul) {
          return _baseCodeToFullLocale(_normLangCode('zh-CN'));
        }
      }
    }

    // Cyrillic → bg-BG or ru-RU
    if (RegExp(r'[\u0400-\u04FF]').hasMatch(sample)) {
      // Bulgarian-specific characters: ѝ (U+045D), Ѝ (U+040D) - very strong marker
      if (RegExp(r'[\u040D\u045D]').hasMatch(sample)) {
        return _baseCodeToFullLocale(_normLangCode('bg-BG'));
      }
      // Count hard sign ъ (U+044A) - Bulgarian uses it frequently
      final hardSignCount = RegExp(r'ъ').allMatches(sample).length;
      if (hardSignCount >= 2) {
        return _baseCodeToFullLocale(_normLangCode('bg-BG'));
      }
      return _baseCodeToFullLocale(_normLangCode('ru-RU'));
    }

    // STEP 1C — Turkish (Latin unique letters)
    // Check for Turkish-specific characters: ğ, ü, ş, ı, ö, ç (case-insensitive, include İ)
    if (RegExp(r'[ğĞşŞıİ]').hasMatch(sample)) {
      return _baseCodeToFullLocale(_normLangCode('tr-TR'));
    }

    // STEP 1D — Latin heuristics (safe, minimal, no chaos)
    // Unique markers first
    // German → de-DE: require ß OR at least 5 äöü chars
    // "Rönnlund", "Médecins", "Frontières" gibi yabancı özel isimler Almanca tetiklemesin
    final hasEszett = sample.contains('ß');
    final germanCharCount = RegExp(r'[äöüÄÖÜ]').allMatches(sample).length;
    // Ayrıca tipik Almanca kelimelere bak
    final hasGermanWords = RegExp(
            r'\b(und|der|die|das|ist|mit|von|für|nicht|auch|sich|dem|den|des)\b')
        .hasMatch(sample.toLowerCase());
    if (hasEszett || (germanCharCount >= 5 && hasGermanWords)) {
      return _baseCodeToFullLocale(_normLangCode('de-DE'));
    }

    // Dutch → nl-NL: ij digraph + Dutch stopwords required (prevents English false positives)
    // English words like "majority", "injury", "enjoy", "project" also contain ij — stopwords needed
    final dutchStopwords = RegExp(
        r'\b(zijn|hebben|niet|maar|ook|voor|met|van|het|een|die|dat|deze|worden|heeft|kunnen|naar|wordt|zij|wij|mijn|ons|onze|nog|wel|als|dan|door|bij|aan|uit|zou|kan)\b');
    if (RegExp(r'\b\w*ij\w*\b', caseSensitive: false).hasMatch(sample) &&
        dutchStopwords.hasMatch(sampleLower) &&
        !RegExp(r'[äöüßÄÖÜ]').hasMatch(sample)) {
      return _baseCodeToFullLocale(_normLangCode('nl-NL'));
    }

    // Spanish → es-ES if contains ¿ or ¡ or ñ
    if (RegExp(r'[¿¡ñÑ]').hasMatch(sample)) {
      return _baseCodeToFullLocale(_normLangCode('es-ES'));
    }

    // Portuguese → pt-PT guard (before French check to prevent pt→fr misdetection)
    // NOTE: nh/lh pattern removed — causes English false positives (although, highlight, unhappy, relationship)
    if (RegExp(r'ção|ções|ão|ões', caseSensitive: false)
            .hasMatch(sampleLower) ||
        RegExp(r'\bnão\b', caseSensitive: false).hasMatch(sampleLower)) {
      return _baseCodeToFullLocale(_normLangCode('pt-PT'));
    }

    // French → fr-FR if contains œ or ç, or qu'/l' with French accents
    // Guard: exclude Italian text (Italian also uses l' and accents heavily)
    final hasItalianAccents = RegExp(r'[àèìòùÀÈÌÒÙ]').hasMatch(sample);
    final hasItalianWords = RegExp(
            r'\b(della|degli|dalle|dello|nella|negli|sulle|questo|questa|quello|quella|perché|però|già|più)\b')
        .hasMatch(sampleLower);
    final isMostlyItalian = hasItalianAccents && hasItalianWords;

    if (!isMostlyItalian &&
        (RegExp(r'[œŒçÇ]').hasMatch(sample) ||
            (RegExp(r"qu'|l'", caseSensitive: false).hasMatch(sampleLower) &&
                RegExp(r'[éèêëàâîïôùûüÿÉÈÊËÀÂÎÏÔÙÛÜŸ]').hasMatch(sample)))) {
      return _baseCodeToFullLocale(_normLangCode('fr-FR'));
    }

    // Italian early detection — before scoring, unique Italian patterns
    // Italian-specific: double consonants + common endings + accents
    final italianStopwords = RegExp(
        r'\b(della|degli|dello|delle|nella|negli|nello|nelle|questo|questa|quello|quella|perché|però|già|più|così|dopo|prima|ancora|sempre|anche|tutto|tutti|tutte|altra|altro|nostro|vostra|vostro)\b');
    final italianStopCount = italianStopwords.allMatches(sampleLower).length;
    if (italianStopCount >= 2) {
      return _baseCodeToFullLocale(_normLangCode('it-IT'));
    }

    // Portuguese → pt-PT if contains ã or õ (fallback check)
    if (RegExp(r'[ãõÃÕ]').hasMatch(sample)) {
      return _baseCodeToFullLocale(_normLangCode('pt-PT'));
    }

    // Scoring (only if none of the above matched)
    bool hasWord(String w) =>
        RegExp(r'\b' + RegExp.escape(w) + r'\b').hasMatch(sampleLower);

    int scoreEn = 0;
    int scoreIt = 0;
    int scoreFr = 0;
    int scoreEs = 0;
    int scorePt = 0;

    // English words
    for (final w in [
      'the',
      'and',
      'with',
      'of',
      'to',
      'in',
      'is',
      'that',
      'for'
    ]) {
      if (hasWord(w)) scoreEn++;
    }

    // Italian words — unique to Italian, not shared with French/Spanish
    for (final w in [
      'della',
      'degli',
      'dello',
      'nelle',
      'negli',
      'questo',
      'questa',
      'quello',
      'quella',
      'perché',
      'però',
      'già',
      'più',
      'così',
      'dopo',
      'sempre',
      'ogni',
      'loro',
      'fare',
      'sono',
      'anche',
      'tutto',
      'può',
    ]) {
      if (hasWord(w)) scoreIt++;
    }

    // French words
    for (final w in [
      'que',
      'pas',
      'une',
      'dans',
      'pour',
      'avec',
      'est',
      'les'
    ]) {
      if (hasWord(w)) scoreFr++;
    }
    if (sampleLower.contains("l'")) scoreFr++; // l' bonus

    // Spanish words - unique to Spanish (not shared with Italian/French)
    for (final w in [
      'los',
      'las',
      'una',
      'del',
      'con',
      'por',
      'como',
      'pero',
      'este',
      'esta',
      'todo',
      'todos',
      'porque',
      'cuando',
      'donde',
      'mientras',
      'también',
      'muy',
      'hay',
      'hace',
      'tiene',
      'pueden',
      'están',
    ]) {
      if (hasWord(w)) scoreEs++;
    }

    // Portuguese words
    for (final w in [
      'que',
      'para',
      'com',
      'uma',
      'não',
      'dos',
      'das',
      'pelo'
    ]) {
      if (hasWord(w)) scorePt++;
    }
    if (sampleLower.contains('ção')) scorePt++; // ção bonus

    // TASK 3: Scoring-based detection with ratio thresholds
    final scores = <String, int>{
      'en-US': scoreEn,
      'it-IT': scoreIt,
      'fr-FR': scoreFr,
      'es-ES': scoreEs,
      'pt-PT': scorePt,
    };

    // Calculate total score for ratio calculation
    final totalScore = scoreEn + scoreIt + scoreFr + scoreEs + scorePt;

    // If no scores at all, skip to fallback check
    if (totalScore == 0) {
      // Check Spanish fallback before returning null
      if (_looksSpanish(text)) {
        return _baseCodeToFullLocale(_normLangCode('es-ES'));
      }
      // If mostly ASCII/latin letters → return en-US (English fallback)
      // But with low confidence, so require higher threshold
      final latinOnlyPattern =
          RegExp('^[a-zA-Z0-9\\s\\.,;:!?\'"\\-\\(\\)\\[\\]{}]+\$');
      if (latinOnlyPattern.hasMatch(sample.replaceAll(RegExp(r'\s'), ''))) {
        // TASK 3: Fallback en-US has no confidence score, so don't auto-detect
        // This prevents Spanish->null and other false positives
        return null;
      }
      return null;
    }

    // Convert scores to candidates with ratios
    final candidates = scores.entries.map((e) {
      return MapEntry(e.key, e.value / totalScore);
    }).toList()
      ..sort((a, b) => b.value.compareTo(a.value));

    String? detected;

    if (candidates.isNotEmpty) {
      final topLang = candidates[0];
      final topLangCode = topLang.key;
      final topLangRatio = topLang.value;
      final secondLangRatio = candidates.length > 1 ? candidates[1].value : 0.0;

      // TASK 3: Apply thresholds for multiple candidates
      // Rule 1: topLangRatio must be >= dominanceThreshold (40%)
      if (topLangRatio >= dominanceThreshold) {
        // Rule 2: Margin between top and second must be >= margin (15%)
        if ((topLangRatio - secondLangRatio) >= margin) {
          // Rule 3: topLangCode must not be null/empty
          if (topLangCode.isNotEmpty) {
            // All checks passed, normalize and convert to full locale
            final normalized = _normLangCode(topLangCode);
            detected =
                normalized != null ? _baseCodeToFullLocale(normalized) : null;
          }
        }
      }
      // If dominance rules failed but we have candidates, check Spanish fallback
      if (detected == null && _looksSpanish(text)) {
        detected = _baseCodeToFullLocale(_normLangCode('es-ES'));
      }
    }

    // STEP 3 — Spanish fallback if nothing detected
    if (detected == null && _looksSpanish(text)) {
      detected = _baseCodeToFullLocale(_normLangCode('es-ES'));
    }

    // Return detected language (already normalized and converted to full locale)
    return detected;
  }

  // Show language detection SnackBar with YES/NO buttons and spam prevention
  // ⚠️ CRITICAL: This function MUST ONLY update reading/TTS language (_selectedLocale).
  // It MUST NEVER change UI language (AppLang.code). Auto-detection should never affect UI locale.
  void _showLanguageDetectionSnackBar(String detectedLocale) {
    if (!mounted) return;

    // Only auto-detect if enabled
    if (!_autoDetectEnabled) {
      return;
    }

    final detectedLang = _findLanguageEntryByLocale(detectedLocale);
    if (detectedLang == null) return;

    // Don't show if already the same language
    final currentLocale = _selectedLocale ?? kLanguages.first.ttsLocale;
    final normalizedDetected = _normalizeLocale(detectedLocale);
    final normalizedCurrent = _normalizeLocale(currentLocale);

    if (normalizedCurrent == normalizedDetected) {
      return;
    }

    // Save previous language for undo
    _prevReadingLang = _selectedLocale;

    // ⚠️ Auto-update reading language ONLY - NEVER touch AppLang.code (UI language)
    setState(() {
      _selectedLocale = normalizedDetected;
      _selectedVoice =
          _findBestVoiceForLocaleAndGender(normalizedDetected, _voiceGender);
      final actualGender =
          (_selectedVoice?['gender'] as String? ?? 'female').toLowerCase();
      if (actualGender != _voiceGender.toLowerCase()) {
        _voiceGender = actualGender;
      }
    });

    // Update TTS language asynchronously
    _tts.setLanguage(normalizedDetected).then((_) async {
      if (_selectedVoice != null && mounted) {
        await _tts.setVoice({
          'name': _selectedVoice!['name'],
          'locale': normalizedDetected,
        });
      }
    }).catchError((e) {});

    // Get language name for display
    final languageName = _getLanguageName(normalizedDetected);
    final message = 'Detected: $languageName — Reading language updated';

    // Create SnackBar with Undo action
    final snackBar = SnackBar(
      backgroundColor: Colors.transparent,
      elevation: 0,
      behavior: SnackBarBehavior.floating,
      padding: EdgeInsets.zero,
      content: Container(
        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
        decoration: BoxDecoration(
          gradient: const LinearGradient(
            colors: [kGoldMain, kGoldDark],
            begin: Alignment.centerLeft,
            end: Alignment.centerRight,
          ),
          borderRadius: BorderRadius.circular(8),
        ),
        child: Text(message,
            style: GoogleFonts.lora(
                fontSize: 13,
                fontWeight: FontWeight.w300,
                color: Colors.white)),
      ),
      action: SnackBarAction(
        label: 'Undo',
        onPressed: () {
          // Revert to previous language
          if (_prevReadingLang != null) {
            final prevLocale = _normalizeLocale(_prevReadingLang!);
            setState(() {
              _selectedLocale = prevLocale;
              _selectedVoice =
                  _findBestVoiceForLocaleAndGender(prevLocale, _voiceGender);
            });
            _tts.setLanguage(prevLocale).then((_) async {
              if (_selectedVoice != null && mounted) {
                await _tts.setVoice({
                  'name': _selectedVoice!['name'],
                  'locale': prevLocale,
                });
              }
            }).catchError((e) {});
          }
          // Disable auto-detect for this text
          _autoDetectEnabled = false;
        },
      ),
      duration: const Duration(seconds: 3),
    );

    // Show snackbar
    ScaffoldMessenger.of(context).showSnackBar(snackBar);
  }

  // Run auto language detection if needed (show snackbar)
  void _runAutoLanguageDetectionIfNeeded({required String source}) {
    final text = _text.text;
    // Always detect if text is not empty
    if (text.isEmpty || !mounted) return;

    // Cancel existing debounce
    _languageDetectionDebounce?.cancel();

    // Debounce language detection (300ms)
    _languageDetectionDebounce = Timer(const Duration(milliseconds: 300), () {
      if (!mounted) return;
      final currentLocale = _selectedLocale ?? '';
      final detectedLang = _detectLanguageFromText(text);
      if (detectedLang != null) {
        if (detectedLang == 'fr-FR') {
          _allowAutoFrenchOnce = true;
        }
        _switchToLanguageSilently(detectedLang);
        // OCR'dan geliyorsa ve dil farklıysa uyarı göster
        if (source == 'camera_ocr') {
          final detectedBase = detectedLang.toLowerCase().split('-')[0];
          final currentBase = currentLocale.toLowerCase().split('-')[0];
          if (detectedBase != currentBase) {
            Future.delayed(const Duration(milliseconds: 800), () {
              if (!mounted) return;
              ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
                  t('ocr.langMismatch'),
                  behavior: SnackBarBehavior.floating));
            });
          }
        }
      }
    });
  }

  // Helper: Auto-detect and switch language silently
  void _maybeAutoDetectLanguageAfterTextSet(String text) {
    if (text.isEmpty || !mounted) return;

    // Cancel existing debounce
    _languageDetectionDebounce?.cancel();

    // Debounce language detection (300ms)
    _languageDetectionDebounce = Timer(const Duration(milliseconds: 300), () {
      if (!mounted) return;
      final detectedLang = _detectLanguageFromText(text);
      if (detectedLang != null) {
        if (detectedLang == 'fr-FR') {
          _allowAutoFrenchOnce = true;
        }
        _switchToLanguageSilently(detectedLang);
      }
    });
  }

  // Silent switch to detected language (no SnackBar) - for auto-detection after paste
  // ⚠️ CRITICAL: This function MUST ONLY update reading/TTS language (_selectedLocale).
  // It MUST NEVER change UI language (AppLang.code). Auto-detection should never affect UI locale.
  Future<void> _switchToLanguageSilently(String locale) async {
    final normalizedLocale = _normalizeLocale(locale);

    // Guard: prevent any non-detect path from forcing French
    if (normalizedLocale == 'fr-FR' && !_allowAutoFrenchOnce) {
      return;
    }

    final langEntry = _findLanguageEntryByLocale(normalizedLocale);
    if (langEntry == null) return;

    // Don't switch if already the same language
    final currentLocale = _selectedLocale ?? kLanguages.first.ttsLocale;
    if (_normalizeLocale(currentLocale) == normalizedLocale) {
      return;
    }

    // Save previous locale for revert on error
    final previousLocale = _selectedLocale ?? kLanguages.first.ttsLocale;

    // ⚠️ ONLY update reading/TTS language - NEVER touch AppLang.code (UI language)
    setState(() {
      _selectedLocale = normalizedLocale;
      _selectedVoice =
          _findBestVoiceForLocaleAndGender(normalizedLocale, _voiceGender);
      final actualGender =
          (_selectedVoice?['gender'] as String? ?? 'female').toLowerCase();
      if (actualGender != _voiceGender.toLowerCase()) {
        _voiceGender = actualGender;
      }
    });

    try {
      // Set language first
      final langResult = await _tts.setLanguage(normalizedLocale);

      final langOk =
          (langResult is int) ? (langResult == 1 || langResult == 0) : true;

      if (!langOk) {
        throw Exception('setLanguage returned: $langResult');
      }

      // Then set voice if available
      if (_selectedVoice != null) {
        await _tts.setVoice({
          'name': _selectedVoice!['name'],
          'locale': normalizedLocale,
        });
      }

      // Also set speech parameters (but don't start TTS)
      await _tts.setSpeechRate(_rate);
      await _tts.setPitch(_pitch);
      await _tts.setVolume(_volume);

      await _savePersisted();
      // No SnackBar - silent update

      // Consume the one-shot permission if French was set
      if (normalizedLocale == 'fr-FR') {
        _allowAutoFrenchOnce = false;
      }
    } catch (e) {
      // Revert to previous locale silently
      if (mounted) {
        setState(() {
          _selectedLocale = previousLocale;
          _selectedVoice =
              _findBestVoiceForLocaleAndGender(previousLocale, _voiceGender);
        });
        // No SnackBar on error either - silent fail
      }
    }
  }

  // Switch to detected language (update dropdown and TTS locale, but don't auto-start TTS)
  // ⚠️ CRITICAL: This function MUST ONLY update reading/TTS language (_selectedLocale).
  // It MUST NEVER change UI language (AppLang.code). Auto-detection should never affect UI locale.
  Future<void> _switchToLanguage(String locale) async {
    final normalizedLocale = _normalizeLocale(locale);
    final langEntry = _findLanguageEntryByLocale(normalizedLocale);
    if (langEntry == null) return;

    // Save previous locale for revert on error
    final previousLocale = _selectedLocale ?? kLanguages.first.ttsLocale;

    // ⚠️ ONLY update reading/TTS language - NEVER touch AppLang.code (UI language)
    setState(() {
      _selectedLocale = normalizedLocale;
      _selectedVoice =
          _findBestVoiceForLocaleAndGender(normalizedLocale, _voiceGender);
      final actualGender =
          (_selectedVoice?['gender'] as String? ?? 'female').toLowerCase();
      if (actualGender != _voiceGender.toLowerCase()) {
        _voiceGender = actualGender;
      }
    });

    try {
      // Set language first
      final langResult = await _tts.setLanguage(normalizedLocale);

      final langOk =
          (langResult is int) ? (langResult == 1 || langResult == 0) : true;

      if (!langOk) {
        throw Exception('setLanguage returned: $langResult');
      }

      // Then set voice if available
      if (_selectedVoice != null) {
        await _tts.setVoice({
          'name': _selectedVoice!['name'],
          'locale': normalizedLocale,
        });
      }

      // Also set speech parameters (but don't start TTS)
      await _tts.setSpeechRate(_rate);
      await _tts.setPitch(_pitch);
      await _tts.setVolume(_volume);

      await _savePersisted();

      final langDisplay = '${langEntry.displayName} ${langEntry.flag}';
      ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
          t('language_switched_success'),
          behavior: SnackBarBehavior.floating));
    } catch (e) {
      // Revert to previous locale
      if (mounted) {
        setState(() {
          _selectedLocale = previousLocale;
          _selectedVoice =
              _findBestVoiceForLocaleAndGender(previousLocale, _voiceGender);
        });

        ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
            'language_switch_failed',
            behavior: SnackBarBehavior.floating));
      }
    }
  }

  // 🌍 Bayrak emojisi (dil koduna göre)
  String flagForLocale(String code) {
    final parts = code.split('-');
    final lang = parts[0].toLowerCase();
    final country = parts.length > 1 ? parts[1].toUpperCase() : '';

    // Handle special locale cases first (full locale match)
    // English locales must be handled before language code fallback
    if (code.toLowerCase() == 'en-us') {
      return '🇺🇸';
    }
    if (code.toLowerCase() == 'en-gb') {
      return '🇬🇧';
    }
    if (code.toLowerCase() == 'zh-tw') {
      return '🇹🇼';
    }
    if (code.toLowerCase() == 'zh-cn') {
      return '🇨🇳';
    }
    if (code.toLowerCase() == 'pt-br') {
      return '🇧🇷';
    }
    if (code.toLowerCase() == 'pt-pt') {
      return '🇵🇹';
    }

    // Language code mappings (by prefix)
    // Note: 'en' removed from here to prevent en-GB from getting US flag
    const langFlags = {
      'nl': '🇳🇱', // Dutch
      'da': '🇩🇰', // Danish
      'he': '🇮🇱', // Hebrew
      'iw': '🇮🇱', // Hebrew (alternative code)
      'fa': '🇮🇷', // Persian/Farsi
      'tr': '🇹🇷',
      // 'en' removed - handled above by special cases
      'de': '🇩🇪',
      'fr': '🇫🇷',
      'es': '🇪🇸',
      'it': '🇮🇹',
      'hi': '🇮🇳',
      'ja': '🇯🇵',
      'ko': '🇰🇷',
      'bg': '🇧🇬',
      'pt': '🇵🇹', // Default for Portuguese (non-BR/PT variants)
      'zh': '🇨🇳', // Default for Chinese (non-CN/TW variants)
      'el': '🇬🇷',
      'ru': '🇷🇺',
    };

    // Country code mappings (fallback)
    const countryFlags = {
      'TR': '🇹🇷',
      'US': '🇺🇸',
      'GB': '🇬🇧',
      'AU': '🇦🇺',
      'DE': '🇩🇪',
      'FR': '🇫🇷',
      'ES': '🇪🇸',
      'IT': '🇮🇹',
      'IN': '🇮🇳',
      'BR': '🇧🇷',
      'PT': '🇵🇹',
      'CN': '🇨🇳',
      'TW': '🇹🇼',
      'JP': '🇯🇵',
      'KR': '🇰🇷',
      'BG': '🇧🇬',
      'EL': '🇬🇷',
      'RU': '🇷🇺',
      'NL': '🇳🇱',
      'DK': '🇩🇰',
      'IL': '🇮🇱',
      'IR': '🇮🇷',
    };

    // Try language code first, then country code
    final flag = langFlags[lang] ?? countryFlags[country] ?? '';
    return flag;
  }

  Future<void> _bootstrap() async {
    await _initTts();
    await _loadFavorites();
    await _loadNotes();
    await _loadReadingNotes();
    // Voices yüklemeyi doğrudan main thread'e taşı (isolate sorunu için compute kaldırıldı)
    // Use fallback mechanism to ensure we get voices from a working engine
    try {
      _voices = await _loadVoicesWithFallback();
      _voices.sort((a, b) => humanizeLocale(a['locale'] ?? '')
          .compareTo(humanizeLocale(b['locale'] ?? '')));

      // Filter to only supported languages
      const supportedLocales = [
        'tr-TR',
        'en-US',
        'en-GB',
        'es-ES',
        'it-IT',
        'fr-FR',
        'de-DE',
        'ru-RU',
        'el-GR',
        'bg-BG',
      ];

      _uniqueLocales = _voices
          .map((v) => v['locale'] as String?)
          .whereType<String>()
          .where((loc) {
            // Normalize Turkish variants
            if (loc.toLowerCase().startsWith('tr')) {
              return supportedLocales.contains('tr-TR');
            }
            return supportedLocales.contains(loc);
          })
          .map((loc) {
            // Normalize Turkish to tr-TR
            if (loc.toLowerCase().startsWith('tr')) {
              return 'tr-TR';
            }
            return loc;
          })
          .toSet()
          .toList();

      // Refresh languages cache after engine fallback (important for Samsung devices)
      // This must execute BEFORE the loop that uses _isLocaleSupported to ensure fresh cache
      if (Platform.isAndroid || Platform.isIOS) {
        try {
          final languages = await _tts.getLanguages;
          _availableLanguagesCache = (languages as List?)?.cast<String>() ?? [];
        } catch (e) {}
      }

      // Only add supported locales that are actually available (checked via _isLocaleSupported)
      // This ensures dropdown only shows locales that work
      for (final supported in supportedLocales) {
        if (!_uniqueLocales.contains(supported) &&
            await _isLocaleSupported(supported)) {
          _uniqueLocales.add(supported);
        }
      }
      _uniqueLocales
          .sort((a, b) => humanizeLocale(a).compareTo(humanizeLocale(b)));

      if (_selectedLocale != null) {}
    } catch (e) {
      // Hata handling: Voices yüklenemediğinde logla
      _voices = [];
      _uniqueLocales = [];
    }

    // If still no voices after fallback, show message but don't block
    if (_voices.isEmpty && mounted) {
      WidgetsBinding.instance.addPostFrameCallback((_) {
        final isTr = AppLang.code.value == 'tr';
        ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
            isTr
                ? 'TTS ses verisi bulunamadı. Android Ayarlar > Sistem > Metin-konuşma çıkışından ses verilerini yükleyin.'
                : 'No TTS voice data found. Install voice data from Android Settings > System > Text-to-speech output.',
            behavior: SnackBarBehavior.floating));
      });
    }
    // Seçilen UI diline göre locale seç (eğer persisted mismatch ise)
    String targetLang = AppLang.code.value;
    if (_selectedLocale == null) {
      _selectedLocale = _uniqueLocales.firstWhere(
        (loc) => loc.toLowerCase().startsWith(targetLang.toLowerCase()),
        orElse: () =>
            _uniqueLocales.isNotEmpty ? _uniqueLocales.first : 'en-US',
      );
    }

    // Normalize Turkish locale to "tr-TR"
    if (_selectedLocale != null &&
        _selectedLocale!.toLowerCase().startsWith('tr')) {
      _selectedLocale = 'tr-TR';
    }

// Prefer MALE voice (default changed to male)
    _voiceGender = 'male';

    _selectedVoice =
        _findBestVoiceForLocaleAndGender(_selectedLocale, _voiceGender);
    if (_selectedVoice == null && _voices.isNotEmpty) {
      _selectedVoice = _voices.first;
      String voiceLocale = _selectedVoice!['locale'] as String? ?? 'en-US';
      // Normalize Turkish locale
      if (voiceLocale.toLowerCase().startsWith('tr')) {
        voiceLocale = 'tr-TR';
      }
      _selectedLocale = voiceLocale;
    }

    // Prevent null-crash when voices are empty
    if (_selectedVoice == null) {
      await _refreshNovaStatus();
      return;
    }

    try {
      // Normalize locale before setting voice
      String localeToUse = _selectedVoice!['locale'] as String? ?? 'en-US';
      if (localeToUse.toLowerCase().startsWith('tr')) {
        localeToUse = 'tr-TR';
      }
      await _tts.setVoice({
        "name": _selectedVoice!["name"],
        "locale": localeToUse,
      });
    } catch (_) {}

    // Auto-scroll should NOT start automatically on launch - user must press Play button
    // Removed: if (_autoScroll) _toggleAutoScroll(true);
    await _refreshNovaStatus();
  }

  // Isolate fonksiyonu (artık doğrudan çağrılıyor, compute olmadan)
  static Future<List<Map<String, dynamic>>> _loadVoicesIsolate(
      FlutterTts tts) async {
    final v = await tts.getVoices;
    return (v as List? ?? []).map((e) {
      final map = e as Map;
      return <String, dynamic>{for (var k in map.keys) k.toString(): map[k]};
    }).toList();
  }

  // Load voices with automatic engine fallback (Google TTS preferred if no voices)
  Future<List<Map<String, dynamic>>> _loadVoicesWithFallback() async {
    // Try current engine first
    List<Map<String, dynamic>> voices = await _loadVoicesIsolate(_tts);

    if (voices.isNotEmpty) {
      return voices;
    }

    // No voices from current engine - try Google TTS if available
    if (Platform.isAndroid && _availableEngines != null) {
      dynamic googleEngine;

      for (var engine in _availableEngines!) {
        try {
          String packageName = '';
          String engineStr = '';
          if (engine is Map) {
            packageName = (engine['package'] ?? '').toString().toLowerCase();
            engineStr = (engine['package'] ?? engine['name'] ?? '')
                .toString()
                .toLowerCase();
          } else {
            engineStr = engine.toString().toLowerCase();
          }

          // Detect Google TTS reliably using package name
          if (packageName == 'com.google.android.tts' ||
              (packageName.contains('google') && packageName.contains('tts')) ||
              (engineStr.contains('google') && engineStr.contains('tts'))) {
            googleEngine = engine;
            break;
          }
        } catch (e) {}
      }

      if (googleEngine != null) {
        try {
          String engineId = '';
          if (googleEngine is Map) {
            // Prefer package over name for reliable detection
            engineId = googleEngine['package'] ?? googleEngine['name'] ?? '';
          } else {
            engineId = googleEngine.toString();
          }

          if (engineId.isNotEmpty) {
            await _tts.setEngine(engineId);
            // Wait a bit for engine switch to complete (Android needs time)
            if (Platform.isAndroid) {
              await Future.delayed(const Duration(milliseconds: 400));
            }
            // Refresh getLanguages cache after setEngine
            try {
              final languages = await _tts.getLanguages;
              _availableLanguagesCache =
                  (languages as List?)?.cast<String>() ?? [];
            } catch (e) {}
            voices = await _loadVoicesIsolate(_tts);

            if (voices.isNotEmpty) {
              return voices;
            }
          }
        } catch (e) {}
      }
    }

    // Still no voices - try default engine
    try {
      await _tts.setEngine('');
      // Wait a bit for engine switch to complete (Android needs time)
      if (Platform.isAndroid) {
        await Future.delayed(const Duration(milliseconds: 400));
      }
      // Refresh getLanguages cache after setEngine
      try {
        final languages = await _tts.getLanguages;
        _availableLanguagesCache = (languages as List?)?.cast<String>() ?? [];
      } catch (e) {}
      voices = await _loadVoicesIsolate(_tts);
    } catch (e) {}

    return voices;
  }

  Future<void> _initTts() async {
    // Prevent concurrent initialization
    if (_ttsInitInProgress) {
      if (_ttsInitCompleter != null) {
        return _ttsInitCompleter!.future;
      }
    }

    _ttsInitInProgress = true;
    _ttsInitCompleter = Completer<void>();
    _ttsInitialized = false;

    try {
      // Audio session: arka planda ses devam etsin
      try {
        final session = await AudioSession.instance;
        await session.configure(const AudioSessionConfiguration(
          avAudioSessionCategory: AVAudioSessionCategory.playback,
          androidAudioAttributes: AndroidAudioAttributes(
            contentType: AndroidAudioContentType.speech,
            usage: AndroidAudioUsage.media,
          ),
          androidAudioFocusGainType: AndroidAudioFocusGainType.gain,
        ));
        await session.setActive(true);
      } catch (_) {}

      // Diagnostics (non-blocking)
      try {
        if (Platform.isAndroid) {
          // Add small delay for engine readiness on Android (especially Samsung devices)
          await Future.delayed(const Duration(milliseconds: 100));

          // Engine'leri kaydet (sadece Android) - must be first for engine detection
          try {
            _availableEngines = await _tts.getEngines;

            // Force Google TTS on Android when available (best effort)
            String? googleEngineId;
            for (var engine in _availableEngines ?? []) {
              try {
                String packageName = '';
                if (engine is Map) {
                  packageName =
                      (engine['package'] ?? '').toString().toLowerCase();
                } else {
                  packageName = engine.toString().toLowerCase();
                }

                if (packageName == 'com.google.android.tts') {
                  if (engine is Map) {
                    googleEngineId = engine['package'] ?? engine['name'] ?? '';
                  } else {
                    googleEngineId = engine.toString();
                  }
                  break;
                }
              } catch (e) {}
            }

            if (googleEngineId != null && googleEngineId.isNotEmpty) {
              try {
                await _tts.setEngine(googleEngineId);
                _currentEngineId = googleEngineId;
              } catch (e) {
                // Fallback to default engine
                try {
                  final defaultEngine = await _tts.getDefaultEngine;
                  _currentEngineId = defaultEngine;
                } catch (_) {}
              }
            } else {
              // No Google TTS found, use default
              try {
                final defaultEngine = await _tts.getDefaultEngine;
                _currentEngineId = defaultEngine;
              } catch (_) {}
            }
          } catch (e) {
            _availableEngines = null;
          }
          // Languages bilgisi - cache for fallback detection (after engines)
          try {
            final languages = await _tts.getLanguages;
            _availableLanguagesCache =
                (languages as List?)?.cast<String>() ?? [];
          } catch (e) {
            _availableLanguagesCache = null;
          }
        } else if (Platform.isIOS) {
          // iOS'ta engine listesi yok, sadece languages
          try {
            final languages = await _tts.getLanguages;
            _availableLanguagesCache =
                (languages as List?)?.cast<String>() ?? [];
          } catch (e) {
            _availableLanguagesCache = null;
          }
        }
      } catch (e) {}

      // Ekran kapanınca ses devam etsin
      if (Platform.isIOS) {
        try {
          await _tts.setSharedInstance(true);
          await _tts.setIosAudioCategory(
            IosTextToSpeechAudioCategory.playback,
            [
              IosTextToSpeechAudioCategoryOptions.allowBluetooth,
              IosTextToSpeechAudioCategoryOptions.allowBluetoothA2DP,
              IosTextToSpeechAudioCategoryOptions.mixWithOthers,
            ],
            IosTextToSpeechAudioMode.defaultMode,
          );
        } catch (_) {}
      }

      await _tts.awaitSpeakCompletion(true);
      await _tts.setSpeechRate(_rate);
      await _tts.setPitch(_pitch);
      await _tts.setVolume(_volume);

      _tts.setStartHandler(() {
        // Konuşma başladı, timer'ı iptal et ve başlangıcı onayla
        _ttsStartCheckTimer?.cancel();
        _ttsStartCheckTimer = null;
        _ttsWatchdogTimer?.cancel();
        _ttsWatchdogTimer = null;
        _ttsStartConfirmed = true;
        // TASK 3: Track TTS start time for fallback estimation
        _ttsStartTime = DateTime.now();
        if (mounted) {
          setState(() {
            _isSpeaking = true;
            _ttsPaused = false;
          });
          try {
            WakelockPlus.enable();
          } catch (_) {}
        }

        // RTL/CJK: progress callback gelmiyor, START'ta stepper başlat
        if (_isSyntheticStepLocale() && _readingMode == ReadingMode.both) {
          final idx = _currentSentenceIndex;
          if (idx >= 0 && idx < _sentenceChunks.length) {
            final chunk = _sentenceChunks[idx];
            final uiStart = chunk.globalStart;
            final uiEnd = (chunk.globalStart + chunk.text.length)
                .clamp(0, _uiTextForReading.length);
            if (uiEnd > uiStart) {
              _startSyntheticStepper(uiStart, uiEnd);
            }
          }
        }
      });

      _tts.setCancelHandler(() {
        // Timer'ı iptal et ve başlangıç onayını sıfırla
        _ttsStartCheckTimer?.cancel();
        _ttsStartCheckTimer = null;
        _ttsWatchdogTimer?.cancel();
        _ttsWatchdogTimer = null;
        _syntheticStepTimer?.cancel();
        _syntheticStepTimer = null;
        _ttsStartConfirmed = false;
        _ttsWatchdogRetried = false;
        _ttsBusy = false; // Clear busy flag on cancel
        // TASK 3: Reset reading position on cancel (stop)
        _ttsCharOffset = 0;
        _ttsStartTime = null;
        if (mounted) {
          _lastAppliedStart = 0;
          _lastAppliedEnd = 0;
          _lastUiStart = 0;
          _lastUiEnd = 0;
          setState(() {
            _isSpeaking = false;
            _ttsPaused = false;
            _ttsOffset = 0;
            _ttsText = '';
            _ttsHighlightStart = 0;
            _ttsHighlightEnd = 0;
            _pendingHlStart = -1;
            _pendingHlEnd = -1;
            _pendingHighlightPaint = false;
            _ttsLastChunk = '';
            _ttsChunkBase = 0;
            _highlightRects = [];
          });
        }
      });

      _tts.setPauseHandler(() {
        if (mounted) {
          setState(() {
            _isSpeaking = false;
            _ttsPaused = true;
          });
        }
      });

      _tts.setContinueHandler(() {
        // This handler should only fire on explicit resume, not auto-resume
        // Do NOT automatically resume - user must press Play button
        if (mounted) {
          setState(() {
            // Only update state if we're actually resuming (not auto-resuming)
            if (!_ttsPaused) {
              _isSpeaking = true;
            }
          });
        }
      });

      _tts.setProgressHandler((text, start, end, word) {
        // Konuşma ilerliyor, timer'ı iptal et ve başlangıcı onayla
        _ttsStartCheckTimer?.cancel();
        _ttsStartCheckTimer = null;
        _ttsWatchdogTimer?.cancel();
        _ttsWatchdogTimer = null;
        _ttsStartConfirmed = true;

        if (!mounted || _ttsText.isEmpty) return;

        final chunkText = text ?? '';

        // Yeni bir parça (chunk) başladıysa, önceki parçanın uzunluğunu baz al
        if (chunkText != _ttsLastChunk) {
          _ttsChunkBase += _ttsLastChunk.length;
          _ttsLastChunk = chunkText;
        }

        int localStart = start ?? 0;
        int localEnd = end ?? 0;

        // --- FIX: sentence-mode vs queue-mode index spaces are different -----------
        // In sentence mode, localStart/localEnd are offsets into the *cleaned sentence*
        // string that was passed to _tts.speak(). chunk.globalStart is the UI-text
        // position of that sentence. We compute UI positions directly and call
        // _handleProgress (word-snap + highlight) without going through the full-text
        // TTS↔UI map (_onTtsProgressMapped), which would produce wrong positions.
        //
        // In queue mode, _ttsChunkBase + local* gives a TTS-space index into _ttsText
        // (built from the full UI text), so _onTtsProgressMapped is the right path.
        // -------------------------------------------------------------------------
        bool inSentenceMode = _currentSentenceIndex >= 0 &&
            _currentSentenceIndex < _sentenceChunks.length;

        if (inSentenceMode) {
          final chunk = _sentenceChunks[_currentSentenceIndex];
          final uiLen = _uiTextForReading.length;
          // Map localStart/localEnd (into SPOKEN/cleaned sentence) → UI positions.
          // Use _spokenToOrigMap which aligns the transformed spoken text back to
          // the original chunk.text character positions, then add chunk.globalStart.
          final origStart = _spokenOffsetToOrig(localStart);
          final origEnd = _spokenOffsetToOrig(localEnd);
          int uiStart = (chunk.globalStart + origStart).clamp(0, uiLen);
          int uiEnd = (chunk.globalStart + origEnd).clamp(0, uiLen);
          if (uiEnd < uiStart) uiEnd = uiStart;

          // Update scroll/position trackers in UI space
          _ttsCharOffset = uiStart;
          final now = DateTime.now();
          if (_lastSpokenOffsetUpdateTime == null ||
              now.difference(_lastSpokenOffsetUpdateTime!).inMilliseconds >=
                  150) {
            _lastSpokenOffset = uiEnd;
            _lastSpokenOffsetUpdateTime = now;
          }

          final isVoiceMode = _readingMode == ReadingMode.voiceOnly;
          final isBothMode = _readingMode == ReadingMode.both;

          if (isVoiceMode) {
            if (mounted) setState(() => _ttsOffset = uiEnd);
            return;
          }
          if (isBothMode) {
            _ttsOffset = uiEnd;
            // For CJK/RTL, use synthetic word-by-word stepper
            if (_isSyntheticStepLocale()) {
              _startSyntheticStepper(uiStart, uiEnd);
            } else {
              _syntheticStepTimer?.cancel();
              _handleProgress(uiStart, uiEnd);
            }
          }
        } else {
          // Queue mode: indices are into _ttsText (full-text TTS space)
          int globalStart = _ttsChunkBase + localStart;
          int globalEnd = _ttsChunkBase + localEnd;

          final ttsLen = _ttsText.length;
          if (globalStart < 0) globalStart = 0;
          if (globalStart > ttsLen) globalStart = ttsLen;
          if (globalEnd < globalStart) globalEnd = globalStart;
          if (globalEnd > ttsLen) globalEnd = ttsLen;

          _ttsCharOffset = globalStart;
          final now = DateTime.now();
          if (_lastSpokenOffsetUpdateTime == null ||
              now.difference(_lastSpokenOffsetUpdateTime!).inMilliseconds >=
                  150) {
            _lastSpokenOffset = globalEnd;
            _lastSpokenOffsetUpdateTime = now;
          }

          final isVoiceMode = _readingMode == ReadingMode.voiceOnly;
          final isBothMode = _readingMode == ReadingMode.both;

          if (isVoiceMode) {
            if (mounted) setState(() => _ttsOffset = globalEnd);
            return;
          }
          if (isBothMode) {
            _ttsOffset = globalEnd;
            // For CJK/RTL, use synthetic word-by-word stepper
            if (_isSyntheticStepLocale()) {
              _startSyntheticStepper(
                  _ttsIndexToUi(globalStart), _ttsIndexToUi(globalEnd));
            } else {
              _syntheticStepTimer?.cancel();
              _onTtsProgressMapped(globalStart, globalEnd);
            }
          }
        }
      });

      await _ttsInitCallbacks();

      // Mark initialization as complete
      _ttsInitialized = true;
    } catch (e) {
      // Still mark as initialized to prevent blocking, but log the error
      _ttsInitialized = true;
    } finally {
      _ttsInitInProgress = false;
      final completer = _ttsInitCompleter;
      _ttsInitCompleter = null;
      completer?.complete();

      // Process any pending play request (only if not already busy)
      if (_pendingPlayRequest && !_ttsBusy) {
        _pendingPlayRequest = false;
        Future.microtask(() => _playSafe());
      } else if (_pendingPlayRequest) {
        // Clear the flag even if busy (the waiting _playSafe will handle it)
        _pendingPlayRequest = false;
      }
    }
  }

  Future<void> _applySettingsAndSave() async {
    try {
      await _tts.setVoice({
        "name": _selectedVoice!["name"],
        "locale": _selectedVoice!["locale"],
      });
      await _tts.setSpeechRate(_rate);
      await _tts.setPitch(_pitch);
      await _tts.setVolume(_volume);
    } catch (_) {}
    await _savePersisted();
  }

  String _cleanTextForTTS(String text) {
    // Check if Turkish locale or UI language is Turkish
    final isTurkish = (_selectedLocale != null &&
            _selectedLocale!.toLowerCase().startsWith('tr')) ||
        AppLang.code.value.toLowerCase() == 'tr';

    // Normalize thousands separators for TTS reading
    // Her iki dil için de binlik nokta ayraçlarını kaldır: 36.670.680 → 36670680
    text = text.replaceAllMapped(
      RegExp(r'\b(\d{1,3})(\.\d{3})+\b'),
      (m) => m.group(0)!.replaceAll('.', ''),
    );

    // Turkish: remove punctuation-name words with word boundaries
    if (isTurkish) {
      // List of Turkish punctuation-name words to remove
      final punctuationWords = [
        r'\bnokta\b',
        r'\bvirgül\b',
        r'\bünlem\b',
        r'\bsoru işareti\b',
        r'\biki nokta\b',
        r'\bnoktalı virgül\b',
      ];

      // Remove each word with word boundaries
      for (final word in punctuationWords) {
        text = text.replaceAll(RegExp(word, caseSensitive: false), '');
      }
    }

    // 1) Normalize ellipsis and dot runs (TTS-only)
    // Replace unicode ellipsis with a space
    text = text.replaceAll('…', ' ');
    // Replace any run of 2+ dots with a single space
    text = text.replaceAll(RegExp(r'\.{2,}'), ' ');

    // Birden fazla ünlem/soru işaretini temizle: !! !!! → boşluk, tek ! kalır
    text = text.replaceAll(RegExp(r'!{2,}'), ' ');
    text = text.replaceAll(RegExp(r'\?+'), ' ');

    // 2) Remove "lonely dots" that are likely to be spoken
    // Dot surrounded by spaces
    text = text.replaceAll(RegExp(r'(?<=\s)\.(?=\s)'), ' ');
    // Dot after a space at end-of-line
    text = text.replaceAll(RegExp(r'(?<=\s)\.(?=$)'), ' ');
    // Dot at start-of-line before a space
    text = text.replaceAll(RegExp(r'(?<=^)\.(?=\s)'), ' ');

    // 3) Parentheses and similar brackets: remove characters but keep inner text
    text = text.replaceAll('(', ' ');
    text = text.replaceAll(')', ' ');
    text = text.replaceAll('[', ' ');
    text = text.replaceAll(']', ' ');
    text = text.replaceAll('{', ' ');
    text = text.replaceAll('}', ' ');

    // --- DOT / ELLIPSIS HARD FIX ---
    // 1) Dot + space + dot / ellipsis varyantlarını tamamen yok et
    text = text.replaceAll(RegExp(r'(\.\s*){2,}'), ' ');

    // 2) Tek başına kalmış noktaları temizle (sayıları bozmaz)
    text = text.replaceAll(RegExp(r'(?<!\d)\.(?!\d)'), ' ');

    // 3) Boşlukları normalize et
    text = text.replaceAll(RegExp(r'\s+'), ' ').trim();

    return text;
  }

  Future<void> _showInstallTtsDialogOnce(BuildContext context) async {
    // UI'dan manuel çağrı için kullanılıyor, bu yüzden kaldırılmadı
    await showDialog(
      context: context,
      builder: (_) => AlertDialog(
        title: const Text('Text-to-Speech Not Available'),
        content: const Text(
          'Required voice data for the selected language is not available.\n\n'
          'Android: Settings > System > Languages & input > '
          'Text-to-speech output > Install voice data',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: const Text('OK'),
          ),
        ],
      ),
    );
  }

  Future<void> _openAndroidTtsSettings() async {
    try {
      await _sys.invokeMethod('openTtsSettings');
    } catch (_) {}
  }

  // speak() dönüş değerini kontrol et: SUCCESS ise true
  bool _isSpeakSuccess(dynamic res) {
    if (res == null) return false;
    if (res is bool) return res == true;
    if (res is int) return res == 1;
    if (res is String) {
      final s = res.toLowerCase().trim();
      return s == '1' || s == 'true';
    }
    return false;
  }

  // Helper to attempt Google TTS fallback - returns engine ID if found, null otherwise
  // NOTE: This should NOT switch engines mid-session - engine should be set during init
  Future<String?> _tryGoogleFallback() async {
    if (!Platform.isAndroid) return null;

    // DO NOT switch engines mid-session - engine should already be set during initialization
    // This function is kept for compatibility but should not change engine

    // Return current engine ID if it's Google, otherwise return null
    if (_currentEngineId != null) {
      if (_currentEngineId!.toLowerCase().contains('google') ||
          _currentEngineId!.toLowerCase() == 'com.google.android.tts') {
        return _currentEngineId;
      }
    }

    return null;
  }

  // speak() başlamazsa uyarı göster (sadece bu durumda)
  Future<void> _showTtsNotStartedWarning(String text) async {
    // Aynı metin için tekrar uyarı gösterme
    if (_lastWarnedText == text || !mounted) return;
    _lastWarnedText = text;

    final bool isTr =
        Localizations.localeOf(context).languageCode.toLowerCase() == 'tr';

    final String title = isTr ? 'Ses paketi gerekli' : 'Voice data required';

    final String msg = isTr
        ? 'Türkçe ses paketi bu telefonda yüklü değil. Ayarlardan “Metin okuma” bölümüne girip Türkçe ses verisini indirmen gerekiyor.'
        : 'Seçtiğin dil için ses paketi bu telefonda yüklü değil. Ayarlardan “Metin okuma” bölümünden ses verisini indirebilirsin.';

    await showDialog(
      context: context,
      builder: (_) => AlertDialog(
        title: Text(
          isTr ? 'Sesli okuma başlamadı' : 'Speech did not start',
        ),
        content: Text(
          '$msg\n\n'
          '${isTr ? 'Android: Ayarlar > Sistem > Diller ve giriş > Metin-konuşma çıkışı > Ses verilerini yükle' : 'Android: Settings > System > Languages & input > Text-to-speech output > Install voice data'}',
        ),
        actions: [
          TextButton(
            onPressed: () async {
              Navigator.pop(context);
              await _openAndroidTtsSettings();
            },
            child: Text(isTr ? 'Ayarları Aç' : 'Open Settings'),
          ),
          TextButton(
            onPressed: () => Navigator.pop(context),
            child: Text(isTr ? 'Tamam' : 'OK'),
          ),
        ],
      ),
    );

    // 10 saniye sonra aynı metin için tekrar uyarı gösterebilir
    Future.delayed(const Duration(seconds: 10), () {
      _lastWarnedText = null;
    });
  }

  Future<void> _ttsInitCallbacks() async {
    try {
      await _tts.awaitSpeakCompletion(true);
    } catch (_) {}

    _tts.setCompletionHandler(() async {
      // Timer'ı iptal et ve başlangıç onayını sıfırla
      _ttsStartCheckTimer?.cancel();
      _ttsStartCheckTimer = null;
      _ttsWatchdogTimer?.cancel();
      _ttsWatchdogTimer = null;
      _syntheticStepTimer?.cancel();
      _syntheticStepTimer = null;
      _ttsStartConfirmed = false;
      _ttsWatchdogRetried = false;
      _ttsBusy = false; // Clear busy flag on completion
      if (_ttsStopRequested) {
        // Stop requested: state already reset in _ttsRunNextSentence or _stop
        return;
      }
      if (_ttsPaused) {
        // Paused: keep paused state, DO NOT auto-resume
        return;
      }
      // Sentence-based: increment index and speak next sentence
      if (_currentSentenceIndex < _sentenceChunks.length) {
        _currentSentenceIndex++;
        if (_currentSentenceIndex < _sentenceChunks.length) {
          // More sentences to speak
          _ttsBusy = true;
          await _ttsRunNextSentence();
        } else {
          // All sentences completed
          _ttsRunning = false;
          if (mounted) {
            setState(() {
              _isSpeaking = false;
              _ttsPaused = false;
            });
          }
        }
      } else {
        // Fallback to old queue system if sentence chunks not available
        await _ttsRunNext();
      }
    });

    _tts.setErrorHandler((msg) async {
      // Timer'ı iptal et ve başlangıç onayını sıfırla
      _ttsStartCheckTimer?.cancel();
      _ttsStartCheckTimer = null;
      _ttsWatchdogTimer?.cancel();
      _ttsWatchdogTimer = null;
      _ttsStartConfirmed = false;
      _ttsWatchdogRetried = false;
      _ttsBusy = false; // Clear busy flag on error
      if (_ttsStopRequested) {
        // Stop requested: state already reset in _ttsRunNextSentence or _stop
        return;
      }
      if (_ttsPaused) {
        // Paused: keep paused state, DO NOT auto-resume
        return;
      }
      // Sentence-based: increment index and speak next sentence
      if (_currentSentenceIndex < _sentenceChunks.length) {
        _currentSentenceIndex++;
        if (_currentSentenceIndex < _sentenceChunks.length) {
          // More sentences to speak
          _ttsBusy = true;
          await _ttsRunNextSentence();
        } else {
          // All sentences completed
          _ttsRunning = false;
          if (mounted) {
            setState(() {
              _isSpeaking = false;
              _ttsPaused = false;
            });
          }
        }
      } else {
        // Fallback to old queue system if sentence chunks not available
        await _ttsRunNext();
      }
    });
  }

  // C) Normalize text for TTS - preserve punctuation, only clean whitespace/special chars
  // DO NOT replace punctuation with words (e.g., "." should stay ".", not become "nokta")
  String _normalizeText(String t) {
    return t
        .replaceAll('\u00AD', '') // soft hyphen
        .replaceAll('\u200B', '') // zero width
        .replaceAll('\r', '\n')
        .trim();
  }

  // Çok büyük metni güvenli parçalara böler
  List<String> _chunkForTts(String text, {int maxChars = 320}) {
    final cleaned = _normalizeText(text)
        .replaceAll('\n', ' ')
        .replaceAll(RegExp(r'\s+'), ' ')
        .trim();
    if (cleaned.isEmpty) return [];

    final rough = cleaned.split(RegExp(r'(?<=[\\.!\\?:])\\s+'));
    final out = <String>[];

    for (final seg0 in rough) {
      var seg = seg0.trim();
      if (seg.isEmpty) continue;

      if (seg.length > maxChars) {
        final words = seg.split(' ');
        var buf = '';
        for (final w in words) {
          if (buf.isEmpty) {
            buf = w;
          } else if (buf.length + 1 + w.length <= maxChars) {
            buf = '$buf $w';
          } else {
            out.add(buf);
            buf = w;
          }
        }
        if (buf.isNotEmpty) out.add(buf);
      } else {
        out.add(seg);
      }
    }
    return out;
  }

  // Engine seçim fonksiyonu - Türkçe için Samsung, diğerleri için Google
  Future<void> _selectEngineForLocale(String locale) async {
    if (!Platform.isAndroid) {
      return;
    }

    final isTurkish = locale.toLowerCase().startsWith('tr');

    // NON-FORCING: Only log the current default engine, do not override user preference
    try {
      final currentEngine = await _tts.getDefaultEngine;
    } catch (e) {}

    // Return immediately - never override user preference
    return;
  }

  // Simple helper to set language from selectedLocale (for entry points)
  Future<void> _ensureLanguageSet() async {
    // Get selectedLocale with safe default
    String locale;
    if (_selectedLocale == null || _selectedLocale!.isEmpty) {
      locale = 'tr-TR';
    } else if (_selectedLocale!.toLowerCase().startsWith('tr')) {
      locale = 'tr-TR';
    } else {
      locale = _selectedLocale!;
    }

    try {
      await _tts.setLanguage(locale);
    } catch (e) {
      // Continue even if setLanguage fails
    }
  }

  /// Ensures TTS engine is initialized and language is set
  /// Returns true if ready, false if failed
  Future<bool> _ensureTtsReady() async {
    try {
      // 1) Initialize TTS if needed
      if (!_ttsInitialized && !_ttsInitInProgress) {
        await _initTts();
      } else if (_ttsInitInProgress && _ttsInitCompleter != null) {
        await _ttsInitCompleter!.future;
      }

      // 2) Ensure language is set
      await _ensureLanguageSet();

      return true;
    } catch (e) {
      return false;
    }
  }

  // Android 9+ defensive TTS preparation with proper error handling
  Future<bool> _applySpeechLanguage(String locale) async {
    // TR normalize
    final normalized = locale.toLowerCase().startsWith('tr') ? 'tr-TR' : locale;

    try {
      // HARD RESET (required on Android 9+)
      await _tts.stop();
      await _tts.awaitSpeakCompletion(true);

      // Re-apply params every time
      await _tts.setSpeechRate(_rate);
      await _tts.setPitch(_pitch);
      await _tts.setVolume(_volume);

      final r = await _tts.setLanguage(normalized);

      final ok = (r is int) ? (r == 1 || r == 0) : true;
      if (ok) {
        return true;
      }

      // 1) TR başarısızsa en-US fallback (A07/A10'da en çok bu kurtarır)
      if (normalized == 'tr-TR') {
        final r2 = await _tts.setLanguage('en-US');
        final ok2 = (r2 is int) ? (r2 == 1 || r2 == 0) : true;
        if (ok2) {
          return true;
        }
      }

      // 2) Failed - log and return false (caller will handle user notification)
      return false;
    } catch (e) {
      return false;
    }
  }

  // Speak only the current sentence chunk (sentence-based queue)
  Future<void> _ttsSpeakSentence({required String locale}) async {
    // Request guard: prevent duplicate calls
    if (!_ttsBusy) {}

    // Ensure sentence queue is synced with current text before starting TTS
    _ensureSentenceQueueSynced(resetIndexIfTextChanged: false);

    // Check if current index is valid
    if (_currentSentenceIndex < 0 ||
        _currentSentenceIndex >= _sentenceChunks.length) {
      _currentSentenceIndex = 0;
    }

    if (_currentSentenceIndex >= _sentenceChunks.length) {
      _ttsBusy = false;
      if (mounted) {
        setState(() {
          _isSpeaking = false;
          _ttsPaused = false;
        });
      }
      return;
    }

    // Get current sentence chunk
    final chunk = _sentenceChunks[_currentSentenceIndex];
    final sentenceText = chunk.text;

    // Ensure engine hasn't changed mid-session (prevent engine switching)
    if (Platform.isAndroid && _currentEngineId != null) {
      try {
        final currentEngine = await _tts.getDefaultEngine;
        if (currentEngine != _currentEngineId) {
          await _tts.setEngine(_currentEngineId!);
          await Future.delayed(const Duration(milliseconds: 200));
        }
      } catch (e) {}
    }

    // Apply language
    final okLang = await _applySpeechLanguage(locale);
    if (!okLang) {
      _ttsBusy = false; // Clear busy flag on error
      // Show user-friendly error message
      if (mounted) {
        final isTr = AppLang.code.value == 'tr';
        ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
            isTr
                ? 'Dil ayarlanamadı. Android Ayarlar > Sistem > Metin-konuşma çıkışından ses verilerini yükleyin.'
                : 'Language could not be set. Install voice data from Android Settings > System > Text-to-speech output.',
            behavior: SnackBarBehavior.floating));
      }
      return;
    }

    // Build TTS text and map from UI text so progress mapping is consistent
    _buildTtsTextAndIndexMap(_text.text);
    _ttsOffset = chunk.globalEnd;
    _lastAppliedStart = 0;
    _lastAppliedEnd = 0;
    _lastUiStart = 0;
    _lastUiEnd = 0;
    _ttsHighlightStart = 0;
    _ttsHighlightEnd = 0;
    _pendingHlStart = -1;
    _pendingHlEnd = -1;
    _pendingHighlightPaint = false;
    _ttsLastChunk = '';
    _ttsChunkBase = chunk.globalStart; // Base offset for this sentence

    // Clear old queue (not used in sentence-based mode)
    _ttsQueue.clear();
    _ttsStopRequested = false;
    _ttsPaused = false;

    // Normalize and clean text for TTS
    final normalized = _normalizeText(sentenceText);
    if (normalized.isEmpty) {
      _ttsBusy = false;
      return;
    }

    // Clean text for TTS (remove Turkish punctuation-name words)
    final text = _cleanTextForTTS(normalized);
    if (text.isEmpty) {
      _ttsBusy = false;
      return;
    }

    _ttsRunning = true;
    try {
      await _tts.stop();
    } catch (_) {}
    // Ensure language is set from selectedLocale before starting
    await _ensureLanguageSet();
    await _ttsRunNextSentence();
  }

  // Kuyruğu doldur ve başlat
  Future<void> _ttsSpeakUnlimited(String fullText,
      {required String locale, int startOffset = 0}) async {
    // Request guard: prevent duplicate calls
    if (!_ttsBusy) {}

    // If startOffset is provided and valid, start from that position
    // Use substring from original fullText BEFORE normalization/cleaning
    final full = fullText;
    final clampedStartOffset = startOffset.clamp(0, full.length);
    final slice = full.substring(clampedStartOffset);
    final normalized = _normalizeText(slice);
    if (normalized.isEmpty) {
      _ttsBusy = false;
      return;
    }

    // E) Clean text for TTS (remove Turkish punctuation-name words, does not change on-screen text)
    final text = _cleanTextForTTS(normalized);
    int actualStartOffset = clampedStartOffset;
    if (text.isEmpty) {
      _ttsBusy = false;
      return;
    }

    // Ensure engine hasn't changed mid-session (prevent engine switching)
    if (Platform.isAndroid && _currentEngineId != null) {
      try {
        final currentEngine = await _tts.getDefaultEngine;
        if (currentEngine != _currentEngineId) {
          await _tts.setEngine(_currentEngineId!);
          await Future.delayed(const Duration(milliseconds: 200));
        }
      } catch (e) {}
    }

    // Apply language
    final okLang = await _applySpeechLanguage(locale);
    if (!okLang) {
      _ttsBusy = false; // Clear busy flag on error
      // Show user-friendly error message
      if (mounted) {
        final isTr = AppLang.code.value == 'tr';
        ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
            isTr
                ? 'Dil ayarlanamadı. Android Ayarlar > Sistem > Metin-konuşma çıkışından ses verilerini yükleyin.'
                : 'Language could not be set. Install voice data from Android Settings > System > Text-to-speech output.',
            behavior: SnackBarBehavior.floating));
      }
      return;
    }

    // Build TTS text and index map from UI text (single source for highlight mapping)
    _buildTtsTextAndIndexMap(fullText);
    final ttsStart = _uiIndexToTts(actualStartOffset);
    _ttsOffset = actualStartOffset;
    _lastAppliedStart = 0;
    _lastAppliedEnd = 0;
    _lastUiStart = 0;
    _lastUiEnd = 0;
    _ttsHighlightStart = 0;
    _ttsHighlightEnd = 0;
    _pendingHlStart = -1;
    _pendingHlEnd = -1;
    _pendingHighlightPaint = false;
    _ttsLastChunk = '';
    _ttsChunkBase = ttsStart;

    // Kuyruğu _ttsText'ten kur (exact substrings so progress indices match)
    _ttsQueue.clear();
    _ttsStopRequested = false;
    _ttsPaused = false;

    final toSpeak =
        ttsStart < _ttsText.length ? _ttsText.substring(ttsStart) : '';
    final parts = _chunkTtsTextPreserving(toSpeak, maxChars: 320);
    for (final p in parts) {
      if (p.isNotEmpty) _ttsQueue.add(p);
    }
    if (_ttsQueue.isEmpty) {
      _ttsBusy = false; // Clear busy flag when queue is empty
      return;
    }

    _ttsRunning = true;
    try {
      await _tts.stop();
    } catch (_) {}
    // Ensure language is set from selectedLocale before starting queue
    await _ensureLanguageSet();
    await _ttsRunNext();
  }

  // Speak the current sentence chunk
  Future<void> _ttsRunNextSentence() async {
    if (_ttsStopRequested) {
      _ttsRunning = false;
      _ttsBusy = false; // Clear busy flag
      // Stop requested: reset to IDLE state immediately
      if (mounted) {
        setState(() {
          _isSpeaking = false;
          _ttsPaused = false;
        });
      }
      return;
    }
    if (_ttsPaused) {
      return;
    }
    if (_currentSentenceIndex >= _sentenceChunks.length) {
      _ttsRunning = false;
      _ttsBusy = false; // Clear busy flag when all sentences done
      // All sentences finished: reset to IDLE state (Play icon)
      if (mounted) {
        setState(() {
          _isSpeaking = false;
          _ttsPaused = false;
        });
      }
      return;
    }

    // Get current sentence chunk
    final chunk = _sentenceChunks[_currentSentenceIndex];
    final sentenceText = chunk.text;

    // Normalize and clean text for TTS
    final normalized = _normalizeText(sentenceText);
    if (normalized.isEmpty) {
      // Empty sentence, move to next
      _currentSentenceIndex++;
      await _ttsRunNextSentence();
      return;
    }

    // Clean text for TTS
    final text = _cleanTextForTTS(normalized);
    if (text.isEmpty) {
      // Empty after cleaning, move to next
      _currentSentenceIndex++;
      await _ttsRunNextSentence();
      return;
    }

    // Ensure engine hasn't changed mid-session
    if (Platform.isAndroid && _currentEngineId != null) {
      try {
        final currentEngine = await _tts.getDefaultEngine;
        if (currentEngine != _currentEngineId) {
          await _tts.setEngine(_currentEngineId!);
          await Future.delayed(const Duration(milliseconds: 200));
        }
      } catch (e) {}
    }

    try {
      // Önceki timer'ı iptal et ve başlangıç onayını sıfırla
      _ttsStartCheckTimer?.cancel();
      _ttsStartCheckTimer = null;
      _ttsWatchdogTimer?.cancel();
      _ttsWatchdogTimer = null;
      _ttsStartConfirmed = false;
      _ttsWatchdogRetried = false;

      // Ensure language is set before speaking
      await _ensureLanguageSet();

      // Ensure TTS engine always receives the current rate before speaking
      await _tts.setSpeechRate(_rate);

      // Keep original sentence text through the flow; final TTS prep happens only in _ttsSpeakFinal.
      _ttsText = text;

      // Store per-sentence spoken↔original map for accurate progress highlight mapping
      // Use normalized (not raw sentenceText) as the "original" so the map aligns with
      // what _cleanTextForTTS receives — reduces drift between original and spoken.
      _currentSentenceOriginal = normalized;
      _currentSentenceSpoken = sentenceText;
      _currentSentenceUiBase = chunk.globalStart;

      // RTL diller için: _ttsSpeakFinal sembol temizleme yapıyor,
      // bu karakter offset'lerini kaydırıyor. Map'i temizlenmiş metinle kur.
      final locale = (_selectedLocale ?? '').toLowerCase();
      final isRtlLocale = locale.startsWith('ar') ||
          locale.startsWith('he') ||
          locale.startsWith('iw');
      if (isRtlLocale) {
        final sanitized = _sanitizeSymbolsForTts(sentenceText, false);
        _spokenToOrigMap = _buildSpokenToOrigMap(normalized, sanitized);
      } else {
        _spokenToOrigMap = _buildSpokenToOrigMap(normalized, sentenceText);
      }

      // Not: _tts.stop() burada gereksiz - önceki cümle onComplete ile bitti.
      // stop() kaldırıldı → cümleler arası gecikme azaldı.
      final speakResult = await _ttsSpeakFinal(sentenceText);

      // SUCCESS ise uyarı gösterme
      if (_isSpeakSuccess(speakResult)) {
        // RTL diller (Arapça/İbranice): progress callback gelmez, stepper'ı hemen başlat
        if (_isSyntheticStepLocale() && _readingMode == ReadingMode.both) {
          final uiStart = chunk.globalStart;
          final uiEnd = (chunk.globalStart + chunk.text.length)
              .clamp(0, _uiTextForReading.length);
          // Kısa gecikme — TTS motorunun başlamasını bekle
          Future.delayed(const Duration(milliseconds: 150), () {
            if (mounted && _isSpeaking && !_ttsStopRequested) {
              _startSyntheticStepper(uiStart, uiEnd);
            }
          });
        }

        // Başarılı, watchdog timer kur (1s timeout for onStart callback)
        // Store the chunk in case we need to retry
        final chunkToRetry = chunk;
        _ttsWatchdogTimer = Timer(const Duration(milliseconds: 1000), () async {
          if (!_ttsStartConfirmed && !_ttsWatchdogRetried && mounted) {
            _ttsWatchdogRetried = true;
            // Reset internal state
            _ttsBusy = false;
            _ttsPaused = false;
            // Retry same sentence
            await _ttsRunNextSentence();
          }
          _ttsWatchdogTimer = null;
        });
        return;
      }

      // Başarısız görünüyor, 1400ms timer kur (NO engine switching mid-session)
      _ttsStartCheckTimer = Timer(const Duration(milliseconds: 1400), () async {
        // Timer bitmişse ve başlangıç onayı hala yoksa
        if (!_ttsStartConfirmed && mounted) {
          // Still failed, show warning (no engine switching)
          _showTtsNotStartedWarning(text);
        }
        _ttsStartCheckTimer = null;
      });
    } catch (_) {
      // Exception durumunda da timer kur (başarısız kabul et)
      _ttsStartCheckTimer = Timer(const Duration(milliseconds: 1400), () async {
        if (!_ttsStartConfirmed && mounted) {
          // Still failed, show warning
          _showTtsNotStartedWarning(text);
        }
        _ttsStartCheckTimer = null;
      });
    }
  }

  // Kuyruktan sıradakini çalıştır
  Future<void> _ttsRunNext() async {
    if (_ttsStopRequested) {
      _ttsRunning = false;
      _ttsBusy = false; // Clear busy flag
      // Stop requested: reset to IDLE state immediately
      if (mounted) {
        setState(() {
          _isSpeaking = false;
          _ttsPaused = false;
        });
      }
      return;
    }
    if (_ttsPaused) {
      return;
    }
    if (_ttsQueue.isEmpty) {
      _ttsRunning = false;
      _ttsBusy = false; // Clear busy flag when queue is empty
      // Queue finished: reset to IDLE state (Play icon)
      if (mounted) {
        setState(() {
          _isSpeaking = false;
          _ttsPaused = false;
        });
      }
      return;
    }

    final next = _ttsQueue.removeFirst();

    // Ensure engine hasn't changed mid-session
    if (Platform.isAndroid && _currentEngineId != null) {
      try {
        final currentEngine = await _tts.getDefaultEngine;
        if (currentEngine != _currentEngineId) {
          await _tts.setEngine(_currentEngineId!);
          await Future.delayed(const Duration(milliseconds: 200));
        }
      } catch (e) {}
    }

    try {
      // Önceki timer'ı iptal et ve başlangıç onayını sıfırla
      _ttsStartCheckTimer?.cancel();
      _ttsStartCheckTimer = null;
      _ttsWatchdogTimer?.cancel();
      _ttsWatchdogTimer = null;
      _ttsStartConfirmed = false;
      _ttsWatchdogRetried = false;

      // Ensure language is set before speaking
      await _ensureLanguageSet();

      // Ensure TTS engine always receives the current rate before speaking
      await _tts.setSpeechRate(_rate);

      // Do NOT overwrite _ttsText (full text + map must stay for _onTtsProgressMapped).
      await _tts.stop();
      final speakResult = await _ttsSpeakFinal(next);

      // SUCCESS ise uyarı gösterme
      if (_isSpeakSuccess(speakResult)) {
        // Başarılı, watchdog timer kur (1s timeout for onStart callback)
        // Store the chunk in case we need to retry
        final chunkToRetry = next;
        _ttsWatchdogTimer = Timer(const Duration(milliseconds: 1000), () async {
          if (!_ttsStartConfirmed && !_ttsWatchdogRetried && mounted) {
            _ttsWatchdogRetried = true;
            // Reset internal state
            _ttsBusy = false;
            _ttsPaused = false;
            // Put the chunk back at the front of the queue and retry
            // Queue doesn't have addFirst, so we recreate it with the chunk first
            final queueList = _ttsQueue.toList();
            _ttsQueue.clear();
            _ttsQueue.add(chunkToRetry);
            for (final item in queueList) {
              _ttsQueue.add(item);
            }
            await _ttsRunNext();
          }
          _ttsWatchdogTimer = null;
        });
        return;
      }

      // Başarısız görünüyor, 1400ms timer kur (NO engine switching mid-session)
      _ttsStartCheckTimer = Timer(const Duration(milliseconds: 1400), () async {
        // Timer bitmişse ve başlangıç onayı hala yoksa
        if (!_ttsStartConfirmed && mounted) {
          // Still failed, show warning (no engine switching)
          _showTtsNotStartedWarning(next);
        }
        _ttsStartCheckTimer = null;
      });
    } catch (_) {
      // Exception durumunda da timer kur (başarısız kabul et)
      _ttsStartCheckTimer = Timer(const Duration(milliseconds: 1400), () async {
        if (!_ttsStartConfirmed && mounted) {
          // Still failed, show warning
          _showTtsNotStartedWarning(next);
        }
        _ttsStartCheckTimer = null;
      });
    }
  }

  Future<void> _ttsStopAll() async {
    _ttsStopRequested = true;
    _ttsPaused = false;
    _ttsRunning = false;
    _ttsBusy = false; // Clear busy flag on stop
    _ttsQueue.clear();
    // Timer'ı iptal et ve başlangıç onayını sıfırla
    _ttsStartCheckTimer?.cancel();
    _ttsStartCheckTimer = null;
    _ttsWatchdogTimer?.cancel();
    _ttsWatchdogTimer = null;
    _ttsStartConfirmed = false;
    _ttsWatchdogRetried = false;
    // TASK 3: Reset reading position on stop (but keep _lastSpokenOffset for resume)
    _ttsCharOffset = 0;
    _ttsStartTime = null;
    // DO NOT reset _lastSpokenOffset here - allow resume after stop
    try {
      await _tts.stop();
    } catch (_) {}
  }

  Future<void> _ttsPause() async {
    _ttsPaused = true;
    // DO NOT clear _ttsBusy here - pause is not a completion

    // DO NOT compute offsets - simply preserve _currentSentenceIndex

    try {
      await _tts.pause();
    } catch (_) {
      try {
        await _tts.stop();
      } catch (_) {}
    }
  }

  Future<void> _ttsResume() async {
    // Request guard: prevent duplicate resume calls
    if (_ttsBusy && !_ttsPaused) {
      return;
    }

    // If TTS is not running (was stopped), restart from current sentence
    if (!_ttsRunning) {
      _ttsPaused = false;
      // Restart TTS from current sentence using _playSafe
      _playSafe();
      return;
    }

    _ttsPaused = false;
    _ttsBusy = true; // Set busy flag for resume
    // Ensure language is set before resuming
    await _ensureLanguageSet();
    await _ttsRunNextSentence();
  }

  Future<void> _speakSafe(
    BuildContext context,
    String text,
    String locale,
  ) async {
    // Request guard: prevent duplicate calls
    if (_ttsBusy) {
      return;
    }

    if (text.trim().isEmpty) return;

    // Preserve text integrity - only trim, no normalization
    final trimmed = text.trim();
    _ttsText = trimmed;
    _ttsOffset = 0;
    _lastAppliedStart = 0;
    _lastAppliedEnd = 0;
    _lastUiStart = 0;
    _lastUiEnd = 0;
    _ttsHighlightStart = 0;
    _ttsHighlightEnd = 0;
    _pendingHlStart = -1;
    _pendingHlEnd = -1;
    _pendingHighlightPaint = false;
    _ttsLastChunk = '';
    _ttsChunkBase = 0;

    // Ensure engine hasn't changed mid-session
    if (Platform.isAndroid && _currentEngineId != null) {
      try {
        final currentEngine = await _tts.getDefaultEngine;
        if (currentEngine != _currentEngineId) {
          await _tts.setEngine(_currentEngineId!);
          await Future.delayed(const Duration(milliseconds: 200));
        }
      } catch (e) {}
    }

    // Set voice if available
    if (_selectedVoice != null) {
      try {
        String normalizedLocale = locale;
        if (locale.toLowerCase().startsWith('tr')) {
          normalizedLocale = 'tr-TR';
        }
        await _tts.setVoice({
          "name": _selectedVoice!["name"],
          "locale": normalizedLocale,
        });
      } catch (e) {}
    }

    final ok = await _applySpeechLanguage(locale);
    if (!ok) {
      _ttsBusy = false;
      return;
    }

    try {
      // Önceki timer'ı iptal et ve başlangıç onayını sıfırla
      _ttsStartCheckTimer?.cancel();
      _ttsStartCheckTimer = null;
      _ttsStartConfirmed = false;

      // Ensure language is set from selectedLocale before speaking
      await _ensureLanguageSet();

      // Ensure TTS engine always receives the current rate before speaking
      await _tts.setSpeechRate(_rate);

      // Keep raw reading text here; locale-aware normalization is only in _ttsSpeakFinal.
      _ttsText = trimmed;
      await _tts.stop();
      final speakResult = await _ttsSpeakFinal(trimmed);

      // SUCCESS ise uyarı gösterme
      if (_isSpeakSuccess(speakResult)) {
        // Başarılı, uyarı kurma
        return;
      }

      // Başarısız görünüyor, 1400ms timer kur (NO engine switching)
      _ttsStartCheckTimer = Timer(const Duration(milliseconds: 1400), () async {
        // Timer bitmişse ve başlangıç onayı hala yoksa
        if (!_ttsStartConfirmed && mounted) {
          // Still failed, show warning (no engine switching mid-session)
          _showTtsNotStartedWarning(trimmed);
        }
        _ttsStartCheckTimer = null;
      });
    } catch (e) {
      _ttsBusy = false; // Clear busy flag on error
      // Exception durumunda da timer kur (başarısız kabul et)
      _ttsStartCheckTimer = Timer(const Duration(milliseconds: 1400), () async {
        if (!_ttsStartConfirmed && mounted) {
          // Still failed, show warning
          _showTtsNotStartedWarning(trimmed);
        }
        _ttsStartCheckTimer = null;
      });
    }
  }

  Future<void> _playSafe() async {
    // Cursor pozisyonunu başta kaydet — stop/unfocus sonrası kaybolabilir
    final savedCursorOffset = _text.selection.baseOffset;
    // Request guard: prevent duplicate calls
    if (_ttsBusy) {
      return;
    }

    // Ensure TTS is initialized before proceeding
    if (_ttsInitInProgress) {
      _pendingPlayRequest = true;
      // Wait for initialization to complete
      if (_ttsInitCompleter != null) {
        await _ttsInitCompleter!.future;
      }
      // After init completes, _playSafe will be called again via the pending request handler
      // But we should also check if we're still not busy and proceed
      if (_ttsBusy) {
        return;
      }
    } else if (!_ttsInitialized) {
      _pendingPlayRequest = true;
      await _initTts();
      if (_ttsBusy) {
        return;
      }
    }

    // Metni al ve boşsa uyarı ver
    final txt = _text.text.trim();
    if (txt.isEmpty) {
      ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
          t('empty.text'),
          behavior: SnackBarBehavior.floating));
      return;
    }

    // Ensure sentence queue is synced with current text before starting TTS
    _ensureSentenceQueueSynced(resetIndexIfTextChanged: false);

    // Determine sentence index for resume:
    // Priority: 1) _forceStartFromTopOnce -> 0
    //           2) Cursor pozisyonu (> 0 ise)
    //           3) Scroll pozisyonu
    //           4) Scroll 0 ise → baştan başla
    if (_forceStartFromTopOnce) {
      _currentSentenceIndex = 0;
      _forceStartFromTopOnce = false;
    } else if (savedCursorOffset > 0 && _sentenceChunks.isNotEmpty) {
      int foundIndex = 0;
      for (int i = 0; i < _sentenceChunks.length; i++) {
        if (_sentenceChunks[i].globalStart <= savedCursorOffset) {
          foundIndex = i;
        } else {
          break;
        }
      }
      _currentSentenceIndex = foundIndex;
    } else if (_scroll.hasClients && _sentenceChunks.isNotEmpty) {
      final scrollOffset = _scroll.offset;
      final totalChars = _text.text.length;
      final maxScroll = _scroll.position.maxScrollExtent;
      if (scrollOffset > 10 && maxScroll > 0 && totalChars > 0) {
        final charPos = ((scrollOffset / maxScroll) * totalChars).round();
        int foundIndex = 0;
        for (int i = 0; i < _sentenceChunks.length; i++) {
          if (_sentenceChunks[i].globalStart <= charPos) {
            foundIndex = i;
          } else {
            break;
          }
        }
        _currentSentenceIndex = foundIndex;
      } else {
        _currentSentenceIndex = 0;
      }
    } else {
      _currentSentenceIndex = 0;
    }
    // Ensure sentence index is valid
    if (_currentSentenceIndex < 0 ||
        _currentSentenceIndex >= _sentenceChunks.length) {
      _currentSentenceIndex = 0;
    }

    // Set busy flag and increment request ID
    _ttsRequestId++;
    final currentRequestId = _ttsRequestId;
    _ttsBusy = true;

    // 🔵 2) TTS başlıyor → UI state'ini ANINDA güncelle
    setState(() {
      _isTtsPlaying = true;
      _ttsPaused = false;
      _isSpeaking = true; // UI'da playing görünmesi için
    });

    // Determine locale - prefer selectedLocale with safe TR default
    String locale;
    if (_selectedLocale == null || _selectedLocale!.isEmpty) {
      locale = 'tr-TR';
    } else if (_selectedLocale!.toLowerCase().startsWith('tr')) {
      locale = 'tr-TR';
    } else {
      locale = _selectedLocale!;
    }

    // Log engine, locale, and voice info
    try {
      final currentEngine = _currentEngineId ?? await _tts.getDefaultEngine;
      final voiceName = _selectedVoice?['name'] ?? 'default';
      final voiceLocale = _selectedVoice?['locale'] ?? locale;
    } catch (e) {}

    // Scroll to sentence position only if:
    // 1) Not starting from top (resume case)
    // 2) Current sentence index > 0
    // This prevents double scroll (bounce) when starting from top
    if (!_shouldStartFromTop &&
        _currentSentenceIndex > 0 &&
        _currentSentenceIndex < _sentenceChunks.length &&
        _scroll.hasClients) {
      final chunk = _sentenceChunks[_currentSentenceIndex];
      _scrollToCaretPosition(chunk.globalStart);
    }

    // TTS işlemlerini async olarak başlat (UI thread'i beklemesin)
    Future.microtask(() async {
      try {
        // Verify request ID hasn't changed (another request started)
        if (currentRequestId != _ttsRequestId) {
          return;
        }
        await _ttsSpeakSentence(locale: locale);
      } catch (e) {
        _ttsBusy = false; // Clear busy flag on error
        if (mounted) {
          setState(() {
            _isTtsPlaying = false;
            _isSpeaking = false;
            _ttsPaused = false;
          });
        }
      }
    });
  }

  Future<void> _pause() async {
    // UI state zaten _togglePauseResume'da güncellendi, burada sadece TTS işlemini yap
    // On pause, explicitly close keyboard but do not modify selection
    FocusManager.instance.primaryFocus?.unfocus();
    _voiceLimitTimer?.cancel();
    _pauseAutoScroll();
    await _ttsPause();
  }

  Future<void> _resume() async {
    // UI state zaten _togglePauseResume'da güncellendi, burada sadece TTS işlemini yap
    try {
      await _ttsResume();
      if (!PremiumService.instance.hasFullAccess &&
          (_readingMode == ReadingMode.voiceOnly ||
              _readingMode == ReadingMode.both)) {
        _startVoiceLimitTimer();
        FirebaseAnalytics.instance.logEvent(name: 'tts_started');
      }
    } catch (e) {
      if (mounted) {
        setState(() {
          _isTtsPlaying = false;
          _isSpeaking = false;
          _ttsPaused = false;
        });
      }
    }
  }

  /// Track text changes for fresh start scroll position
  /// Sets _shouldStartFromTop when text changes significantly (new text loaded)
  void _trackTextChange(String newText) {
    final newHash = newText.hashCode;
    if (newHash != _lastTextHash) {
      // Text changed significantly - mark for fresh start from top
      _shouldStartFromTop = true;
      _forceStartFromTopOnce = true; // Yeni metin → play'e basınca baştan başla
      _lastTextHash = newHash;
      // Reset last spoken offset for new text (start from top)
      _lastSpokenOffset = 0;
      _currentSentenceIndex = 0;
      // Build sentence chunks for new text
      _buildSentenceChunks(newText);
    }
  }

  // ======================= POETRY DETECTION ==========================
  /// Returns true if the text looks like a poem.
  /// Criteria: most lines are short (2-10 words), text has multiple lines,
  /// and lines don't end with full stops consistently (prose-like).
  bool _isPoetryText(String text) {
    final lines = text
        .split('\n')
        .map((l) => l.trim())
        .where((l) => l.isNotEmpty)
        .toList();
    if (lines.length < 3) return false; // need at least 3 lines

    int shortLines = 0;
    int totalLines = lines.length;
    for (final line in lines) {
      final wordCount =
          line.split(RegExp(r'\s+')).where((w) => w.isNotEmpty).length;
      if (wordCount >= 2 && wordCount <= 12) shortLines++;
    }
    // If 70%+ of lines are short → likely poetry
    return (shortLines / totalLines) >= 0.70;
  }

  /// Adds natural pauses to poetry text for TTS:
  /// - comma after each line (short pause)
  /// - period after blank-line separated stanzas (long pause)
  String _preparePoetryForTts(String text) {
    final lines = text.split('\n');
    final result = StringBuffer();
    for (int i = 0; i < lines.length; i++) {
      final line = lines[i].trim();
      if (line.isEmpty) {
        // Stanza break — long pause
        result.write('. ');
      } else {
        // End of line — short pause (comma if no punctuation already)
        final lastChar = line.isNotEmpty ? line[line.length - 1] : '';
        final hasPunct = ['.', ',', '!', '?', ';', ':'].contains(lastChar);
        result.write(line);
        if (!hasPunct) result.write(',');
        result.write(' ');
      }
    }
    return result.toString();
  }
  // ====================================================================

  // Convert Roman numeral to integer
  int? _romanToInt(String roman) {
    final s = roman.toUpperCase();
    const map = {
      'I': 1,
      'V': 5,
      'X': 10,
      'L': 50,
      'C': 100,
      'D': 500,
      'M': 1000
    };
    int total = 0;
    int prev = 0;

    for (int i = s.length - 1; i >= 0; i--) {
      final ch = s[i];
      final val = map[ch];
      if (val == null) return null;
      if (val < prev)
        total -= val;
      else
        total += val;
      prev = val;
    }

    // Basit geçerlilik kontrolü: aşırı uçları engelleyelim
    if (total <= 0 || total > 3999) return null;
    return total;
  }

  /// Sayıyı Türkçe kardinal kelimeye çevirir (1 → bir, 20 → yirmi, 1900 → bin dokuz yüz)
  String _toTurkishCardinalWord(int n) {
    if (n <= 0) return n.toString();
    final ones = [
      '',
      'bir',
      'iki',
      'üç',
      'dört',
      'beş',
      'altı',
      'yedi',
      'sekiz',
      'dokuz'
    ];
    final tens = [
      '',
      'on',
      'yirmi',
      'otuz',
      'kırk',
      'elli',
      'altmış',
      'yetmiş',
      'seksen',
      'doksan'
    ];
    String result = '';
    if (n >= 1000000000) {
      final billions = n ~/ 1000000000;
      result += '${_toTurkishCardinalWord(billions)} milyar';
      n = n % 1000000000;
      if (n > 0) result += ' ';
    }
    if (n >= 1000000) {
      final millions = n ~/ 1000000;
      result += '${_toTurkishCardinalWord(millions)} milyon';
      n = n % 1000000;
      if (n > 0) result += ' ';
    }
    if (n >= 1000) {
      final thousands = n ~/ 1000;
      result +=
          (thousands == 1 ? 'bin' : '${_toTurkishCardinalWord(thousands)} bin');
      n = n % 1000;
      if (n > 0) result += ' ';
    }
    if (n >= 100) {
      final hundreds = n ~/ 100;
      result += (hundreds == 1 ? 'yüz' : '${ones[hundreds]} yüz');
      n = n % 100;
      if (n > 0) result += ' ';
    }
    if (n >= 10) {
      result += tens[n ~/ 10];
      n = n % 10;
      if (n > 0) result += ' ';
    }
    if (n > 0) result += ones[n];
    return result.trim();
  }

  /// Sayıyı Türkçe sıra sayı ekiyle döndürür (1→birinci, 20→yirminci, 1900→bin dokuz yüzüncü)
  String _toTurkishOrdinalWord(int n) {
    final cardinal = _toTurkishCardinalWord(n);
    if (cardinal.isEmpty) return n.toString();
    // Son hece vokaline göre ek seç
    final vowels = 'aeıioöuü';
    String lastVowel = 'i';
    for (int i = cardinal.length - 1; i >= 0; i--) {
      if (vowels.contains(cardinal[i])) {
        lastVowel = cardinal[i];
        break;
      }
    }
    String suffix;
    if ('aı'.contains(lastVowel))
      suffix = 'ıncı';
    else if ('eı'.contains(lastVowel) || lastVowel == 'e' || lastVowel == 'i')
      suffix = 'inci';
    else if ('ou'.contains(lastVowel))
      suffix = 'uncu';
    else
      suffix = 'üncü'; // öü
    // Özel düzeltmeler
    if (cardinal.endsWith('bir')) suffix = 'inci';
    if (cardinal.endsWith('iki')) suffix = 'nci';
    if (cardinal.endsWith('uc') || cardinal.endsWith('üç')) suffix = 'üncü';
    if (cardinal.endsWith('dort') || cardinal.endsWith('dört')) suffix = 'üncü';
    if (cardinal.endsWith('bes') || cardinal.endsWith('beş')) suffix = 'inci';
    if (cardinal.endsWith('alti') || cardinal.endsWith('altı')) suffix = 'ncı';
    if (cardinal.endsWith('yedi')) suffix = 'nci';
    if (cardinal.endsWith('sekiz')) suffix = 'inci';
    if (cardinal.endsWith('dokuz')) suffix = 'uncu';
    if (cardinal.endsWith('on')) suffix = 'uncu';
    if (cardinal.endsWith('yirmi')) suffix = 'nci';
    if (cardinal.endsWith('otuz')) suffix = 'uncu';
    if (cardinal.endsWith('kirk') || cardinal.endsWith('kırk')) suffix = 'ıncı';
    if (cardinal.endsWith('elli')) suffix = 'nci';
    if (cardinal.endsWith('atmis') || cardinal.endsWith('altmış'))
      suffix = 'ıncı';
    if (cardinal.endsWith('yetmis') || cardinal.endsWith('yetmiş'))
      suffix = 'inci';
    if (cardinal.endsWith('seksen')) suffix = 'inci';
    if (cardinal.endsWith('doksan')) suffix = 'ıncı';
    if (cardinal.endsWith('yuz') || cardinal.endsWith('yüz')) suffix = 'üncü';
    if (cardinal.endsWith('bin')) suffix = 'inci';
    return '$cardinal$suffix';
  }

  /// Locks Roman numeral tokens for Turkish TTS by converting them to protected token
  /// ROMORDnROM (e.g. XIX. -> ROMORD19ROM) so chunking/splitting cannot break them.
  /// Decoded to ordinal word at speak time (right before _tts.speak).
  String _lockRomanTokensForTr(String text) {
    final bool isTr =
        (_selectedLocale?.toLowerCase().startsWith('tr') ?? false);

    if (!isTr) return text;

    // 0a) Yaygın kısaltmaları koru — Roman rakamı olarak algılanmasın
    var result = text;
    // M.Ö. ve M.S. önce koru
    result = result.replaceAll(RegExp(r'M\.Ö\.'), '§MO§');
    result = result.replaceAll(RegExp(r'M\.S\.'), '§MS§');
    final abbrevPlaceholders = <String, String>{};
    const protectedAbbrevs = [
      'ID',
      'CD',
      'DVD',
      'VIP',
      'LCD',
      'LED',
      'MC',
      'DJ',
      'PC',
      'TV',
      'HIV',
      'DNA',
      'RNA',
      'CPU',
      'GPU',
      'SIM',
      'PIN',
      'CVV',
      'CVC',
      'DM',
      'CM',
    ];
    for (final abbrev in protectedAbbrevs) {
      final pattern = RegExp('(?<![A-Za-z])' + abbrev + '(?![A-Za-z])');
      result = result.replaceAllMapped(pattern, (m) {
        final key = '§ABR§' + abbrev + '§';
        abbrevPlaceholders[key] = m.group(0)!;
        return key;
      });
    }

    // 0) XX. yüzyıl / XIX. yüzyıl gibi ifadeleri ÖNCE yakala → yirminci yüzyıl
    result = result.replaceAllMapped(
      RegExp(r'(?<![A-Za-zÀ-ÿğüşıöçĞÜŞİÖÇ])([IVXLCDM]{1,})\.?\s*(yüzyıl\w*)'),
      (m) {
        final roman = m.group(1)!.toUpperCase();
        final suffix = m.group(2)!;
        final n = _romanToInt(roman);
        if (n == null || n < 1) return m.group(0)!;
        return '${_toTurkishOrdinalWord(n)} $suffix';
      },
    );

    // 1) Multi-char roman numerals (with or without dot): II, III, IV, XIX. etc.
    // SADECE büyük harf - küçük harfli kelimeler (ciddi, mix vb.) atlanır
    result = result.replaceAllMapped(
      RegExp(
          r'(?<![A-Za-zÀ-ÿğüşıöçĞÜŞİÖÇ])([IVXLCDM]{2,})\.?(?![A-Za-zÀ-ÿğüşıöçĞÜŞİÖÇ])'),
      (m) {
        final roman = m.group(1)!.toUpperCase();
        final n = _romanToInt(roman);
        if (n == null) return m.group(0)!;
        return 'ROMORD${n}ROM';
      },
    );

    // 2) Single-char roman numerals ONLY when followed by a dot: I. V. X. L. C.
    //    (without dot they could be regular letters)
    result = result.replaceAllMapped(
      RegExp(r'(?<![A-Za-zÀ-ÿğüşıöçĞÜŞİÖÇ])([IVXLCDM])\.(?=\s)'),
      (m) {
        final roman = m.group(1)!.toUpperCase();
        final n = _romanToInt(roman);
        if (n == null) return m.group(0)!;
        // Keep the trailing space
        return 'ROMORD${n}ROM ';
      },
    );

    // 2b) Turkish dotless-ı or I at word start followed by dot + space -> birinci
    //     Handles "ı. dünya" and "I. DÜNYA" where lookbehind above may miss ı (ı)
    result = result.replaceAllMapped(
      RegExp(
          '(?<![A-Za-z\u00C0-\u024F\u0100-\u017F\u0131])([I\u0131])\\.(\\s)'),
      (m) => 'ROMORD1ROM \${m.group(2)!}',
    );

    // 3) Single-char roman numerals at end of string with dot: "...bölüm I."
    result = result.replaceAllMapped(
      RegExp(r'(?<![A-Za-z\u00C0-\u024F\u0130\u0131])([IVXLCDM])\.$'),
      (m) {
        final roman = m.group(1)!.toUpperCase();
        final n = _romanToInt(roman);
        if (n == null) return m.group(0)!;
        return 'ROMORD${n}ROM';
      },
    );

    // Korunan kısaltmaları geri yükle
    abbrevPlaceholders.forEach((key, value) {
      result = result.replaceAll(key, value);
    });

    // M.Ö. ve M.S. geri yükle
    result = result.replaceAll('§MO§', 'M.Ö.');
    result = result.replaceAll('§MS§', 'M.S.');

    return result;
  }

  /// Single final gate for all TTS speech. Uses TTS locale (_selectedLocale), not UI language.
  /// Call this instead of _tts.speak so Roman ordinals and yy are normalized for Turkish.
  /// Roman numerals are locked before normalization so they are never split.
  Future<int> _ttsSpeakFinal(String rawInput) async {
    final bool isTr =
        (_selectedLocale?.toLowerCase().startsWith('tr') ?? false);

    String s = rawInput;

    // ── ADIM 1: Şiir tespiti ─────────────────────────────────────────────────
    // NOT: _preparePoetryForTts kaldırıldı — karakter sayısını değiştirdiği için
    // highlight index'i kayıyordu. \n'ler olduğu gibi bırakılıyor,
    // TTS engine satır sonlarını zaten durak olarak işliyor.

    // ── ADIM 1b: Tarih dönüşümü ──────────────────────────────────────────────
    // GG.AA.YYYY veya GG/AA/YYYY → dile göre okunabilir forma çevir
    final _dateLang = (_selectedLocale ?? 'en').toLowerCase().split('-')[0];
    const _months = {
      'tr': [
        '',
        'Ocak',
        'Şubat',
        'Mart',
        'Nisan',
        'Mayıs',
        'Haziran',
        'Temmuz',
        'Ağustos',
        'Eylül',
        'Ekim',
        'Kasım',
        'Aralık'
      ],
      'en': [
        '',
        'January',
        'February',
        'March',
        'April',
        'May',
        'June',
        'July',
        'August',
        'September',
        'October',
        'November',
        'December'
      ],
      'de': [
        '',
        'Januar',
        'Februar',
        'März',
        'April',
        'Mai',
        'Juni',
        'Juli',
        'August',
        'September',
        'Oktober',
        'November',
        'Dezember'
      ],
      'fr': [
        '',
        'janvier',
        'février',
        'mars',
        'avril',
        'mai',
        'juin',
        'juillet',
        'août',
        'septembre',
        'octobre',
        'novembre',
        'décembre'
      ],
      'it': [
        '',
        'gennaio',
        'febbraio',
        'marzo',
        'aprile',
        'maggio',
        'giugno',
        'luglio',
        'agosto',
        'settembre',
        'ottobre',
        'novembre',
        'dicembre'
      ],
      'es': [
        '',
        'enero',
        'febrero',
        'marzo',
        'abril',
        'mayo',
        'junio',
        'julio',
        'agosto',
        'septiembre',
        'octubre',
        'noviembre',
        'diciembre'
      ],
      'pt': [
        '',
        'janeiro',
        'fevereiro',
        'março',
        'abril',
        'maio',
        'junho',
        'julho',
        'agosto',
        'setembro',
        'outubro',
        'novembro',
        'dezembro'
      ],
      'nl': [
        '',
        'januari',
        'februari',
        'maart',
        'april',
        'mei',
        'juni',
        'juli',
        'augustus',
        'september',
        'oktober',
        'november',
        'december'
      ],
      'ru': [
        '',
        'января',
        'февраля',
        'марта',
        'апреля',
        'мая',
        'июня',
        'июля',
        'августа',
        'сентября',
        'октября',
        'ноября',
        'декабря'
      ],
      'bg': [
        '',
        'януари',
        'февруари',
        'март',
        'април',
        'май',
        'юни',
        'юли',
        'август',
        'септември',
        'октомври',
        'ноември',
        'декември'
      ],
      'el': [
        '',
        'Ιανουαρίου',
        'Φεβρουαρίου',
        'Μαρτίου',
        'Απριλίου',
        'Μαΐου',
        'Ιουνίου',
        'Ιουλίου',
        'Αυγούστου',
        'Σεπτεμβρίου',
        'Οκτωβρίου',
        'Νοεμβρίου',
        'Δεκεμβρίου'
      ],
      'pl': [
        '',
        'stycznia',
        'lutego',
        'marca',
        'kwietnia',
        'maja',
        'czerwca',
        'lipca',
        'sierpnia',
        'września',
        'października',
        'listopada',
        'grudnia'
      ],
      'ro': [
        '',
        'ianuarie',
        'februarie',
        'martie',
        'aprilie',
        'mai',
        'iunie',
        'iulie',
        'august',
        'septembrie',
        'octombrie',
        'noiembrie',
        'decembrie'
      ],
      'cs': [
        '',
        'ledna',
        'února',
        'března',
        'dubna',
        'května',
        'června',
        'července',
        'srpna',
        'září',
        'října',
        'listopadu',
        'prosince'
      ],
      'sv': [
        '',
        'januari',
        'februari',
        'mars',
        'april',
        'maj',
        'juni',
        'juli',
        'augusti',
        'september',
        'oktober',
        'november',
        'december'
      ],
      'hu': [
        '',
        'január',
        'február',
        'március',
        'április',
        'május',
        'június',
        'július',
        'augusztus',
        'szeptember',
        'október',
        'november',
        'december'
      ],
    };
    final _monthList = _months[_dateLang] ?? _months['en']!;
    s = s.replaceAllMapped(
      RegExp(r'\b(\d{1,2})[./](\d{1,2})[./](\d{4})\b'),
      (m) {
        final day = int.tryParse(m.group(1)!);
        final month = int.tryParse(m.group(2)!);
        final year = int.tryParse(m.group(3)!);
        if (day == null || month == null || year == null) return m.group(0)!;
        if (month < 1 || month > 12 || day < 1 || day > 31) return m.group(0)!;
        // AR, HE, HI, JA, KO, ZH → sayısal formatı koru, TTS zaten okur
        if (['ar', 'he', 'hi', 'ja', 'ko', 'zh'].contains(_dateLang))
          return m.group(0)!;
        final mn = _monthList[month];
        if (_dateLang == 'tr') return '$day $mn $year';
        if (_dateLang == 'ru' || _dateLang == 'bg')
          return '$day $mn $year года';
        if (_dateLang == 'el') return '$day $mn $year';
        if (_dateLang == 'en') return '$mn $day, $year';
        return '$day. $mn $year'; // DE, FR, IT, ES, PT, NL, PL, RO, CS, SV, HU
      },
    );
    // ─────────────────────────────────────────────────────────────────────────

    // ── ADIM 2: Türkçe için Roman rakamlarını dönüştür ───────────────────────
    // Bu adım TÜM diğer işlemlerden ÖNCE yapılmalı — başka hiçbir işlem
    // Roman rakamlarına dokunmamalı.
    if (isTr) {
      // 2a-pre) Yaygın kısaltmaları fonetik yaz — Roman rakamı algılanmasın
      s = s.replaceAll(RegExp(r'(?<![A-Za-z])ID(?![A-Za-z])'), 'ay di');
      s = s.replaceAll(RegExp(r'(?<![A-Za-z])CD(?![A-Za-z])'), 'si di');
      s = s.replaceAll(RegExp(r'(?<![A-Za-z])DVD(?![A-Za-z])'), 'di vi di');
      s = s.replaceAll(RegExp(r'(?<![A-Za-z])VIP(?![A-Za-z])'), 'vi ay pi');
      s = s.replaceAll(RegExp(r'(?<![A-Za-z])LCD(?![A-Za-z])'), 'el si di');
      s = s.replaceAll(RegExp(r'(?<![A-Za-z])LED(?![A-Za-z])'), 'el i di');
      s = s.replaceAll(RegExp(r'(?<![A-Za-z])CPU(?![A-Za-z])'), 'si pi yu');
      s = s.replaceAll(RegExp(r'(?<![A-Za-z])GPU(?![A-Za-z])'), 'ci pi yu');
      s = s.replaceAll(RegExp(r'(?<![A-Za-z])DNA(?![A-Za-z])'), 'di en ay');
      s = s.replaceAll(RegExp(r'(?<![A-Za-z])PIN(?![A-Za-z])'), 'pi ay en');

      // 2a) Büyük harfli kelimeleri küçültelim ama ÖNCE Roman rakamlarını koru
      //     Örn: "KİMDİK" içindeki M,D,I harfleri Roman sanılmasın
      //     Sadece Roman rakamı olmayan büyük kelimeleri küçült
      s = s.replaceAllMapped(
        RegExp(r'[A-ZÇĞİÖŞÜ]{2,}'),
        (m) {
          final word = m.group(0)!;
          // Eğer bu kelime geçerli bir Roman rakamıysa küçültme
          final val = _romanToInt(word);
          if (val != null) return word; // Roman rakamı, dokunma
          return _turkishToLowercase(word);
        },
      );

      // 2b) Roman rakamı + yüzyıl → yirminci yüzyıl (noktalı veya noktasız)
      s = s.replaceAllMapped(
        RegExp(
          r'(?<![A-Za-zÀ-ÿğüşıöçĞÜŞİÖÇ])([IVXLCDM]+)\.?\s*(yüzyıl\w*)',
        ),
        (m) {
          final roman = m.group(1)!.toUpperCase();
          final suffix = m.group(2)!;
          final n = _romanToInt(roman);
          if (n == null || n < 1) return m.group(0)!;
          return '${_trOrdinalWords(n)} $suffix';
        },
      );

      // 2c) Roman rakamı + nokta (IV. bölüm, XIX. yüzyıl hariç yukarıda yakalandı)
      // M.Ö. ve M.S. hariç tut
      s = s.replaceAllMapped(
        RegExp(r'(?<![A-Za-zÀ-ÿğüşıöçĞÜŞİÖÇ])([IVXLCDM]+)\.(?!\d)(?![ÖS]\.?)'),
        (m) {
          final roman = m.group(1)!.toUpperCase();
          final n = _romanToInt(roman);
          if (n == null || n < 1) return m.group(0)!;
          return _trOrdinalWords(n);
        },
      );

      // 2d) Tek başına Roman rakamı (nokta olmadan, kelime sınırında)
      //     Dikkat: tek harf (I, V, X) sadece noktalıysa al — yoksa normal harf
      s = s.replaceAllMapped(
        RegExp(
            r'(?<![A-Za-zÀ-ÿğüşıöçĞÜŞİÖÇ])([IVXLCDM]{2,})(?![A-Za-zÀ-ÿğüşıöçĞÜŞİÖÇ\.])'),
        (m) {
          final roman = m.group(1)!.toUpperCase();
          final n = _romanToInt(roman);
          if (n == null || n < 1) return m.group(0)!;
          return _trOrdinalWords(n);
        },
      );

      // 2e) I. ve ı. → birinci (tek harf, noktalı)
      s = s.replaceAllMapped(
        RegExp(r'(?<!\w)[Iı]\.(?=\s|$)'),
        (_) => 'birinci',
      );
      s = s.replaceAll(' I ', ' birinci ');
      s = s.replaceAll('\nI ', '\nbirinci ');
      if (s.startsWith('I ') || s.startsWith('I.'))
        s = 'birinci ${s.substring(2)}';
      if (s == 'I' || s == 'ı') s = 'birinci';

      // 2f) Sayı + yy → on dokuzuncu yüzyıl
      s = s.replaceAllMapped(
        RegExp(r'\b(\d{1,4})\s*\.?\s*yy\b', caseSensitive: false),
        (m) {
          final n = int.tryParse(m.group(1)!);
          if (n == null) return m.group(0)!;
          return '${_trOrdinalWords(n)} yüzyıl';
        },
      );

      // 2g-1) 9+ haneli büyük sayılar → rakam rakam oku (telefon, barkod, kimlik no vb.)
      //       Örnek: 342200034442 → "üç dört iki iki sıfır sıfır sıfır üç dört dört iki"
      s = s.replaceAllMapped(
        RegExp(r'(?<![\.\d])(\d{9,})(?![\d])'),
        (m) {
          final digits = m.group(1)!;
          const trDigits = [
            'sıfır',
            'bir',
            'iki',
            'üç',
            'dört',
            'beş',
            'altı',
            'yedi',
            'sekiz',
            'dokuz'
          ];
          return digits.split('').map((d) {
            final idx = int.tryParse(d);
            return (idx != null && idx >= 0 && idx <= 9) ? trDigits[idx] : d;
          }).join(' ');
        },
      );

      // 2g0) Binlik ayraçlı sayılar → kardinal kelime (50.000 → elli bin, 1.500.000 → bir milyon beş yüz bin)
      //      MUTLAKA 2g'den önce gelmeli; yoksa 50.000 → "ellinci sıfır sıfır sıfır" olur.
      s = s.replaceAllMapped(
        RegExp(r'(?<!\d)(\d{1,3}(?:\.\d{3})+)(?!\d)'),
        (m) {
          final raw = m.group(1)!.replaceAll('.', '');
          final n = int.tryParse(raw);
          if (n == null) return m.group(0)!;
          return _toTurkishCardinalWord(n);
        },
      );

      // 2g) Sayı + nokta → sıra sayısı (19. → on dokuzuncu)
      s = s.replaceAllMapped(
        RegExp(r'(?<!\d)(\d+)\.(?!\d)'),
        (m) {
          final n = int.tryParse(m.group(1)!);
          if (n == null) return m.group(0)!;
          return _trOrdinalWords(n);
        },
      );

      // 2h) yy → yüzyıl (güvenlik)
      s = s.replaceAll(RegExp(r'\byy\b', caseSensitive: false), 'yüzyıl');
    }

    // ── Dile göre kısaltma genişletme (tr hariç, o _normalizeTurkishForTts'de) ──
