    // İngilizce contractions genişletme (düz ' ve eğik ' apostrof her ikisi)
    if (!isTr) {
      s = s
          .replaceAll(
              RegExp(r"\bI['\u2019]d\b", caseSensitive: false), 'I would')
          .replaceAll(RegExp(r"\bI['\u2019]m\b", caseSensitive: false), 'I am')
          .replaceAll(
              RegExp(r"\bI['\u2019]ve\b", caseSensitive: false), 'I have')
          .replaceAll(
              RegExp(r"\bI['\u2019]ll\b", caseSensitive: false), 'I will')
          .replaceAll(
              RegExp(r"\bhe['\u2019]d\b", caseSensitive: false), 'he would')
          .replaceAll(
              RegExp(r"\bshe['\u2019]d\b", caseSensitive: false), 'she would')
          .replaceAll(
              RegExp(r"\bthey['\u2019]d\b", caseSensitive: false), 'they would')
          .replaceAll(
              RegExp(r"\bwe['\u2019]d\b", caseSensitive: false), 'we would')
          .replaceAll(
              RegExp(r"\byou['\u2019]d\b", caseSensitive: false), 'you would')
          .replaceAll(
              RegExp(r"\bwon['\u2019]t\b", caseSensitive: false), 'will not')
          .replaceAll(
              RegExp(r"\bcan['\u2019]t\b", caseSensitive: false), 'cannot')
          .replaceAll(
              RegExp(r"\bdon['\u2019]t\b", caseSensitive: false), 'do not')
          .replaceAll(
              RegExp(r"\bdoesn['\u2019]t\b", caseSensitive: false), 'does not')
          .replaceAll(
              RegExp(r"\bdidn['\u2019]t\b", caseSensitive: false), 'did not')
          .replaceAll(
              RegExp(r"\bisn['\u2019]t\b", caseSensitive: false), 'is not')
          .replaceAll(
              RegExp(r"\baren['\u2019]t\b", caseSensitive: false), 'are not')
          .replaceAll(
              RegExp(r"\bwasn['\u2019]t\b", caseSensitive: false), 'was not')
          .replaceAll(
              RegExp(r"\bweren['\u2019]t\b", caseSensitive: false), 'were not')
          .replaceAll(
              RegExp(r"\bhadn['\u2019]t\b", caseSensitive: false), 'had not')
          .replaceAll(
              RegExp(r"\bhasn['\u2019]t\b", caseSensitive: false), 'has not')
          .replaceAll(
              RegExp(r"\bhaven['\u2019]t\b", caseSensitive: false), 'have not')
          .replaceAll(RegExp(r"\bwouldn['\u2019]t\b", caseSensitive: false),
              'would not')
          .replaceAll(RegExp(r"\bcouldn['\u2019]t\b", caseSensitive: false),
              'could not')
          .replaceAll(RegExp(r"\bshouldn['\u2019]t\b", caseSensitive: false),
              'should not')
          .replaceAll(
              RegExp(r"\bit['\u2019]s\b", caseSensitive: false), 'it is')
          .replaceAll(
              RegExp(r"\bthat['\u2019]s\b", caseSensitive: false), 'that is')
          .replaceAll(
              RegExp(r"\bhe['\u2019]s\b", caseSensitive: false), 'he is')
          .replaceAll(
              RegExp(r"\bshe['\u2019]s\b", caseSensitive: false), 'she is')
          .replaceAll(
              RegExp(r"\blet['\u2019]s\b", caseSensitive: false), 'let us');
    }

    // ── Türkçe kısaltmalar — abbrevMap'ten önce uygula ──────────────────────
    if (isTr) {
      s = s.replaceAll(
          RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])M\.Ö\.'), 'milattan önce');
      s = s.replaceAll(
          RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])M\.S\.'), 'milattan sonra');
      s = s.replaceAll(
          RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])Hz\.(?!\d)'), 'Hazreti');
    }

    if (_abbrevMap.isNotEmpty) {
      // URL'leri abbrev uygulamadan önce koru
      final urlPattern = RegExp(
        r'(?:https?://|www\.)[^\s]+|[a-zA-Z0-9-]+\.[a-zA-Z]{2,}(?:/[^\s]*)?',
        caseSensitive: false,
      );
      final urlPlaceholders = <String, String>{};
      int urlIdx = 0;
      s = s.replaceAllMapped(urlPattern, (m) {
        final key = '§URL${urlIdx++}§';
        urlPlaceholders[key] = m.group(0)!;
        return key;
      });
      // Abbrev uygula
      for (final entry in _abbrevMap.entries) {
        s = s.replaceAll(RegExp(entry.key), entry.value);
      }
      // URL'leri geri yükle
      urlPlaceholders.forEach((key, value) {
        s = s.replaceAll(key, value);
      });
    }
    // ─────────────────────────────────────────────────────────────────────────

    // Boşlukla ayrılmış sayı grupları — her sayı ayrı okunmalı: 123 545 900 → yüzyirmiüç... beşyüzkırkbeş... dokuz yüz
    // TTS motoru boşluklu sayıları birleştirmesin diye her grubu kelimeye çevir
    if (isTr) {
      s = s.replaceAllMapped(
        RegExp(r'(?<!\d)(\d{2,3})((?:\s+\d{2,3}){2,})(?!\d)'),
        (m) {
          final parts = m.group(0)!.trim().split(RegExp(r'\s+'));
          final words = parts.map((p) {
            final n = int.tryParse(p);
            if (n == null) return p;
            return _toTurkishCardinalWord(n);
          });
          return words.join(' ');
        },
      );
    }

    // ── ADIM 3: Sembol temizleme ──────────────────────────────────────────────
    // Türkçe fonetik düzeltme (cop→çop, cart→çart vb.) sanitize'dan önce
    if (isTr) s = _fixTurkishPhoneticWords(s);
    s = _sanitizeSymbolsForTts(s, isTr);

    final String raw = s;
    final String langCode = _selectedLocale ?? 'en-US';
    final String spokenTtsText = _normalizeUrlLikeTextForTts(raw, langCode);

    return await _tts.speak(spokenTtsText);
  }

  // ======================= SEMBOL TEMİZLEME (TTS öncesi) ==========================
  /// TTS'e gönderilecek metinden sembolleri temizler ve büyük harfli kelimeleri
  /// küçük harfe çevirerek Roma rakamı yanlış okumasını engeller.
  String _fixTurkishPhoneticWords(String text) {
    // Önce uzatılmış ünlem seslerini normalize et (öfff→of, üfff→uf vb.)
    // Tam kelime eşleşmesi — cop/cord gibi kelimeleri bozmaz
    String s = text;
    final elongMap = [
      RegExp(r'(?<![a-zA-ZçğışöüÇĞİŞÖÜ])öf+(?![a-zA-ZçğışöüÇĞİŞÖÜ])',
          caseSensitive: false),
      RegExp(r'(?<![a-zA-ZçğışöüÇĞİŞÖÜ])üf+(?![a-zA-ZçğışöüÇĞİŞÖÜ])',
          caseSensitive: false),
      RegExp(r'(?<![a-zA-ZçğışöüÇĞİŞÖÜ])ah+(?![a-zA-ZçğışöüÇĞİŞÖÜ])',
          caseSensitive: false),
      RegExp(r'(?<![a-zA-ZçğışöüÇĞİŞÖÜ])oh+(?![a-zA-ZçğışöüÇĞİŞÖÜ])',
          caseSensitive: false),
      RegExp(r'(?<![a-zA-ZçğışöüÇĞİŞÖÜ])ih+(?![a-zA-ZçğışöüÇĞİŞÖÜ])',
          caseSensitive: false),
      RegExp(r'(?<![a-zA-ZçğışöüÇĞİŞÖÜ])uh+(?![a-zA-ZçğışöüÇĞİŞÖÜ])',
          caseSensitive: false),
    ];
    final elongReplace = ['of', 'uf', 'ah', 'oh', 'ih', 'uh'];
    for (int i = 0; i < elongMap.length; i++) {
      s = s.replaceAll(elongMap[i], elongReplace[i]);
    }
    text = s;
    const Map<String, String> phoneticMap = {
      'cop': 'çop',
      'cart': 'çart',
      'curt': 'çurt',
      'cup': 'çup',
      'can': 'çan',
      'car': 'çar',
      'cat': 'çat',
      'cut': 'çut',
      'curl': 'çurl',
      'cord': 'çord',
      'core': 'çore',
      'corn': 'çorn',
      'cost': 'çost',
    };
    String result = text;
    for (final entry in phoneticMap.entries) {
      final word = entry.key;
      final phonetic = entry.value;
      result = result.replaceAllMapped(
        RegExp(
            '(?<![a-zA-ZçğışöüÇĞİŞÖÜ])(${RegExp.escape(word)})(?![a-zA-ZçğışöüÇĞİŞÖÜ])',
            caseSensitive: false),
        (m) {
          final original = m.group(1)!;
          if (original[0] == original[0].toUpperCase() &&
              original[0] != original[0].toLowerCase()) {
            return phonetic[0].toUpperCase() + phonetic.substring(1);
          }
          if (original == original.toUpperCase()) {
            return phonetic.toUpperCase();
          }
          return phonetic;
        },
      );
    }
    return result;
  }

  String _sanitizeSymbolsForTts(String text, bool isTr) {
    String s = text;

    // TTS diline göre nokta, at ve www okunuşu
    final locale = (_selectedLocale ?? 'tr-TR').toLowerCase();
    final lang = locale.split('-')[0];
    const atMap = {
      'tr': 'et',
      'en': 'at',
      'de': 'ät',
      'it': 'chiocciola',
      'fr': 'arobase',
      'es': 'arroba',
      'pt': 'arroba',
      'nl': 'apenstaartje',
      'ru': 'эт',
      'el': 'παπάκι',
      'hi': 'एट',
      'ja': 'アット',
      'ko': '앳',
      'zh': '艾特',
      'bg': 'ат',
    };
    final at = atMap[lang] ?? 'at';
    final dot = _ttsDotWordForLocale(locale);

    // Email: beytan@yahoo.com → beytan [at] yahoo [dot] com
    s = s.replaceAllMapped(
      RegExp(r'[\w.+-]+@[\w.-]+\.[a-zA-Z]{2,}'),
      (m) {
        final parts = m.group(0)!.split('@');
        final user = parts[0].replaceAll('.', ' $dot ');
        final domain = parts[1].replaceAll('.', ' $dot ');
        return '$user $at $domain';
      },
    );

    // https:// ve http:// kaldır
    s = s.replaceAll(RegExp(r'https?://', caseSensitive: false), '');

    // 1. Sembolleri temizle / değiştir
    if (isTr) {
      s = s.replaceAll('&', ' ve ');
      s = s.replaceAll('%', ' yüzde ');
      s = s.replaceAll('+', ' artı ');
      s = s.replaceAll('=', ' eşittir ');
      // Türkçe kısaltmalar
      s = s.replaceAll(
          RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])M\.Ö\.'), 'milattan önce');
      s = s.replaceAll(
          RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])M\.S\.'), 'milattan sonra');
      s = s.replaceAll(
          RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])Hz\.(?!\d)'), 'Hazreti');
      s = s.replaceAll(RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])Prof\.'), 'Profesör');
      s = s.replaceAll(RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])Doç\.'), 'Doçent');
      s = s.replaceAll(RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])Dr\.'), 'Doktor');
      s = s.replaceAll(RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])Yrd\.'), 'Yardımcı');
      s = s.replaceAll(RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])Op\.'), 'Operatör');
      s = s.replaceAll(RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])Av\.'), 'Avukat');
      s = s.replaceAll(RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])Müh\.'), 'Mühendis');
      s = s.replaceAll(RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])vb\.'), 've benzeri');
      s = s.replaceAll(RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])vs\.'), 've saire');
      s = s.replaceAll(
          RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])vd\.'), 've diğerleri');
      s = s.replaceAll(RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])yy\.'), 'yüzyıl');
      s = s.replaceAll(RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])sy\.'), 'sayfa');
      s = s.replaceAll(RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])No\.'), 'numara');
      s = s.replaceAll(RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])Sok\.'), 'sokak');
      s = s.replaceAll(RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])Cad\.'), 'cadde');
      s = s.replaceAll(RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])Bul\.'), 'bulvar');
      s = s.replaceAll(RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])Apt\.'), 'apartman');
      s = s.replaceAll(RegExp(r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])Kat\.'), 'kat');
    } else {
      s = s.replaceAll('&', ' and ');
      s = s.replaceAll('%', ' percent ');
      s = s.replaceAll('+', ' plus ');
      s = s.replaceAll('=', ' equals ');
    }

    // Sessizce sil — TTS'in isim okuyacağı semboller
    s = s.replaceAll(RegExp(r'!+'), ''); // ! !! !!! → sil (TTS "ünlem" okur)
    s = s.replaceAll(RegExp(r'\?{2,}'), ''); // ?? ??? → sil, tek ? kalır
    s = s.replaceAll('*', '');
    s = s.replaceAll('#', '');
    s = s.replaceAll('@', ' $at '); // @ → dile göre "at/et/arroba" vb.
    s = s.replaceAll('<', '');
    s = s.replaceAll('>', '');
    s = s.replaceAll('|', '');
    s = s.replaceAll('~', '');
    s = s.replaceAll('^', '');
    s = s.replaceAll('`', '');
    s = s.replaceAll('\\', '');
    s = s.replaceAll('{', '');
    s = s.replaceAll('}', '');
    s = s.replaceAll('[', '');
    s = s.replaceAll(']', '');
    s = s.replaceAll('_', ' ');
    // Emoji ve semboller — TTS isimlerini okuyabilir, sil
    s = s.replaceAll(RegExp(r'[\u2600-\u27BF\u2B00-\u2BFF]'), '');
    // Geometric Shapes (●■▲▼◆ vb.) — TTS "içi dolu çember" vb. okur, sil
    s = s.replaceAll(RegExp(r'[\u25A0-\u25FF]'), '');
    // Emoji (surrogate pairs)
    s = s.replaceAll(RegExp(r'[\uD800-\uDFFF]'), '');
    // Ok sembolleri özellikle
    s = s.replaceAll('\u2192', ''); // →
    s = s.replaceAll('\u2190', ''); // ←
    s = s.replaceAll('\u2191', ''); // ↑
    s = s.replaceAll('\u2193', ''); // ↓
    s = s.replaceAll('\u21D2', ''); // ⇒
    s = s.replaceAll('\u21D0', ''); // ⇐
    s = s.replaceAll('\u27A1', ''); // ➡
    s = s.replaceAll('\u2B05', ''); // ⬅
    s = s.replaceAll('\u00BB', ''); // »
    s = s.replaceAll('\u00AB', ''); // «
    s = s.replaceAll('\u203A', ''); // ›
    s = s.replaceAll('\u2039', ''); // ‹

    // Tırnak işaretleri — TTS "tırnak işareti" diye okuyabilir, sil
    s = s.replaceAll('"', ''); // düz tırnak
    s = s.replaceAll('“', ''); // " sol çift tırnak
    s = s.replaceAll('”', ''); // " sağ çift tırnak

    // Türkçe kesme işareti (apostrof): KELIME'ek → "KELIME ek" (boşluk ekle)
    // Örn: AKP'ye → AKP ye, Türkiye'nin → Türkiye nin
    s = s.replaceAllMapped(
      RegExp(
        r"([a-zA-Z\u00C0-\u024F\u011E\u011F\u0130\u0131\u015E\u015F\u00C7\u00E7\u00D6\u00F6\u00DC\u00FC])['’‘]([a-zA-Z\u00C0-\u024F\u011E\u011F\u0130\u0131\u015E\u015F\u00C7\u00E7\u00D6\u00F6\u00DC\u00FC])",
      ),
      (m) => '${m.group(1)} ${m.group(2)}',
    );

    s = s.replaceAll('‘', ''); // ‘ sol tek tırnak (kalan)
    s = s.replaceAll('’', ''); // ’ sağ tek tırnak (kalan)
    s = s.replaceAll("'", ''); // düz apostrof (kalan)
    s = s.replaceAll('«', ''); // « guillemet
    s = s.replaceAll('»', ''); // » guillemet
    s = s.replaceAll('‹', ''); // ‹ tek guillemet
    s = s.replaceAll('›', ''); // › tek guillemet

    // 2. Büyük harfli Türkçe kelimeler → küçük harf
    // (Roma rakamı tuzağını önler: "KİMDİK" içindeki M,D,I harflerini engeller)
    // NOT: \b word boundary Türkçe karakterlerle çalışmaz, bu yüzden
    // boşluk/satır başı/sonu ile sınırlı pattern kullanıyoruz.
    if (isTr) {
      s = s.replaceAllMapped(
        RegExp(
            r'(?<![a-zA-ZğüşıöçĞÜŞİÖÇ])([A-ZÇĞİÖŞÜ][A-ZÇĞİÖŞÜ]+)(?![a-zA-ZğüşıöçĞÜŞİÖÇ])'),
        (match) => _turkishToLowercase(match.group(0)!),
      );
    }

    // Fazla boşlukları temizle
    s = s.replaceAll(RegExp(r'  +'), ' ').trim();
    return s;
  }

  String _ttsDotWordForLocale(String locale) {
    final lang = locale.toLowerCase().split('-')[0];
    const dotMap = {
      'tr': 'nokta',
      'en': 'dot',
      'it': 'punto',
      'fr': 'point',
      'es': 'punto',
      'de': 'punkt',
      'nl': 'punt',
      'pt': 'ponto',
      'el': 'τελεία',
      'bg': 'точка',
      'ro': 'punct',
      'ru': 'точка',
      'pl': 'kropka',
      'hi': 'डॉट',
      'ja': 'ドット',
      'ko': '닷',
      'zh': '点',
    };
    return dotMap[lang] ?? 'dot';
  }

  String _ttsWwwWordForLocale(String locale) {
    final lang = locale.toLowerCase().split('-')[0];
    const wwwMap = {
      'tr': 'W W W',
      'en': 'double u double u double u',
      'it': 'vu vu vu',
      'fr': 'double vé double vé double vé',
      'es': 'uve doble uve doble uve doble',
      'de': 'we we we',
      'nl': 'wee wee wee',
      'pt': 'dáblio dáblio dáblio',
      'el': 'βι βι βι',
      'bg': 'двойно ве двойно ве двойно ве',
      'ro': 'dublu v dublu v dublu v',
      'ru': 'дабл ю дабл ю дабл ю',
      'pl': 'wu wu wu',
      'hi': 'डब्लू डब्लू डब्लू',
      'ja': 'ダブリュー ダブリュー ダブリュー',
      'ko': '더블유 더블유 더블유',
      'zh': '万维网',
    };
    return wwwMap[lang] ?? 'double u double u double u';
  }

  /// Normalizes URL/domain-like segments for speech only (TTS input).
  String _normalizeUrlsForTts(String text, String locale) {
    final lang = locale.toLowerCase().split('-')[0];
    final dotWord = _ttsDotWordForLocale(locale);
    final wwwWord = _ttsWwwWordForLocale(locale);

    return text.replaceAllMapped(
      RegExp(
        r'\b(?:www\.)?(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}\b',
        caseSensitive: false,
      ),
      (m) {
        final raw = m.group(0)!;
        final labels = raw.split('.');
        if (labels.length < 2) return raw;

        final spoken = <String>[];
        for (var i = 0; i < labels.length; i++) {
          final part = labels[i];
          if (i == 0 && part.toLowerCase() == 'www') {
            spoken.add(wwwWord);
          } else {
            if (lang == 'tr' && part.toLowerCase() == 'com') {
              spoken.add('kom');
            } else {
              spoken.add(part);
            }
          }
          if (i < labels.length - 1) {
            spoken.add(dotWord);
          }
        }
        return spoken.join(' ');
      },
    );
  }

  String _ttsDotWord(String lang) {
    final l = lang.toLowerCase();
    if (l.startsWith('tr')) return 'nokta';
    if (l.startsWith('it')) return 'punto';
    if (l.startsWith('fr')) return 'point';
    if (l.startsWith('es')) return 'punto';
    if (l.startsWith('de')) return 'punkt';
    if (l.startsWith('nl')) return 'punt';
    if (l.startsWith('pt')) return 'ponto';
    if (l.startsWith('el')) return 'τελεία';
    if (l.startsWith('bg')) return 'точка';
    if (l.startsWith('ro')) return 'punct';
    if (l.startsWith('ru')) return 'точка';
    if (l.startsWith('pl')) return 'kropka';
    return 'dot';
  }

  String _ttsWwwWord(String lang) {
    final l = lang.toLowerCase();
    if (l.startsWith('tr')) return 'W W W';
    if (l.startsWith('it')) return 'vu vu vu';
    if (l.startsWith('fr')) return 'double vé double vé double vé';
    if (l.startsWith('es')) return 'uve doble uve doble uve doble';
    if (l.startsWith('de')) return 'we we we';
    if (l.startsWith('nl')) return 'wee wee wee';
    if (l.startsWith('pt')) return 'dáblio dáblio dáblio';
    if (l.startsWith('el')) return 'γου γου γου';
    if (l.startsWith('bg')) return 'двойно ве двойно ве двойно ве';
    if (l.startsWith('ro')) return 'dublu ve dublu ve dublu ve';
    if (l.startsWith('ru')) return 'дабл-ю дабл-ю дабл-ю';
    if (l.startsWith('pl')) return 'wu wu wu';
    return 'double u double u double u';
  }

  String _speakDomainPart(String part, String lang) {
    final l = lang.toLowerCase();
    final p = part.toLowerCase();

    if (l.startsWith('tr')) {
      if (p == 'com') return 'kom';
      if (p == 'tr') return 'te re';
      if (p == 'it') return 'i te';
      if (p == 'de') return 'de e';
      if (p == 'fr') return 'ef er';
      if (p == 'uk') return 'yu key';
      if (p == 'ru') return 'er u';
      if (p == 'jp') return 'ji pi';
      if (p == 'cn') return 'si en';
    }

    if (l.startsWith('en')) {
      if (p == 'tr') return 'ti r';
      if (p == 'it') return 'I T';
      if (p == 'de') return 'D E';
      if (p == 'fr') return 'F R';
      if (p == 'uk') return 'U K';
      if (p == 'ru') return 'R U';
      if (p == 'jp') return 'J P';
      if (p == 'cn') return 'C N';
    }

    return part;
  }

  String _urlToSpokenPhrase(String rawUrl, String lang) {
    String s = rawUrl.trim();
    s = s.replaceFirst(RegExp(r'^https?:\/\/', caseSensitive: false), '');

    bool hadWww = false;
    if (s.toLowerCase().startsWith('www.')) {
      hadWww = true;
      s = s.substring(4);
    }

    final parts =
        s.split('.').map((e) => e.trim()).where((e) => e.isNotEmpty).toList();
    if (parts.isEmpty) return rawUrl;

    final tokens = <String>[];
    final separatorWord = _ttsDotWord(lang);

    if (hadWww) {
      tokens.add(_ttsWwwWord(lang));
      if (parts.isNotEmpty) {
        tokens.add(separatorWord);
      }
    }

    for (int i = 0; i < parts.length; i++) {
      tokens.add(_speakDomainPart(parts[i].trim(), lang));
      if (i < parts.length - 1) {
        tokens.add(separatorWord);
      }
    }

    return tokens.join(' ').replaceAll(RegExp(r'\s+'), ' ').trim();
  }

  String _normalizeUrlLikeTextForTts(String text, String lang) {
    final urlRegex = RegExp(
      r'((https?:\/\/)?(www\.)?[A-Za-z0-9-]+(\.[A-Za-z0-9-]+)+)',
      caseSensitive: false,
    );

    return text.replaceAllMapped(urlRegex, (m) {
      return _urlToSpokenPhrase(m.group(0)!, lang);
    });
  }

  /// Türkçe büyük harfleri küçük harfe doğru çevirir
  String _turkishToLowercase(String s) {
    return s
        .replaceAll('İ', 'i')
        .replaceAll('I', 'ı')
        .replaceAll('Ğ', 'ğ')
        .replaceAll('Ü', 'ü')
        .replaceAll('Ş', 'ş')
        .replaceAll('Ö', 'ö')
        .replaceAll('Ç', 'ç')
        .toLowerCase();
  }
  // =============================================================================

  // Turkish ordinal suffix helper
  String _trOrdinalSuffix(int n) {
    n = n.abs();

    // 100, 200, 300... = "yüzüncü" mantığı
    if (n != 0 && n % 100 == 0) return "üncü";

    final lastTwo = n % 100;
    if (lastTwo == 10) return "uncu"; // onuncu

    final last = n % 10;
    switch (last) {
      case 1:
        return "inci"; // birinci
      case 2:
        return "inci"; // ikinci
      case 3:
        return "üncü"; // üçüncü
      case 4:
        return "üncü"; // dördüncü
      case 5:
        return "inci"; // beşinci
      case 6:
        return "ıncı"; // altıncı
      case 7:
        return "inci"; // yedinci
      case 8:
        return "inci"; // sekizinci
      case 9:
        return "uncu"; // dokuzuncu
      case 0:
        // 20/30/40... gibi onlar
        switch (n % 100) {
          case 20:
            return "inci"; // yirminci
          case 30:
            return "uncu"; // otuzuncu
          case 40:
            return "ıncı"; // kırkıncı
          case 50:
            return "inci"; // ellinci
          case 60:
            return "ıncı"; // altmışıncı
          case 70:
            return "inci"; // yetmişinci
          case 80:
            return "inci"; // sekseninci
          case 90:
            return "ıncı"; // doksanıncı
          default:
            return "ıncı";
        }
    }
    return "inci";
  }

  String _trOrdinalSuffixAscii(int n) {
    n = n.abs();

    // 100, 200, 300... -> "uncu" yeterli (TTS doğruya yakın okur, en önemlisi pause olmaz)
    if (n != 0 && n % 100 == 0) return "uncu";

    final lastTwo = n % 100;
    if (lastTwo == 10) return "uncu";

    final last = n % 10;
    switch (last) {
      case 1:
        return "inci";
      case 2:
        return "inci";
      case 3:
        return "uncu";
      case 4:
        return "uncu";
      case 5:
        return "inci";
      case 6:
        return "inci";
      case 7:
        return "inci";
      case 8:
        return "inci";
      case 9:
        return "uncu";
      case 0:
        switch (n % 100) {
          case 20:
            return "inci";
          case 30:
            return "uncu";
          case 40:
            return "inci";
          case 50:
            return "inci";
          case 60:
            return "inci";
          case 70:
            return "inci";
          case 80:
            return "inci";
          case 90:
            return "inci";
          default:
            return "inci";
        }
    }
    return "inci";
  }

  String _trNumberToWords(int n) {
    if (n == 0) return 'sıfır';
    if (n < 0) return 'eksi ${_trNumberToWords(-n)}';

    const ones = {
      0: '',
      1: 'bir',
      2: 'iki',
      3: 'üç',
      4: 'dört',
      5: 'beş',
      6: 'altı',
      7: 'yedi',
      8: 'sekiz',
      9: 'dokuz',
    };
    const tens = {
      0: '',
      1: 'on',
      2: 'yirmi',
      3: 'otuz',
      4: 'kırk',
      5: 'elli',
      6: 'altmış',
      7: 'yetmiş',
      8: 'seksen',
      9: 'doksan',
    };

    final parts = <String>[];

    int x = n;

    if (x >= 1000) {
      final k = x ~/ 1000;
      if (k == 1) {
        parts.add('bin');
      } else {
        parts.add('${_trNumberToWords(k)} bin');
      }
      x = x % 1000;
    }

    if (x >= 100) {
      final h = x ~/ 100;
      if (h == 1) {
        parts.add('yüz');
      } else {
        parts.add('${ones[h]} yüz');
      }
      x = x % 100;
    }

    if (x >= 10) {
      final t = x ~/ 10;
      parts.add(tens[t] ?? '');
      x = x % 10;
    }

    if (x > 0) {
      parts.add(ones[x] ?? '');
    }

    return parts
        .where((e) => e.trim().isNotEmpty)
        .join(' ')
        .replaceAll(RegExp(r'\s+'), ' ')
        .trim();
  }

  String _trOrdinalWords(int n) {
    // En önemli özel durumlar (TTS için garanti)
    const direct = <int, String>{
      0: 'sıfırıncı',
      1: 'birinci',
      2: 'ikinci',
      3: 'üçüncü',
      4: 'dördüncü',
      5: 'beşinci',
      6: 'altıncı',
      7: 'yedinci',
      8: 'sekizinci',
      9: 'dokuzuncu',
      10: 'onuncu',
      20: 'yirminci',
      30: 'otuzuncu',
      40: 'kırkıncı',
      50: 'ellinci',
      60: 'altmışıncı',
      70: 'yetmişinci',
      80: 'sekseninci',
      90: 'doksanıncı',
      100: 'yüzüncü',
      1000: 'bininci',
    };
    if (direct.containsKey(n)) return direct[n]!;

    // Genel: kardinal sözleri üret, son kelimeyi ordinale çevir
    final cardinal = _trNumberToWords(n);
    final words = cardinal.split(' ');
    if (words.isEmpty) return cardinal;

    // Son kelimeyi "-ıncı/-inci/-uncu/-üncü" ile ordinale çevir
    String last = words.removeLast();

    // Eğer son kelime "yüz" ya da "bin" ise özel
    if (last == 'yüz') {
      last = 'yüzüncü';
      words.add(last);
      return words.join(' ');
    }
    if (last == 'bin') {
      last = 'bininci';
      words.add(last);
      return words.join(' ');
    }

    // Son kelime özel tabanlardan biriyse doğrudan çevir
    const baseWordOrdinal = <String, String>{
      'bir': 'birinci',
      'iki': 'ikinci',
      'üç': 'üçüncü',
      'dört': 'dördüncü',
      'beş': 'beşinci',
      'altı': 'altıncı',
      'yedi': 'yedinci',
      'sekiz': 'sekizinci',
      'dokuz': 'dokuzuncu',
      'on': 'onuncu',
      'yirmi': 'yirminci',
      'otuz': 'otuzuncu',
      'kırk': 'kırkıncı',
      'elli': 'ellinci',
      'altmış': 'altmışıncı',
      'yetmiş': 'yetmişinci',
      'seksen': 'sekseninci',
      'doksan': 'doksanıncı',
    };
    if (baseWordOrdinal.containsKey(last)) {
      words.add(baseWordOrdinal[last]!);
      return words.join(' ');
    }

    // Vowel harmony ile suffix seç (en son ünlüye bak)
    const vowels = 'aeıioöuü';
    String lastVowel = '';
    for (int i = last.length - 1; i >= 0; i--) {
      final ch = last[i];
      if (vowels.contains(ch)) {
        lastVowel = ch;
        break;
      }
    }

    String suffix;
    switch (lastVowel) {
      case 'a':
      case 'ı':
        suffix = 'ıncı';
        break;
      case 'e':
      case 'i':
        suffix = 'inci';
        break;
      case 'o':
      case 'u':
        suffix = 'uncu';
        break;
      case 'ö':
      case 'ü':
        suffix = 'üncü';
        break;
      default:
        suffix = 'inci';
    }

    // Son kelime ünlü ile bitiyorsa araya 'n' (örn: altı -> altıncı)
    final endsWithVowel =
        last.isNotEmpty && vowels.contains(last[last.length - 1]);
    if (endsWithVowel) {
      last = '${last}n$suffix'.replaceAll('nn', 'n'); // güvenlik
      // ama "iki" gibi özel durumlar yukarıda zaten yakalandı
      last = last.replaceAll('ikininci', 'ikinci'); // ekstra güvenlik
    } else {
      last = '$last$suffix';
    }

    words.add(last);
    return words.join(' ');
  }

  /// Last-mile normalization for Turkish TTS (runs before _normalizeTurkishForTts).
  /// Roman numerals are converted to ordinal words elsewhere; no Roman->number here.
  String _normalizeRomanFinalForTrTts(String input) {
    // Only apply for Turkish UI language
    final code = (AppLang.code.value).toLowerCase();
    if (!code.startsWith('tr')) return input;

    var s = input;

    // If some earlier code converted roman to a bare number but lost the dot,
    // fix only when it clearly represents a century token:
    // "19 yüzyıl" or "19 yy" or "19. yüzyıl" etc -> force dot so ordinal rule triggers.
    s = s.replaceAllMapped(
      RegExp(
          r'\b(\d{1,2}|30)\b(?=\s*(?:yy\b|yüzyıl\b|yüzyıla\b|yüzyılın\b|yüzyılda\b))',
          caseSensitive: false),
      (m) => '${m.group(1)!}.',
    );

    return s;
  }

  /// Normalize text for Turkish TTS: century (19.yy) and Roman ordinals (XIX.).
  /// ROMORDnROM is decoded only right before _tts.speak, not here.
  String _normalizeTurkishForTts(String text) {
    // Use TTS locale (_selectedLocale) to detect Turkish, not UI language (AppLang.code).
    // This ensures Roman numerals are converted even when the UI language is not Turkish.
    final ttsLocale = (_selectedLocale ?? AppLang.code.value).toLowerCase();
    if (!ttsLocale.startsWith('tr')) return text;

    String result = text;

    // ROMORD tokenlerini geçici olarak koru — içindeki M,X,I,V harfleri Roman regex'e takılmasın
    final tokenMap = <String, String>{};
    int tokenIdx = 0;
    result = result.replaceAllMapped(RegExp(r'ROMORD\d{1,4}ROM'), (m) {
      final key = '§T${tokenIdx++}§';
      tokenMap[key] = m.group(0)!;
      return key;
    });

    // Roman numerals (multi-char, with or without dot) -> Turkish ordinal word
    result = result.replaceAllMapped(
      RegExp(r'(?<![a-zçğışöü])([IVXLCDM]{2,})\.?(?![a-zçğışöü])'),
      (m) {
        final roman = m.group(1)!.toUpperCase();
        final val = _romanToInt(roman);
        if (val == null) return m.group(0)!;
        return _toTurkishOrdinalWord(val).replaceAll(' ', '_');
      },
    );

    // Single-char roman numerals with dot (I. V. X.) -> Turkish ordinal word
    result = result.replaceAllMapped(
      RegExp(r'(?<![A-Za-zÀ-ÿğüşıöçĞÜŞİÖÇ])([IVXLCDM])\.(?=\s|$)'),
      (m) {
        final roman = m.group(1)!.toUpperCase();
        final val = _romanToInt(roman);
        if (val == null) return m.group(0)!;
        return _toTurkishOrdinalWord(val).replaceAll(' ', '_');
      },
    );

    // 19.yy -> on dokuzuncu yüzyıl
    result = result.replaceAllMapped(
      RegExp(r'\b(\d{1,4})\s*\.?\s*yy\b', caseSensitive: false),
      (m) {
        final number = int.tryParse(m.group(1)!);
        if (number == null) return m.group(0)!;
        return '${_toTurkishOrdinalWord(number)} yüzyıl';
      },
    );

    // 19. -> on dokuzuncu (do not treat decimals like 3.14 as ordinal)
    result = result.replaceAllMapped(
      RegExp(r'\b(\d{1,4})\.(?!\d)'),
      (m) {
        final n = int.tryParse(m.group(1)!);
        if (n == null) return m.group(0)!;
        return _toTurkishOrdinalWord(n);
      },
    );

    // ── Türkçe kısaltmalar ──────────────────────────────────────────────────
    final trAbbrevMap = <String, String>{
      r'\bDr\.': 'Doktor',
      r'\bProf\.': 'Profesör',
      r'\bDoç\.': 'Doçent',
      r'\bAv\.': 'Avukat',
      r'\bMüh\.': 'Mühendis',
      r'\bYrd\.': 'Yardımcı',
      r'\bÖğr\.': 'Öğretim',
      r'\bGör\.': 'Görevlisi',
      r'\bArş\.': 'Araştırma',
      r'\bSn\.': 'Sayın',
      r'\bAlb\.': 'Albay',
      r'\bTğm\.': 'Teğmen',
      r'\bYzb\.': 'Yüzbaşı',
      r'\bBnb\.': 'Binbaşı',
      r'\bbkz\.': 'bakınız',
      r'\bBkz\.': 'Bakınız',
      r'\ba\.g\.e\.': 'adı geçen eser',
      r'\ba\.g\.y\.': 'adı geçen yapıt',
      r'\bvb\.': 've benzeri',
      r'\bvb\b': 've benzeri',
      r'\bvd\.': 've diğerleri',
      r'\bvd\b': 've diğerleri',
      r'\bvs\.': 'vesaire',
      r'\bvs\b': 'vesaire',
      r'\bsy\.': 'sayfa',
      r'\bsy\b': 'sayfa',
      r'\bno\.': 'numara',
      r'\bNo\.': 'Numara',
      r'\bnr\.': 'numara',
      r'\bNr\.': 'Numara',
      r'\bdak\.': 'dakika',
      r'\bdak\b': 'dakika',
      r'\bdk\.': 'dakika',
      r'\bdk\b': 'dakika',
      r'\bsn\.': 'saniye',
      r'\bsa\.': 'saat',
      r'\bkm\.': 'kilometre',
      r'\bkm\b': 'kilometre',
      r'\bcm\.': 'santimetre',
      r'\bcm\b': 'santimetre',
      r'\bmm\.': 'milimetre',
      r'\bmm\b': 'milimetre',
      r'\bkg\.': 'kilogram',
      r'\bkg\b': 'kilogram',
      r'\bgr\.': 'gram',
      r'\bgr\b': 'gram',
      r'\blt\.': 'litre',
      r'\blt\b': 'litre',
      r'\bml\.': 'mililitre',
      r'\bml\b': 'mililitre',
      r'\bm²\b': 'metrekare',
      r'\bm³\b': 'metreküp',
      r'\bkm²\b': 'kilometrekare',
      r'\bTL\b': 'Türk lirası',
      r'\bKDV\b': 'Katma Değer Vergisi',
      r'\bÖTV\b': 'Özel Tüketim Vergisi',
      r'\bTBMM\b': 'Türkiye Büyük Millet Meclisi',
      r'\bTHY\b': 'Türk Hava Yolları',
      r'\bPTT\b': 'Posta ve Telgraf Teşkilatı',
      r'\bSGK\b': 'Sosyal Güvenlik Kurumu',
      r'\bMEB\b': 'Milli Eğitim Bakanlığı',
      r'\bYÖK\b': 'Yükseköğretim Kurulu',
      r'\bÖSYM\b': 'Ölçme Seçme ve Yerleştirme Merkezi',
      r'\bYKS\b': 'Yükseköğretim Kurumları Sınavı',
      r'\bLGS\b': 'Liselere Geçiş Sınavı',
      r'\bKPSS\b': 'Kamu Personeli Seçme Sınavı',
      r'\bYDS\b': 'Yabancı Dil Sınavı',
      r'\bCd\.': 'Cadde',
      r'\bSok\.': 'Sokak',
      r'\bSk\.': 'Sokak',
      r'\bBulv\.': 'Bulvar',
      r'\bApt\.': 'Apartmanı',
      r'\bMah\.': 'Mahallesi',
      r'\bMh\.': 'Mahallesi',
    };
    for (final entry in trAbbrevMap.entries) {
      result = result.replaceAll(RegExp(entry.key), entry.value);
    }
    // ────────────────────────────────────────────────────────────────────────

    // Safety: never let "yy" reach TTS
    result =
        result.replaceAll(RegExp(r'\byy\b', caseSensitive: false), 'yüzyıl');

    // ROMORD tokenlerini geri yükle
    tokenMap.forEach((key, value) {
      result = result.replaceAll(key, value);
    });

    return result;
  }

  String _toTurkishOrdinal(int number) {
    final base = number.toString();

    if (base.endsWith('1')) return '$base' 'inci';
    if (base.endsWith('2')) return '$base' 'inci';
    if (base.endsWith('3')) return '$base' 'üncü';
    if (base.endsWith('4')) return '$base' 'üncü';
    if (base.endsWith('5')) return '${base}inci';
    if (base.endsWith('6')) return '${base}encı';
    if (base.endsWith('7')) return '${base}inci';
    if (base.endsWith('8')) return '${base}inci';
    if (base.endsWith('9')) return '${base}uncu';
    if (base.endsWith('0')) return '${base}uncu';

    return '${base}inci';
  }

  // Roman numeral conversion artık _ttsSpeakFinal içinde yapılıyor.
  // Bu fonksiyon geriye dönük uyumluluk için korunuyor.
  String _buildTtsTextTr(String input) {
    // TTS diline göre nokta, at ve www okunuşu — _selectedLocale bazlı
    final locale = (_selectedLocale ?? 'tr-TR').toLowerCase();
    final lang = locale.split('-')[0];

    const dotMap = {
      'tr': 'nokta',
      'en': 'dot',
      'de': 'Punkt',
      'it': 'punto',
      'fr': 'point',
      'es': 'punto',
      'pt': 'ponto',
      'nl': 'punt',
      'ru': 'точка',
      'el': 'τελεία',
      'hi': 'डॉट',
      'ja': 'ドット',
      'ko': '닷',
      'zh': '点',
      'bg': 'точка',
    };
    const atMap = {
      'tr': 'et',
      'en': 'at',
      'de': 'ät',
      'it': 'chiocciola',
      'fr': 'arobase',
      'es': 'arroba',
      'pt': 'arroba',
      'nl': 'apenstaartje',
      'ru': 'эт',
      'el': 'παπάκι',
      'hi': 'एट',
      'ja': 'アット',
      'ko': '앳',
      'zh': '艾特',
      'bg': 'ат',
    };
    const wwwMap = {
      'tr': 'W W W',
      'en': 'double you double you double you',
      'de': 'doppel u doppel u doppel u',
      'it': 'vu vu vu',
      'fr': 'double vé double vé double vé',
      'es': 'doble v doble v doble v',
      'pt': 'dáblio dáblio dáblio',
      'nl': 'de dubbel u de dubbel u de dubbel u',
      'ru': 'дабл ю дабл ю дабл ю',
      'el': 'βι βι βι',
      'hi': 'डब्लू डब्लू डब्लू',
      'ja': 'ダブリュー ダブリュー ダブリュー',
      'ko': '더블유 더블유 더블유',
      'zh': '万维网',
      'bg': 'у у у',
    };

    final dot = dotMap[lang] ?? 'dot';
    final at = atMap[lang] ?? 'at';
    final www = wwwMap[lang] ?? 'double you double you double you';

    String txt = input;

    // Önce https:// ve http:// kaldır
    txt = txt.replaceAll(RegExp(r'https?://', caseSensitive: false), '');
    // www. → www kelimesini okunabilir hale getir + kaldır
    txt = txt.replaceAll(RegExp(r'\bwww\.', caseSensitive: false), '$www ');

    // Kalan URL noktalarını replace et — kelime içindeki noktalar
    // domain.com → domain [dot] com şeklinde
    txt = txt.replaceAllMapped(
      RegExp(r'\b([a-zA-Z0-9-]+)\.([a-zA-Z]{2,})\b'),
      (m) => '${m.group(1)} $dot ${m.group(2)}',
    );

    // Email: beytan@yahoo.com → beytan [at] yahoo [dot] com
    txt = txt.replaceAllMapped(
      RegExp(r'[\w.+-]+@[\w.-]+\.[a-zA-Z]{2,}'),
      (m) {
        final parts = m.group(0)!.split('@');
        final user = parts[0].replaceAll('.', ' $dot ');
        final domain = parts[1].replaceAll('.', ' $dot ');
        return '$user $at $domain';
      },
    );

    return txt
        .replaceAll('://', ' ')
        .replaceAll('|', ' ')
        .replaceAll('~', ' ')
        .replaceAll('^', ' ')
        .replaceAll('`', ' ')
        .replaceAll('\\', ' ')
        .replaceAll('*', ' ')
        .replaceAll('#', ' ')
        .replaceAll('>', ' ')
        .replaceAll('<', ' ')
        .replaceAll('[', ' ')
        .replaceAll(']', ' ')
        .replaceAll('{', ' ')
        .replaceAll('}', ' ')
        .replaceAll('=', ' ')
        .replaceAll('+', ' ')
        .replaceAll('_', ' ')
        .replaceAll('/', ' ')
        .replaceAll(RegExp(r' {2,}'), ' ')
        .trim();
  }

  // Build TTS text with Roman numerals. Dotted first -> ROMORD{val}ROM; then dotless -> ROMORD{val}ROM (no cardinal).
  String _buildTtsTextWithRomanNumerals(String input) {
    var out = input;

    // 1) Dotted roman (XIX.) -> protected token ROMORD{val}ROM
    // Sadece BÜYÜK harf - küçük harfli kelimeler (ciddi, mix vb.) atlanır
    out = out.replaceAllMapped(
      RegExp(
          r'(?<![A-Za-zÀ-ÿğüşıöçĞÜŞİÖÇ])([IVXLCDM]{2,})\.(?!\d)(?![A-Za-zÀ-ÿğüşıöçĞÜŞİÖÇ])'),
      (m) {
        final roman = m.group(1)!;
        final val = _romanToInt(roman);
        if (val == null) return m.group(0)!;
        return 'ROMORD${val}ROM';
      },
    );

    // 2) Dotless roman (XIX) -> ROMORD{val}ROM
    // Sadece BÜYÜK harf - küçük harfli kelimeler atlanır
    out = out.replaceAllMapped(
      RegExp(
          r'(?<![A-Za-zÀ-ÿğüşıöçĞÜŞİÖÇ])([IVXLCDM]{2,})(?![A-Za-zÀ-ÿğüşıöçĞÜŞİÖÇ\.])'),
      (m) {
        final roman = m.group(1)!;
        final val = _romanToInt(roman);
        if (val == null) return m.group(0)!;
        return 'ROMORD${val}ROM';
      },
    );

    // Sayı + nokta (200.) -> "iki yüzüncü"
    final reNumOrdinal = RegExp(r'(?<!\d)(\d+)\.(?!\d)');
    out = out.replaceAllMapped(reNumOrdinal, (m) {
      final n = int.tryParse(m.group(1)!);
      if (n == null) return m.group(0)!;
      return _trOrdinalWords(n);
    });

    // Roman conversion artık _ttsSpeakFinal içinde yapılıyor
    return out;
  }

  /// Unified stop method that fully stops TTS and auto-scroll
  /// Resets ALL flags to ensure clean state for next start
  Future<void> _stopReading() async {
    // Set master flag to false IMMEDIATELY to prevent any delayed starts
    _isPlaying = false;
    _voiceLimitTimer?.cancel();
    if (_voiceSecsUsed > 0)
      PremiumService.instance.setVoiceSecs(_voiceSecsUsed);
    if (_scrollSecsUsed > 0)
      PremiumService.instance.setScrollSecs(_scrollSecsUsed);
    _scrollTickCount = 0;
    try {
      WakelockPlus.disable();
    } catch (_) {}

    // On stop, explicitly close keyboard but do not modify selection
    FocusManager.instance.primaryFocus?.unfocus();

    // TASK: Call hard stop BEFORE setState flags finalize
    _stopAutoScrollHard();

    // Stop TTS synchronously
    try {
      await _tts.stop();
    } catch (e) {}

    // Stop all TTS operations
    await _ttsStopAll();

    // DO NOT compute offsets - simply preserve _currentSentenceIndex

    // Reset ALL flags to false
    if (mounted) {
      _lastAppliedStart = 0;
      _lastAppliedEnd = 0;
      _lastUiStart = 0;
      _lastUiEnd = 0;
      setState(() {
        _isPaused = false;
        _autoScroll = false;
        _isAutoScrollOn = false; // Ensure blocker is cleared
        _ttsText = '';
        _ttsOffset = 0;
        _ttsHighlightStart = 0;
        _ttsHighlightEnd = 0;
        _pendingHlStart = -1;
        _pendingHlEnd = -1;
        _pendingHighlightPaint = false;
        _ttsLastChunk = '';
        _ttsChunkBase = 0;
        _isSpeaking = false;
        _ttsPaused = false;
        _ttsRunning = false;
        _isTtsPlaying = false;
        _ttsBusy = false;
      });
    }
  }

  Future<void> _stop() async {
    // Redirect to unified stop method
    await _stopReading();
  }

  bool get _isScrollPlaying =>
      _autoScroll && !_isPaused && (_autoScrollTimer != null);

  bool get _isScrollPaused => _autoScroll && _isPaused;

  bool get _isTtsPlayingActive => _isSpeaking && !_ttsPaused;

  // Unified session state: single source of truth for "is running" per mode
  bool get _isSessionActive {
    switch (_readingMode) {
      case ReadingMode.voiceOnly:
        return _isPlaying || _isTtsPlaying || _ttsRunning || _isSpeaking;
      case ReadingMode.scrollOnly:
        return _autoScroll && !_isPaused;
      case ReadingMode.both:
        return (_autoScroll && !_isPaused) ||
            (_isPlaying || _isTtsPlaying || _ttsRunning || _isSpeaking);
    }
  }

  bool get _isPrimaryPlaying =>
      (_readingMode == ReadingMode.scrollOnly && _isScrollPlaying) ||
      (_readingMode == ReadingMode.voiceOnly && _isTtsPlayingActive) ||
      (_readingMode == ReadingMode.both &&
          (_isScrollPlaying || _isTtsPlayingActive));

  bool get _isPrimaryPaused =>
      (_readingMode == ReadingMode.scrollOnly && _isScrollPaused) ||
      (_readingMode == ReadingMode.voiceOnly && _ttsPaused) ||
      (_readingMode == ReadingMode.both &&
          !_isPrimaryPlaying &&
          (_isScrollPaused || _ttsPaused));

  IconData get _primaryControlIcon =>
      _isSessionActive ? Icons.pause : Icons.play_arrow;

  /// İmmersive modu aç - 3 sn sonra otomatik kapat
  void _enterImmersive() {
    _immersiveAutoHideTimer?.cancel();
    if (!_isImmersive) {
      setState(() => _isImmersive = true);
    }
  }

  /// Dokunuşta: menüyü 3 sn göster, sonra tekrar gizle
  void _onImmersiveTap() {
    _immersiveAutoHideTimer?.cancel();
    setState(() => _isImmersive = false);
    // 3 sn sonra tekrar gizle (okuma devam ediyorsa)
    _immersiveAutoHideTimer = Timer(const Duration(seconds: 3), () {
      if (mounted && _isSessionActive) {
        setState(() => _isImmersive = true);
      }
    });
  }

  /// Stop: menüyü kalıcı göster
  void _exitImmersivePermanently() {
    _immersiveAutoHideTimer?.cancel();
    if (mounted) setState(() => _isImmersive = false);
  }

  void _handlePrimaryTap() {
    _handlePlayToggle();
  }

  /// True toggle handler: Play -> Stop -> Play -> Stop
  /// Always stops completely (not pause) when toggling off
  /// Always starts fresh when toggling on
  Future<void> _handlePlayToggle() async {
    if (_isSessionActive) {
      _voiceLimitTimer?.cancel();
      await _stopReading();
    } else {
      await _startByModeFresh();
    }
  }

  /// Start reading by mode - always works on first press
  /// This method MUST, every time:
  /// 1) Stop any previous reading session completely
  /// 2) Clear pause flags
  /// 3) Start fresh based on current mode
  /// 4) Handle "start from top" for new text
  Future<void> _startByModeFresh() async {
    // Cursor pozisyonunu en başta kaydet — _stopReading/unfocus öncesi!
    final savedCursorOffset = _text.selection.baseOffset;

    // Ekran kararmasın — TTS çalışırken
    if (Platform.isAndroid || Platform.isIOS) {
      try {
        await SystemChannels.platform.invokeMethod<void>(
          'SystemChrome.setEnabledSystemUIMode',
        );
      } catch (_) {}
    }

    // 1) Stop completely first to clear leftover state from previous mode
    await _stopReading();

    // 2) Clear pause flags
    if (mounted) {
      setState(() {
        _isPaused = false;
        _ttsPaused = false;
      });
    } else {
      _isPaused = false;
      _ttsPaused = false;
    }

    // 3) Start based on current mode
    // Note: "start from top" is handled in _startAutoScrollFresh
    final mode = _readingMode;
    final withScroll =
        mode == ReadingMode.scrollOnly || mode == ReadingMode.both;
    await startReading(withScroll: withScroll, cursorOffset: savedCursorOffset);
  }

  /// Unified function to start reading with TTS and/or scroll
  /// TASK 0B: BOTH mode starts TTS and auto-scroll at the SAME moment with unified lifecycle
  ///
  /// Rules:
  /// - BOTH mode: TTS and auto-scroll start at the SAME moment (unified start)
  /// - Single master flag _isPlaying controls both lifecycle
  /// - Auto-scroll may ONLY start if _isPlaying == true AND mode == BOTH
  Future<void> startReading(
      {required bool withScroll, int cursorOffset = 0}) async {
    // cursorOffset: _startByModeFresh'ten gelir, stop öncesi kaydedilmiş cursor pozisyonu
    final savedCursorOffset =
        cursorOffset > 0 ? cursorOffset : _text.selection.baseOffset;
    await Future.microtask(() async {
      try {
        // 1) STOP TTS + STOP SCROLL (in order) - IMPORTANT: await TTS stop to break stuck sessions
        _isPlaying = false; // Set flag FIRST to prevent any delayed starts
        _stopAutoScrollHard();
        // Reset TTS state flags to ensure clean start
        _ttsBusy = false;
        _ttsPaused = false;
        _ttsRunning = false;
        // CRITICAL: Await TTS stop to break any stuck TTS session
        try {
          await _tts.stop();
        } catch (e) {}
        await _ttsStopAll();
        // Reset stop flag AFTER stop completes to allow new start
        _ttsStopRequested = false;

        // Reset scroll state
        if (mounted) {
          setState(() {
            _isPaused = false;
            _autoScroll = false;
          });
        }

        // Check if TTS is needed based on reading mode
        final needsTts = _readingMode == ReadingMode.voiceOnly ||
            _readingMode == ReadingMode.both;
        final isBothMode = _readingMode == ReadingMode.both;

        // TASK 0B: For BOTH mode, set master flag and start TTS only (scroll = follow-highlight only)
        if (isBothMode && withScroll && needsTts) {
          // Set master flag FIRST
          _isPlaying = true;
          _enterImmersive();

          // BOTH (Scroll+Voice) başlarken: scroll timer kapalı, scroll sadece follow-highlight ile
          _autoScrollTimer?.cancel();
          _autoScrollTimer = null;

          // Scroll only when highlight leaves viewport (_followHighlightIfNeeded); no auto-scroll speed.

          // Continue with TTS setup below
        } else if (withScroll && !needsTts) {
          // Scroll-only mode: start scroll directly
          // Set master flag for scroll-only mode to ensure proper state tracking
          _isPlaying = true;
          _enterImmersive();

          // Skip caret scroll if we should start from top (new text)
          // NOTE: Do NOT scroll here - _startAutoScrollFresh will handle jumpTo(0) if needed
          // This prevents double scroll (bounce) when starting from top
          _startAutoScrollFresh();

          // Done for scroll-only mode
          return;
        }

        // For TTS modes (voiceOnly or both): Start TTS
        // Note: For BOTH mode, scroll was already started above at the SAME moment
        if (needsTts) {
          if (isBothMode) {
          } else {}

          // Step 2.1: Ensure TTS is initialized
          final ttsReady = await _ensureTtsReady();
          if (!ttsReady) {
            // TASK 0B: Reset master flag on TTS failure in BOTH mode
            if (isBothMode) {
              _isPlaying = false;
            }
            if (mounted) {
              ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
                  t('tts.start_failed'),
                  behavior: SnackBarBehavior.floating));
            }
            // Note: Scroll continues even if TTS fails, but flag is reset
            return;
          }

          // Step 2.2: Check text is not empty and get caret position
          final txt = _text.text.trim();
          if (txt.isEmpty) {
            // TASK 0B: Reset master flag on empty text in BOTH mode
            if (isBothMode) {
              _isPlaying = false;
            }
            if (mounted) {
              ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
                  t('empty.text'),
                  behavior: SnackBarBehavior.floating));
            }
            // Note: Scroll continues even if text is empty, but flag is reset
            return;
          }

          // Determine sentence index for resume:
          // Priority: 1) _forceStartFromTopOnce -> 0
          //           2) Cursor pozisyonu (> 0 ise) → cursor'dan cümle bul
          //           3) _lastSpokenOffset > 0 → kaldığı yerden devam et
          //           4) Scroll pozisyonu → ekranda görünen yerden başla
          //           5) Hepsi 0 ise → baştan başla
          if (_forceStartFromTopOnce) {
            _currentSentenceIndex = 0;
            _forceStartFromTopOnce = false;
          } else if (savedCursorOffset > 0 && _sentenceChunks.isNotEmpty) {
            // Cursor neredeyse oradan başla
            int foundIndex = 0;
            for (int i = 0; i < _sentenceChunks.length; i++) {
              if (_sentenceChunks[i].globalStart <= savedCursorOffset) {
                foundIndex = i;
              } else {
                break;
              }
            }
            _currentSentenceIndex = foundIndex;
          } else if (_lastSpokenOffset > 0 && _sentenceChunks.isNotEmpty) {
            // Kaldığı yerden devam et — _lastSpokenOffset scroll'dan önce gelir
            int foundIndex = 0;
            for (int i = 0; i < _sentenceChunks.length; i++) {
              if (_sentenceChunks[i].globalStart <= _lastSpokenOffset) {
                foundIndex = i;
              } else {
                break;
              }
            }
            _currentSentenceIndex = foundIndex;
          } else if (_scroll.hasClients && _sentenceChunks.isNotEmpty) {
            // Scroll pozisyonundan başla
            final scrollOffset = _scroll.offset;
            final totalChars = _text.text.length;
            final maxScroll = _scroll.position.maxScrollExtent;
            if (scrollOffset > 10 && maxScroll > 0 && totalChars > 0) {
              final charPos = ((scrollOffset / maxScroll) * totalChars).round();
              int foundIndex = 0;
              for (int i = 0; i < _sentenceChunks.length; i++) {
                if (_sentenceChunks[i].globalStart <= charPos) {
                  foundIndex = i;
                } else {
                  break;
                }
              }
              _currentSentenceIndex = foundIndex;
            } else {
              _currentSentenceIndex = 0;
            }
          } else {
            _currentSentenceIndex = 0;
          }
          // Ensure sentence index is valid
          if (_currentSentenceIndex < 0 ||
              _currentSentenceIndex >= _sentenceChunks.length) {
            _currentSentenceIndex = 0;
          }

          // Step 2.3: STOP ALL first
          await _ttsStopAll();

          // Step 2.4: AWAIT ensureLanguage
          await _ensureLanguageSet();

          // Step 2.5: AWAIT setSpeechRate(_rate)
          try {
            await _tts.setSpeechRate(_rate);
          } catch (e) {
            // TASK 0B: Reset master flag on speech rate error in BOTH mode
            if (isBothMode) {
              _isPlaying = false;
            }
            if (mounted) {
              ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
                  t('tts.start_failed'),
                  behavior: SnackBarBehavior.floating));
            }
            // Note: Scroll continues even if speech rate setting fails, but flag is reset
            return;
          }

          // Step 2.6: Prepare for speak - reset confirmation flag and set UI state
          _ttsStartConfirmed = false;
          _ttsBusy = true;
          _ttsRequestId++;
          final currentRequestId = _ttsRequestId;
          if (mounted) {
            setState(() {
              _isTtsPlaying = true;
              _ttsPaused = false;
              _isSpeaking = true;
            });
          }

          // Step 2.7: SPEAK - use sentence-based TTS
          String locale;
          if (_selectedLocale == null || _selectedLocale!.isEmpty) {
            locale = 'tr-TR';
          } else if (_selectedLocale!.toLowerCase().startsWith('tr')) {
            locale = 'tr-TR';
          } else {
            locale = _selectedLocale!;
          }

          bool speakSucceeded = false;
          try {
            await _ttsSpeakSentence(locale: locale);
            speakSucceeded = true;
          } catch (e) {
            // TASK 0B: Reset master flag on speak error in BOTH mode
            if (isBothMode) {
              _isPlaying = false;
            }
            _ttsBusy = false;
            if (mounted) {
              setState(() {
                _isTtsPlaying = false;
                _isSpeaking = false;
              });
              ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
                  t('tts.start_failed'),
                  behavior: SnackBarBehavior.floating));
            }
            // Note: Scroll continues even if TTS speak fails, but flag is reset
            return;
          }

          // TTS started successfully - scroll was already started above
          // Start 180-second daily free limit timer for non-premium users
          if (!PremiumService.instance.hasFullAccess) {
            _voiceSecsUsed = await PremiumService.instance.getTodayVoiceSecs();
            _startVoiceLimitTimer();
          }
        }
      } catch (e) {
        // TASK 0B: Reset master flag on general error in BOTH mode
        if (_readingMode == ReadingMode.both) {
          _isPlaying = false;
        }
        if (mounted) {
          setState(() {
            _isTtsPlaying = false;
            _isSpeaking = false;
            // Note: Keep scroll running even on error (user can stop manually), but flag is reset
          });
        }
      }
    });
    // END FIX 1
  }

  void _startByMode(ReadingMode mode) {
    // DEPRECATED: Use startReading instead
    // Keeping for backward compatibility, redirecting to startReading
    final withScroll =
        mode == ReadingMode.scrollOnly || mode == ReadingMode.both;
    startReading(withScroll: withScroll);
  }

  void _pauseByMode(ReadingMode mode) {
    // TASK 2: Set master flag to false IMMEDIATELY to prevent any delayed starts
    // Apply to both scroll-only and both modes
    if (mode == ReadingMode.both || mode == ReadingMode.scrollOnly) {
      _isPlaying = false;
    }

    // On pause, explicitly close keyboard but do not modify selection
    FocusManager.instance.primaryFocus?.unfocus();

    if (mode == ReadingMode.scrollOnly || mode == ReadingMode.both) {
      _pauseAutoScroll();
    }

    if (mode == ReadingMode.voiceOnly || mode == ReadingMode.both) {
      if (_isSpeaking && !_ttsPaused) {
        setState(() => _ttsPaused = true);
        Future.microtask(() => _pauseTtsOnly());
      }
    }
  }

  Future<void> _pauseTtsOnly() async {
    // UI state zaten _togglePauseResume'da güncellendi, burada sadece TTS işlemini yap
    // On pause, explicitly close keyboard but do not modify selection
    FocusManager.instance.primaryFocus?.unfocus();
    _pauseAutoScroll();
    await _ttsPause();
  }

  void _resumeByMode(ReadingMode mode) {
    // Set master flag to true when resuming (for both scroll-only and both modes)
    if (mode == ReadingMode.both || mode == ReadingMode.scrollOnly) {
      _isPlaying = true;
      _enterImmersive();
    }

    // Reset stop flag to allow resume
    _ttsStopRequested = false;

    // Fix: Start operations after first frame to ensure widget tree is ready
    WidgetsBinding.instance.addPostFrameCallback((_) async {
      if (mode == ReadingMode.scrollOnly || mode == ReadingMode.both) {
        _resumeAutoScroll();
      }

      if (mode == ReadingMode.voiceOnly || mode == ReadingMode.both) {
        if (_ttsPaused) {
          setState(() => _ttsPaused = false);
          Future.microtask(() => _resume());
        }
      }
    });
  }

  Future<void> _handlePrimaryLongPress() async {
    final mode = _readingMode;
    _voiceLimitTimer?.cancel();

    // TASK 2: Set master flag to false IMMEDIATELY when stopping
    // Apply to both scroll-only and both modes
    if (mode == ReadingMode.both || mode == ReadingMode.scrollOnly) {
      _isPlaying = false;
    }

    if (mode == ReadingMode.scrollOnly || mode == ReadingMode.both) {
      // TASK: Call hard stop BEFORE setState flags finalize
      _stopAutoScrollHard();
      setState(() {
        _isPaused = false;
        _autoScroll = false;
      });
    }

    // TASK 3: Reset reading position on stop (but NOT on pause)
    _ttsCharOffset = 0;
    _ttsStartTime = null;
    // DO NOT reset _lastSpokenOffset here - allow resume after stop

    if (mode == ReadingMode.voiceOnly || mode == ReadingMode.both) {
      await _stop();
    }
  }

  void _restartFromBeginning() {
    // Başa Gel Oku button: scrolls to top and moves cursor to beginning

    // TASK 2: Set master flag to false when stopping
    // Apply to both scroll-only and both modes
    if (_readingMode == ReadingMode.both ||
        _readingMode == ReadingMode.scrollOnly) {
      _isPlaying = false;
    }

    // Stop TTS if running (but don't start it) - fire and forget
    Future.microtask(() => _ttsStopAll());

    // TASK: Call hard stop to fully reset scroll state
    _stopAutoScrollHard();

    // HOTFIX: Reset ALL TTS offset variables to ensure clean start from top
    _ttsCharOffset = 0;
    _ttsOffset = 0;
    _lastAppliedStart = 0;
    _lastAppliedEnd = 0;
    _lastUiStart = 0;
    _lastUiEnd = 0;
    _ttsHighlightStart = 0;
    _ttsHighlightEnd = 0;
    _pendingHlStart = -1;
    _pendingHlEnd = -1;
    _pendingHighlightPaint = false;
    _ttsStartTime = null;

    // HOTFIX: Set flag to force next TTS start from top
    _forceStartFromTopOnce = true;
    _lastSpokenOffset = 0;
    _currentSentenceIndex = 0;

    // Reset scroll state to IDLE and move cursor to beginning
    setState(() {
      _isPaused = false;
      _autoScroll = false;
      _text.selection = TextSelection.collapsed(offset: 0);
    });

    // HOTFIX: Scroll to top after frame (using addPostFrameCallback)
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (_scroll.hasClients) {
        _scroll.jumpTo(0.0);
      }
    });

    // DO NOT start voice reading
    // DO NOT start auto-scroll
    // DO NOT call startReading, _startByMode, _playSafe, _speakSafe, _ttsRunNext, resume, or any TTS start function
    // User will press Play to start according to selected ReadingMode
    // Next Play will start from top due to _forceStartFromTopOnce flag
  }

  void _togglePauseResume() {
    if (_autoScroll) {
      setState(() {
        _isPaused = !_isPaused;
      });
      if (_isPaused) {
        _pauseAutoScroll();
      } else {
        _resumeAutoScroll();
      }
    } else {
      if (_ttsPaused) {
        // UI'ı anında güncelle
        setState(() {
          _ttsPaused = false;
        });
        // TTS resume işlemini async olarak başlat
        Future.microtask(() => _resume());
      } else if (_isSpeaking) {
        // UI'ı anında güncelle
        setState(() {
          _ttsPaused = true;
        });
        // TTS pause işlemini async olarak başlat
        Future.microtask(() => _pause());
      } else {
        // Play için UI güncellemesi _playSafe içinde yapılıyor
        _playSafe();
      }
    }
  }

  // 📋 Yapıştır
  Future<void> _pasteText() async {
    await _pasteFromClipboard(_text);
    _selectedLocale ??= 'tr-TR';
    await _savePersisted();
  }

  // Safe paste handler using controller.value.copyWith approach
  Future<void> _pasteFromClipboard(TextEditingController controller) async {
    final data = await Clipboard.getData('text/plain');
    final paste = data?.text;
    if (paste == null || paste.isEmpty) return;
    _userPastedText = true; // paste sonrası sol hizalama

    // Eski test verisini engelle — clipboard eski içerikle aynıysa blokla
    final sp = await SharedPreferences.getInstance();
    final blocked = sp.getString('blocked_clipboard_content') ?? '';
    if (blocked.isNotEmpty && paste.trim() == blocked.trim()) {
      return;
    }

    // Remove paragraph indents, fix hyphenation, normalize newlines (PDF paste fix)
    final cleaned = _normalizeForReading(_normalizeParagraphIndents(paste));

    final old = controller.value;

    // Her zaman başa yapıştır
    const start = 0;
    const end = 0;
    final separator = old.text.isNotEmpty ? '\n\n' : '';

    final newText = old.text.replaceRange(start, end, '$cleaned$separator');
    final newOffset = cleaned.length + separator.length;

    if (controller == _text) {
      _trackTextChange(newText);
    }
    controller.value = old.copyWith(
      text: newText,
      selection: TextSelection.collapsed(offset: newOffset),
      composing: TextRange.empty, // CRITICAL: prevents "paste only once" bug
    );
    // History capture: paste will also trigger listener, but we capture here too
    // The debounce and duplicate check will prevent duplicate entries
    if (controller == _text) {
      if ((_selectedLocale ?? '').startsWith('tr')) {
        _ttsText = _buildTtsTextWithRomanNumerals(newText);
      } else {
        _ttsText = newText;
      }
      _captureHistory(newText);

      // Auto-detect language and show snackbar (always, no char limit)
      if (mounted && cleaned.isNotEmpty) {
        // Cancel existing debounce
        _languageDetectionDebounce?.cancel();

        // Debounce language detection (300ms)
        _languageDetectionDebounce =
            Timer(const Duration(milliseconds: 300), () {
          if (!mounted) return;
          final detectedLang = _detectLanguageFromText(cleaned);
          if (detectedLang != null) {
            if (detectedLang == 'fr-FR') {
              _allowAutoFrenchOnce = true;
            }
            _switchToLanguageSilently(detectedLang);
          }
        });
      }
    }
  }

  // 🗑️ Temizle
  Future<void> _clearText() async {
    // Unfocus to prevent keyboard from appearing
    FocusScope.of(context).unfocus();

    // Stop any reading/autoscroll if running
    if (_isPlaying) {
      await _stop();
    }

    // Set flags to prevent _onTextChanged from triggering history capture and favorites removal
    _isUpdatingTextProgrammatically = true;
    _isProgrammaticClear = true;

    // Reset text change tracking when clearing
    _lastTextHash = 0;
    _shouldStartFromTop = false;
    // Clear sentence queue to prevent stale TTS
    _sentenceChunks.clear();
    _currentSentenceIndex = 0;
    _lastBuiltTextHash = 0;
    _userPastedText = false;
    _userOcrText = false;
    setState(() {
      _text.clear();
      _currentFile = null;
      _selectedFileName = null;
    });

    // Reset flags after clearing completes
    WidgetsBinding.instance.addPostFrameCallback((_) {
      _isUpdatingTextProgrammatically = false;
      _isProgrammaticClear = false;
    });

    // Explicitly remove the SharedPreferences key so it cannot reappear after restart
    final sp = await SharedPreferences.getInstance();
    await sp.remove(_prefsKeyFile);
    await sp.setBool(_prefsKeyUserCleared, true);
    await _savePersisted();
    ScaffoldMessenger.of(context)
        .showSnackBar(_gradientSnackBar(t('file.cleared')));
  }

  // 🔄 Auto-scroll toggle
  void _toggleAutoScroll(bool v) {
    setState(() => _autoScroll = v);

    if (v) {
      // TASK 0B: For BOTH mode, check master flag before starting auto-scroll
      final isBothMode = _readingMode == ReadingMode.both;
      if (isBothMode && !_isPlaying) {
        return;
      }
      if (!_isPaused) _startAutoScrollFresh();
    } else {
      _stopAutoScrollHard();
    }

    _savePersisted();
  }

  // ⚙️ Settings sheet
  // Settings sheet — theme-aware colors for dark mode readability
  Future<void> _openSettings() async {
    final isDark = Theme.of(context).brightness == Brightness.dark;
    final sheetBg = isDark ? const Color(0xFF1E1A16) : kCream; // 0xFFF7F1E8
