  // Check if a locale has voices available (is supported)
  // Uses both getVoices and getLanguages APIs for reliable detection (Samsung-safe)
  Future<bool> _isLocaleSupported(String locale) async {
    // Normalize locale format: _ → -, handle variants
    String normalizedLocale = locale.replaceAll('_', '-');

    // Normalize Turkish variants to tr-TR
    if (normalizedLocale.toLowerCase().startsWith('tr')) {
      normalizedLocale = 'tr-TR';
    }
    // Normalize Hebrew variants (iw → he-IL)
    else if (normalizedLocale.toLowerCase().startsWith('iw')) {
      normalizedLocale = 'he-IL';
    } else if (normalizedLocale.toLowerCase().startsWith('he')) {
      normalizedLocale = 'he-IL';
    }

    final lang = normalizedLocale.split('-')[0].toLowerCase();
    final normalizedLower = normalizedLocale.toLowerCase();

    // First check: voices list (preferred, most reliable)
    if (_voices.isNotEmpty) {
      final hasVoices = _voices.any((v) {
        final vMap = v as Map;
        final vLoc = (vMap['locale'] as String? ?? '')
            .toLowerCase()
            .replaceAll('_', '-');
        if (vLoc.startsWith('tr')) {
          return normalizedLower == 'tr-tr';
        }
        if (vLoc.startsWith('iw')) {
          return normalizedLower == 'he-il';
        }
        if (vLoc.startsWith('he')) {
          return normalizedLower == 'he-il';
        }
        return vLoc == normalizedLower || vLoc.startsWith('$lang-');
      });

      if (hasVoices) {
        return true;
      }
    }

    // Second check: getLanguages API (fallback for Samsung devices when getVoices is empty)
    if (_availableLanguagesCache != null &&
        _availableLanguagesCache!.isNotEmpty) {
      final hasLanguage = _availableLanguagesCache!.any((l) {
        final lLower = l.toLowerCase().replaceAll('_', '-');
        if (lLower.startsWith('tr')) {
          return normalizedLower == 'tr-tr';
        }
        if (lLower.startsWith('iw')) {
          return normalizedLower == 'he-il';
        }
        if (lLower.startsWith('he')) {
          return normalizedLower == 'he-il';
        }
        return lLower == normalizedLower || lLower.startsWith('$lang-');
      });

      if (hasLanguage) {
        return true;
      }
    }

    // Not supported
    return false;
  }

  Map<String, dynamic>? _findBestVoiceForLocaleAndGender(
      String? locale, String gender) {
    if (locale == null || _voices.isEmpty) return null;

    final lang = locale.split('-')[0].toLowerCase();

    // iOS-ONLY: Türkçe + erkek ses isteniyorsa, öncelik sırası:
    // Siri 1 → Siri 2 → Yelda → Cem (kullanıcı testiyle belirlendi)
    if (Platform.isIOS && lang == 'tr' && gender.toLowerCase() == 'male') {
      List<Map<String, dynamic>> trVoices() => _voices
          .whereType<Map>()
          .map((v) => v.cast<String, dynamic>())
          .where((v) =>
              (v['locale'] as String? ?? '').toLowerCase().startsWith('tr'))
          .toList();

      Map<String, dynamic>? findByNameParts(List<String> parts) {
        final matches = trVoices().where((v) {
          final vName = (v['name'] as String? ?? '').toLowerCase();
          return parts.every((p) => vName.contains(p));
        }).toList();
        return matches.isNotEmpty ? matches.first : null;
      }

      final priorityOrder = [
        ['siri', '1'],
        ['siri', '2'],
        ['yelda'],
        ['cem'],
      ];

      for (final parts in priorityOrder) {
        final found = findByNameParts(parts);
        if (found != null) return found;
      }
    }

    // Cihazdan gelen ses listesini filtrele ve Map<String, dynamic>e cast et
    final List<Map<String, dynamic>> candidates = _voices
        .whereType<Map>()
        .map((v) => v.cast<String, dynamic>())
        .where((v) {
      final vLoc = (v['locale'] as String? ?? '').toLowerCase();
      return vLoc.startsWith(lang);
    }).toList();

    // Bu dilde hiç ses yoksa, eldeki ilk sesi dön
    if (candidates.isEmpty) {
      final all = _voices
          .whereType<Map>()
          .map((v) => v.cast<String, dynamic>())
          .toList();
      return all.isNotEmpty ? all.first : null;
    }

    String normGender(Map<String, dynamic> v) {
      final g = (v['gender'] as String? ?? '').toLowerCase();
      if (g == 'male' || g == 'female') return g;

      final name = (v['name'] as String? ?? '').toLowerCase();

      // Apple'ın resmi Türkçe ses isimleri (Android'de bu isimler hiç yok)
      if (name.contains('cem')) return 'male';
      if (name.contains('yelda')) return 'female';

      if (name.contains('male') ||
          name.contains('man') ||
          name.contains('masc')) {
        return 'male';
      }
      if (name.contains('female') ||
          name.contains('woman') ||
          name.contains('fem')) {
        return 'female';
      }
      return g;
    }

    // iOS-ONLY: Enhanced/Premium kaliteli sesleri tercih et
    // (Android'in ses seçim davranışına dokunulmuyor)
    int iosQualityScore(Map<String, dynamic> v) {
      final q = v['quality'];
      if (q is num) return q.toInt();
      final qStr = (q?.toString() ?? '').toLowerCase();
      final idStr = (v['identifier']?.toString() ?? '').toLowerCase();
      final nameStr = (v['name']?.toString() ?? '').toLowerCase();
      final combined = '$qStr $idStr $nameStr';
      if (combined.contains('premium')) return 3;
      if (combined.contains('enhanced')) return 2;
      if (combined.contains('compact') || combined.contains('default')) {
        return 1;
      }
      return 1; // bilinmiyorsa varsayılan/düşük kabul et
    }

    List<Map<String, dynamic>> pickBest(List<Map<String, dynamic>> list) {
      if (list.isEmpty || !Platform.isIOS) return list;
      final sorted = [...list]
        ..sort((a, b) => iosQualityScore(b).compareTo(iosQualityScore(a)));
      return sorted;
    }

    final requested = gender.toLowerCase();

    // 1) İstenen cinsiyete tam uyan ses varsa, aralarından en kalitelisini seç
    final exact =
        pickBest(candidates.where((v) => normGender(v) == requested).toList());
    if (exact.isNotEmpty) {
      return exact.first;
    }

    // 2) İstenen cinsiyet bulunamadı → kalan adaylardan en kalitelisi
    final ranked = pickBest(candidates);
    return ranked.first;
  }

  // 🌐 WebLink dialog
  Future<void> _openWebLinkDialog() async {
    final ctl = TextEditingController();
    final mq = MediaQuery.of(context);
    final bool isLandscape = mq.orientation == Orientation.landscape;

    bool? ok;

    if (isLandscape) {
      // Landscape: use showModalBottomSheet so keyboard doesn't close it
      ok = await showModalBottomSheet<bool>(
        context: context,
        isScrollControlled: true,
        useSafeArea: true,
        backgroundColor: Colors.transparent,
        builder: (ctx) {
          final viewInsets = MediaQuery.of(ctx).viewInsets;

          return Padding(
            padding: EdgeInsets.only(bottom: viewInsets.bottom),
            child: DraggableScrollableSheet(
              expand: false,
              initialChildSize: 0.45,
              minChildSize: 0.35,
              maxChildSize: 0.85,
              builder: (_, controller) {
                return Material(
                  borderRadius:
                      const BorderRadius.vertical(top: Radius.circular(20)),
                  child: SingleChildScrollView(
                    controller: controller,
                    child: Padding(
                      padding: const EdgeInsets.all(16),
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        crossAxisAlignment: CrossAxisAlignment.stretch,
                        children: [
                          Text(
                            t('weblink.title'),
                            style: const TextStyle(
                                fontSize: 20, fontWeight: FontWeight.bold),
                          ),
                          const SizedBox(height: 16),
                          TextField(
                            controller: ctl,
                            decoration:
                                InputDecoration(hintText: t('weblink.hint')),
                            autofocus: true,
                            onSubmitted: (_) => Navigator.pop(ctx, true),
                          ),
                          const SizedBox(height: 16),
                          Row(
                            mainAxisAlignment: MainAxisAlignment.end,
                            children: [
                              TextButton(
                                onPressed: () => Navigator.pop(ctx, false),
                                child: Text(t('btn.back')),
                              ),
                              TextButton(
                                onPressed: () => Navigator.pop(ctx, true),
                                child: Text(t('weblink.open')),
                              ),
                            ],
                          ),
                        ],
                      ),
                    ),
                  ),
                );
              },
            ),
          );
        },
      );
    } else {
      // Portrait: use showModalBottomSheet so keyboard doesn't push TextField away
      ok = await showModalBottomSheet<bool>(
        context: context,
        isScrollControlled: true,
        useSafeArea: true,
        backgroundColor: Colors.transparent,
        builder: (ctx) {
          final mq = MediaQuery.of(ctx);
          // Always use the larger of keyboard height or system bottom padding
          // so buttons are never hidden behind nav bar or keyboard
          final bottomInset = mq.viewInsets.bottom > 0
              ? mq.viewInsets.bottom
              : mq.padding.bottom;
          return AnimatedPadding(
            duration: const Duration(milliseconds: 180),
            curve: Curves.easeOut,
            padding: EdgeInsets.only(bottom: bottomInset),
            child: Material(
              borderRadius:
                  const BorderRadius.vertical(top: Radius.circular(20)),
              child: SingleChildScrollView(
                child: Padding(
                  padding: const EdgeInsets.fromLTRB(16, 20, 16, 16),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    crossAxisAlignment: CrossAxisAlignment.stretch,
                    children: [
                      Text(
                        t('weblink.title'),
                        style: const TextStyle(
                            fontSize: 20, fontWeight: FontWeight.bold),
                      ),
                      const SizedBox(height: 16),
                      TextField(
                        controller: ctl,
                        decoration:
                            InputDecoration(hintText: t('weblink.hint')),
                        autofocus: true,
                        keyboardType: TextInputType.url,
                        onSubmitted: (_) => Navigator.pop(ctx, true),
                      ),
                      const SizedBox(height: 12),
                      Row(
                        mainAxisAlignment: MainAxisAlignment.end,
                        children: [
                          TextButton(
                            onPressed: () => Navigator.pop(ctx, false),
                            child: Text(t('btn.back')),
                          ),
                          const SizedBox(width: 8),
                          ElevatedButton(
                            onPressed: () => Navigator.pop(ctx, true),
                            child: Text(t('weblink.open')),
                          ),
                        ],
                      ),
                      const SizedBox(height: 4),
                    ],
                  ),
                ),
              ),
            ),
          );
        },
      );
    }

    if (ok != true) return;
    String rawUrl = ctl.text.trim();

    // ── URL normalization ──────────────────────────────────────────────────
    // Accept plain domains like "hurriyet.com.tr" or "www.bbc.com" without scheme
    if (rawUrl.isNotEmpty && !rawUrl.startsWith('http')) {
      // If starts with "www." or looks like a domain (contains a dot, no spaces)
      if (!rawUrl.contains(' ') && rawUrl.contains('.')) {
        rawUrl = 'https://$rawUrl';
      }
    }
    final url = rawUrl;
    if (url.isEmpty || !url.startsWith('http')) {
      ScaffoldMessenger.of(context)
          .showSnackBar(_gradientSnackBar(t('weblink_failed_invalid')));
      return;
    }

    // Show parsing indicator
    ScaffoldMessenger.of(context)
        .showSnackBar(_gradientSnackBar(t('weblink.parsing')));

    try {
      final client = HttpClient();
      client.connectionTimeout = const Duration(seconds: 15);

      // Validate URL
      Uri? uri;
      try {
        uri = Uri.parse(url);
        if (!uri.hasScheme || (!uri.scheme.startsWith('http'))) {
          throw FormatException('Invalid URL scheme');
        }
      } catch (e) {
        ScaffoldMessenger.of(context)
            .showSnackBar(_gradientSnackBar(t('weblink_failed_invalid')));
        return;
      }

      final req = await client.getUrl(uri).timeout(const Duration(seconds: 15));

      // Set user agent to avoid some bot detection
      req.headers.set('User-Agent',
          'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36');

      final res = await req.close().timeout(const Duration(seconds: 15));

      // Track status code for protected check
      final statusCode = res.statusCode;

      // Track final URL (may differ from original if redirected)
      String finalUrl = url;
      if (res.headers.value('location') != null) {
        finalUrl = res.headers.value('location')!;
        // Handle relative redirects
        if (!finalUrl.startsWith('http')) {
          finalUrl = uri.resolve(finalUrl).toString();
        }
      }

      // Don't return early for 401/403/429 - still try fallback attempts
      // But track if these status codes occur for warning later
      final isProtectedStatusCode =
          (statusCode == 401 || statusCode == 403 || statusCode == 429);

      if (statusCode != 200 && !isProtectedStatusCode) {
        ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
            t('weblink.failed'),
            behavior: SnackBarBehavior.floating));
        return;
      }

      final html = await res
          .transform(utf8.decoder)
          .join()
          .timeout(const Duration(seconds: 10));

      // Debug: Track HTML length
      final htmlLength = html.length;

      // Check for clear Cloudflare wall markers (only for status 200)
      // These are specific indicators of a Cloudflare challenge page
      final htmlLower = html.toLowerCase();
      final isProtected = (htmlLower.contains('checking your browser') &&
              htmlLower.contains('cloudflare')) ||
          (htmlLower.contains('just a moment') &&
              htmlLower.contains('cloudflare')) ||
          (htmlLower.contains('ddos protection') &&
              htmlLower.contains('cloudflare')) ||
          htmlLower.contains('cf-browser-verification') ||
          (htmlLower.contains('cf-ray') &&
              (htmlLower.contains('access denied') ||
                  htmlLower.contains('blocked')));

      // Parse HTML
      final document = html_parser.parse(html);
      if (document == null) {
        // Debug log
        ScaffoldMessenger.of(context)
            .showSnackBar(_gradientSnackBar(t('weblink_failed_empty')));
        return;
      }

      // ========== STEP 1: Extract readable text (Readability-like scoring) ==========
      // Remove clearly unwanted elements first
      for (final tag in [
        'script',
        'style',
        'svg',
        'nav',
        'header',
        'footer',
        'iframe',
        'noscript',
        'aside',
        'form',
        'button',
        'select',
        'input',
        'figure',
        'figcaption'
      ]) {
        document.querySelectorAll(tag).forEach((e) => e.remove());
      }

      // Remove ad/cookie/popup/social elements by class or id patterns
      const badPatterns = [
        'ad',
        'advertisement',
        'advert',
        'ads-',
        'adsense',
        'sidebar',
        'side-bar',
        'widget',
        'popup',
        'modal',
        'cookie',
        'consent',
        'gdpr',
        'banner',
        'promo',
        'share',
        'social',
        'related',
        'recommended',
        'more-news',
        'newsletter',
        'subscribe',
        'subscription',
        'comment',
        'comments',
        'disqus',
        'breadcrumb',
        'pagination',
        'pager',
        'menu',
        'navigation',
        'nav-',
        'topbar',
        'toolbar',
        'tag',
        'tags',
        'label',
        'category',
        'author-bio',
        'byline-extra',
      ];
      for (final pat in badPatterns) {
        document.querySelectorAll('[class*="$pat"]').forEach((e) => e.remove());
        document.querySelectorAll('[id*="$pat"]').forEach((e) => e.remove());
      }

      // ── Priority 1: Well-known article/content selectors (works on most news sites) ──
      // Ordered from most-specific to least-specific
      const contentSelectors = [
        // Turkish news sites
        'div.news-detail-text', // Hurriyet, Sabah
        'div.article-body', // Milliyet, HaberTurk
        'div.news-content', // NTV, Star
        'div.detay-icerik', // Sozcu
        'div.haber-detay-icerik',
        'div.content-body',
        'div.article-content',
        // International news
        'article',
        'div[itemprop="articleBody"]',
        'div[itemprop="description"]',
        'div.article__body',
        'div.story-body',
        'div.post-content',
        'div.entry-content',
        'div.td-post-content',
        'div.content__article-body', // Guardian
        'div.article-body-viewer-selector', // CNN
        'div.zn-body__paragraph', // CNN older
        'section.article-body',
        'main article',
        'main',
        // Wikipedia / encyclopedic
        '#mw-content-text',
        '.mw-parser-output',
        '#bodyContent',
      ];

      String? selectorText;
      for (final sel in contentSelectors) {
        final el = document.querySelector(sel);
        if (el != null) {
          // Clean the found element further
          for (final tag in [
            'script',
            'style',
            'noscript',
            'figure',
            'figcaption'
          ]) {
            el.querySelectorAll(tag).forEach((e) => e.remove());
          }
          for (final pat in [
            'caption',
            'photo',
            'image',
            'mw-editsection',
            'reference',
            'navbox',
            'infobox',
            'hatnote'
          ]) {
            el.querySelectorAll('[class*="$pat"]').forEach((e) => e.remove());
          }
          final txt = el.text.replaceAll(RegExp(r'\s+'), ' ').trim();
          if (txt.length >= 200) {
            selectorText = txt;
            break;
          }
        }
      }

      // ── Priority 2: Readability-like paragraph scoring ──
      // Score every block element by text density and link ratio
      String? readabilityText;
      if (selectorText == null || selectorText.length < 300) {
        final body = document.querySelector('body');
        if (body != null) {
          // Collect candidate blocks
          final candidates =
              body.querySelectorAll('div, section, article, td, blockquote');

          String bestText = '';
          double bestScore = 0;

          for (final el in candidates) {
            final innerText = el.text.replaceAll(RegExp(r'\s+'), ' ').trim();
            if (innerText.length < 150) continue;

            // Count <p> children — high count = likely article body
            final pCount = el.querySelectorAll('p').length;
            // Count anchor text to compute link density
            final linkText =
                el.querySelectorAll('a').map((a) => a.text.trim()).join(' ');
            final linkDensity =
                innerText.isEmpty ? 0.0 : (linkText.length / innerText.length);

            // High link density = likely nav/menu → skip
            if (linkDensity > 0.5) continue;

            // Score: length + p-count bonus - link-density penalty
            final score = innerText.length * (1 - linkDensity) + pCount * 80.0;

            if (score > bestScore) {
              bestScore = score;
              bestText = innerText;
            }
          }

          if (bestText.length >= 200) {
            readabilityText = bestText;
          }
        }
      }

      // Pick the better result between selector and readability
      String? readableText;
      if (selectorText != null && selectorText.length >= 200) {
        readableText = selectorText;
      } else if (readabilityText != null && readabilityText.length >= 200) {
        readableText = readabilityText;
      } else if (selectorText != null && selectorText.isNotEmpty) {
        readableText = selectorText;
      } else {
        readableText = readabilityText ?? '';
      }
      readableText ??= '';
      final readableLength = readableText.length;

      // ========== STEP 2: Apply fallbacks if readable text is still insufficient ==========
      String? pText;
      String? bodyText;

      if (readableText.isEmpty || readableText.length < 300) {
        // Fallback-1: collect all <p> tags with meaningful text
        final pDoc = html_parser.parse(html);
        if (pDoc != null) {
          final pElements = pDoc.querySelectorAll('p');
          final pTexts = <String>[];
          for (final p in pElements) {
            final text = p.text.trim();
            if (text.length >= 30) pTexts.add(text);
          }
          if (pTexts.isNotEmpty) {
            pText = pTexts.join(' ').replaceAll(RegExp(r'\s+'), ' ').trim();
          }
        }

        // Fallback-2: raw body text after tag removal
        if (pText == null || pText.length < 200) {
          final bodyDoc = html_parser.parse(html);
          if (bodyDoc != null) {
            for (final tag in [
              'script',
              'style',
              'noscript',
              'svg',
              'nav',
              'header',
              'footer',
              'iframe',
              'aside'
            ]) {
              bodyDoc.querySelectorAll(tag).forEach((e) => e.remove());
            }
            final fb = bodyDoc.querySelector('body');
            if (fb != null) {
              bodyText = fb.text.replaceAll(RegExp(r'\s+'), ' ').trim();
            }
          }
        }
      }

      // ========== STEP 3: Select final text in priority order: readableText → pText → bodyText ==========
      // Use first non-empty result in priority order
      String finalText = '';
      if (readableText.isNotEmpty) {
        // Use readableText if it exists (even if <500, fallbacks were just attempted for better options)
        finalText = readableText;
      } else if (pText != null && pText.isNotEmpty) {
        // Use pText if readableText is empty
        finalText = pText;
      } else if (bodyText != null && bodyText.isNotEmpty) {
        // Use bodyText if both readableText and pText are empty
        finalText = bodyText;
      }

      final pTextLength = pText?.length ?? 0;
      final bodyTextLength = bodyText?.length ?? 0;

      // Debug log: statusCode, finalUrl, htmlLength, readableLength, pTextLength, bodyTextLength

      // ========== STEP 4: Final check and protected site warning ==========
      // Only show "protected" warning if:
      // 1. Status code is 401/403/429 OR explicit Cloudflare wall detected
      // 2. AND all fallbacks failed (finalText is still empty/too short)
      final shouldShowProtected =
          (isProtectedStatusCode || (isProtected && statusCode == 200)) &&
              (finalText.isEmpty || finalText.length < 100);

      if (shouldShowProtected) {
        ScaffoldMessenger.of(context)
            .showSnackBar(_gradientSnackBar(t('weblink_failed_protected')));
        // Still continue to show empty message if text is empty
      }

      // Only show "no readable content" if all fallbacks failed (including protected check)
      if (finalText.isEmpty || finalText.length < 100) {
        ScaffoldMessenger.of(context)
            .showSnackBar(_gradientSnackBar(t('weblink_failed_empty')));
        return;
      }

      // Use the final text (either readable or fallback)
      final text = finalText;

      // Normalize paragraph indents before inserting
      final normalizedText = _normalizeParagraphIndents(text);

      _isUpdatingTextProgrammatically = true;
      _userOcrText = true; // Web içeriği — şiir formatı uygulanmasın
      _trackTextChange(normalizedText);
      setState(() {
        _text.text = normalizedText;
        _currentFile = url;
        _selectedFileName = url;
        _text.selection = TextSelection.collapsed(offset: 0);
      });
      _buildTtsTextAndIndexMap(normalizedText);
      _isUpdatingTextProgrammatically = false;
      // Scroll to top when loading new text
      if (_scroll.hasClients) {
        _scroll.jumpTo(0);
      }
      // Capture history (web link)
      _captureHistory(normalizedText, fileName: url);
      await _savePersisted();
      ScaffoldMessenger.of(context)
          .showSnackBar(_gradientSnackBar(t('file.loaded')));

      // Auto-detect language and switch silently
      final detectedLang = _detectLanguageFromText(normalizedText);
      if (detectedLang != null && mounted) {
        if (detectedLang == 'fr-FR') {
          _allowAutoFrenchOnce = true;
        }
        _switchToLanguageSilently(detectedLang);
      }
    } on SocketException catch (e) {
      // Network error
      ScaffoldMessenger.of(context)
          .showSnackBar(_gradientSnackBar(t('weblink_failed_network')));
    } on TimeoutException catch (e) {
      // Timeout
      ScaffoldMessenger.of(context)
          .showSnackBar(_gradientSnackBar(t('weblink_failed_network')));
    } on FormatException catch (e) {
      // Invalid URL
      ScaffoldMessenger.of(context)
          .showSnackBar(_gradientSnackBar(t('weblink_failed_invalid')));
    } catch (e) {
      // Generic error - check if it's a protected site error (only for 401/403/429)
      final errorStr = e.toString().toLowerCase();
      if (errorStr.contains('403') ||
          errorStr.contains('401') ||
          errorStr.contains('429')) {
        ScaffoldMessenger.of(context)
            .showSnackBar(_gradientSnackBar(t('weblink_failed_protected')));
      } else {
        ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
            t('weblink.failed'),
            behavior: SnackBarBehavior.floating));
      }
    }
  }

  // ⭐ Favori ekle
  Future<void> _addFavorite() async {
    final txt = _text.text.trim();
    if (txt.isEmpty) return;
    final titleCtl =
        TextEditingController(text: txt.substring(0, txt.length.clamp(0, 40)));
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(t('favs.title')),
        content: TextField(
          controller: titleCtl,
          decoration: InputDecoration(
            labelText: t('favs.input.title'),
          ),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: Text(t('btn.back')),
          ),
          TextButton(
            onPressed: () => Navigator.pop(ctx, true),
            child: Text(t('btn.add')),
          ),
        ],
      ),
    );
    if (ok != true) return;
    final title = titleCtl.text.trim();
    final fav = _Fav(
        title: title.isEmpty ? 'Untitled' : title,
        content: txt,
        ts: DateTime.now().millisecondsSinceEpoch);
    _favs.add(fav);
    await _saveFavorites();
    ScaffoldMessenger.of(context)
        .showSnackBar(_gradientSnackBar(t('favs.saved')));
  }

  // Open Google Translate with selected text
  Future<void> _openTranslate(String text) async {
    if (text.trim().isEmpty) return;
    final encodedText = Uri.encodeComponent(text.trim());
    final url = Uri.parse(
        'https://translate.google.com/?sl=auto&tl=en&text=$encodedText');
    try {
      if (await canLaunchUrl(url)) {
        await launchUrl(url, mode: LaunchMode.externalApplication);
      } else {
        await launchUrl(url, mode: LaunchMode.platformDefault);
      }
    } catch (e) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
            t('weblink.failed'),
            behavior: SnackBarBehavior.floating));
      }
    }
  }

  // Open note add/edit sheet
  Future<void> _openNoteSheet(
      {_Note? existingNote, String? initialText}) async {
    final textController = TextEditingController(text: initialText ?? '');
    final isEditing = existingNote != null;

    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: kCream,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(18)),
      ),
      builder: (ctx) {
        final mq = MediaQuery.of(ctx);
        final kbHeight = mq.viewInsets.bottom;
        final safeBottom = mq.padding.bottom;
        final safeRight = mq.padding.right;
        final isLandscapeNote = mq.orientation == Orientation.landscape;
        final screenHNote = mq.size.height;
        final bottomPad = kbHeight > 0 ? kbHeight : safeBottom;
        final availableH = screenHNote - kbHeight;
        final maxH = isLandscapeNote
            ? availableH * 0.90
            : (availableH * 0.86).clamp(200.0, double.infinity);
        return Padding(
          padding: EdgeInsets.only(bottom: bottomPad, right: safeRight),
          child: ConstrainedBox(
            constraints: BoxConstraints(maxHeight: maxH),
            child: SingleChildScrollView(
              child: Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  // Title
                  Padding(
                    padding: const EdgeInsets.fromLTRB(16, 12, 16, 8),
                    child: Text(
                      t('notes.title'),
                      style: const TextStyle(
                          fontSize: 20, fontWeight: FontWeight.bold),
                    ),
                  ),
                  // TextField - multiline, bounded so it fits in available height
                  Padding(
                    padding: const EdgeInsets.symmetric(horizontal: 16),
                    child: TextField(
                      controller: textController,
                      minLines: 2,
                      maxLines: 8,
                      decoration: InputDecoration(
                        hintText: t('notes.hint'),
                        border: OutlineInputBorder(
                          borderRadius: BorderRadius.circular(12),
                        ),
                      ),
                      autofocus: true,
                    ),
                  ),
                  // Buttons — inside scrollable content so reachable
                  Padding(
                    padding: const EdgeInsets.fromLTRB(16, 8, 16, 12),
                    child: Row(
                      mainAxisAlignment: MainAxisAlignment.end,
                      children: [
                        if (isEditing)
                          TextButton(
                            onPressed: () async {
                              // Delete note
                              _notes
                                  .removeWhere((n) => n.id == existingNote.id);
                              await _saveNotes();
                              if (mounted) {
                                Navigator.pop(ctx);
                                if (mounted) {
                                  ScaffoldMessenger.of(context).showSnackBar(
                                      _gradientSnackBar(t('notes.delete')));
                                }
                              }
                            },
                            style: TextButton.styleFrom(
                              foregroundColor: Colors.red,
                            ),
                            child: Text(t('notes.delete')),
                          ),
                        const SizedBox(width: 8),
                        TextButton(
                          onPressed: () => Navigator.pop(ctx),
                          child: Text(t('notes.cancel')),
                        ),
                        const SizedBox(width: 8),
                        ElevatedButton(
                          onPressed: () async {
                            final text = textController.text.trim();
                            if (text.isEmpty) {
                              Navigator.pop(ctx);
                              return;
                            }
                            final now = DateTime.now().millisecondsSinceEpoch;
                            if (isEditing) {
                              // Update existing note
                              final index = _notes
                                  .indexWhere((n) => n.id == existingNote.id);
                              if (index >= 0) {
                                _notes[index] = _Note(
                                  id: existingNote.id,
                                  text: text,
                                  createdAt: existingNote.createdAt,
                                  updatedAt: now,
                                );
                              }
                            } else {
                              // Add new note
                              final note = _Note(
                                id: now.toString(),
                                text: text,
                                createdAt: now,
                                updatedAt: now,
                              );
                              _notes.add(note);
                            }
                            await _saveNotes();
                            if (mounted) {
                              Navigator.pop(ctx);
                            }
                          },
                          child: Text(t('notes.save')),
                        ),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          ),
        );
      },
    );
  }

  // Open reading note sheet (note attached to selected text)
  Future<void> _openReadingNoteSheet({
    required String selectedText,
    required int startIndex,
    required int endIndex,
  }) async {
    if (selectedText.trim().isEmpty) {
      if (mounted) {
        ScaffoldMessenger.of(context).showSnackBar(_gradientSnackBar(
            t('notes.empty'),
            behavior: SnackBarBehavior.floating));
      }
      return;
    }
    final noteTextController = TextEditingController();
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: kCream,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(18)),
      ),
      builder: (ctx) {
        return SafeArea(
          child: LayoutBuilder(
            builder: (context, constraints) {
              final media = MediaQuery.of(context);
              final safeWidth = constraints.maxWidth;
              // Orientation değişiminde overflow önle — hem keyboard hem nav bar padding al
              final bottomPad =
                  math.max(media.viewInsets.bottom, media.padding.bottom);
              final Widget content = AnimatedPadding(
                duration: const Duration(milliseconds: 120),
                curve: Curves.easeOut,
                padding: EdgeInsets.only(bottom: bottomPad),
                child: Align(
                  alignment: Alignment.bottomCenter,
                  child: SingleChildScrollView(
                    child: Padding(
                      padding: EdgeInsets.only(
                          left: media.padding.left + 16,
                          right: media.padding.right + 16,
                          top: 8,
                          bottom: 8),
                      child: SizedBox(
                        width: math.min(680.0, safeWidth - 32),
                        child: Material(
                          clipBehavior: Clip.antiAlias,
                          shape: const RoundedRectangleBorder(
                            borderRadius:
                                BorderRadius.vertical(top: Radius.circular(18)),
                          ),
                          child: Column(
                            mainAxisSize: MainAxisSize.min,
                            crossAxisAlignment: CrossAxisAlignment.stretch,
                            children: [
                              Padding(
                                padding:
                                    const EdgeInsets.fromLTRB(16, 12, 16, 8),
                                child: Text(
                                  t('note.add'),
                                  style: const TextStyle(
                                      fontSize: 20,
                                      fontWeight: FontWeight.bold),
                                ),
                              ),
                              // Read-only selected text preview
                              Padding(
                                padding:
                                    const EdgeInsets.symmetric(horizontal: 16),
                                child: Container(
                                  width: double.infinity,
                                  padding: const EdgeInsets.all(12),
                                  decoration: BoxDecoration(
                                    color: Theme.of(ctx)
                                        .colorScheme
                                        .surfaceContainerHighest
                                        .withValues(alpha: 0.5),
                                    borderRadius: BorderRadius.circular(12),
                                    border: Border.all(
                                      color: Theme.of(ctx)
                                          .dividerColor
                                          .withValues(alpha: 0.5),
                                    ),
                                  ),
                                  child: SelectableText(
                                    selectedText,
                                    style: TextStyle(
                                      fontSize: 14,
                                      color:
                                          Theme.of(ctx).colorScheme.onSurface,
                                    ),
                                  ),
                                ),
                              ),
                              const SizedBox(height: 12),
                              // Editable note text
                              Padding(
                                padding:
                                    const EdgeInsets.symmetric(horizontal: 16),
                                child: TextField(
                                  controller: noteTextController,
                                  minLines: 2,
                                  maxLines: 6,
                                  decoration: InputDecoration(
                                    hintText: t('notes.hint'),
                                    border: OutlineInputBorder(
                                      borderRadius: BorderRadius.circular(12),
                                    ),
                                  ),
                                  autofocus: true,
                                ),
                              ),
                              Padding(
                                padding:
                                    const EdgeInsets.fromLTRB(16, 8, 16, 16),
                                child: Wrap(
                                  alignment: WrapAlignment.end,
                                  spacing: 8,
                                  runSpacing: 8,
                                  children: [
                                    TextButton(
                                      onPressed: () => Navigator.pop(ctx),
                                      child: Text(t('notes.cancel')),
                                    ),
                                    ElevatedButton(
                                      onPressed: () async {
                                        final noteText =
                                            noteTextController.text.trim();
                                        if (noteText.isEmpty) {
                                          Navigator.pop(ctx);
                                          return;
                                        }
                                        final now = DateTime.now()
                                            .millisecondsSinceEpoch;
                                        final note = ReadingNote(
                                          id: now.toString(),
                                          documentId:
                                              _getReadingNoteDocumentId(),
                                          selectedText: selectedText,
                                          noteText: noteText,
                                          startIndex: startIndex,
                                          endIndex: endIndex,
                                          createdAt: now,
                                        );
                                        _readingNotes.insert(0, note);
                                        await _saveReadingNotes();
                                        if (mounted) {
                                          Navigator.pop(ctx);
                                          ScaffoldMessenger.of(context)
                                              .showSnackBar(_gradientSnackBar(
                                                  t('notes.saved'),
                                                  behavior: SnackBarBehavior
                                                      .floating));
                                        }
                                      },
                                      child: Text(t('notes.save')),
                                    ),
                                  ],
                                ),
                              ),
                            ],
                          ),
                        ),
                      ),
                    ),
                  ),
                ),
              );
              return content;
            },
          ),
        );
      },
    );
  }

  // ⭐ Favoriler sheet
  Future<void> _openFavoritesSheet() async {
    final txt = _text.text.trim();
    final isCurrentFavorite = txt.isNotEmpty && _isFavorite;

    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: kCream,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(18)),
      ),
      builder: (ctx) {
        final screenHeight = MediaQuery.of(ctx).size.height;
        final isLandscapeFavs =
            MediaQuery.of(ctx).orientation == Orientation.landscape;
        return SizedBox(
          height: screenHeight * (isLandscapeFavs ? 0.92 : 0.75),
          child: Padding(
            padding: const EdgeInsets.all(16),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(t('favs.title'), style: const TextStyle(fontSize: 20)),
                const SizedBox(height: 12),

                // Add/Remove current toggle button
                if (txt.isNotEmpty)
                  Padding(
                    padding: const EdgeInsets.only(bottom: 12),
                    child: SizedBox(
                      width: double.infinity,
                      child: ElevatedButton.icon(
                        onPressed: () async {
                          if (isCurrentFavorite) {
                            // Remove current favorite
                            _favs.removeWhere((f) => f.content == txt);
                            await _saveFavorites();
                            Navigator.pop(ctx);
                            _openFavoritesSheet(); // Refresh
                          } else {
                            // Add current favorite
                            Navigator.pop(ctx);
                            await _addFavorite();
                            _openFavoritesSheet(); // Reopen to show updated list
                          }
                        },
                        icon: Icon(
                          isCurrentFavorite ? Icons.star : Icons.star_outline,
                          color: isCurrentFavorite ? Colors.amber : null,
                        ),
                        label: Text(
                          isCurrentFavorite
                              ? t('favs.remove_current')
                              : t('favs.add_current'),
                        ),
                        style: ElevatedButton.styleFrom(
                          backgroundColor: isCurrentFavorite
                              ? Colors.amber.withValues(alpha: 0.2)
                              : null,
                        ),
                      ),
                    ),
                  ),

                // Divider
                if (txt.isNotEmpty && _favs.isNotEmpty)
                  const Divider(height: 24),

                // Favorites list
                if (_favs.isEmpty)
                  Expanded(
                    child: Center(
                      child: Text(t('favs.empty')),
                    ),
                  )
                else
                  Expanded(
                    child: ListView.builder(
                      shrinkWrap: true,
                      itemCount: _favs.length,
                      itemBuilder: (_, i) {
                        final f = _favs[i];
                        final isCurrent = f.content == txt;
                        return ListTile(
                          leading: Icon(
                            isCurrent ? Icons.star : Icons.star_outline,
                            color: isCurrent ? Colors.amber : null,
                          ),
                          title: Text(f.title),
                          subtitle: Text(
                            DateTime.fromMillisecondsSinceEpoch(f.ts)
                                .toString()
                                .substring(0, 16),
                          ),
                          trailing: IconButton(
                            icon: const Icon(Icons.delete),
                            onPressed: () {
                              _favs.removeAt(i);
                              _saveFavorites();
                              Navigator.of(context).maybePop();
                              WidgetsBinding.instance.addPostFrameCallback((_) {
                                appScaffoldMessengerKey.currentState
                                  ?..clearSnackBars()
                                  ..showSnackBar(_gradientSnackBar(
                                      t('item.removed'),
                                      behavior: SnackBarBehavior.floating));
                              });
                            },
                          ),
                          onTap: () {
                            _isUpdatingTextProgrammatically = true;
                            _trackTextChange(f.content);
                            setState(() => _text.text = f.content);
                            _buildTtsTextAndIndexMap(f.content);
                            _isUpdatingTextProgrammatically = false;
                            // Capture history (restoring from favorites)
                            _captureHistory(f.content);
                            _maybeAutoDetectLanguageAfterTextSet(f.content);
                            _savePersisted();
                            Navigator.pop(ctx);
                          },
                        );
                      },
                    ),
                  ),
              ],
            ),
          ),
        );
      },
    );
  }

  // ⭐ Nova sheet
  Future<void> _openNova() async {
    // Guard: Prevent double-opening with flag (hard guard against double push)
    // Check guard flag first - if already opening, ignore this call
    if (_openingNova) {
      return; // Already opening, ignore this call
    }

    // Set guard flag immediately (before any async operations)
    // This ensures only one Nova sheet can be opened at a time
    _openingNova = true;

    // Examples map for Nova sheet (same as in build method)
    final p = <String, List<String>>{
      'en': [
        'Summarize this paragraph in 2 sentences.',
        'What does "resilience" mean?',
        'What is the main idea of this text?',
      ],
      'tr': [
        'Bu paragrafı 2 cümlede özetler misin?',
        '"resilience" ne demek?',
        'Okuduğum metnin ana fikri nedir?',
      ],
      'it': [
        'Riassumi questo paragrafo in 2 frasi.',
        'Cosa significa "resilience"?',
        "Qual è l'idea principale di questo testo?",
      ],
      'de': [
        'Fasse diesen Absatz in 2 Sätzen zusammen.',
        'Was bedeutet "resilience"?',
        'Was ist die Hauptidee dieses Textes?',
      ],
      'fr': [
        'Résumez ce paragraphe en 2 phrases.',
        'Que signifie "resilience" ?',
        'Quelle est l\'idée principale de ce texte ?',
      ],
      'es': [
        'Resume este párrafo en 2 oraciones.',
        '¿Qué significa "resilience"?',
        '¿Cuál es la idea principal de este texto?',
      ],
      'hi': [
        'इस पैराग्राफ को 2 वाक्यों में सारांशित करो।',
        '"resilience" का क्या मतलब है?',
        'इस पाठ का मुख्य विचार क्या है?',
      ],
      'ru': [
        'Кратко перескажите этот абзац в двух предложениях.',
        'Что означает слово «resilience»?',
        'Какова основная идея этого текста?',
      ],
      'el': [
        'Περίγραψε αυτή την παράγραφο σε 2 προτάσεις.',
        'Τι σημαίνει «resilience»;',
        'Ποια είναι η κύρια ιδέα αυτού του κειμένου;',
      ],
      'ja': [
        'この段落を2文で要約してください。',
        '「resilience」とは何ですか？',
        'このテキストの主なアイデアは何ですか？',
      ],
      'ko': [
        '이 단락을 두 문장으로 요약해 주세요.',
        '"resilience"가 무슨 뜻인가요?',
        '이 글의 핵심 내용은 무엇인가요?',
      ],
      'bg': [
        'Резюмирайте този параграф в две изречения.',
        'Какво означава "resilience"?',
        'Каква е основната идея на този текст?',
      ],
    };

    // Get examples for current language, fallback to 'en'
    final langCode = AppLang.code.value;
    final examples = p[langCode] ?? p['en']!;

    try {
      await showModalBottomSheet<void>(
        context: context,
        isScrollControlled: true,
        backgroundColor: kCream,
        shape: const RoundedRectangleBorder(
          borderRadius: BorderRadius.vertical(top: Radius.circular(18)),
        ),
        builder: (ctx) => _NovaSheet(examples: examples),
      );
    } finally {
      // Reset guard flag when navigation completes (sheet closed)
      // This ensures the flag is reset even if an error occurs
      _openingNova = false;
    }
  }

  // 📜 History sheet
  Future<void> _openHistorySheet() async {
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: Theme.of(context).brightness == Brightness.dark
          ? Theme.of(context).scaffoldBackgroundColor
          : kCream,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(18)),
      ),
      builder: (ctx) {
        final mq = MediaQuery.of(ctx);
        final screenHeight = mq.size.height;
        final isLandscapeHistory = mq.orientation == Orientation.landscape;
        return SizedBox(
          height: screenHeight * (isLandscapeHistory ? 0.92 : 0.75),
          child: StatefulBuilder(
            builder: (ctx2, setLocalState) {
              return Column(
                mainAxisSize: MainAxisSize.min,
                crossAxisAlignment: CrossAxisAlignment.start,
                children: [
                  // Header: title + delete selected button
                  StatefulBuilder(
                    builder: (ctx3, setHeaderState) {
                      // selectedIndices is managed in outer setLocalState scope
                      return const SizedBox.shrink();
                    },
                  ),
                  Padding(
                    padding: const EdgeInsets.fromLTRB(16, 12, 16, 8),
                    child: Builder(builder: (context) {
                      return Text(t('history.title'),
                          style: const TextStyle(fontSize: 20));
                    }),
                  ),
                  // History list (most recent first)
                  if (_history.isEmpty)
                    Expanded(
                      child: Center(
                        child: Text(t('history.empty')),
                      ),
                    )
                  else
                    Expanded(
                      child: Builder(builder: (ctx3) {
                        // Track selected indices (original indices in _history)
                        final selectedSet = <int>{};
                        return StatefulBuilder(
                          builder: (ctx4, setSelState) {
                            return Column(
                              children: [
                                // Delete selected bar
                                if (selectedSet.isNotEmpty)
                                  Padding(
                                    padding:
                                        const EdgeInsets.fromLTRB(16, 0, 16, 8),
                                    child: Row(
                                      mainAxisAlignment:
                                          MainAxisAlignment.spaceBetween,
                                      children: [
                                        Text('${selectedSet.length} seçildi',
                                            style:
                                                const TextStyle(fontSize: 14)),
                                        TextButton.icon(
                                          icon: const Icon(Icons.delete_outline,
                                              size: 18),
                                          label: Text(t('btn.delete')),
                                          style: TextButton.styleFrom(
                                            foregroundColor: kBeigeDark,
                                          ),
                                          onPressed: () async {
                                            // Delete all selected (highest index first)
                                            final sorted = selectedSet.toList()
                                              ..sort((a, b) => b.compareTo(a));
                                            for (final idx in sorted) {
                                              if (idx < _history.length) {
                                                _history.removeAt(idx);
                                              }
                                            }
                                            await _saveHistory();
                                            setState(() {});
                                            setSelState(
                                                () => selectedSet.clear());
                                            setLocalState(() {});
                                          },
                                        ),
                                      ],
                                    ),
                                  ),
                                Expanded(
                                  child: ListView.builder(
                                    reverse: true,
                                    shrinkWrap: true,
                                    itemCount: _history.length,
                                    itemBuilder: (_, i) {
                                      final originalIndex =
                                          _history.length - 1 - i;
                                      final h = _history[originalIndex];
                                      final dateTime =
                                          DateTime.fromMillisecondsSinceEpoch(
                                              h.timestamp);
                                      final dateStr =
                                          '${dateTime.year}-${dateTime.month.toString().padLeft(2, '0')}-${dateTime.day.toString().padLeft(2, '0')} ${dateTime.hour.toString().padLeft(2, '0')}:${dateTime.minute.toString().padLeft(2, '0')}';
                                      final isSelected =
                                          selectedSet.contains(originalIndex);
                                      return ListTile(
                                        leading: Checkbox(
                                          value: isSelected,
                                          activeColor: kBeigeDark,
                                          onChanged: (val) {
                                            setSelState(() {
                                              if (val == true) {
                                                selectedSet.add(originalIndex);
                                              } else {
                                                selectedSet
                                                    .remove(originalIndex);
                                              }
                                            });
                                          },
                                        ),
                                        title: Text(h.title),
                                        subtitle: Column(
                                          crossAxisAlignment:
                                              CrossAxisAlignment.start,
                                          children: [
                                            Text(h.preview),
                                            const SizedBox(height: 4),
                                            Text(
                                              dateStr,
                                              style: TextStyle(
                                                fontSize: 12,
                                                color: Colors.grey.shade600,
                                              ),
                                            ),
                                          ],
                                        ),
                                        trailing: IconButton(
                                          icon:
                                              const Icon(Icons.delete_outline),
                                          tooltip: t('btn.delete'),
                                          onPressed: () async {
                                            // Remove single item — stay in sheet
                                            _history.removeAt(originalIndex);
                                            await _saveHistory();
                                            setState(() {});
                                            setSelState(() => selectedSet
                                                .remove(originalIndex));
                                            setLocalState(() {});
                                            ScaffoldMessenger.of(context)
                                                .showSnackBar(_gradientSnackBar(
                                                    t('item.removed'),
                                                    behavior: SnackBarBehavior
                                                        .floating));
                                          },
                                        ),
                                        onTap: () {
                                          if (selectedSet.isNotEmpty) {
                                            // Selection mode: tap toggles checkbox
                                            setSelState(() {
                                              if (isSelected) {
                                                selectedSet
                                                    .remove(originalIndex);
                                              } else {
                                                selectedSet.add(originalIndex);
                                              }
                                            });
                                          } else {
                                            // Normal mode: open item
                                            _isUpdatingTextProgrammatically =
                                                true;
                                            _trackTextChange(h.fullText);
                                            setState(() {
                                              _text.text = h.fullText;
                                              _selectedFileName = h.title !=
                                                      t('history.manual_text')
                                                  ? h.title
                                                  : null;
                                            });
                                            _buildTtsTextAndIndexMap(
                                                h.fullText);
                                            _isUpdatingTextProgrammatically =
                                                false;
                                            _captureHistory(h.fullText,
                                                fileName: _selectedFileName);
                                            _maybeAutoDetectLanguageAfterTextSet(
                                                h.fullText);
                                            _savePersisted();
                                            Navigator.pop(ctx);
                                            WidgetsBinding.instance
                                                .addPostFrameCallback((_) {
                                              _runAutoLanguageDetectionIfNeeded(
                                                  source: 'history');
                                            });
                                          }
                                        },
                                      );
                                    },
                                  ),
                                ),
                              ],
                            );
                          },
                        );
                      }),
                    ),
                ],
              );
            },
          ),
        );
      },
    );
  }

  // 🔹 Nova helpers
  Future<void> _refreshNovaStatus() async {
    final sp = await SharedPreferences.getInstance();
    final user = sp.getString(_novaUserKey) ?? '';
    final key = sp.getString(_novaApiKey) ?? '';
    if (!mounted) return;
    setState(() => _novaOnline = user.isNotEmpty && key.isNotEmpty);
  }

  Future<void> _editNovaConnection() async {
    final sp = await SharedPreferences.getInstance();
    final userCtl =
        TextEditingController(text: sp.getString(_novaUserKey) ?? '');
    final keyCtl = TextEditingController(text: sp.getString(_novaApiKey) ?? '');
    await showDialog<void>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Nova Bağlantısı'),
        content: SingleChildScrollView(
          child: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              TextField(
                  controller: userCtl,
                  decoration:
                      const InputDecoration(labelText: 'Kullanıcı Adı')),
              const SizedBox(height: 12),
              TextField(
                  controller: keyCtl,
                  decoration: const InputDecoration(labelText: 'API Key'),
                  obscureText: true),
              const SizedBox(height: 8),
              Text(
                  'Bilgiler cihazında saklanır. ${AppLang.code.value == 'tr' ? 'Girildiğinde ikon yeşil olur.' : 'Icon turns green when set.'}'),
            ],
          ),
        ),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx), child: Text(t('btn.back'))),
          TextButton(
            onPressed: () async {
              await sp.setString(_novaUserKey, userCtl.text.trim());
              await sp.setString(_novaApiKey, keyCtl.text.trim());
              if (context.mounted) Navigator.pop(ctx);
              await _refreshNovaStatus();
            },
            child: const Text('Kaydet'),
          ),
        ],
      ),
    );
  }

  Future<void> _clearNovaConnection() async {
    final ok = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Bağlantıyı Temizle'),
        content: const Text(
            'Kayıtlı Nova kullanıcı adı ve API anahtarını silmek istiyor musun?'),
        actions: [
          TextButton(
              onPressed: () => Navigator.pop(ctx, false),
              child: const Text('İptal')),
          TextButton(
              onPressed: () => Navigator.pop(ctx, true),
              child: const Text('Temizle')),
        ],
      ),
    );
    if (ok == true) {
      final sp = await SharedPreferences.getInstance();
      await sp.remove(_novaUserKey);
      await sp.remove(_novaApiKey);
      await _refreshNovaStatus();
    }
  }

