  // 💾 Persist
  Future<void> _loadPersisted() async {
    final sp = await SharedPreferences.getInstance();
    final stored = sp.getString(_prefsKeyContent) ?? '';
    final scroll = sp.getDouble(_prefsKeyScroll) ?? 0;

    // Metni yükle — satır yapısını koru
    final cleaned = stored;
    final savedTtsOffset = sp.getInt(_prefsKeyTtsOffset) ?? 0;
    // Only set text if controller is empty (initial load) - don't overwrite existing text
    // This prevents clearing text during rebuilds triggered by selection/context menu
    if (_text.text.isEmpty) {
      final userCleared = sp.getBool(_prefsKeyUserCleared) ?? false;
      _text.text = (cleaned.isEmpty || _isDemoText(cleaned)) && !userCleared
          ? _getDemoText(AppLang.code.value)
          : cleaned;
      // Set cursor to top-left on initial load
      _text.selection = TextSelection.collapsed(offset: 0);
      // Scroll pozisyonunu restore et — kaydedilen yer varsa oraya git
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) return;
        if (_scroll.hasClients) {
          if (scroll > 0) {
            _scroll.jumpTo(scroll.clamp(0.0, _scroll.position.maxScrollExtent));
          } else {
            _scroll.jumpTo(0);
          }
        }
      });
      _buildTtsTextAndIndexMap(cleaned);
      _buildSentenceChunks(cleaned); // sentence chunks'ı hemen build et
      _maybeAutoDetectLanguageAfterTextSet(cleaned);

      // Kaydedilen TTS pozisyonundan cümle index'ini hesapla
      // Böylece Play'e basınca direkt oradan başlar
      if (savedTtsOffset > 0 && _sentenceChunks.isNotEmpty) {
        int foundIndex = 0;
        for (int i = 0; i < _sentenceChunks.length; i++) {
          if (_sentenceChunks[i].globalStart <= savedTtsOffset) {
            foundIndex = i;
          } else {
            break;
          }
        }
        _currentSentenceIndex = foundIndex;
      }

      // Kaldığı yeri göster — snackbar
      if (savedTtsOffset > 0 && cleaned.isNotEmpty) {
        _lastSpokenOffset = savedTtsOffset;
        final percent =
            ((savedTtsOffset / cleaned.length) * 100).round().clamp(0, 100);
        final remaining = 100 - percent;
        WidgetsBinding.instance.addPostFrameCallback((_) {
          if (!mounted) return;
          final messenger = ScaffoldMessenger.of(context);
          messenger.clearSnackBars();
          ScaffoldFeatureController? controller;
          controller = messenger.showSnackBar(
            SnackBar(
              backgroundColor: Colors.transparent,
              elevation: 0,
              behavior: SnackBarBehavior.floating,
              duration: const Duration(seconds: 4),
              padding: EdgeInsets.zero,
              content: Container(
                padding:
                    const EdgeInsets.symmetric(horizontal: 16, vertical: 10),
                decoration: BoxDecoration(
                  gradient: const LinearGradient(
                    colors: [kGoldMain, kGoldDark],
                    begin: Alignment.centerLeft,
                    end: Alignment.centerRight,
                  ),
                  borderRadius: BorderRadius.circular(8),
                ),
                child: Row(
                  children: [
                    Expanded(
                      child: Text(
                        t('reading.resumed')
                            .replaceFirst('{percent}', percent.toString()),
                        maxLines: 1,
                        overflow: TextOverflow.ellipsis,
                      ),
                    ),
                    const SizedBox(width: 8),
                    GestureDetector(
                      onTap: () {
                        if (_scroll.hasClients && scroll > 0) {
                          _scroll.animateTo(
                            scroll,
                            duration: const Duration(milliseconds: 600),
                            curve: Curves.easeOut,
                          );
                        }
                        // Kaydedilen TTS pozisyonundan cümleyi bul ve index'i set et
                        // Böylece Play'e basınca oradan devam eder
                        if (savedTtsOffset > 0 && _sentenceChunks.isNotEmpty) {
                          int foundIndex = 0;
                          for (int i = 0; i < _sentenceChunks.length; i++) {
                            if (_sentenceChunks[i].globalStart <=
                                savedTtsOffset) {
                              foundIndex = i;
                            } else {
                              break;
                            }
                          }
                          _currentSentenceIndex = foundIndex;
                        }
                        controller?.close();
                      },
                      child: Text(
                        t('reading.resumeBtn'),
                        style: const TextStyle(
                          color: Colors.white,
                          fontWeight: FontWeight.bold,
                        ),
                      ),
                    ),
                  ],
                ),
              ),
            ),
          );
          // Force close after 4 seconds regardless of action button
          Future.delayed(const Duration(seconds: 4), () {
            controller?.close();
          });
        });
      }
    } else {
      // If text already exists, restore scroll position
      if (_scroll.hasClients) _scroll.jumpTo(scroll);
    }
    final savedRate = sp.getDouble(_prefsKeyRate) ?? defaultVoiceRate;
    // Migration/clamping: Handle old saved values that might be too fast
    if (savedRate > 1.2 || savedRate < 0.2) {
      // Out of sane range, use default
      _rate = defaultVoiceRate;
    } else {
      // Clamp to reasonable range (0.45-0.90) to prevent values that are too fast or too slow
      _rate = savedRate.clamp(0.45, 0.90);
    }
    _pitch = sp.getDouble(_prefsKeyPitch) ?? 1.0;
    _volume = sp.getDouble(_prefsKeyVolume) ?? 1.0;
    final voiceJson = sp.getString(_prefsKeyVoice);
    _selectedVoice = voiceJson != null ? jsonDecode(voiceJson) : null;
    _selectedLocale = sp.getString(_prefsKeyLocale);
    // Menü diliyle senkronize et — prefs'teki eski locale yerine güncel menü dili kullan
    final uiLocale = _getLocaleFromAppLangCode(AppLang.code.value);
    if (uiLocale != null) {
      _selectedLocale = uiLocale;
      // Voice'u da güncelle
      _selectedVoice = _findBestVoiceForLocaleAndGender(uiLocale, _voiceGender);
      // TTS engine'e hemen bildir
      try {
        await _tts.setLanguage(uiLocale);
        if (_selectedVoice != null) {
          await _tts.setVoice({
            'name': _selectedVoice!['name'],
            'locale': uiLocale,
          });
        }
      } catch (e) {}
    }
    // Load gender from preferences, default to 'male' if not set
    _voiceGender = sp.getString(_prefsKeyGender) ?? 'male';
    _autoScrollPxPerSec = sp.getDouble(_prefsKeyAutoSpd) ?? defaultScrollSpeed;
    // Only restore file label if text is not empty (prevents label from appearing with empty text)
    final finalText = _text.text.trim();
    if (finalText.isNotEmpty) {
      _currentFile = sp.getString(_prefsKeyFile);
    } else {
      _currentFile = null;
      _selectedFileName = null;
      // Also remove the key from SharedPreferences if text is empty
      await sp.remove(_prefsKeyFile);
    }
    final modeStr = sp.getString(_prefsKeyReadingMode);
    if (modeStr != null) {
      _readingMode = ReadingMode.values.firstWhere(
        (m) => m.name == modeStr,
        orElse: () => ReadingMode.both,
      );
    } else {
      // First run: no key → default to BOTH and create the key
      _readingMode = ReadingMode.both;
      await sp.setString(_prefsKeyReadingMode, ReadingMode.both.name);
    }
    // OCR/WebLink/dosya formatı flag'ini yükle
    _userOcrText = sp.getBool(_prefsKeyUserOcr) ?? false;
    _userPastedText = sp.getBool(_prefsKeyUserPaste) ?? false;
    // Auto-scroll should NOT start automatically on launch - user must press Play button
    // Always set to false on initial load, regardless of reading mode
    _autoScroll = false;

    if (mounted) setState(() {});
  }

  Future<void> _savePersisted() async {
    final sp = await SharedPreferences.getInstance();
    await sp.setString(_prefsKeyContent, _text.text);
    await sp.setDouble(
        _prefsKeyScroll, _scroll.hasClients ? _scroll.offset : 0);
    await sp.setInt(_prefsKeyTtsOffset, _lastSpokenOffset);
    await sp.setDouble(_prefsKeyRate, _rate);
    await sp.setDouble(_prefsKeyPitch, _pitch);
    await sp.setDouble(_prefsKeyVolume, _volume);
    if (_selectedVoice != null)
      await sp.setString(_prefsKeyVoice, jsonEncode(_selectedVoice));
    if (_selectedLocale != null)
      await sp.setString(_prefsKeyLocale, _selectedLocale!);
    await sp.setString(_prefsKeyGender, _voiceGender);
    await sp.setBool(_prefsKeyAutoOn, _autoScroll);
    await sp.setDouble(_prefsKeyAutoSpd, _autoScrollPxPerSec);
    if (_currentFile != null) {
      await sp.setString(_prefsKeyFile, _currentFile!);
    } else {
      // Explicitly remove the key when file is null to prevent reappearance
      await sp.remove(_prefsKeyFile);
    }
    await sp.setString(_prefsKeyReadingMode, _readingMode.name);
    await sp.setBool(_prefsKeyUserOcr, _userOcrText);
    await sp.setBool(_prefsKeyUserPaste, _userPastedText);
  }

  Future<void> _loadFavorites() async {
    final sp = await SharedPreferences.getInstance();
    final encoded = sp.getStringList(_prefsFavs) ?? [];
    _favs = encoded.map(_Fav.decode).toList();
  }

  Future<void> _saveFavorites() async {
    final sp = await SharedPreferences.getInstance();
    final List<String> encoded = _favs.map((f) => f.encode()).toList();
    await sp.setStringList(_prefsFavs, encoded);
  }

  Future<void> _loadNotes() async {
    final sp = await SharedPreferences.getInstance();
    final jsonStr = sp.getString(_prefsNotes);
    if (jsonStr == null || jsonStr.isEmpty) {
      _notes = [];
      return;
    }
    try {
      final List<dynamic> jsonList = jsonDecode(jsonStr);
      _notes = jsonList
          .map((j) => _Note.fromJson(j as Map<String, dynamic>))
          .toList();
    } catch (e) {
      _notes = [];
    }
  }

  Future<void> _saveNotes() async {
    final sp = await SharedPreferences.getInstance();
    final List<Map<String, dynamic>> jsonList =
        _notes.map((n) => n.toJson()).toList();
    await sp.setString(_prefsNotes, jsonEncode(jsonList));
  }

  Future<void> _loadReadingNotes() async {
    final sp = await SharedPreferences.getInstance();
    final jsonStr = sp.getString(_prefsReadingNotes);
    if (jsonStr == null || jsonStr.isEmpty) {
      _readingNotes = [];
      return;
    }
    try {
      final List<dynamic> jsonList = jsonDecode(jsonStr);
      _readingNotes = jsonList
          .map((j) => ReadingNote.fromJson(j as Map<String, dynamic>))
          .toList();
      _readingNotes.sort((a, b) => b.createdAt.compareTo(a.createdAt));
    } catch (e) {
      _readingNotes = [];
    }
  }

  Future<void> _saveReadingNotes() async {
    final sp = await SharedPreferences.getInstance();
    final List<Map<String, dynamic>> jsonList =
        _readingNotes.map((n) => n.toJson()).toList();
    await sp.setString(_prefsReadingNotes, jsonEncode(jsonList));
  }

  String _getReadingNoteDocumentId() {
    if (_selectedFileName != null && _selectedFileName!.isNotEmpty) {
      return _selectedFileName!;
    }
    if (_history.isNotEmpty) {
      return 'reading_${_history.last.timestamp}';
    }
    return 'reading_${DateTime.now().millisecondsSinceEpoch}';
  }

  Future<void> _loadHistory() async {
    final sp = await SharedPreferences.getInstance();
    final jsonStr = sp.getString(_prefsHistory);
    if (jsonStr == null || jsonStr.isEmpty) {
      _history = [];
      return;
    }
    try {
      final List<dynamic> jsonList = jsonDecode(jsonStr);
      _history = jsonList
          .map((j) => _HistoryItem.fromJson(j as Map<String, dynamic>))
          .toList();
    } catch (e) {
      _history = [];
    }
  }

  Future<void> _saveHistory() async {
    final sp = await SharedPreferences.getInstance();
    // Keep only last 50 entries (FIFO)
    if (_history.length > 50) {
      _history = _history.sublist(_history.length - 50);
    }
    final jsonList = _history.map((h) => h.toJson()).toList();
    await sp.setString(_prefsHistory, jsonEncode(jsonList));
  }

  void _captureHistory(String text, {String? fileName}) {
    final trimmed = text.trim();

    // Do not save if trimmed text length < 30 chars
    if (trimmed.length < 30) return;

    // Check for duplicates: compare first 500 chars with last saved entry
    if (_history.isNotEmpty) {
      final lastEntry = _history.last;
      final lastFirst500 = lastEntry.fullText.length > 500
          ? lastEntry.fullText.substring(0, 500)
          : lastEntry.fullText;
      final newFirst500 =
          trimmed.length > 500 ? trimmed.substring(0, 500) : trimmed;
      if (lastFirst500 == newFirst500) {
        // Skip duplicate
        return;
      }
    }

    // Debounce: cancel previous timer and set new one (800-1200ms range, using 1000ms)
    _historyDebounceTimer?.cancel();
    _historyDebounceTimer = Timer(const Duration(milliseconds: 1000), () {
      _addHistoryEntry(trimmed, fileName: fileName);
    });
  }

  Future<void> _addHistoryEntry(String text, {String? fileName}) async {
    final title = fileName ?? t('history.manual_text');
    final preview = text.length > 120 ? text.substring(0, 120) : text;
    final item = _HistoryItem(
      timestamp: DateTime.now().millisecondsSinceEpoch,
      title: title,
      preview: preview,
      fullText: text,
    );
    _history.add(item);
    await _saveHistory();
  }

