                      _lastUiEnd = 0;
                      setState(() {
                        _readingMode = ReadingMode.voiceOnly;
                        _autoScroll = false;
                        _ttsHighlightStart = 0;
                        _ttsHighlightEnd = 0;
                        _pendingHlStart = -1;
                        _pendingHlEnd = -1;
                        _pendingHighlightPaint = false;
                      });
                      _stopAutoScrollHard();
                      _savePersisted();
