  Widget _buildReadingBodyLandscape(BuildContext context,
      {bool hideTopToolbarInLandscape = false}) {
    // Landscape: SafeArea + sağlam layout with real reading body
    final mq = MediaQuery.of(context);
    // Klavye açık mı? Tüm cihazlarda viewInsets.bottom kullan
    // resizeToAvoidBottomInset=false olduğundan viewInsets.bottom her zaman doğru değeri verir
    final mqKb = mq.viewInsets.bottom;
    final bool kbOpen = mqKb > 50;

    // PART 1: Check if tour is active and needs secondary row visible
    final bool isTourActive = _tourOverlayEntry != null;
    final int stepShown = _rootTourStep + 1;
    final bool needsSecondaryRow =
        (stepShown == 3 || stepShown == 4 || stepShown == 12);
    // Secondary row: klavye kapalıyken göster, açıkken gizle (overflow önlemek için)
    final bool showSecondaryRow = !kbOpen;

    return SafeArea(
      bottom: false,
      child: LayoutBuilder(
        builder: (context, constraints) {
          return Stack(
            key: _readingTourStackKey,
            children: [
              Padding(
                padding: EdgeInsets.only(bottom: mqKb),
                child: Column(
                  children: [
                    // Top toolbar (Turkish, Weblink, OCR, Okuma Ayarları): hide in landscape when keyboard open
                    if (!_isImmersive && !hideTopToolbarInLandscape)
                      _buildTopControlsBar(context),
                    // Açık dosya etiketi
                    if (_currentFile != null)
                      Padding(
                        padding: const EdgeInsets.fromLTRB(16, 0, 16, 6),
                        child: Align(
                          alignment: Alignment.centerLeft,
                          child: Chip(
                            label: Text(_currentFile!,
                                overflow: TextOverflow.ellipsis,
                                style: const TextStyle(color: Colors.black87)),
                            deleteIcon: const Icon(Icons.close),
                            onDeleted: () {
                              setState(() => _currentFile = null);
                              _savePersisted();
                            },
                            backgroundColor: kBeige,
                          ),
                        ),
                      ),
                    // Metin alanı
                    Expanded(
                      child: DecoratedBox(
                        decoration: BoxDecoration(
                          color: Theme.of(context).brightness == Brightness.dark
                              ? Theme.of(context).scaffoldBackgroundColor
                              : Theme.of(context).colorScheme.surface,
                        ),
                        child: ClipRect(
                          child: SingleChildScrollView(
                            controller: _scroll,
                            padding: EdgeInsets.only(
                              left: 8,
                              right: 8,
                              top: 8,
                              bottom:
                                  120 + MediaQuery.paddingOf(context).bottom,
                            ),
                            physics: _text.text.isEmpty
                                ? const NeverScrollableScrollPhysics()
                                : const ClampingScrollPhysics(),
                            child: _buildReadingBody(context),
                          ),
                        ),
                      ),
                    ),
                  ],
                ),
              ),
              // 📝 Notes button - Fixed bottom-right, above History
              Positioned(
                right: 16,
                bottom: 96 + MediaQuery.paddingOf(context).bottom,
                child: AnimatedOpacity(
                  opacity: _isImmersive ? 0.0 : 1.0,
                  duration: Duration.zero,
                  child: IgnorePointer(
                    ignoring: _isImmersive,
                    child: KeyedSubtree(
                      key: _readingTourKeyNote,
                      child: TourTarget(
                        id: 'tour.note',
                        onRect: _onTourRectChanged,
                        child: FloatingActionButton.small(
                          backgroundColor:
                              Theme.of(context).colorScheme.surface,
                          elevation: 4,
                          heroTag:
                              'notes_button', // Prevent hero animation conflicts
                          onPressed: () {
                            Navigator.pushNamed(context, '/notes');
                          },
                          child: const Icon(
                            Icons.note,
                            color: Colors.grey,
                            size: 22,
                          ),
                        ),
                      ),
                    ),
                  ), // IgnorePointer
                ), // AnimatedOpacity
              ),
              // 📜 History button - Fixed bottom-right, above Favorite
              Positioned(
                right: 16,
                bottom: 56 + MediaQuery.paddingOf(context).bottom,
                child: AnimatedOpacity(
                  opacity: _isImmersive ? 0.0 : 1.0,
                  duration: Duration.zero,
                  child: IgnorePointer(
                    ignoring: _isImmersive,
                    child: KeyedSubtree(
                      key: _tourKeyHistory,
                      child: TourTarget(
                        id: 'tour.history',
                        onRect: _onTourRectChanged,
                        child: KeyedSubtree(
                          key: _readingTourKeyHistory,
                          child: FloatingActionButton.small(
                            backgroundColor:
                                Theme.of(context).colorScheme.surface,
                            elevation: 4,
                            heroTag:
                                'history_button', // Prevent hero animation conflicts
                            onPressed: () {
                              _openHistorySheet();
                            },
                            child: const Icon(
                              Icons.history,
                              color: Colors.grey,
                              size: 22,
                            ),
                          ),
                        ),
                      ),
                    ),
                  ), // IgnorePointer
                ), // AnimatedOpacity
              ),
              // ⭐ Favorite star - Fixed bottom-right (optimized for Android 10+)
              Positioned(
                right: 16,
                bottom: 16 + MediaQuery.paddingOf(context).bottom,
                child: AnimatedOpacity(
                  opacity: _isImmersive ? 0.0 : 1.0,
                  duration: Duration.zero,
                  child: IgnorePointer(
                    ignoring: _isImmersive,
                    child: KeyedSubtree(
                      key: _readingTourKeyFavorites,
                      child: TourTarget(
                        id: 'tour.favorites',
                        onRect: _onTourRectChanged,
                        child: FloatingActionButton.small(
                          backgroundColor:
                              Theme.of(context).colorScheme.surface,
                          elevation: 4,
                          // Ensure button doesn't interfere with system gestures on Android 10+
                          heroTag:
                              'favorite_star', // Prevent hero animation conflicts
                          onPressed: () {
                            // Favorites list should be accessible even when text is empty
                            _openFavoritesSheet();
                          },
                          child: Icon(
                            _isFavorite ? Icons.star : Icons.star_outline,
                            color: _isFavorite
                                ? Colors.amber
                                : Colors.grey.shade600,
                            size: 22,
                          ),
                        ),
                      ),
                    ),
                  ), // IgnorePointer
                ), // AnimatedOpacity
              ),

              // ⌨️ Klavye kapat butonu — klavye açıkken klavyenin hemen üstünde sağ köşe
              if (!_isImmersive && kbOpen)
                Positioned(
                  right: 8,
                  bottom: mqKb + 8,
                  child: FloatingActionButton.small(
                    backgroundColor: Theme.of(context).colorScheme.surface,
                    elevation: 4,
                    heroTag: 'landscape_keyboard_dismiss',
                    onPressed: () => FocusScope.of(context).unfocus(),
                    child: Icon(Icons.keyboard_hide,
                        color: Colors.grey.shade600, size: 22),
                  ),
                ),

              // Watermark logo — landscape
              Positioned.fill(
                child: IgnorePointer(
                  ignoring: true,
                  child: Center(
                    child: Opacity(
                      opacity: 0.18,
                      child: Image.asset(
                        'assets/reading_watermark.png',
                        width: 280,
                        height: 280,
                        fit: BoxFit.contain,
                      ),
                    ),
                  ),
                ),
              ),
              // Immersive tap overlay (landscape)
              if (_isImmersive)
                Positioned.fill(
                  child: GestureDetector(
                    behavior: HitTestBehavior.opaque,
                    onTap: _onImmersiveTap,
                    child: const SizedBox.expand(),
                  ),
                ),
              // Mini floating player (landscape) — sağ alt köşe
              if (_isImmersive)
                Positioned(
                  bottom: 16 + MediaQuery.paddingOf(context).bottom,
                  right: 16,
                  child: Material(
                    elevation: 8,
                    borderRadius: BorderRadius.circular(32),
                    color: Colors.grey.shade300,
                    child: Padding(
                      padding: const EdgeInsets.symmetric(
                          horizontal: 4, vertical: 2),
                      child: Row(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          _MiniPlayerButton(
                              onTap: () async => _handlePrimaryTap(),
                              icon: _primaryControlIcon),
                          _MiniPlayerButton(
                            onTap: () async {
                              await _handlePrimaryLongPress();
                              _exitImmersivePermanently();
                            },
                            icon: Icons.stop,
                          ),
                        ],
                      ),
                    ),
                  ),
                ),
              if (_readingTourCurrentStep != null)
                Positioned.fill(
                  child: _buildReadingTourHighlightOverlay(),
                ),

              // Tour aktifken tüm dokunuşları blokla — klavye açılmasın
              if (_readingTourCurrentStep != null)
                Positioned.fill(
                  child: GestureDetector(
                    behavior: HitTestBehavior.opaque,
                    onTap: () {
                      FocusManager.instance.primaryFocus?.unfocus();
                    },
                    onPanDown: (_) {
                      FocusManager.instance.primaryFocus?.unfocus();
                    },
                    child: const SizedBox.expand(),
                  ),
                ),

              if (_readingTourCurrentStep != null)
                Positioned.fill(
                  child: Builder(
                    builder: (context) {
                      final step =
                          _buildReadingTourStep(_readingTourCurrentStep!);
                      if (step == null) return const SizedBox.shrink();
                      return ReadingPageTour(
                        step: step,
                        onNext: _nextReadingTourStep,
                        onClose: _endReadingTour,
                        onBack: _readingTourCurrentStep != null &&
                                _readingTourCurrentStep! > 1
                            ? _previousReadingTourStep
                            : null,
                        onDontShowAgain: _dontShowAgainReadingTour,
                        totalSteps: _getTotalReadingTourSteps(),
                      );
                    },
                  ),
                ),
            ],
          );
        },
      ),
    );
  }

  // Helper for landscape reading content - uses existing _buildReadingBody
  Widget _buildLandscapeReadingContentOrFallback(BuildContext context) {
    return _buildReadingBody(context);
  }

  Widget _buildReadingBody(BuildContext context) {
    // Ekran genişliğine göre dinamik margin (Kindle/Moon Reader standardı: %6-8)
    final screenWidth = MediaQuery.of(context).size.width;

    // Şiir tespiti — şiirde daha dar margin ve orta hizalama
    final currentText = _text.text;
    // Şiir tespiti — OCR veya paste'ten geliyorsa şiir formatı uygulanmasın
    final isPoetry =
        _isPoetryText(currentText) && !_userPastedText && !_userOcrText;

    // Şiirde daha geniş margin (metin ortada dar görünsün), düz metinde standart
    final hPadding = isPoetry
        ? (screenWidth * 0.10).clamp(20.0, 48.0)
        : (screenWidth * 0.06).clamp(14.0, 28.0);

    final baseStyle = TextStyle(
      color: Theme.of(context).colorScheme.onSurface,
      fontSize: 16,
      height: isPoetry ? 1.9 : 1.7, // şiirde satırlar daha ferah
      fontFamilyFallback: ['Roboto', 'Noto Sans', 'Arial'],
      letterSpacing: isPoetry ? 0.1 : 0.2,
      fontStyle:
          (isPoetry && !(_selectedLocale ?? '').toLowerCase().startsWith('ko'))
              ? FontStyle.italic
              : FontStyle.normal, // şiir hafif italic (Korece hariç)
    );
    _readingTextStyle = baseStyle;

    final isBothMode = _readingMode == ReadingMode.both;
    final isBothPlaying = isBothMode && _isPlaying;

    // Check if we have a valid highlight when playing (for CustomPaint)
    final hasValidHighlight = isBothPlaying &&
        _ttsHighlightStart >= 0 &&
        _ttsHighlightEnd > _ttsHighlightStart;

    return ValueListenableBuilder<String>(
      valueListenable: AppLang.code,
      builder: (context, langCode, _) {
        return GestureDetector(
          onTap: () {
            // While reading OR tour is active, do NOT request focus or open keyboard.
            if (_readingTourCurrentStep != null) {
              FocusScope.of(context).unfocus();
              return;
            }
            if (!_isReadingRunningNow) {
              _textFocus.requestFocus();
            } else {
              // Secim yapilabilir ama klavye acilmasin
              FocusScope.of(context).unfocus();
            }
          },
          onLongPress: () {
            // Long press: sadece secim, klavye yok
            FocusScope.of(context).unfocus();
          },
          child: SizedBox(
            width: double.infinity,
            child: LayoutBuilder(
              builder: (context, constraints) {
                _textAreaWidth = constraints.maxWidth;
                return KeyedSubtree(
                  key: ValueKey(
                      'reading_stack_${MediaQuery.of(context).orientation}'),
                  child: Stack(
                    children: [
                      // CustomPaint for highlight background (BOTH mode only, behind TextField)
                      if (isBothMode && hasValidHighlight)
                        Positioned.fill(
                          child: IgnorePointer(
                            ignoring: true,
                            child: LayoutBuilder(
                              builder: (context, constraints) {
                                return CustomPaint(
                                  painter: _HighlightPainter(
                                    fullText: _text.text,
                                    baseStyle: baseStyle,
                                    highlightStart: _ttsHighlightStart.clamp(
                                        0, _text.text.length),
                                    highlightEnd: _ttsHighlightEnd.clamp(
                                        0, _text.text.length),
                                    padding: EdgeInsets.symmetric(
                                        horizontal: hPadding, vertical: 12),
                                    maxWidth: constraints.maxWidth,
                                    highlightColor:
                                        Colors.grey.withValues(alpha: 0.48),
                                    highlightRects: _highlightRects,
                                    textScaler:
                                        MediaQuery.textScalerOf(context),
                                  ),
                                );
                              },
                            ),
                          ),
                        ),
                      // TextField for editing (always present)
                      // KeyedSubtree forces full rebuild on orientation change → no stretch glitch
                      AnimatedOpacity(
                        opacity: _voiceFadeOpacity,
                        duration: const Duration(milliseconds: 800),
                        child: KeyedSubtree(
                          key: ValueKey(
                              'reading_tf_${MediaQuery.of(context).orientation}_${MediaQuery.of(context).size.width.round()}'),
                          child: TextField(
                            key: _readingTextKey,
                            controller: _text,
                            focusNode: _textFocus,
                            autofocus: false,
                            maxLines: null,
                            minLines: 1,
                            keyboardType: TextInputType.multiline,
                            textInputAction: TextInputAction.newline,
                            enableSuggestions: false,
                            autocorrect: false,
                            inputFormatters: const [],
                            // While reading is running, make field read-only to freeze cursor and prevent typing.
                            // Interactive selection stays enabled so user can still select text.
                            readOnly: _isReadingRunningNow ||
                                _readingTourCurrentStep != null,
                            enableInteractiveSelection: true,
                            selectionControls:
                                materialTextSelectionHandleControls,
                            showCursor: !_isReadingRunningNow &&
                                _readingTourCurrentStep == null,
                            magnifierConfiguration:
                                TextMagnifierConfiguration.disabled,
                            cursorColor: baseStyle.color,
                            cursorWidth: 2.0,
                            cursorHeight: 20.0,
                            style:
                                baseStyle, // Always visible in BOTH mode to prevent flicker
                            strutStyle: const StrutStyle(
                              fontSize: 16,
                              height: 1.7,
                              leading: 0.15,
                              forceStrutHeight: true,
                            ),
                            textAlign:
                                isPoetry ? TextAlign.center : TextAlign.left,
                            textAlignVertical: TextAlignVertical.top,
                            decoration: InputDecoration(
                              isCollapsed: true,
                              border: InputBorder.none,
                              enabledBorder: InputBorder.none,
                              focusedBorder: InputBorder.none,
                              hintText: t('hint.text'),
                              hintStyle: TextStyle(
                                fontSize:
                                    (_readingTextStyle?.fontSize ?? 18) * 0.75,
                                color: Colors.grey.shade600,
                              ),
                              contentPadding: EdgeInsets.symmetric(
                                  horizontal: hPadding, vertical: 12),
                            ),
                            onChanged: (_) {
                              _savePersisted();
                              // Yazarken imleci görünür tut — klavye arkasında kalmasın
                              WidgetsBinding.instance.addPostFrameCallback((_) {
                                _scrollToCursor();
                              });
                            },
                            contextMenuBuilder: (context, editableTextState) {
                              // AppLang.code.value okunarak dil her zaman güncel alınır
                              final _ = AppLang.code.value;
                              final selection =
                                  editableTextState.textEditingValue.selection;
                              final fullText =
                                  editableTextState.textEditingValue.text;
                              final hasSelection = selection != null &&
                                  selection.isValid &&
                                  !selection.isCollapsed;
                              // Check if all text is selected
                              final isAllSelected = hasSelection &&
                                  selection.start == 0 &&
                                  selection.end == fullText.length;
                              final selectedText = hasSelection
                                  ? fullText.substring(
                                      selection.start, selection.end)
                                  : '';

                              final buttonItems = <ContextMenuButtonItem>[];

                              // CUT
                              if (hasSelection) {
                                buttonItems.add(
                                  ContextMenuButtonItem(
                                    label: t('selection.cut'),
                                    onPressed: () {
                                      ContextMenuController.removeAny();
                                      Clipboard.setData(
                                          ClipboardData(text: selectedText));
                                      final newText = fullText.replaceRange(
                                          selection.start, selection.end, '');
                                      _text.value = TextEditingValue(
                                        text: newText,
                                        selection: TextSelection.collapsed(
                                            offset: selection.start),
                                      );
                                    },
                                  ),
                                );
                              }

                              // COPY
                              if (hasSelection) {
                                buttonItems.add(
                                  ContextMenuButtonItem(
                                    label: t('selection.copy'),
                                    onPressed: () {
                                      ContextMenuController.removeAny();
                                      Clipboard.setData(
                                          ClipboardData(text: selectedText));
                                    },
                                  ),
                                );
                              }

                              // PASTE
                              buttonItems.add(
                                ContextMenuButtonItem(
                                  label: t('selection.paste'),
                                  onPressed: () async {
                                    ContextMenuController.removeAny();
                                    final clipboardData =
                                        await Clipboard.getData(
                                            Clipboard.kTextPlain);
                                    if (clipboardData?.text != null) {
                                      final pasteText = clipboardData!.text!;
                                      final currentText = editableTextState
                                          .textEditingValue.text;
                                      final currentSelection = editableTextState
                                          .textEditingValue.selection;
                                      final newText = currentText.replaceRange(
                                        currentSelection.start,
                                        currentSelection.end,
                                        pasteText,
                                      );
                                      final newOffset = currentSelection.start +
                                          pasteText.length;
                                      _text.value = TextEditingValue(
                                        text: newText,
                                        selection: TextSelection.collapsed(
                                            offset: newOffset),
                                      );
                                    }
                                  },
                                ),
                              );

                              // SHARE - Show if has selection, or if all text is selected
                              if ((hasSelection &&
                                      selectedText.trim().isNotEmpty) ||
                                  isAllSelected) {
                                final textToShare =
                                    isAllSelected ? fullText : selectedText;
                                buttonItems.add(
                                  ContextMenuButtonItem(
                                    label: t('selection.share'),
                                    onPressed: () {
                                      ContextMenuController.removeAny();
                                      Share.share(textToShare);
                                    },
                                  ),
                                );
                              }

                              // WHATSAPP
                              if ((hasSelection &&
                                      selectedText.trim().isNotEmpty) ||
                                  isAllSelected) {
                                final textToSend =
                                    isAllSelected ? fullText : selectedText;
                                buttonItems.add(
                                  ContextMenuButtonItem(
                                    label: t('selection.whatsapp'),
                                    onPressed: () async {
                                      ContextMenuController.removeAny();
                                      final encoded =
                                          Uri.encodeComponent(textToSend);
                                      final uri = Uri.parse(
                                          'whatsapp://send?text=$encoded');
                                      if (await canLaunchUrl(uri)) {
                                        await launchUrl(uri,
                                            mode:
                                                LaunchMode.externalApplication);
                                      } else {
                                        // WhatsApp yüklü değil — genel paylaşıma düş
                                        Share.share(textToSend);
                                      }
                                    },
                                  ),
                                );
                              }

                              // MAIL
                              if ((hasSelection &&
                                      selectedText.trim().isNotEmpty) ||
                                  isAllSelected) {
                                final textToMail =
                                    isAllSelected ? fullText : selectedText;
                                buttonItems.add(
                                  ContextMenuButtonItem(
                                    label: t('selection.mail'),
                                    onPressed: () async {
                                      ContextMenuController.removeAny();
                                      final encoded =
                                          Uri.encodeComponent(textToMail);
                                      final uri =
                                          Uri.parse('mailto:?body=$encoded');
                                      if (await canLaunchUrl(uri)) {
                                        await launchUrl(uri,
                                            mode:
                                                LaunchMode.externalApplication);
                                      } else {
                                        Share.share(textToMail);
                                      }
                                    },
                                  ),
                                );
                              }

                              // SELECT ALL
                              buttonItems.add(
                                ContextMenuButtonItem(
                                  label: t('selection.selectAll'),
                                  onPressed: () {
                                    // Select all text first
                                    _text.value = TextEditingValue(
                                      text: fullText,
                                      selection: TextSelection(
                                        baseOffset: 0,
                                        extentOffset: fullText.length,
                                      ),
                                    );
                                    // Close current menu and reopen it after selection update
                                    ContextMenuController.removeAny();
                                    // Reopen menu after frame to show all options
                                    WidgetsBinding.instance
                                        .addPostFrameCallback((_) {
                                      if (mounted && _text.text.isNotEmpty) {
                                        try {
                                          // Try to show toolbar programmatically
                                          editableTextState.showToolbar();
                                        } catch (e) {
                                          // If showToolbar() doesn't work, request focus to trigger menu,
                                          // but never request focus while a reading session is running.
                                          if (!_isReadingRunningNow &&
                                              _readingTourCurrentStep == null) {
                                            _textFocus.requestFocus();
                                          }
                                          // Use a small delay to ensure selection is set before triggering menu
                                          Future.delayed(
                                              const Duration(milliseconds: 100),
                                              () {
                                            if (mounted) {
                                              // Trigger menu by simulating selection change
                                              final currentSelection =
                                                  _text.selection;
                                              _text.selection =
                                                  TextSelection.collapsed(
                                                      offset:
                                                          currentSelection.end);
                                              _text.selection = TextSelection(
                                                baseOffset: 0,
                                                extentOffset: _text.text.length,
                                              );
                                            }
                                          });
                                        }
                                      }
                                    });
                                  },
                                ),
                              );

                              // TRANSLATE - Show if has selection, or if all text is selected
                              if ((hasSelection &&
                                      selectedText.trim().isNotEmpty) ||
                                  isAllSelected) {
                                final textToTranslate =
                                    isAllSelected ? fullText : selectedText;
                                buttonItems.add(
                                  ContextMenuButtonItem(
                                    label: t('selection.translate'),
                                    onPressed: () {
                                      ContextMenuController.removeAny();
                                      _openTranslate(textToTranslate);
                                    },
                                  ),
                                );
                              }

                              // ASK CHAT GPT - Show if has selection, or if all text is selected
                              if ((hasSelection &&
                                      selectedText.trim().isNotEmpty) ||
                                  isAllSelected) {
                                final textToAsk =
                                    isAllSelected ? fullText : selectedText;
                                buttonItems.add(
                                  ContextMenuButtonItem(
                                    label: t('selection.askChatGPT'),
                                    onPressed: () {
                                      ContextMenuController.removeAny();
                                      _openChatGptWithText(textToAsk);
                                    },
                                  ),
                                );
                              }

                              // NOTE - Show if has selection, or if all text is selected
                              if ((hasSelection &&
                                      selectedText.trim().isNotEmpty) ||
                                  isAllSelected) {
                                final textForNote =
                                    isAllSelected ? fullText : selectedText;
                                final startIdx =
                                    isAllSelected ? 0 : selection.start;
                                final endIdx = isAllSelected
                                    ? fullText.length
                                    : selection.end;
                                buttonItems.add(
                                  ContextMenuButtonItem(
                                    label: t('selection.note'),
                                    onPressed: () {
                                      ContextMenuController.removeAny();
                                      _openReadingNoteSheet(
                                        selectedText: textForNote,
                                        startIndex: startIdx,
                                        endIndex: endIdx,
                                      );
                                    },
                                  ),
                                );
                              }

                              final isDark = Theme.of(context).brightness ==
                                  Brightness.dark;
                              return Theme(
                                data: Theme.of(context).copyWith(
                                  canvasColor: isDark
                                      ? const Color(0xFF2A2A2A)
                                      : const Color(0xFFF5EDE0),
                                ),
                                child: AdaptiveTextSelectionToolbar.buttonItems(
                                  anchors: editableTextState.contextMenuAnchors,
                                  buttonItems: buttonItems,
                                ),
                              );
                            },
                          ),
                        ), // KeyedSubtree TextField
                      ), // AnimatedOpacity
                    ],
                  ), // Stack
                ); // KeyedSubtree Stack
              },
            ),
          ),
        ); // GestureDetector
      }, // ValueListenableBuilder builder
    ); // ValueListenableBuilder
  }

  @override
  Widget build(BuildContext context) {
    final isTablet = _isTablet(context);
    _buildCount++;

    // Orientation routing: Check at build level
    final mediaQuery = MediaQuery.of(context);
    final bool isLandscape = mediaQuery.orientation == Orientation.landscape;
    // Toolbar gizleme: focus'a bağla — viewInsets.bottom rebuild'lerde titrer, focus stabil
    final bool isKeyboardOpen = _textFocus.hasFocus;
    final bool hideTopToolbarInLandscape = isLandscape && isKeyboardOpen;

    // Tour step computation (moved outside children list)
    // TEMPORARY DIAGNOSTIC: Kill-switch - force tour state to null if disabled
    final int? stepIndex =
        kDisableReadingTourForDiag ? null : _readingTourCurrentStep;
    final step = (stepIndex != null) ? _buildReadingTourStep(stepIndex) : null;

    // Determine if tour state is invalid (stepIndex set but step is null)
    final bool invalidTourState = (stepIndex != null && step == null);

    // Use effectiveStepIndex for rendering - if invalid, treat as null to prevent overlay
    final int? effectiveStepIndex = invalidTourState ? null : stepIndex;

    // Lifecycle logs (first 3 builds only)
    if (_buildCount <= 3) {
      final dontShow = _getReadingTourDontShowAgain();
    }

    // CRITICAL FIX: If tour state is invalid, schedule a clear after the frame
    // Use pending flag to prevent multiple callbacks
    if (invalidTourState && !_pendingTourClear) {
      _pendingTourClear = true;
      WidgetsBinding.instance.addPostFrameCallback((_) {
        if (!mounted) {
          _pendingTourClear = false;
          return;
        }
        setState(() {
          _readingTourCurrentStep = null;
          _pendingTourClear = false;
        });
      });
    } else if (!invalidTourState && _pendingTourClear) {
      // If state becomes valid again, clear the pending flag
      _pendingTourClear = false;
    }

    // Nova butonu widget'ı - Android'de varsayılan olarak gizle (ChatGPT app yüklü)
    final novaButton = Platform.isAndroid
        ? const SizedBox.shrink()
        : IconButton(
            padding: EdgeInsets.zero,
            constraints: const BoxConstraints(minWidth: 40, minHeight: 40),
            visualDensity: VisualDensity.compact,
            icon: Icon(
              Icons.auto_awesome,
              color: _novaOnline ? Colors.green : Colors.red,
            ),
            tooltip: _novaOnline ? 'Nova (Online)' : 'Nova (Offline)',
            onPressed: _openChatGptExternal,
            onLongPress: _clearNovaConnection,
          );
    final p = <String, List<String>>{
      'en': [
        'Summarize this paragraph in 2 sentences.',
        'What does “resilience” mean?',
        'What is the main idea of this text?',
      ],
      'tr': [
        'Bu paragrafı 2 cümlede özetler misin?',
        '“resilience” ne demek?',
        'Okuduğum metnin ana fikri nedir?',
      ],
      'it': [
        'Riassumi questo paragrafo in 2 frasi.',
        'Cosa significa "resilience"?',
        "Qual è l'idea principale di questo testo?",
      ],
      'de': [
        'Fasse diesen Absatz in 2 Sätzen zusammen.',
        'Was bedeutet “resilience”?',
        'Was ist die Hauptidee dieses Textes?',
      ],
      'fr': [
        'Résumez ce paragraphe en 2 phrases.',
        'Que signifie “resilience” ?',
        'Quelle est l’idée principale de ce texte ?',
      ],
      'es': [
        'Resume este párrafo en 2 oraciones.',
        '¿Qué significa “resilience”?',
        '¿Cuál es la idea principal de este texto?',
      ],
      'hi': [
        'इस पैराग्राफ को 2 वाक्यों में सारांशित करो।',
        '“resilience” का क्या मतलब है?',
        'इस पाठ का मुख्य विचार क्या है?',
      ],
      'ru': [
        'Кратко перескажите этот абзац в двух предложениях.',
        'Что означает слово «resilience»?',
        'Какова основная идея этого текста?',
      ],
      'el': [
        'Περίγραψε αυτή την παράγραφο σε 2 προτάσεις.',
        'Τι σημαίνει «resilience»;',
        'Ποια είναι η κύρια ιδέα αυτού του κειμένου;',
      ],
      'ja': [
        'この段落を2文で要約してください。',
        '「resilience」とは何ですか？',
        'このテキストの主なアイデアは何ですか？',
      ],
      'ko': [
        '이 단락을 두 문장으로 요약해 주세요.',
        '“resilience”가 무슨 뜻인가요?',
        '이 글의 핵심 내용은 무엇인가요?',
      ],
      'bg': [
        'Резюмирайте този параграф в две изречения.',
        'Какво означава “resilience”?',
        'Каква е основната идея на този текст?',
      ],
    };

    final isLandscapeNow =
        MediaQuery.of(context).orientation == Orientation.landscape;
    return Scaffold(
      // Portrait: always resize. Landscape: resize when keyboard open so text area stays fully visible.
      resizeToAvoidBottomInset: isLandscape ? false : true,
      appBar: _isImmersive
          ? null
          : AppBar(
              centerTitle: false,
              titleSpacing: 0,
              leadingWidth: 48,
              leading: IconButton(
                padding: EdgeInsets.zero,
                constraints: const BoxConstraints(minWidth: 40, minHeight: 40),
                visualDensity: VisualDensity.compact,
                icon: const Icon(Icons.arrow_back),
                tooltip: t('btn.back'),
                onPressed: () async {
                  await _savePersisted();
                  if (!mounted) return;
                  Navigator.pushReplacement(
                    context,
                    PageRouteBuilder(
                      pageBuilder: (context, a1, a2) => const LanguageScreen(),
                      transitionDuration: Duration.zero,
                      transitionsBuilder: (context, a1, a2, child) => child,
                    ),
                  );
                },
              ),
              title: Builder(
                builder: (context) {
                  final isLandscape = MediaQuery.of(context).orientation ==
                      Orientation.landscape;
                  return Row(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      const SizedBox(width: 4),
                      Flexible(
                        child: KeyedSubtree(
                          key: _tourKeyLanguage,
                          child: TourTarget(
                            id: 'tour.language',
                            onRect: _onTourRectChanged,
                            child: _buildLanguageDropdownCompact(
                                key: _readingTourKeyLanguage),
                          ),
