        preview: json['preview'] as String,
        fullText: json['fullText'] as String,
      );
}

// ========================= NOTES ========================
class NotesPage extends StatefulWidget {
  const NotesPage({super.key});

  @override
  State<NotesPage> createState() => _NotesPageState();
}

class _NotesPageState extends State<NotesPage> {
  static const _prefsReadingNotes = 'reading_notes_v1';
  List<ReadingNote> _readingNotes = [];

  @override
  void initState() {
    super.initState();
    _loadReadingNotes();
  }

  Future<void> _loadReadingNotes() async {
    final sp = await SharedPreferences.getInstance();
    final jsonStr = sp.getString(_prefsReadingNotes);
    if (jsonStr == null || jsonStr.isEmpty) {
      setState(() => _readingNotes = []);
      return;
    }
    try {
      final List<dynamic> jsonList = jsonDecode(jsonStr);
      setState(() {
        _readingNotes = jsonList
            .map((j) => ReadingNote.fromJson(j as Map<String, dynamic>))
            .toList();
        _readingNotes.sort((a, b) => b.createdAt.compareTo(a.createdAt));
      });
    } catch (e) {
      setState(() => _readingNotes = []);
    }
  }

  Future<void> _saveReadingNotes() async {
    final sp = await SharedPreferences.getInstance();
    final List<Map<String, dynamic>> jsonList =
        _readingNotes.map((n) => n.toJson()).toList();
    await sp.setString(_prefsReadingNotes, jsonEncode(jsonList));
  }

  Future<void> _deleteReadingNote(ReadingNote note, int index) async {
    FocusScope.of(context).unfocus();
    setState(() {
      _readingNotes.removeAt(index);
    });
    await _saveReadingNotes();
    if (mounted) {
      ScaffoldMessenger.of(context)
        ..clearSnackBars()
        ..showSnackBar(_gradientSnackBar(t('notes.deleted'),
            behavior: SnackBarBehavior.floating));
    }
  }

  Future<void> _openEditReadingNoteSheet(ReadingNote note) async {
    final noteTextController = TextEditingController(text: note.noteText);
    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      backgroundColor: kCream,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(18)),
      ),
      builder: (ctx) {
        final mq = MediaQuery.of(ctx);
        final kbHeight = mq.viewInsets.bottom;
        final bottomPad = kbHeight > 0 ? kbHeight : mq.padding.bottom;
        final availableH = mq.size.height - kbHeight;
        final maxH = (availableH * 0.86).clamp(200.0, double.infinity);
        final hPad = mq.padding.left + mq.padding.right > 0
            ? EdgeInsets.only(
                left: mq.padding.left + 8, right: mq.padding.right + 8)
            : const EdgeInsets.symmetric(horizontal: 8);
        return Padding(
          padding: EdgeInsets.only(bottom: bottomPad),
          child: ConstrainedBox(
            constraints: BoxConstraints(maxHeight: maxH),
            child: SingleChildScrollView(
              child: Padding(
                padding: hPad,
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Padding(
                      padding: const EdgeInsets.fromLTRB(16, 12, 16, 8),
                      child: Text(
                        t('notes.title'),
                        style: const TextStyle(
                            fontSize: 20, fontWeight: FontWeight.bold),
                      ),
                    ),
                    Padding(
                      padding: const EdgeInsets.symmetric(horizontal: 16),
                      child: Container(
                        width: double.infinity,
                        padding: const EdgeInsets.all(12),
                        decoration: BoxDecoration(
                          color: Theme.of(ctx)
                              .colorScheme
                              .surfaceContainerHighest
                              .withValues(alpha: 0.5),
                          borderRadius: BorderRadius.circular(12),
                          border: Border.all(
                            color: Theme.of(ctx)
                                .dividerColor
                                .withValues(alpha: 0.5),
                          ),
                        ),
                        child: SelectableText(
                          note.selectedText,
                          style: TextStyle(
                            fontSize: 14,
                            color: Theme.of(ctx).colorScheme.onSurface,
                          ),
                        ),
                      ),
                    ),
                    const SizedBox(height: 12),
                    Padding(
                      padding: const EdgeInsets.symmetric(horizontal: 16),
                      child: TextField(
                        controller: noteTextController,
                        minLines: 2,
                        maxLines: 6,
                        decoration: InputDecoration(
                          hintText: t('notes.hint'),
                          border: OutlineInputBorder(
                            borderRadius: BorderRadius.circular(12),
                          ),
                        ),
                        autofocus: true,
                      ),
                    ),
                    Padding(
                      padding: const EdgeInsets.fromLTRB(16, 8, 16, 20),
                      child: Row(
                        mainAxisAlignment: MainAxisAlignment.end,
                        children: [
                          TextButton(
                            onPressed: () => Navigator.pop(ctx),
                            child: Text(t('notes.cancel')),
                          ),
                          const SizedBox(width: 8),
                          ElevatedButton(
                            onPressed: () async {
                              final newText = noteTextController.text.trim();
                              if (newText.isEmpty) {
                                Navigator.pop(ctx);
                                return;
                              }
                              final index = _readingNotes
                                  .indexWhere((n) => n.id == note.id);
                              if (index >= 0) {
                                setState(() {
                                  _readingNotes[index] = ReadingNote(
                                    id: note.id,
                                    documentId: note.documentId,
                                    selectedText: note.selectedText,
                                    noteText: newText,
                                    startIndex: note.startIndex,
                                    endIndex: note.endIndex,
                                    createdAt: note.createdAt,
                                  );
                                });
                                await _saveReadingNotes();
                              }
                              if (mounted) {
                                Navigator.pop(ctx);
                                ScaffoldMessenger.of(context).showSnackBar(
                                    _gradientSnackBar(t('notes.saved'),
                                        behavior: SnackBarBehavior.floating));
                              }
                            },
                            child: Text(t('notes.save')),
                          ),
                        ],
                      ),
                    ),
                  ],
                ),
              ), // hPad Padding
            ),
          ),
        );
      },
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      resizeToAvoidBottomInset: true,
      appBar: AppBar(
        title: Text(t('notes.title')),
      ),
      body: _readingNotes.isEmpty
          ? ResponsivePage(
              centerWhenFits: true,
              child: Center(
                child: Text(t('notes.empty')),
              ),
            )
          : ResponsivePage(
              centerWhenFits: false,
              padding: EdgeInsets.zero,
              skipScrollView: true,
              child: ListView.builder(
                padding: const EdgeInsets.symmetric(vertical: 8),
                itemCount: _readingNotes.length,
                itemBuilder: (context, index) {
                  final note = _readingNotes[index];
                  final dateTime =
                      DateTime.fromMillisecondsSinceEpoch(note.createdAt);
                  final dateStr =
                      '${dateTime.year}-${dateTime.month.toString().padLeft(2, '0')}-${dateTime.day.toString().padLeft(2, '0')} ${dateTime.hour.toString().padLeft(2, '0')}:${dateTime.minute.toString().padLeft(2, '0')}';
                  final selectedPreview = note.selectedText.length > 200
                      ? '${note.selectedText.substring(0, 200)}...'
                      : note.selectedText;
                  return Card(
                    margin:
                        const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                    child: Padding(
                      padding: const EdgeInsets.all(12),
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            selectedPreview,
                            maxLines: 4,
                            overflow: TextOverflow.ellipsis,
                            style: TextStyle(
                              fontSize: 13,
                              color: Theme.of(context)
                                  .colorScheme
                                  .onSurface
                                  .withValues(alpha: 0.8),
                            ),
                          ),
                          const SizedBox(height: 8),
                          Text(
                            note.noteText,
                            style: const TextStyle(fontSize: 15),
                          ),
                          const SizedBox(height: 6),
                          Text(
                            dateStr,
                            style: TextStyle(
                              fontSize: 12,
                              color: Theme.of(context)
                                  .colorScheme
                                  .onSurface
                                  .withValues(alpha: 0.6),
                            ),
                          ),
                          Row(
                            mainAxisAlignment: MainAxisAlignment.end,
                            children: [
                              PopupMenuButton<String>(
                                icon: const Icon(Icons.more_vert),
                                color: Theme.of(context)
                                    .colorScheme
                                    .surfaceContainerHighest,
                                surfaceTintColor: Colors.transparent,
                                elevation: 6,
                                shape: RoundedRectangleBorder(
                                  borderRadius: BorderRadius.circular(16),
                                ),
                                onSelected: (value) {
                                  if (value == 'edit') {
                                    _openEditReadingNoteSheet(note);
                                  } else if (value == 'delete') {
                                    _deleteReadingNote(note, index);
                                  }
                                },
                                itemBuilder: (ctx) {
                                  final onSurface = Theme.of(ctx)
                                      .colorScheme
                                      .onSurface
                                      .withValues(alpha: 0.9);
                                  return [
                                    PopupMenuItem<String>(
                                      value: 'edit',
                                      padding: const EdgeInsets.symmetric(
                                          horizontal: 16, vertical: 12),
                                      child: Row(
                                        mainAxisSize: MainAxisSize.min,
                                        children: [
                                          Icon(Icons.edit_outlined,
                                              size: 20, color: onSurface),
                                          const SizedBox(width: 12),
                                          Text(
                                            t('notes.edit'),
                                            style: TextStyle(
                                                fontSize: 14, color: onSurface),
                                          ),
                                        ],
                                      ),
                                    ),
                                    PopupMenuItem<String>(
                                      value: 'delete',
                                      padding: const EdgeInsets.symmetric(
                                          horizontal: 16, vertical: 12),
                                      child: Row(
                                        mainAxisSize: MainAxisSize.min,
                                        children: [
                                          Icon(Icons.delete_outlined,
                                              size: 20, color: onSurface),
                                          const SizedBox(width: 12),
                                          Text(
                                            t('notes.delete'),
                                            style: TextStyle(
                                                fontSize: 14, color: onSurface),
                                          ),
                                        ],
                                      ),
                                    ),
                                  ];
                                },
                              ),
                            ],
                          ),
                        ],
                      ),
                    ),
                  );
                },
              ),
            ),
    );
  }
}

// ========================= NOTE EDITOR ========================
class _NoteEditorPage extends StatefulWidget {
  final _Note? existingNote;
  final Future<void> Function(String text) onSave;
  final Future<void> Function()? onDelete;
  final String Function(String) t;

  const _NoteEditorPage({
    this.existingNote,
    required this.onSave,
    this.onDelete,
    required this.t,
  });

  @override
  State<_NoteEditorPage> createState() => _NoteEditorPageState();
}

class _NoteEditorPageState extends State<_NoteEditorPage> {
  late TextEditingController _controller;

  @override
  void initState() {
    super.initState();
    _controller = TextEditingController(text: widget.existingNote?.text ?? '');
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final orientation = MediaQuery.of(context).orientation;
    final viewInsets = MediaQuery.of(context).viewInsets;
    final keyboardOpen = viewInsets.bottom > 0;
    return Scaffold(
      resizeToAvoidBottomInset: true,
      body: Stack(
        children: [
          SafeArea(
            child: _buildBody(context, orientation == Orientation.landscape,
                viewInsets, keyboardOpen),
          ),
        ],
      ),
    );
  }

  /// Single flex layout: compactHeader | Expanded(editor) | actionRow.
  /// viewInsets.bottom used only as bottom padding. When keyboard is open,
  /// gaps are reduced so the editor keeps usable height.
  Widget _buildBody(BuildContext context, bool isLandscape,
      EdgeInsets viewInsets, bool keyboardOpen) {
    final horizontal = isLandscape ? 12.0 : 16.0;
    final top = isLandscape ? 4.0 : 6.0;
    final gap = keyboardOpen ? 4.0 : 10.0;
    final bottomBase = keyboardOpen ? 6.0 : 14.0;
    return Padding(
      padding: EdgeInsets.fromLTRB(
          horizontal, top, horizontal, bottomBase + viewInsets.bottom),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          _buildCompactHeader(context, isLandscape),
          SizedBox(height: gap),
          Expanded(child: _buildEditor(context)),
          SizedBox(height: gap),
          _buildActionRow(context),
        ],
      ),
    );
  }

  Widget _buildCompactHeader(BuildContext context, bool isLandscape) {
    return Row(
      children: [
        IconButton(
          icon: const Icon(Icons.arrow_back),
          onPressed: () => Navigator.pop(context),
          style: IconButton.styleFrom(
            visualDensity: VisualDensity.compact,
            minimumSize: const Size(40, 40),
          ),
        ),
        if (!isLandscape)
          Expanded(
            child: Center(
              child: Text(
                widget.t('notes.title'),
                style: Theme.of(context).textTheme.titleMedium,
              ),
            ),
          )
        else
          const Expanded(child: SizedBox.shrink()),
      ],
    );
  }

  Widget _buildEditor(BuildContext context) {
    return TextField(
      controller: _controller,
      maxLines: null,
      expands: true,
      autofocus: true,
      textAlignVertical: TextAlignVertical.top,
      decoration: InputDecoration(
        hintText: widget.t('hint.text'),
        border: OutlineInputBorder(
          borderRadius: BorderRadius.circular(12),
        ),
        contentPadding:
            const EdgeInsets.symmetric(horizontal: 16, vertical: 12),
      ),
    );
  }

  Widget _buildActionRow(BuildContext context) {
    return Row(
      mainAxisAlignment: MainAxisAlignment.end,
      children: [
        if (widget.existingNote != null && widget.onDelete != null) ...[
          TextButton.icon(
            onPressed: () async {
              await widget.onDelete!();
              if (context.mounted) Navigator.pop(context);
            },
            icon: const Icon(Icons.delete_outline, size: 20),
            label: Text(widget.t('notes.delete')),
          ),
          const SizedBox(width: 8),
        ],
        TextButton(
          onPressed: () {
            if (context.mounted) Navigator.pop(context);
          },
          child: Text(widget.t('notes.cancel')),
        ),
        const SizedBox(width: 12),
        FilledButton(
          onPressed: () async {
            final text = _controller.text.trim();
            if (text.isNotEmpty) {
              await widget.onSave(text);
            }
            if (context.mounted) Navigator.pop(context);
          },
          child: Text(
            widget.t('notes.save'),
            style: const TextStyle(fontWeight: FontWeight.bold),
          ),
        ),
      ],
    );
  }
}

