  @override
  void initState() {
    super.initState();
    // Uygulama dilini varsayılan olarak kullan
    final appLang = AppLang.code.value;
    _selectedLang = _texts.containsKey(appLang) ? appLang : 'en';
    _scrollController = ScrollController();
    _scrollController.addListener(_onScrollChanged);
    WidgetsBinding.instance.addPostFrameCallback((_) {
      Future.delayed(const Duration(milliseconds: 2500), () {
        if (mounted) _startAutoScroll();
      });
    });
  }

  void _onScrollChanged() {
    if (_isAutoScrolling) {
      _lastScrollPosition = _scrollController.position.pixels;
      return;
    }
    final currentPosition = _scrollController.position.pixels;
    if ((currentPosition - _lastScrollPosition).abs() > 0.1) {
      _lastScrollPosition = currentPosition;
      _handleUserInteraction();
    }
  }

  void _handleUserInteraction() {
    _stopAutoScroll();
    _restartTimer?.cancel();
    _restartTimer = Timer(const Duration(milliseconds: 1500), () {
      if (mounted && !_isAutoScrolling) _startAutoScroll();
    });
  }

  void _startAutoScroll() {
    if (!mounted) return;
    if (!_scrollController.hasClients) {
      Future.delayed(const Duration(milliseconds: 100), () {
        if (mounted) _startAutoScroll();
      });
      return;
    }
    if (_isAutoScrolling) return;
    _isAutoScrolling = true;
    _lastScrollPosition = _scrollController.position.pixels;
    _autoScrollTimer?.cancel();
    _autoScrollTimer =
        Timer.periodic(const Duration(milliseconds: 40), (timer) {
      if (!mounted || !_scrollController.hasClients) {
        timer.cancel();
        _isAutoScrolling = false;
        return;
      }
      final maxScroll = _scrollController.position.maxScrollExtent;
      final currentScroll = _scrollController.position.pixels;
      if (currentScroll >= maxScroll - 1) {
        timer.cancel();
        _isAutoScrolling = false;
        return;
      }
      final nextScroll = currentScroll + 0.8;
      if (nextScroll <= maxScroll) {
        _scrollController.jumpTo(nextScroll);
        _lastScrollPosition = nextScroll;
      } else {
        _scrollController.jumpTo(maxScroll);
        _lastScrollPosition = maxScroll;
        timer.cancel();
        _isAutoScrolling = false;
      }
    });
  }

  void _stopAutoScroll() {
    _autoScrollTimer?.cancel();
    _autoScrollTimer = null;
    _isAutoScrolling = false;
    if (_scrollController.hasClients) {
      _lastScrollPosition = _scrollController.position.pixels;
    }
  }

  void _selectLang(String code) {
    _stopAutoScroll();
    setState(() => _selectedLang = code);
    // Scroll to top and restart auto-scroll
    WidgetsBinding.instance.addPostFrameCallback((_) {
      if (_scrollController.hasClients) {
        _scrollController.jumpTo(0);
      }
      Future.delayed(const Duration(milliseconds: 600), () {
        if (mounted) _startAutoScroll();
      });
    });
  }

  @override
  void dispose() {
    _autoScrollTimer?.cancel();
    _autoScrollTimer = null;
    _restartTimer?.cancel();
    _restartTimer = null;
    _scrollController.removeListener(_onScrollChanged);
    _scrollController.dispose();
    super.dispose();
  }

  Widget _buildAboutText({
    required String text,
    required TextStyle normalStyle,
    required TextStyle boldStyle,
  }) {
    final parts = text.split('EasyReading');
    final spans = <TextSpan>[];
    for (int i = 0; i < parts.length; i++) {
      if (parts[i].isNotEmpty) {
        spans.add(TextSpan(text: parts[i], style: normalStyle));
      }
      if (i < parts.length - 1) {
        spans.add(TextSpan(text: 'EasyReading', style: boldStyle));
      }
    }
    return RichText(
      textAlign: TextAlign.center,
      text: TextSpan(children: spans),
    );
  }

  @override
  Widget build(BuildContext context) {
    final cs = Theme.of(context).colorScheme;
    final styleMain = GoogleFonts.lora(
        textStyle: TextStyle(fontSize: 15.0, height: 1.7, color: cs.onSurface));
    final styleBold = GoogleFonts.lora(
        textStyle: TextStyle(
            fontSize: 15.0,
            height: 1.7,
            color: cs.onSurface,
            fontWeight: FontWeight.bold));

    final text = _texts[_selectedLang] ?? _texts['en']!;

    return Scaffold(
      appBar: AppBar(
        leading: IconButton(
          icon: const Icon(Icons.arrow_back),
          onPressed: () => Navigator.pop(context),
        ),
      ),
      body: ResponsivePage(
        padding: const EdgeInsets.fromLTRB(24, 6, 24, 16),
        centerWhenFits: false,
        skipScrollView: true,
        child: Column(
          children: [
            // ── Dil bayrakları ──────────────────────────────────
            Padding(
              padding: const EdgeInsets.only(bottom: 12),
              child: Wrap(
                spacing: 8,
                runSpacing: 8,
                alignment: WrapAlignment.center,
                children: _langs.map((lang) {
                  final code = lang.$1;
                  final flag = lang.$2;
                  final isSelected = _selectedLang == code;
                  return GestureDetector(
                    onTap: () => _selectLang(code),
                    child: AnimatedContainer(
                      duration: const Duration(milliseconds: 180),
                      padding: const EdgeInsets.all(4),
                      decoration: BoxDecoration(
                        shape: BoxShape.circle,
                        border: Border.all(
                          color: isSelected ? cs.primary : Colors.transparent,
                          width: 2.5,
                        ),
                        boxShadow: isSelected
                            ? [
                                BoxShadow(
                                    color: cs.primary.withValues(alpha: 0.25),
                                    blurRadius: 6)
                              ]
                            : [],
                      ),
                      child: _CircleFlag(emoji: flag, size: 34),
                    ),
                  );
                }).toList(),
              ),
            ),

            // ── İnce ayırıcı ────────────────────────────────────
            Divider(height: 1, color: cs.outlineVariant),
            const SizedBox(height: 8),

            // ── Metin ───────────────────────────────────────────
            Expanded(
              child: Center(
                child: GestureDetector(
                  onTap: _handleUserInteraction,
                  onPanStart: (_) => _handleUserInteraction(),
                  onPanUpdate: (_) => _handleUserInteraction(),
                  child: NotificationListener<ScrollNotification>(
                    onNotification: (notification) {
                      if (notification is ScrollStartNotification &&
                          notification.dragDetails != null) {
                        _handleUserInteraction();
                      }
                      return false;
                    },
                    child: SingleChildScrollView(
                      controller: _scrollController,
                      child: _buildAboutText(
                        text: text,
                        normalStyle: styleMain,
                        boldStyle: styleBold,
                      ),
                    ),
                  ),
                ),
              ),
            ),

            // ── Footer ──────────────────────────────────────────
            Padding(
              padding: const EdgeInsets.only(top: 12, bottom: 8),
              child: Text(
                'designed & developed by KUN APPS',
                textAlign: TextAlign.center,
                style: GoogleFonts.lora(
                    textStyle: const TextStyle(
                  fontSize: 11,
                  fontWeight: FontWeight.normal,
                  letterSpacing: 0.8,
                  color: Color(0xFF8B6F47),
                )),
              ),
            ),
          ],
        ),
      ),
    );
  }
}

// ─── Yuvarlak bayrak widget'ı ────────────────────────────────────────────────
class _CircleFlag extends StatelessWidget {
  final String emoji;
  final double size;
  const _CircleFlag({required this.emoji, this.size = 32});
  @override
  Widget build(BuildContext context) {
    return Container(
      width: size,
      height: size,
      decoration: const BoxDecoration(shape: BoxShape.circle),
      clipBehavior: Clip.antiAlias,
      child: Center(
        child: Text(emoji,
            style: TextStyle(fontSize: size * 0.7),
            textScaler: TextScaler.noScaling),
      ),
    );
  }
}

